def _current_data_manager_object():
    """Return the manager bound to this request/task, or the default manager."""
    manager = _request_data_manager.get()
    return manager if manager is not None else _default_data_manager


class _DataManagerProxy:
    """Delegate legacy ``data_manager`` access to the current local manager."""

    def __bool__(self):
        return _current_data_manager_object() is not None

    def __getattr__(self, name):
        manager = _current_data_manager_object()
        if manager is None:
            raise AttributeError(f"Data manager is not initialized; cannot access {name!r}")
        return getattr(manager, name)

    def __setattr__(self, name, value):
        manager = _current_data_manager_object()
        if manager is None:
            raise AttributeError(f"Data manager is not initialized; cannot set {name!r}")
        setattr(manager, name, value)

    def __repr__(self):
        return repr(_current_data_manager_object())


data_manager = _DataManagerProxy()


def get_default_data_manager():
    """Return the process default manager used outside request contexts."""
    return _default_data_manager


def _set_default_data_manager(manager, company_code=None):
    global _default_data_manager, _active_company_code
    _default_data_manager = manager
    if company_code:
        _active_company_code = _normalise_company_code(company_code, DEFAULT_COMPANY_CODE)
    return manager


def set_data_manager_for_testing(manager):
    """Install an isolated test manager and prevent requests from selecting live data."""
    if not app.config.get('TESTING'):
        raise RuntimeError('TESTING must be enabled before installing a test data manager')

    _request_data_manager.set(None)
    data_folder = os.path.abspath(getattr(manager, 'data_folder', '') or '')
    live_companies_folder = LIVE_COMPANIES_FOLDER
    if data_folder:
        try:
            if os.path.commonpath([live_companies_folder, data_folder]) == live_companies_folder:
                raise RuntimeError('Tests may not use a manager inside the live companies folder')
        except ValueError:
            pass

    app.config['TEST_DATA_MANAGER'] = manager
    _set_default_data_manager(manager)
    mark_data_snapshot_current(manager)
    return manager


def clear_test_data_manager(restore_manager=None):
    """Remove the test override and optionally restore the previous default manager."""
    _request_data_manager.set(None)
    test_manager = app.config.pop('TEST_DATA_MANAGER', None)
    if test_manager is not None:
        _manager_caches.pop(id(test_manager), None)
        _data_snapshot_signatures.pop(id(test_manager), None)
        _data_signature_checks.pop(id(test_manager), None)
        with _data_reload_locks_guard:
            _data_reload_locks.pop(id(test_manager), None)
    _set_default_data_manager(restore_manager)


def _app_tests_allow_postgres():
    """Return whether app-level tests may use the configured PostgreSQL database."""
    return bool(app.config.get('ALLOW_POSTGRES_IN_TESTS'))


def _database_url_for_runtime():
    """Return the PostgreSQL URL for this runtime, excluding normal app tests."""
    if app.config.get('TESTING') and not _app_tests_allow_postgres():
        return ''
    return DATABASE_URL


def _assert_safe_test_company_folder(data_folder):
    """Prevent app tests from accidentally selecting live company folders."""
    if not app.config.get('TESTING') or app.config.get('ALLOW_LIVE_COMPANY_DATA_IN_TESTS'):
        return

    data_folder = os.path.abspath(data_folder or '')
    if not data_folder:
        return

    try:
        if os.path.commonpath([LIVE_COMPANIES_FOLDER, data_folder]) == LIVE_COMPANIES_FOLDER:
            raise RuntimeError(
                'Tests may not use a manager inside the live companies folder. '
                'Install a TEST_DATA_MANAGER or point COMPANY_REGISTRY_FILE at temporary data.'
            )
    except ValueError:
        return


def _path_from_config(path):
    path = str(path or '').strip()
    if not path:
        return ''
    if os.path.isabs(path):
        return path
    return os.path.join(BASE_DIR, path)


def _normalise_company_code(value, fallback=''):
    code = str(value or '').strip().upper()
    code = re.sub(r'[^A-Z0-9_-]+', '', code)
    return code or fallback


def _company_base_folder_for_code(code):
    code = _normalise_company_code(code, DEFAULT_COMPANY_CODE)
    return os.path.join('companies', code)


def _new_company_record(code, name, created_by='', requires_branding_setup=False):
    code = _normalise_company_code(code, DEFAULT_COMPANY_CODE)
    base_folder = _company_base_folder_for_code(code)
    return {
        'code': code,
        'name': str(name or code).strip() or code,
        'backendFolder': os.path.join(base_folder, 'backend').replace('\\', '/'),
        'frontendFolder': os.path.join(base_folder, 'frontend').replace('\\', '/'),
        'createdAt': datetime.now().isoformat(timespec='seconds'),
        'createdBy': str(created_by or '').strip(),
        'brandingSetupRequired': bool(requires_branding_setup),
    }


def _company_record_backend_folder(record):
    return _path_from_config((record or {}).get('backendFolder'))


def _company_record_frontend_folder(record):
    return _path_from_config((record or {}).get('frontendFolder'))


_COMPANY_STORAGE_CATEGORIES = (
    ('uploads', 'Invoices, claims & expense uploads'),
    ('events', 'Events & event files'),
    ('maintenance', 'Maintenance files'),
    ('inventory', 'Inventory & asset data'),
    ('workforce', 'Manpower & transport data'),
    ('finance', 'Quotations & finance data'),
    ('branding', 'Branding & PDF settings'),
    ('logs', 'Logs & live state'),
    ('company_data', 'Company settings & users'),
    ('other', 'Other company files'),
)


def _invalidate_company_storage_cache(*company_codes):
    with _company_storage_cache_lock:
        if not company_codes:
            _company_storage_cache.clear()
            return
        for company_code in company_codes:
            _company_storage_cache.pop(_normalise_company_code(company_code), None)


def _company_storage_category(root_kind, relative_path):
    relative_path = str(relative_path or '').replace('\\', '/').lower()
    filename = os.path.basename(relative_path)
    stem = os.path.splitext(filename)[0]

    if root_kind == 'frontend':
        return 'branding'
    if relative_path.startswith('workforce_uploads/'):
        return 'uploads'
    if relative_path.startswith('maintenance_media/') or stem.startswith('maintenance'):
        return 'maintenance'
    if relative_path.startswith('events/'):
        return 'events'
    if stem.startswith('finance'):
        return 'finance'
    if stem.startswith('workforce'):
        return 'workforce'
    if stem in {'assetlist', 'inventory', 'containers', 'clients', 'departments'}:
        return 'inventory'
    if stem in {'logs', 'realtimestate'}:
        return 'logs'
    if stem.startswith('pdfsettings'):
        return 'branding'
    if stem in {'users', 'company', 'companies'}:
        return 'company_data'
    return 'other'


def _company_storage_usage(company_code, force=False):
    code = _normalise_company_code(company_code)
    now = time.monotonic()
    with _company_storage_cache_lock:
        cached = _company_storage_cache.get(code)
        if cached and not force and now - cached['cachedAt'] < _company_storage_cache_seconds:
            return cached['data']

    registry = _load_company_registry()
    record = registry.get('companies', {}).get(code)
    if not record:
        raise KeyError(code)

    totals = {
        key: {'key': key, 'label': label, 'bytes': 0, 'fileCount': 0, 'recordCount': 0}
        for key, label in _COMPANY_STORAGE_CATEGORIES
    }
    seen_paths = set()
    for root_kind, root_path in (
        ('backend', _company_record_backend_folder(record)),
        ('frontend', _company_record_frontend_folder(record)),
    ):
        if not root_path or not os.path.isdir(root_path):
            continue
        root_path = os.path.abspath(root_path)
        for current_root, dirnames, filenames in os.walk(root_path, followlinks=False):
            dirnames[:] = [
                dirname for dirname in dirnames
                if not os.path.islink(os.path.join(current_root, dirname))
            ]
            for filename in filenames:
                absolute_path = os.path.abspath(os.path.join(current_root, filename))
                normalized_path = os.path.normcase(absolute_path)
                if normalized_path in seen_paths or os.path.islink(absolute_path):
                    continue
                try:
                    file_size = os.path.getsize(absolute_path)
                except OSError:
                    continue
                seen_paths.add(normalized_path)
                relative_path = os.path.relpath(absolute_path, root_path)
                category = _company_storage_category(root_kind, relative_path)
                totals[category]['bytes'] += max(0, int(file_size))
                totals[category]['fileCount'] += 1

    database_url = _database_url_for_runtime()
    if database_url:
        try:
            from postgres_data_manager import company_storage_breakdown

            for category, usage in company_storage_breakdown(database_url, code).items():
                if category not in totals:
                    category = 'other'
                totals[category]['bytes'] += max(0, int(usage.get('bytes') or 0))
                totals[category]['recordCount'] += max(0, int(usage.get('recordCount') or 0))
        except Exception as error:
            logger.warning('Unable to calculate PostgreSQL storage for company %s: %s', code, error)

    breakdown = list(totals.values())
    total_bytes = sum(item['bytes'] for item in breakdown)
    for item in breakdown:
        item['percent'] = round((item['bytes'] / total_bytes) * 100, 1) if total_bytes else 0
    breakdown.sort(key=lambda item: (-item['bytes'], item['label']))

    result = {
        'companyCode': code,
        'totalBytes': total_bytes,
        'fileCount': sum(item['fileCount'] for item in breakdown),
        'recordCount': sum(item['recordCount'] for item in breakdown),
        'breakdown': breakdown,
        'calculatedAt': datetime.now().isoformat(timespec='seconds'),
    }
    with _company_storage_cache_lock:
        _company_storage_cache[code] = {'cachedAt': now, 'data': result}
    return result


def _fallback_company_code(registry):
    companies = (registry or {}).get('companies') or {}
    default_company = _normalise_company_code((registry or {}).get('defaultCompany'))
    if default_company in companies:
        return default_company
    if DEFAULT_COMPANY_CODE in companies:
        return DEFAULT_COMPANY_CODE
    return sorted(companies.keys())[0] if companies else DEFAULT_COMPANY_CODE


def _standard_company_folder_for_code(code):
    return os.path.abspath(_path_from_config(_company_base_folder_for_code(code)))


def _safe_company_delete_folder(code, record):
    code = _normalise_company_code(code)
    company_root = os.path.abspath(os.path.join(BASE_DIR, 'companies'))
    target_folder = _standard_company_folder_for_code(code)

    if not code:
        raise ValueError('Company code is required')

    try:
        if os.path.commonpath([company_root, target_folder]) != company_root:
            raise ValueError('Company folder is outside the companies folder')
    except ValueError:
        raise ValueError('Company folder is outside the companies folder')

    if target_folder == company_root:
        raise ValueError('Refusing to delete the companies folder')

    for folder in (_company_record_backend_folder(record), _company_record_frontend_folder(record)):
        if not folder:
            continue
        folder = os.path.abspath(folder)
        try:
            if os.path.commonpath([target_folder, folder]) != target_folder:
                raise ValueError('Company assets must be inside the standard company folder before deletion')
        except ValueError:
            raise ValueError('Company assets must be inside the standard company folder before deletion')

    return target_folder


def _validate_company_rename_folder(old_code, new_code, record):
    old_code = _normalise_company_code(old_code)
    new_code = _normalise_company_code(new_code)
    if not old_code or not new_code:
        raise ValueError('Company code is required')
    if old_code == new_code:
        return _standard_company_folder_for_code(old_code), _standard_company_folder_for_code(new_code)

    old_folder = _standard_company_folder_for_code(old_code)
    new_folder = _standard_company_folder_for_code(new_code)
    company_root = os.path.abspath(os.path.join(BASE_DIR, 'companies'))

    try:
        if os.path.commonpath([company_root, new_folder]) != company_root:
            raise ValueError('Company folder is outside the companies folder')
    except ValueError:
        raise ValueError('Company folder is outside the companies folder')

    record_folders = [
        os.path.abspath(folder)
        for folder in (
            _company_record_backend_folder(record),
            _company_record_frontend_folder(record)
        )
        if folder
    ]
    standard_folder_matches = True

    for folder in record_folders:
        if not folder:
            continue
        try:
            if os.path.commonpath([old_folder, folder]) != old_folder:
                standard_folder_matches = False
                break
        except ValueError:
            standard_folder_matches = False
            break

    if not standard_folder_matches:
        # Legacy installs may have a normalized company code (SHOWBASE) while
        # the actual assets still live in the old AVPL folder. Allow that
        # one-hop migration when backend/frontend share a company parent.
        parent_folders = {os.path.dirname(folder) for folder in record_folders}
        if len(parent_folders) != 1:
            raise ValueError('Company assets must be inside one company folder before renaming')
        legacy_folder = os.path.abspath(next(iter(parent_folders)))
        try:
            if (
                os.path.commonpath([company_root, legacy_folder]) != company_root
                or legacy_folder == company_root
            ):
                raise ValueError('Company assets must be inside the companies folder before renaming')
            for folder in record_folders:
                if os.path.commonpath([legacy_folder, folder]) != legacy_folder:
                    raise ValueError('Company assets must be inside one company folder before renaming')
        except ValueError:
            raise ValueError('Company assets must be inside one company folder before renaming')
        old_folder = legacy_folder

    if (
        os.path.exists(new_folder)
        and os.path.normcase(os.path.abspath(new_folder)) != os.path.normcase(os.path.abspath(old_folder))
    ):
        raise ValueError(f'Company folder for {new_code} already exists')

    return old_folder, new_folder


def _safe_company_rename_record(old_code, new_code, record):
    old_code = _normalise_company_code(old_code)
    new_code = _normalise_company_code(new_code)
    if not old_code or not new_code:
        raise ValueError('Company code is required')
    if old_code == new_code:
        updated = dict(record or {})
        updated['code'] = new_code
        return updated

    old_folder, new_folder = _validate_company_rename_folder(old_code, new_code, record)

    if (
        os.path.exists(old_folder)
        and os.path.normcase(os.path.abspath(old_folder)) != os.path.normcase(os.path.abspath(new_folder))
    ):
        try:
            os.makedirs(os.path.dirname(new_folder), exist_ok=True)
            shutil.move(old_folder, new_folder)
        except OSError as exc:
            logger.warning(
                'Could not rename company folder %s to %s; preserving existing folder paths for company code %s: %s',
                old_folder,
                new_folder,
                new_code,
                exc,
            )
            updated = dict(record or {})
            updated['code'] = new_code
            _ensure_company_folders(updated)
            return updated

    updated = dict(record or {})
    updated['code'] = new_code
    updated['backendFolder'] = os.path.join('companies', new_code, 'backend').replace('\\', '/')
    updated['frontendFolder'] = os.path.join('companies', new_code, 'frontend').replace('\\', '/')
    _ensure_company_folders(updated)
    return updated


def _normalise_company_registry(registry):
    if not isinstance(registry, dict):
        registry = {}

    companies = registry.get('companies') if isinstance(registry.get('companies'), dict) else {}
    user_companies = registry.get('userCompanies') if isinstance(registry.get('userCompanies'), dict) else {}
    user_company_memberships = (
        registry.get('userCompanyMemberships')
        if isinstance(registry.get('userCompanyMemberships'), dict)
        else {}
    )
    raw_super_admins = registry.get('superAdmins')

    default_record = _new_company_record(DEFAULT_COMPANY_CODE, DEFAULT_COMPANY_NAME)
    existing_default = companies.get(DEFAULT_COMPANY_CODE) if isinstance(companies.get(DEFAULT_COMPANY_CODE), dict) else {}
    default_record.update({k: v for k, v in existing_default.items() if v not in (None, '')})
    default_record['code'] = DEFAULT_COMPANY_CODE
    default_record['name'] = default_record.get('name') or DEFAULT_COMPANY_NAME
    legacy_backend = f'{LEGACY_DEFAULT_COMPANY_CODE}/backend'
    legacy_frontend = f'{LEGACY_DEFAULT_COMPANY_CODE}/frontend'
    if str(default_record.get('backendFolder') or '').replace('\\', '/') == legacy_backend:
        default_record['backendFolder'] = f'companies/{LEGACY_DEFAULT_COMPANY_CODE}/backend'
    if str(default_record.get('frontendFolder') or '').replace('\\', '/') == legacy_frontend:
        default_record['frontendFolder'] = f'companies/{LEGACY_DEFAULT_COMPANY_CODE}/frontend'
    default_record['backendFolder'] = default_record.get('backendFolder') or os.path.join('companies', DEFAULT_COMPANY_CODE, 'backend').replace('\\', '/')
    default_record['frontendFolder'] = default_record.get('frontendFolder') or os.path.join('companies', DEFAULT_COMPANY_CODE, 'frontend').replace('\\', '/')
    default_record['brandingSetupRequired'] = bool(default_record.get('brandingSetupRequired', False))

    normalised_companies = {}
    if DEFAULT_COMPANY_CODE in companies or not companies:
        normalised_companies[DEFAULT_COMPANY_CODE] = default_record

    for raw_code, record in companies.items():
        code = _normalise_company_code(raw_code)
        if not code or code == DEFAULT_COMPANY_CODE or not isinstance(record, dict):
            continue
        company = _new_company_record(code, record.get('name') or code)
        company.update({k: v for k, v in record.items() if v not in (None, '')})
        company['code'] = code
        company['backendFolder'] = company.get('backendFolder') or os.path.join('companies', code, 'backend').replace('\\', '/')
        company['frontendFolder'] = company.get('frontendFolder') or os.path.join('companies', code, 'frontend').replace('\\', '/')
        company['brandingSetupRequired'] = bool(company.get('brandingSetupRequired', False))
        normalised_companies[code] = company

    if not normalised_companies:
        normalised_companies[DEFAULT_COMPANY_CODE] = default_record

    normalised_users = {}
    for username, raw_code in user_companies.items():
        username = str(username or '').strip()
        code = _normalise_company_code(raw_code, DEFAULT_COMPANY_CODE)
        if username and code in normalised_companies:
            normalised_users[username] = code

    normalised_memberships = {}
    for username, raw_codes in user_company_memberships.items():
        username = str(username or '').strip()
        if not username:
            continue
        codes = raw_codes if isinstance(raw_codes, list) else [raw_codes]
        valid_codes = []
        for raw_code in codes:
            code = _normalise_company_code(raw_code)
            if code in normalised_companies and code not in valid_codes:
                valid_codes.append(code)
        if valid_codes:
            normalised_memberships[username] = valid_codes

    if isinstance(raw_super_admins, list):
        super_admins = [
            str(username or '').strip()
            for username in raw_super_admins
            if str(username or '').strip()
        ]
    else:
        super_admins = [SUPER_ADMIN_USERNAME]

    if not super_admins:
        super_admins = [SUPER_ADMIN_USERNAME]

    deduped_super_admins = []
    seen_super_admins = set()
    for username in super_admins:
        key = username.lower()
        if key in seen_super_admins:
            continue
        seen_super_admins.add(key)
        deduped_super_admins.append(username)

    default_company = _normalise_company_code(registry.get('defaultCompany'))
    if default_company not in normalised_companies:
        default_company = DEFAULT_COMPANY_CODE if DEFAULT_COMPANY_CODE in normalised_companies else sorted(normalised_companies.keys())[0]

    if normalised_users.get(SUPER_ADMIN_USERNAME) not in normalised_companies:
        normalised_users[SUPER_ADMIN_USERNAME] = default_company

    return {
        'defaultCompany': default_company,
        'companies': normalised_companies,
        'userCompanies': normalised_users,
        'userCompanyMemberships': normalised_memberships,
        'superAdmins': deduped_super_admins,
        'updatedAt': str(registry.get('updatedAt') or '').strip(),
    }


def _load_company_registry():
    global _company_registry_cache
    if _company_registry_cache is not None:
        return _company_registry_cache

    registry = {}
    if os.path.exists(COMPANY_REGISTRY_FILE) and os.path.getsize(COMPANY_REGISTRY_FILE) > 0:
        try:
            with open(COMPANY_REGISTRY_FILE, 'r', encoding='utf-8') as f:
                registry = json.load(f)
        except Exception as e:
            logger.warning("Failed to read Companies.json, rebuilding default registry: %s", e)

    _company_registry_cache = _normalise_company_registry(registry)
    return _company_registry_cache


def _save_company_registry(registry):
    global _company_registry_cache
    registry = _normalise_company_registry(registry)
    registry['updatedAt'] = datetime.now().isoformat(timespec='seconds')
    folder = os.path.dirname(COMPANY_REGISTRY_FILE)
    if folder and not os.path.exists(folder):
        os.makedirs(folder)
    with open(COMPANY_REGISTRY_FILE, 'w', encoding='utf-8') as f:
        json.dump(registry, f, ensure_ascii=False, indent=2)
    _company_registry_cache = registry
    return registry


def _current_company_code():
    registry = None
    if has_request_context():
        code = session.get('company_code')
        if code:
            code = _normalise_company_code(code, DEFAULT_COMPANY_CODE)
            registry = _load_company_registry()
            if code in registry.get('companies', {}):
                return code
            fallback = registry.get('defaultCompany', DEFAULT_COMPANY_CODE)
            session['company_code'] = fallback
            return fallback
    code = _normalise_company_code(_active_company_code, DEFAULT_COMPANY_CODE)
    registry = registry or _load_company_registry()
    if code in registry.get('companies', {}):
        return code
    return registry.get('defaultCompany', DEFAULT_COMPANY_CODE)


def _company_record_for_code(code=None):
    registry = _load_company_registry()
    code = _normalise_company_code(code or _current_company_code(), registry.get('defaultCompany', DEFAULT_COMPANY_CODE))
    return registry['companies'].get(code) or registry['companies'][_fallback_company_code(registry)]


def _all_company_records():
    return _load_company_registry()['companies']


def _user_company_codes(username):
    registry = _load_company_registry()
    username = str(username or '').strip()
    codes = list(registry.get('userCompanyMemberships', {}).get(username) or [])
    legacy_code = registry.get('userCompanies', {}).get(username)
    if not codes and legacy_code:
        codes.append(legacy_code)
    return [
        code for code in codes
        if code in registry.get('companies', {})
    ]


def _user_assigned_company_code(username, preferred_company=None):
    registry = _load_company_registry()
    codes = _user_company_codes(username)
    preferred = _normalise_company_code(
        preferred_company or (session.get('company_code') if has_request_context() else None)
    )
    if preferred in codes:
        return preferred
    if len(codes) == 1:
        return codes[0]
    legacy = registry.get('userCompanies', {}).get(str(username or '').strip())
    if legacy in codes:
        return legacy
    return registry.get('defaultCompany', DEFAULT_COMPANY_CODE)


def _assign_user_to_company(username, company_code):
    registry = _load_company_registry()
    username = str(username or '').strip()
    code = _normalise_company_code(company_code, DEFAULT_COMPANY_CODE)
    if not username:
        return registry
    if code not in registry['companies']:
        raise ValueError('Company not found')
    memberships = registry.setdefault('userCompanyMemberships', {})
    codes = list(memberships.get(username) or [])
    legacy_code = registry.get('userCompanies', {}).get(username)
    if not codes and legacy_code:
        codes.append(legacy_code)
    if code not in codes:
        codes.append(code)
    memberships[username] = codes
    if len(codes) == 1:
        registry['userCompanies'][username] = code
        memberships.pop(username, None)
    else:
        # The legacy map can only represent one company. Removing an
        # ambiguous entry prevents one company from hijacking another.
        registry['userCompanies'].pop(username, None)
    return _save_company_registry(registry)


def _unassign_user_from_company(username, company_code):
    registry = _load_company_registry()
    username = str(username or '').strip()
    code = _normalise_company_code(company_code)
    memberships = registry.setdefault('userCompanyMemberships', {})
    existing_codes = list(memberships.get(username) or [])
    legacy_code = registry.get('userCompanies', {}).get(username)
    if not existing_codes and legacy_code:
        existing_codes.append(legacy_code)
    codes = [item for item in existing_codes if item != code]
    if codes:
        memberships[username] = codes
    else:
        memberships.pop(username, None)
    if len(codes) == 1:
        registry['userCompanies'][username] = codes[0]
        memberships.pop(username, None)
    else:
        registry['userCompanies'].pop(username, None)
    return _save_company_registry(registry)


def _update_username_history_references(old_username, new_username, company_code):
    """Rename persisted history in the company the user belongs to."""
    code = _normalise_company_code(company_code, DEFAULT_COMPANY_CODE)
    test_manager = app.config.get('TEST_DATA_MANAGER')
    if app.config.get('TESTING') and test_manager is not None and code not in _company_data_managers:
        manager = test_manager
    else:
        manager = _get_company_data_manager(code)
    current_manager = _current_data_manager_object()
    acquired = False
    try:
        if manager is not current_manager and hasattr(manager, 'acquire_write_request'):
            manager.acquire_write_request()
            acquired = True
        if manager is not current_manager:
            manager.load_all_data()
        return manager.update_username_references(old_username, new_username)
    finally:
        if acquired:
            manager.release_write_request()


def _username_history_reference_counts(manager, username):
    """Count company-scoped history that a recreated username would inherit."""
    username = str(username or '').strip()
    counts = {
        'systemLogs': 0,
        'eventLogs': 0,
        'maintenanceLogs': 0,
        'quotes': 0,
    }
    if not username or manager is None:
        return counts

    counts['systemLogs'] = sum(
        1 for log in getattr(manager, 'logs', []) or []
        if getattr(log, 'user', '') == username
    )
    for event in getattr(manager, 'events', {}).values():
        counts['eventLogs'] += sum(
            1 for record in manager.normalize_event_logs(
                getattr(event, 'event_logs', []) or []
            )
            if record.get('user') == username
        )
    for item in getattr(manager, 'inventory', {}).values():
        counts['maintenanceLogs'] += sum(
            1 for record in getattr(item, 'maintenance_logs', []) or []
            if (
                normalize_maintenance_log(record).get('user') == username
                or (normalize_maintenance_log(record).get('source') or {}).get('recordedBy') == username
            )
        )
    for container in getattr(manager, 'containers', {}).values():
        counts['maintenanceLogs'] += sum(
            1 for record in getattr(container, 'maintenance_logs', []) or []
            if (
                normalize_maintenance_log(record).get('user') == username
                or (normalize_maintenance_log(record).get('source') or {}).get('recordedBy') == username
            )
        )

    finance_data = None
    if hasattr(manager, 'load_company_document'):
        finance_data = manager.load_company_document('finance', None)
    else:
        finance_path = manager._data_path('Finance.json')
        if os.path.isfile(finance_path):
            try:
                with open(finance_path, 'r', encoding='utf-8') as finance_file:
                    finance_data = json.load(finance_file)
            except (OSError, ValueError, TypeError):
                finance_data = None

    owner_keys = {'createdBy', 'updatedBy', 'salesperson', 'salespersonUsername'}

    def contains_username(value):
        if isinstance(value, list):
            return any(contains_username(item) for item in value)
        if isinstance(value, dict):
            return any(
                (key in owner_keys and item == username)
                or (isinstance(item, (dict, list)) and contains_username(item))
                for key, item in value.items()
            )
        return False

    if isinstance(finance_data, dict):
        counts['quotes'] = sum(
            1 for document in finance_data.get('documents', []) or []
            if isinstance(document, dict)
            and str(document.get('type') or '').lower() in {'quotation', 'quote'}
            and contains_username(document)
        )
    counts['total'] = sum(counts.values())
    return counts


def _user_is_assigned_to_current_company(username):
    current_company = _normalise_company_code(_current_company_code(), DEFAULT_COMPANY_CODE)
    user_company = _normalise_company_code(_user_assigned_company_code(username), DEFAULT_COMPANY_CODE)
    return user_company == current_company


def _current_admin_can_manage_user(username):
    if _current_user_is_super_admin():
        return True
    return _user_is_assigned_to_current_company(username)


def _active_company_admin_usernames(company_code):
    """Return active company admins, excluding the global Showbase owner."""
    code = _normalise_company_code(company_code, DEFAULT_COMPANY_CODE)
    registry = _load_company_registry()
    usernames = []
    for username, user in data_manager.users.items():
        assigned_code = _normalise_company_code(
            registry.get('userCompanies', {}).get(username)
            or registry.get('defaultCompany'),
            DEFAULT_COMPANY_CODE,
        )
        if assigned_code != code or _is_owner_username(username):
            continue
        if (
            getattr(user, 'is_active', True)
            and _effective_user_role(user) == 'admin'
        ):
            usernames.append(username)
    return usernames


def _last_company_admin_error(company_code, self_update=False):
    company_name = _company_payload(company_code).get('name') or company_code
    if self_update:
        return (
            f'{company_name} must have at least one active admin. '
            'Promote or activate another admin before changing your own admin account.'
        )
    return (
        f'{company_name} must have at least one active admin. '
        'Promote or activate another admin before changing this account.'
    )


def _role_label(role):
    return ROLE_LABELS.get(normalize_user_role(role), 'User')


def _is_super_admin_username(username):
    username = str(username or '').strip()
    if not username:
        return False

    registry = _load_company_registry()
    super_admins = registry.get('superAdmins', [SUPER_ADMIN_USERNAME])
    return username.lower() in {
        str(super_admin or '').strip().lower()
        for super_admin in super_admins
        if str(super_admin or '').strip()
    }


def _is_owner_username(username):
    return _is_super_admin_username(username)


def _current_user_is_super_admin():
    if not has_request_context():
        return False
    if session.get('self_user_changes_pending'):
        return bool(session.get('is_super_admin'))
    return _is_super_admin_username(session.get('user'))


def _current_user_is_owner():
    return _current_user_is_super_admin()


def _effective_user_role(user_or_username=None):
    if hasattr(user_or_username, 'username'):
        user = user_or_username
        username = user.username
    else:
        username = str(user_or_username or '').strip()
        user = data_manager.users.get(username) if username and data_manager else None

    if _is_owner_username(username):
        return 'owner'

    if user:
        role = normalize_user_role(
            getattr(user, 'role', None),
            getattr(user, 'is_admin', False),
        )
        return 'admin' if role == 'owner' else role

    return 'user'


def _user_has_sales_access(user_or_username=None):
    if hasattr(user_or_username, 'username'):
        user = user_or_username
        username = user.username
    else:
        username = str(user_or_username or '').strip()
        user = data_manager.users.get(username) if username and data_manager else None

    if _is_owner_username(username):
        return True

    return bool(user and getattr(user, 'has_sales_access', False))


def _current_user_can_manage_roles():
    if not has_request_context():
        return False
    if session.get('self_user_changes_pending'):
        return normalize_user_role(session.get('role'), session.get('is_admin')) in {'owner', 'admin'}
    return _effective_user_role(session.get('user')) in {'owner', 'admin'}


def _current_user_can_view_logs():
    """System and event history is restricted to company admins and owners."""
    return _current_user_can_manage_roles()


def _current_user_has_sales_access():
    if not has_request_context():
        return False
    if session.get('self_user_changes_pending'):
        return bool(session.get('is_super_admin') or session.get('has_sales_access'))
    return _user_has_sales_access(session.get('user'))


def _sync_user_role_flags(user):
    role = normalize_user_role(
        getattr(user, 'role', None),
        getattr(user, 'is_admin', False),
    )
    if role == 'owner' and not _is_owner_username(getattr(user, 'username', '')):
        role = 'admin'
    user.role = role
    user.is_admin = user_role_is_adminish(role)
    return user


def _requested_role_from_payload(data, fallback=None):
    if 'role' in data:
        return normalize_user_role(data.get('role'), False)

    owner_value = data.get('isOwner') if 'isOwner' in data else data.get('isSuperAdmin')
    if owner_value is not None:
        if bool(owner_value):
            return 'owner'
        if 'isAdmin' in data:
            return 'admin' if bool(data.get('isAdmin')) else 'user'
        return normalize_user_role(fallback or 'admin', True)

    if 'isAdmin' in data:
        return 'admin' if bool(data.get('isAdmin')) else 'user'

    return None


def _user_payload(user):
    role = _effective_user_role(user)
    is_platform_admin = role == 'owner'
    public_role = 'admin' if is_platform_admin else role
    company = _company_payload(_user_assigned_company_code(user.username))
    has_sales_access = _user_has_sales_access(user)
    return {
        'username': user.username,
        'name': getattr(user, 'name', '') or '',
        'phone': getattr(user, 'phone', '') or '',
        'role': public_role,
        'roleLabel': _role_label(public_role),
        'isAdmin': user_role_is_adminish(role),
        'isManager': role == 'manager',
        'isSuperAdmin': is_platform_admin,
        'canManageRoles': role in {'owner', 'admin'},
        'hasSalesAccess': has_sales_access,
        'isSales': has_sales_access,
        'isActive': getattr(user, 'is_active', True),
        'lastOnline': getattr(user, 'last_online', '-') or '-',
        'companyCode': company.get('code'),
        'companyName': company.get('name'),
        'company': company,
        'assignedCompanyCode': company.get('code'),
    }


def _user_display_name(username):
    """Resolve a durable username to the account's current display name."""
    username = str(username or '').strip()
    user = data_manager.users.get(username) if username and data_manager else None
    return str(getattr(user, 'name', '') or username).strip()


def _set_user_super_admin(username, enabled):
    registry = _load_company_registry()
    username = str(username or '').strip()
    if not username:
        return registry

    existing = [
        str(super_admin or '').strip()
        for super_admin in registry.get('superAdmins', [])
        if str(super_admin or '').strip()
    ]
    existing_lower = {super_admin.lower() for super_admin in existing}

    if enabled:
        if username.lower() not in existing_lower:
            existing.append(username)
    else:
        existing = [super_admin for super_admin in existing if super_admin.lower() != username.lower()]
        if not existing:
            raise ValueError('This protected administrator account is required')

    registry['superAdmins'] = existing
    return _save_company_registry(registry)


def _rename_super_admin_reference(old_username, new_username):
    registry = _load_company_registry()
    old_key = str(old_username or '').strip().lower()
    new_username = str(new_username or '').strip()
    if not old_key or not new_username:
        return registry

    changed = False
    updated = []
    for username in registry.get('superAdmins', []):
        if str(username or '').strip().lower() == old_key:
            updated.append(new_username)
            changed = True
        else:
            updated.append(username)

    if changed:
        registry['superAdmins'] = updated
        return _save_company_registry(registry)

    return registry


def _current_user_effective_is_admin():
    if not has_request_context():
        return False
    if session.get('self_user_changes_pending'):
        return bool(session.get('is_admin'))
    user = _current_user_obj()
    return bool(user and user_role_is_adminish(_effective_user_role(user)))


def _current_user_effective_is_active():
    if not has_request_context():
        return False
    if session.get('self_user_changes_pending'):
        return bool(session.get('is_active', True))
    user = _current_user_obj()
    return bool(user and getattr(user, 'is_active', True))


def _normalise_event_assigned_users(values, require_known=False):
    if values is None:
        return []
    if isinstance(values, str):
        raw = values.strip()
        if not raw:
            values = []
        else:
            try:
                parsed = json.loads(raw)
                values = parsed if isinstance(parsed, list) else [raw]
            except (TypeError, ValueError, json.JSONDecodeError):
                values = [part.strip() for part in raw.split(',')]
    if not isinstance(values, (list, tuple, set)):
        values = [values]

    known_by_lower = {
        str(username or '').strip().lower(): str(username or '').strip()
        for username in (data_manager.users.keys() if data_manager else [])
        if str(username or '').strip()
    }
    assigned = []
    seen = set()
    for value in values:
        if isinstance(value, dict):
            raw_username = str(value.get('username') or '').strip()
        else:
            raw_username = str(value or '').strip()
        if not raw_username:
            continue
        canonical = known_by_lower.get(raw_username.lower(), raw_username)
        if require_known and canonical.lower() not in known_by_lower:
            raise ValueError(f'Assigned user not found: {raw_username}')
        if require_known and not _user_is_assigned_to_current_company(canonical):
            raise ValueError(f'You can only assign users from your company: {canonical}')
        key = canonical.lower()
        if key in seen:
            continue
        seen.add(key)
        assigned.append(canonical)
    return assigned


def _event_assigned_usernames(event):
    return _normalise_event_assigned_users(getattr(event, 'assigned_users', []) or [])


def _event_assignee_payloads(event):
    rows = []
    for username in _event_assigned_usernames(event):
        user = data_manager.users.get(username) if data_manager else None
        internal_role = _effective_user_role(user or username)
        public_role = 'admin' if internal_role == 'owner' else internal_role
        rows.append({
            'username': username,
            'name': getattr(user, 'name', '') if user else '',
            'role': public_role,
            'roleLabel': _role_label(public_role),
            'isActive': bool(getattr(user, 'is_active', True)) if user else False,
        })
    return rows


def _current_user_can_access_event(event):
    if _current_user_effective_is_admin():
        return True
    username = str(session.get('user') or '').strip().lower()
    if not username:
        return False
    return username in {
        str(assigned or '').strip().lower()
        for assigned in _event_assigned_usernames(event)
        if str(assigned or '').strip()
    }


def _event_access_denied_response():
    return jsonify({'error': 'You are not assigned to this event'}), 403


def require_event_access(f):
    """Require admin/manager access or assignment to the route's event_id."""
    @wraps(f)
    def decorated_function(*args, **kwargs):
        event_id = kwargs.get('event_id')
        if event_id is None and args:
            event_id = args[0]
        try:
            event_id = int(event_id)
        except (TypeError, ValueError):
            return jsonify({'error': 'Event not found'}), 404

        event = data_manager.events.get(event_id) if data_manager else None
        if not event:
            return jsonify({'error': 'Event not found'}), 404
        if not _current_user_can_access_event(event):
            return _event_access_denied_response()
        return f(*args, **kwargs)

    return decorated_function


def _ensure_company_folders(record):
    backend_folder = _company_record_backend_folder(record)
    frontend_folder = _company_record_frontend_folder(record)
    if backend_folder and not os.path.exists(backend_folder):
        os.makedirs(backend_folder)
    if frontend_folder and not os.path.exists(frontend_folder):
        os.makedirs(frontend_folder)


def _ensure_super_admin_users(manager):
    if not manager:
        return
    changed = False
    registry = _load_company_registry()
    for username in registry.get('superAdmins', [SUPER_ADMIN_USERNAME]):
        user = manager.users.get(username)
        if not user:
            continue
        if not getattr(user, 'is_admin', False) or normalize_user_role(getattr(user, 'role', None), True) != 'owner':
            user.role = 'owner'
            user.is_admin = True
            changed = True
    if changed:
        manager.save_users()


def _reload_users_for_all_company_managers():
    for company_code, manager in list(_company_data_managers.items()):
        if company_code == SYSTEM_LOG_COMPANY_CODE:
            continue
        try:
            manager.load_users()
            _ensure_super_admin_users(manager)
        except Exception as e:
            logger.warning("Failed to reload users for company manager %s: %s", getattr(manager, 'data_folder', ''), e)


def _get_company_data_manager(company_code=None):
    code = _normalise_company_code(company_code, DEFAULT_COMPANY_CODE)
    registry = _load_company_registry()
    is_system_log_scope = code == SYSTEM_LOG_COMPANY_CODE
    if not is_system_log_scope and code not in registry['companies']:
        code = registry.get('defaultCompany', DEFAULT_COMPANY_CODE)

    with _company_manager_lock:
        cached = _company_data_managers.get(code)
        if cached is not None:
            return cached

        record = (
            {
                'code': SYSTEM_LOG_COMPANY_CODE,
                'name': SYSTEM_LOG_COMPANY_NAME,
                'backendFolder': os.path.join(APP_CONFIG_FOLDER, 'system'),
            }
            if is_system_log_scope
            else registry['companies'][code]
        )
        backend_folder = _company_record_backend_folder(record)
        _assert_safe_test_company_folder(backend_folder)
        if is_system_log_scope:
            os.makedirs(backend_folder, exist_ok=True)
        else:
            _ensure_company_folders(record)
        database_url = _database_url_for_runtime()

        if database_url:
            from postgres_data_manager import PostgresDataManager

            logger.info("Using PostgreSQL data manager for company %s", code)
            manager = PostgresDataManager(
                database_url,
                company_code=code,
                company_name=record.get('name') or code,
                data_folder=backend_folder,
                users_file=GLOBAL_USERS_FILE,
            )
        else:
            manager = DataManager(
                backend_folder,
                users_file=GLOBAL_USERS_FILE,
            )
            manager.company_code = code
        manager.setup_data_folder()
        manager.check_and_initialize_files()
        manager.load_all_data()
        migrated_locations = manager.migrate_legacy_event_locations()
        if migrated_locations:
            logger.info(
                "Migrated %s legacy event location(s) for company %s",
                migrated_locations,
                code,
            )
        if not is_system_log_scope:
            _ensure_super_admin_users(manager)
        _company_data_managers[code] = manager
        return manager


def _activate_company(company_code=None):
    code = _normalise_company_code(company_code, DEFAULT_COMPANY_CODE)
    manager = _get_company_data_manager(code)
    try:
        manager.load_all_data()
        _ensure_super_admin_users(manager)
    except Exception as e:
        logger.warning("Failed to reload active company %s: %s", code, e)
    _set_default_data_manager(manager, code)
    mark_data_snapshot_current(manager)
    return manager


def _activate_company_for_session():
    test_manager = app.config.get('TEST_DATA_MANAGER')
    if app.config.get('TESTING') and test_manager is not None:
        return test_manager

    if not has_request_context() or 'user' not in session:
        return get_default_data_manager()

    username = session.get('user')
    code = session.get('company_code') if _current_user_is_super_admin() else None
    if not code:
        code = _user_assigned_company_code(username)
        session['company_code'] = code
    return _get_company_data_manager(code)


def _user_management_company_for_request(default_company_code):
    """Resolve login and owner user-management requests to the affected company."""
    if not has_request_context():
        return default_company_code

    endpoint = str(request.endpoint or '')
    if endpoint == 'login' and request.method == 'POST':
        payload = request.get_json(silent=True) or {}
        username = str(payload.get('username') or '').strip()
        requested = _normalise_company_code(payload.get('companyCode'))
        registry = _load_company_registry()
        if requested in registry.get('companies', {}) and requested in _user_company_codes(username):
            return requested
        memberships = _user_company_codes(username)
        if len(memberships) == 1:
            return memberships[0]
        assigned = _normalise_company_code(
            registry.get('userCompanies', {}).get(username)
        )
        if assigned in registry.get('companies', {}):
            return assigned
        # An unmapped username must never inherit the registry's default
        # company. Keep unknown login attempts in the owner-only system scope.
        return SYSTEM_LOG_COMPANY_CODE

    if not _current_user_is_super_admin():
        return default_company_code

    if endpoint == 'create_user' and request.method == 'POST':
        payload = request.get_json(silent=True) or {}
        requested = _normalise_company_code(payload.get('companyCode'))
        if requested in _all_company_records():
            return requested

    if endpoint in {'update_user', 'reset_user_password', 'delete_user'}:
        username = unquote_plus(str((request.view_args or {}).get('username') or ''))
        payload = request.get_json(silent=True) or {}
        requested = _normalise_company_code(
            payload.get('sourceCompanyCode')
            or request.args.get('companyCode')
        )
        if requested in _user_company_codes(username):
            return requested
        registry = _load_company_registry()
        assigned = _normalise_company_code(
            registry.get('userCompanies', {}).get(username)
        )
        if assigned in registry.get('companies', {}):
            return assigned

    return default_company_code


def _bind_request_data_manager(manager):
    tokens = getattr(g, 'data_manager_tokens', None)
    if tokens is None:
        tokens = []
        g.data_manager_tokens = tokens
    tokens.append(_request_data_manager.set(manager))
    return manager


def _company_payload(code=None):
    registry = _load_company_registry()
    code = _normalise_company_code(code or _current_company_code(), registry.get('defaultCompany', DEFAULT_COMPANY_CODE))
    record = registry['companies'].get(code) or registry['companies'][_fallback_company_code(registry)]
    return {
        'code': record.get('code') or code,
        'name': record.get('name') or code,
        'brandingSetupRequired': bool(record.get('brandingSetupRequired', False)),
        'backendFolder': record.get('backendFolder') or '',
        'frontendFolder': record.get('frontendFolder') or '',
        'logoUrl': f"/api/company-branding/{quote(str(record.get('code') or code))}/logo",
    }


def _same_file_hash(left_path, right_path):
    try:
        if not left_path or not right_path:
            return False
        if os.path.abspath(left_path) == os.path.abspath(right_path):
            return False
        if not os.path.isfile(left_path) or not os.path.isfile(right_path):
            return False
        with open(left_path, 'rb') as left_file, open(right_path, 'rb') as right_file:
            return hashlib.sha256(left_file.read()).digest() == hashlib.sha256(right_file.read()).digest()
    except OSError:
        return False


def _is_inherited_default_company_logo(code, logo_path):
    code = _normalise_company_code(code)
    if not code or code in {DEFAULT_COMPANY_CODE, LEGACY_DEFAULT_COMPANY_CODE}:
        return False
    default_logo_paths = [
        os.path.join(BASE_DIR, 'companies', DEFAULT_COMPANY_CODE, 'frontend', 'logo.png'),
        os.path.join(BASE_DIR, 'companies', LEGACY_DEFAULT_COMPANY_CODE, 'frontend', 'logo.png'),
    ]
    return any(_same_file_hash(logo_path, default_logo_path) for default_logo_path in default_logo_paths)


@app.route('/api/company-branding/<company_code>/logo', methods=['GET'])
def company_branding_logo(company_code):
    registry = _load_company_registry()
    code = _normalise_company_code(company_code)
    if code not in registry.get('companies', {}):
        return jsonify({'error': 'Company not found'}), 404
    logo_path = os.path.join(_company_frontend_folder(code), 'logo.png')
    if not os.path.isfile(logo_path) or _is_inherited_default_company_logo(code, logo_path):
        settings = _load_pdf_settings(code)
        logo_path = _pdf_logo_path(settings, code) if settings.get('logoFilename') else ''
    if not logo_path or not os.path.isfile(logo_path):
        return jsonify({'error': 'Company logo not found'}), 404
    return send_file(
        logo_path,
        mimetype=mimetypes.guess_type(logo_path)[0] or 'image/png',
        max_age=3600,
    )


def _mark_company_branding_setup_complete(company_code=None):
    registry = _load_company_registry()
    code = _normalise_company_code(company_code or _current_company_code(), DEFAULT_COMPANY_CODE)
    record = registry['companies'].get(code)
    if not record:
        return registry
    settings = _load_pdf_settings(code)
    logo_path = _pdf_logo_path(settings, code) if settings.get('logoFilename') else ''
    if not str(settings.get('companyName') or '').strip() or not os.path.isfile(logo_path):
        return registry
    if record.get('brandingSetupRequired'):
        record['brandingSetupRequired'] = False
        registry['companies'][code] = record
        registry = _save_company_registry(registry)
    return registry


def _truthy_env(name, default=False):
    value = os.environ.get(name)
    if value is None:
        return default
    return str(value).strip().lower() in ('1', 'true', 'yes', 'y', 'on')


def _local_lan_ip():
    """Best-effort local IP for the development HTTPS certificate SAN list."""
    import socket

    sock = socket.socket(socket.AF_INET, socket.SOCK_DGRAM)
    try:
        # No packets are actually sent; this only lets the OS pick the LAN iface.
        sock.connect(('8.8.8.8', 80))
        return sock.getsockname()[0]
    except OSError:
        return None
    finally:
        sock.close()


def _certificate_hosts():
    hosts = {'localhost', '127.0.0.1', '::1'}

    lan_ip = _local_lan_ip()
    if lan_ip:
        hosts.add(lan_ip)

    configured_hosts = os.environ.get('SSL_HOSTS', '')
    for host in configured_hosts.split(','):
        host = host.strip()
        if host:
            hosts.add(host)

    return sorted(hosts)


def _generate_self_signed_certificate(cert_file, key_file):
    """Create a persistent self-signed certificate for local/LAN HTTPS."""
    import ipaddress
    from cryptography import x509
    from cryptography.hazmat.primitives import hashes, serialization
    from cryptography.hazmat.primitives.asymmetric import rsa
    from cryptography.x509.oid import NameOID

    os.makedirs(os.path.dirname(cert_file), exist_ok=True)
    hosts = _certificate_hosts()

    private_key = rsa.generate_private_key(public_exponent=65537, key_size=2048)
    subject = issuer = x509.Name([
        x509.NameAttribute(NameOID.COUNTRY_NAME, 'SG'),
        x509.NameAttribute(NameOID.ORGANIZATION_NAME, APP_NAME),
        x509.NameAttribute(NameOID.COMMON_NAME, hosts[0] if hosts else 'localhost'),
    ])

    san_entries = []
    for host in hosts:
        try:
            san_entries.append(x509.IPAddress(ipaddress.ip_address(host)))
        except ValueError:
            san_entries.append(x509.DNSName(host))

    certificate = (
        x509.CertificateBuilder()
        .subject_name(subject)
        .issuer_name(issuer)
        .public_key(private_key.public_key())
        .serial_number(x509.random_serial_number())
        .not_valid_before(datetime.utcnow() - timedelta(minutes=5))
        .not_valid_after(datetime.utcnow() + timedelta(days=825))
        .add_extension(x509.SubjectAlternativeName(san_entries), critical=False)
        .sign(private_key, hashes.SHA256())
    )

    with open(key_file, 'wb') as f:
        f.write(private_key.private_bytes(
            encoding=serialization.Encoding.PEM,
            format=serialization.PrivateFormat.TraditionalOpenSSL,
            encryption_algorithm=serialization.NoEncryption(),
        ))

    with open(cert_file, 'wb') as f:
        f.write(certificate.public_bytes(serialization.Encoding.PEM))

    logger.info('Generated HTTPS self-signed certificate at %s', cert_file)


def get_ssl_context():
    """
    Return the Flask ssl_context.

    HTTPS is enabled by default and uses the standard HTTPS port (443). To run
    plain HTTP on the standard HTTP port (80), start with ENABLE_HTTPS=0.

    Optional production/LAN certificate paths:
      SSL_CERT_FILE=/path/fullchain.pem
      SSL_KEY_FILE=/path/privkey.pem
    """
    if not _truthy_env('ENABLE_HTTPS', True):
        return None

    cert_file = os.environ.get('SSL_CERT_FILE') or os.environ.get('SSL_CERT')
    key_file = os.environ.get('SSL_KEY_FILE') or os.environ.get('SSL_KEY')

    if cert_file and key_file:
        if not os.path.exists(cert_file):
            raise FileNotFoundError(f'SSL certificate file not found: {cert_file}')
        if not os.path.exists(key_file):
            raise FileNotFoundError(f'SSL key file not found: {key_file}')
        return (cert_file, key_file)

    cert_dir = os.environ.get('CERT_DIR') or os.path.join(os.path.dirname(os.path.abspath(__file__)), 'certs')
    cert_file = os.path.join(cert_dir, 'showbase_selfsigned.crt')
    key_file = os.path.join(cert_dir, 'showbase_selfsigned.key')

    if not os.path.exists(cert_file) or not os.path.exists(key_file):
        _generate_self_signed_certificate(cert_file, key_file)

    return (cert_file, key_file)


def run_https_app(flask_app):
    host = os.environ.get('HOST', '0.0.0.0')
    ssl_context = get_ssl_context()
    scheme = 'https' if ssl_context else 'http'
    default_port = '443' if ssl_context else '80'
    port = int(os.environ.get('PORT', default_port))

    flask_app.config['PREFERRED_URL_SCHEME'] = scheme
    flask_app.config['SESSION_COOKIE_SECURE'] = bool(ssl_context)
    flask_app.config.setdefault('SESSION_COOKIE_SAMESITE', 'Lax')
    logger.info('Starting %s at %s://%s:%s', APP_NAME, scheme, host, port)

    backend = os.environ.get('SERVER_BACKEND', 'auto').strip().lower()
    if backend == 'auto':
        backend = 'werkzeug' if ssl_context else 'waitress'

    if backend == 'waitress':
        if ssl_context:
            raise RuntimeError(
                'Waitress does not terminate TLS. Set ENABLE_HTTPS=0 and place '
                'the app behind an HTTPS reverse proxy, or set '
                'SERVER_BACKEND=werkzeug for local direct-HTTPS development.'
            )
        try:
            from waitress import serve
        except ImportError as exc:
            raise RuntimeError(
                'Waitress is required for the production HTTP server. '
                'Install the project requirements first.'
            ) from exc

        logger.info('Serving with Waitress using %s worker threads', os.environ.get('WAITRESS_THREADS', '32'))
        serve(
            flask_app,
            host=host,
            port=port,
            # Each open server-sent-event stream occupies one Waitress thread.
            # Keep enough headroom for normal requests while browsers stay live.
            threads=max(16, int(os.environ.get('WAITRESS_THREADS', '32'))),
            channel_timeout=max(
                30,
                int(os.environ.get('WAITRESS_CHANNEL_TIMEOUT', '120')),
            ),
            url_scheme=scheme,
        )
        return

    if backend != 'werkzeug':
        raise RuntimeError(
            f'Unsupported SERVER_BACKEND {backend!r}; use auto, waitress, or werkzeug'
        )

    logger.warning(
        'Using the Werkzeug development server. Use Waitress behind an HTTPS '
        'reverse proxy for production.'
    )
    flask_app.run(
        debug=os.environ.get('FLASK_DEBUG') == '1',
        host=host,
        port=port,
        ssl_context=ssl_context,
    )


def _realtime_state_path():
    if not data_manager or not getattr(data_manager, 'data_folder', ''):
        return None
    return os.path.join(data_manager.data_folder, 'RealtimeState.json')


def _write_realtime_state(payload):
    manager = _current_data_manager_object()
    if manager is not None and hasattr(manager, 'save_company_document'):
        try:
            manager.save_company_document('realtime_state', payload)
        except Exception as e:
            logger.warning("Failed to write realtime state: %s", e)
        return
    path = _realtime_state_path()
    if not path:
        return

    try:
        folder = os.path.dirname(path)
        if folder and not os.path.exists(folder):
            os.makedirs(folder)
        tmp_path = f"{path}.{secrets.token_hex(6)}.tmp"
        with open(tmp_path, 'w', encoding='utf-8') as f:
            json.dump(payload, f, ensure_ascii=False)
        os.replace(tmp_path, path)
    except Exception as e:
        logger.warning("Failed to write realtime state: %s", e)


def _read_realtime_state():
    manager = _current_data_manager_object()
    if manager is not None and hasattr(manager, 'load_company_document'):
        try:
            return manager.load_company_document('realtime_state', None)
        except Exception as e:
            logger.debug("Failed to read realtime state: %s", e)
            return None
    path = _realtime_state_path()
    if not path or not os.path.exists(path):
        return None

    try:
        with open(path, 'r', encoding='utf-8') as f:
            return json.load(f)
    except Exception as e:
        logger.debug("Failed to read realtime state: %s", e)
        return None


def _client_id_from_request():
    if not has_request_context():
        return ''
    return (
        request.headers.get('X-Client-Id')
        or request.args.get('clientId')
        or ''
    )[:120]


def _current_actor_for_realtime():
    if not has_request_context():
        return 'system'
    return session.get('user', 'system')


def _company_code_for_realtime():
    manager = _current_data_manager_object()
    manager_code = _normalise_company_code(
        getattr(manager, 'company_code', None),
        ''
    ) if manager is not None else ''
    if manager_code:
        return manager_code
    if has_request_context():
        return _normalise_company_code(_current_company_code(), DEFAULT_COMPANY_CODE)
    return _normalise_company_code(_active_company_code, DEFAULT_COMPANY_CODE)


def _with_realtime_scope(details=None):
    scoped = dict(details or {})
    scoped.setdefault('companyCode', _company_code_for_realtime())
    return scoped


def _publish_realtime_update_now(topic='data-changed', details=None, origin_client_id=None):
    """Push a compact change notice to every connected browser."""
    global _realtime_sequence

    with _realtime_subscribers_lock:
        _realtime_sequence += 1
        event_id = f"{int(time.time() * 1000)}-{_realtime_sequence}-{secrets.token_hex(4)}"

    payload = {
        'id': event_id,
        'topic': topic,
        'details': _with_realtime_scope(details),
        'actor': _current_actor_for_realtime(),
        'originClientId': origin_client_id or _client_id_from_request(),
        'timestamp': datetime.now().isoformat(timespec='seconds')
    }

    # The file stamp lets separate WSGI workers observe the same change without
    # adding Redis or another service to this CSV-backed app.
    _write_realtime_state(payload)

    with _realtime_subscribers_lock:
        if not _realtime_subscribers:
            return

        dead_subscribers = []
        for subscriber_id, subscriber_queue in _realtime_subscribers.items():
            try:
                subscriber_queue.put_nowait(payload)
            except queue.Full:
                dead_subscribers.append(subscriber_id)

        for subscriber_id in dead_subscribers:
            _realtime_subscribers.pop(subscriber_id, None)


def mark_realtime_change(topic='data-changed', details=None):
    """Mark this request as having changed shared data.

    The actual publish happens after the response succeeds, so failed writes do
    not trigger other browsers to refresh. Background jobs publish immediately.
    """
    if has_request_context():
        changes = getattr(g, 'realtime_changes', [])
        changes.append({'topic': topic, 'details': _with_realtime_scope(details)})
        g.realtime_changes = changes
        return

    _publish_realtime_update_now(topic, _with_realtime_scope(details), '')


def _event_asset_realtime_change_for_request():
    """Describe prepare/return mutations so browsers can refresh one event only."""
    action_by_endpoint = {
        'prepare_event_asset': 'prepare',
        'unprepare_event_asset': 'unprepare',
        'assign_specific_asset_to_model': 'prepare',
        'unassign_specific_asset_from_model': 'unprepare',
        'return_event_asset': 'return',
        'unreturn_event_asset': 'unreturn',
        'return_department_assets': 'return-department',
        'close_return_event': 'close-return',
    }
    action = action_by_endpoint.get(request.endpoint)
    if request.endpoint == 'prepare_event_model_quantity':
        requested_action = str(
            (request.get_json(silent=True) or {}).get('action') or 'prepare'
        ).strip().lower()
        action = 'unprepare' if requested_action in {'unprepare', 'unprepared'} else 'prepare'
    event_id = (request.view_args or {}).get('event_id')
    if not action or event_id is None:
        return None

    request_data = request.get_json(silent=True) or {}
    details = {
        'eventId': int(event_id),
        'action': action,
    }
    if request_data.get('assetId'):
        details['assetId'] = str(request_data['assetId'])
    if request_data.get('department'):
        details['department'] = str(request_data['department'])
    return details


_MUTATION_AUDIT_EXCLUDED_ENDPOINTS = {
    '_finance_get_update_delete',
    'asset_check_group',
    'preview_asset_serial_ids',
    'quotation_item',
    'update_all_event_states',
    'worker_company_status',
    'worker_lookup',
}

_MUTATION_AUDIT_LABELS = {
    'complete_company_branding_setup': 'Completed company branding setup',
    'create_transport_location': 'Created a saved transport location',
    'create_workforce_role': 'Created a workforce role',
    'delete_transport_location': 'Deleted a saved transport location',
    'delete_transport_profile': 'Deleted a saved transport profile',
    'update_worker_profile': 'Updated worker profile',
    'worker_access': 'Accessed the worker portal',
    'worker_delete_submission': 'Deleted a worker submission',
    'worker_setup_credentials': 'Set up worker portal credentials',
    'worker_submission_details': 'Updated worker submission details',
}


def _fallback_mutation_audit_action():
    """Return a readable audit entry for successful mutations with no explicit log."""
    endpoint = str(request.endpoint or '').strip()
    if (
        request.method not in {'POST', 'PUT', 'PATCH', 'DELETE'}
        or endpoint in _MUTATION_AUDIT_EXCLUDED_ENDPOINTS
        or getattr(g, 'action_logged', False)
        or 'user' not in session
        or _current_user_is_owner()
    ):
        return ''

    action = _MUTATION_AUDIT_LABELS.get(endpoint)
    if not action:
        words = endpoint.replace('_', ' ').strip()
        verb = {
            'POST': 'Completed',
            'PUT': 'Updated',
            'PATCH': 'Updated',
            'DELETE': 'Deleted',
        }.get(request.method, 'Completed')
        action = words.capitalize() if words.startswith(verb.lower()) else f'{verb} {words}'

    view_args = request.view_args or {}
    if view_args.get('event_id') is not None and not re.search(r'\bevent\s+\d+\b', action, re.IGNORECASE):
        action += f" for event {view_args['event_id']}"
    elif view_args.get('asset_id') and 'asset' not in action.lower():
        action += f" for asset {unquote_plus(str(view_args['asset_id']))}"
    return action


@app.after_request
def publish_marked_realtime_changes(response):
    if response.status_code < 400:
        fallback_action = _fallback_mutation_audit_action()
        if fallback_action:
            log_action(fallback_action)
        event_asset_change = _event_asset_realtime_change_for_request()
        if event_asset_change:
            changes = getattr(g, 'realtime_changes', [])
            changes.append({'topic': 'event-assets', 'details': event_asset_change})
            g.realtime_changes = changes

    changes = getattr(g, 'realtime_changes', None)
    if changes and response.status_code < 400:
        topics = sorted({change.get('topic', 'data-changed') for change in changes})
        _publish_realtime_update_now(
            'data-changed',
            {
                'topics': topics,
                'changes': changes[-10:],
                'path': request.path,
                'method': request.method
            },
            _client_id_from_request()
        )

    if (
        request.method == 'GET'
        and response.status_code == 200
        and response.is_json
        and not response.direct_passthrough
    ):
        response.add_etag(overwrite=True, weak=True)
        response.make_conditional(request)
    return response

def _with_action_lock(lock):
    """Build a route decorator that serializes operations using the given lock."""
    def decorator(function):
        @wraps(function)
        def locked_function(*args, **kwargs):
            with lock:
                return function(*args, **kwargs)

        return locked_function

    return decorator


with_transfer_action_lock = _with_action_lock(_transfer_action_lock)
with_prepare_action_lock = _with_action_lock(_prepare_action_lock)
with_inventory_action_lock = _with_action_lock(_inventory_action_lock)


def _parse_any_date(value):
    if not value:
        return None

    value = str(value).strip()
    for fmt in ("%Y%m%d", "%Y/%m/%d", "%Y-%m-%d"):
        try:
            return datetime.strptime(value, fmt).date()
        except ValueError:
            pass
    return None


def _ranges_overlap(a_start, a_end, b_start, b_end):
    ad1, ad2 = _parse_any_date(a_start), _parse_any_date(a_end)
    bd1, bd2 = _parse_any_date(b_start), _parse_any_date(b_end)
    if not all([ad1, ad2, bd1, bd2]):
        return False
    return ad1 <= bd2 and bd1 <= ad2

def invalidate_cache(realtime_details=None):
    """Invalidate the asset cache when data changes"""
    reset_cache()
    # The current process made this change, so its in-memory manager is already
    # authoritative. Recording the new file signature prevents the next request
    # from mistaking our own write for an external update and reloading all CSVs.
    mark_data_snapshot_current()
    mark_realtime_change('inventory-data', realtime_details)


def reset_cache():
    """Clear in-process derived data without publishing a realtime event."""
    manager = _current_data_manager_object()
    if manager is not None:
        _manager_caches.pop(id(manager), None)


def _current_manager_cache():
    manager = _current_data_manager_object()
    if manager is None:
        return {
            'assigned_assets': None,
            'available_assets': None,
            'cache_timestamp': None,
            'event_state_refreshes': {},
        }
    return _manager_caches.setdefault(id(manager), {
        'assigned_assets': None,
        'available_assets': None,
        'cache_timestamp': None,
        'event_state_refreshes': {},
    })


def _shared_data_signature(manager=None):
    """Fingerprint CSV-backed files so separate workers can detect fresh data."""
    manager = manager or _current_data_manager_object()
    if manager is None:
        return None
    if hasattr(manager, 'shared_data_signature'):
        return manager.shared_data_signature()

    entries = []
    data_folder = getattr(manager, 'data_folder', '') or ''
    events_folder = getattr(manager, 'events_folder', '') or ''

    def add_file(label, path):
        try:
            stat = os.stat(path)
            entries.append((label, stat.st_mtime_ns, stat.st_size))
        except FileNotFoundError:
            entries.append((label, 0, 0))
        except OSError as e:
            logger.debug("Unable to stat %s for data refresh: %s", path, e)
            entries.append((label, -1, -1))

    for filename in ('Inventory.csv', 'Logs.csv', 'Users.csv', 'Containers.csv', 'Clients.csv'):
        if hasattr(manager, '_data_path'):
            add_file(filename, manager._data_path(filename))
        else:
            add_file(filename, os.path.join(data_folder, filename))

    try:
        with os.scandir(events_folder) as event_files:
            for entry in event_files:
                if not entry.is_file() or not entry.name.endswith('.csv'):
                    continue
                try:
                    stat = entry.stat()
                    entries.append((f"events/{entry.name}", stat.st_mtime_ns, stat.st_size))
                except OSError as e:
                    logger.debug("Unable to stat event file %s: %s", entry.path, e)
                    entries.append((f"events/{entry.name}", -1, -1))
    except FileNotFoundError:
        entries.append(('events/', 0, 0))
    except OSError as e:
        logger.debug("Unable to scan events folder for data refresh: %s", e)
        entries.append(('events/', -1, -1))

    return tuple(sorted(entries))


def mark_data_snapshot_current(manager=None):
    """Record that this process has loaded the latest CSV-backed data."""
    global _data_snapshot_signature
    manager = manager or _current_data_manager_object()
    if manager is None:
        return
    signature = _shared_data_signature(manager)
    _data_snapshot_signatures[id(manager)] = signature
    _data_signature_checks[id(manager)] = time.monotonic()
    if manager is get_default_data_manager():
        _data_snapshot_signature = signature


def _data_reload_lock_for(manager):
    """Return the refresh lock dedicated to one company data manager."""
    manager_id = id(manager)
    with _data_reload_locks_guard:
        return _data_reload_locks.setdefault(manager_id, threading.RLock())


def refresh_shared_data_if_changed(force=False):
    """Reload CSV data when another process or user has changed the files."""
    global _data_snapshot_signature

    manager = _current_data_manager_object()
    if manager is None:
        return False

    manager_id = id(manager)
    now = time.monotonic()
    if (
        not force
        and now - _data_signature_checks.get(manager_id, 0)
        < _data_signature_check_interval
    ):
        return False

    # Revision/file checks do not mutate manager state, so they do not need to
    # hold up requests for other companies (or readers of this company).
    current_signature = _shared_data_signature(manager)
    _data_signature_checks[manager_id] = now
    previous_signature = _data_snapshot_signatures.get(manager_id)
    if not force and previous_signature == current_signature:
        return False

    with _data_reload_lock_for(manager):
        # Another thread may have completed the reload while this one waited.
        previous_signature = _data_snapshot_signatures.get(id(manager))
        if not force and previous_signature == current_signature:
            return False

        manager.load_all_data()
        reset_cache()
        new_signature = _shared_data_signature(manager)
        _data_snapshot_signatures[manager_id] = new_signature
        _data_signature_checks[manager_id] = time.monotonic()
        if manager is get_default_data_manager():
            _data_snapshot_signature = new_signature
        logger.info(
            "Reloaded shared data after an external change for %s",
            getattr(manager, 'company_code', None)
            or getattr(manager, 'data_folder', 'default company'),
        )
        return True


# ---------------- Department configuration helpers ----------------
# Departments used to be hard-coded in CSS and in dropdowns.  These helpers keep
# the existing DepartmentCode value as the stable key, while allowing admins to
# add/rename department codes and change badge colours without editing code.
DEFAULT_DEPARTMENTS = {
    'AX':   {'code': 'AX',   'name': 'Audio',    'color': '#cce5ff', 'textColor': '#004085'},
    'LX':   {'code': 'LX',   'name': 'Lighting', 'color': '#d4edda', 'textColor': '#155724'},
    'VX':   {'code': 'VX',   'name': 'Video',    'color': '#e2d9f3', 'textColor': '#44297a'},
    'LOAN': {'code': 'LOAN', 'name': 'Loan',     'color': '#f8d7da', 'textColor': '#721c24'},
    'MISC': {'code': 'MISC', 'name': 'Misc',     'color': '#fff3cd', 'textColor': '#856404'},
    'UN':   {'code': 'UN',   'name': 'Unknown',  'color': '#e2e3e5', 'textColor': '#383d41'},
}


def _normalise_department_code(code):
    code = str(code or '').strip().upper()
    code = re.sub(r'[^A-Z0-9_-]+', '', code)
    return code


def _normalise_hex_colour(value, fallback='#e2e3e5'):
    value = str(value or '').strip()
    if re.match(r'^#[0-9a-fA-F]{6}$', value):
        return value.upper()
    if re.match(r'^[0-9a-fA-F]{6}$', value):
        return f'#{value.upper()}'
    return fallback


def _best_text_colour(background):
    colour = _normalise_hex_colour(background)
    try:
        r = int(colour[1:3], 16)
        g = int(colour[3:5], 16)
        b = int(colour[5:7], 16)
        # Perceived brightness. Light backgrounds get dark text; dark backgrounds get white text.
        brightness = (r * 299 + g * 587 + b * 114) / 1000
        return '#111827' if brightness > 150 else '#FFFFFF'
    except Exception:
        return '#111827'


def _departments_csv_path():
    if not data_manager:
        return os.path.join('.', 'Departments.csv')
    return os.path.join(data_manager.data_folder, 'Departments.csv')


def _department_record(code, name=None, colour=None, text_colour=None):
    code = _normalise_department_code(code) or 'UN'
    defaults = DEFAULT_DEPARTMENTS.get(code, {})
    colour = _normalise_hex_colour(colour or defaults.get('color', '#e2e3e5'))
    return {
        'code': code,
        'name': str(name if name is not None else defaults.get('name', code)).strip() or code,
        'color': colour,
        'textColor': _normalise_hex_colour(text_colour or defaults.get('textColor') or _best_text_colour(colour), _best_text_colour(colour))
    }


def _save_departments(departments):
    manager = _current_data_manager_object()
    if manager is not None and hasattr(manager, 'save_departments'):
        manager.save_departments(departments)
        return

    filepath = _departments_csv_path()
    folder = os.path.dirname(filepath)
    if folder and not os.path.exists(folder):
        os.makedirs(folder)

    with open(filepath, 'w', newline='', encoding='utf-8') as f:
        writer = csv.DictWriter(f, fieldnames=['Code', 'Name', 'Color', 'TextColor'])
        writer.writeheader()
        for code in sorted(departments.keys()):
            dept = _department_record(
                code,
                departments[code].get('name'),
                departments[code].get('color'),
                departments[code].get('textColor')
            )
            writer.writerow({
                'Code': dept['code'],
                'Name': dept['name'],
                'Color': dept['color'],
                'TextColor': dept['textColor']
            })


def _load_departments():
    filepath = _departments_csv_path()
    departments = {}
    changed = False
    manager = _current_data_manager_object()
    database_backed = manager is not None and hasattr(manager, 'load_departments')

    if database_backed:
        departments = manager.load_departments()
    elif os.path.exists(filepath) and os.path.getsize(filepath) > 0:
        try:
            with open(filepath, 'r', newline='', encoding='utf-8-sig') as f:
                reader = csv.DictReader(f)
                for row in reader:
                    code = _normalise_department_code(row.get('Code') or row.get('code'))
                    if not code:
                        continue
                    departments[code] = _department_record(
                        code,
                        row.get('Name') or row.get('name') or code,
                        row.get('Color') or row.get('color'),
                        row.get('TextColor') or row.get('textColor')
                    )
        except Exception as e:
            logger.warning(f"Failed to read Departments.csv, rebuilding defaults: {e}")
            departments = {}
            changed = True

    # Always keep the defaults available, unless the admin has already changed them.
    for code, dept in DEFAULT_DEPARTMENTS.items():
        if code not in departments:
            departments[code] = dept.copy()
            changed = True

    # Auto-register any existing inventory department codes so old CSVs keep working.
    if data_manager and getattr(data_manager, 'inventory', None):
        for asset in data_manager.inventory.values():
            code = _normalise_department_code(getattr(asset, 'department_code', 'UN')) or 'UN'
            if code not in departments:
                departments[code] = _department_record(code)
                changed = True

    if changed or (not database_backed and not os.path.exists(filepath)):
        _save_departments(departments)

    return departments


def _department_payload(code, departments=None):
    departments = departments or _load_departments()
    code = _normalise_department_code(code) or 'UN'
    return departments.get(code) or _department_record(code)


