def _remove_custom_pdf_logos():
    folder = _pdf_assets_folder()
    if not os.path.isdir(folder):
        return

    for filename in os.listdir(folder):
        if filename.startswith('logo.'):
            try:
                os.remove(os.path.join(folder, filename))
            except OSError as e:
                logger.warning(f"Failed to remove old PDF logo {filename}: {e}")


def _replace_department_in_model_marker(value, old_code, new_code):
    if not isinstance(value, str) or not value.startswith('[MODEL]'):
        return value, False

    parts = value[7:].split('|', 4)
    if not parts or _normalise_department_code(parts[0]) != old_code:
        return value, False

    parts[0] = new_code
    return '[MODEL]' + '|'.join(parts), True


def _replace_department_in_model_description(value, old_code, new_code):
    if not isinstance(value, str):
        return value, False

    prefix = f'[{old_code}]'
    if value.startswith(prefix):
        return f'[{new_code}]' + value[len(prefix):], True

    return value, False


def _replace_department_in_custom_marker(value, old_code, new_code):
    custom = _parse_custom_marker(value) if isinstance(value, str) else None
    if not custom or custom.get('legacy'):
        return value, False
    if _normalise_department_code(custom.get('department')) != old_code:
        return value, False
    return _make_custom_marker(
        custom.get('type'),
        custom.get('name'),
        custom.get('quantity'),
        new_code,
        custom.get('company'),
        uid=custom.get('uid') or None,
        description=custom.get('description') or ''
    ), True

def _clean_group_value(value, uppercase=False):
    cleaned = str(value or '').strip()
    return cleaned.upper() if uppercase else cleaned


def _asset_group_key(asset):
    """
    Asset model type key.

    Model types are identified by department, brand, and model number only.
    Description is display/detail text and must not split availability,
    preparation, transfer, or asset-check groups.
    """
    return (
        _clean_group_value(getattr(asset, 'department_code', ''), True),
        _clean_group_value(getattr(asset, 'brand', '')),
        _clean_group_value(getattr(asset, 'model_number', '')),
        ''
    )


def _asset_family_key_from_values(brand, model):
    return (
        _clean_group_value(brand).lower(),
        _clean_group_value(model).lower()
    )


def _asset_family_key(asset):
    return _asset_family_key_from_values(
        getattr(asset, 'brand', ''),
        getattr(asset, 'model_number', '')
    )


def _asset_id_parts(asset_id):
    match = re.match(r'^(.*?)#(\d+)$', str(asset_id or '').strip())
    if not match:
        return None, None, 0

    number_text = match.group(2)
    return match.group(1), int(number_text), len(number_text)


def _normalise_asset_id_prefix(value):
    prefix = str(value or '').strip().upper()
    prefix = re.sub(r'\s+', ' ', prefix)
    prefix = prefix.replace('#', '')
    return prefix.strip()


def _prefix_fragment(value):
    return re.sub(r'[^A-Z0-9]+', '', str(value or '').upper())


def _brand_prefix_fragment(brand):
    words = re.findall(r'[A-Z0-9]+', str(brand or '').upper())
    if not words:
        return ''

    if len(words) > 1:
        return ''.join(word[0] for word in words if word)[:4]

    word = words[0]
    if len(word) <= 3:
        return word

    # Short brand mark that keeps prefixes readable while still separating
    # common same-model collisions such as L-Acoustics P1 -> LAP1.
    return word[:3]


def _default_asset_id_prefix(brand, model, used_prefixes=None, existing_model_brand_collision=False):
    model_fragment = _prefix_fragment(model)
    brand_fragment = _brand_prefix_fragment(brand)

    if not model_fragment:
        model_fragment = brand_fragment or 'ASSET'

    candidate = model_fragment
    used_prefixes = used_prefixes or {}

    if existing_model_brand_collision or candidate in used_prefixes:
        candidate = f"{brand_fragment}{model_fragment}" if brand_fragment else model_fragment

    base_candidate = candidate or 'ASSET'
    counter = 2
    while candidate in used_prefixes:
        candidate = f"{base_candidate}{counter}"
        counter += 1

    return candidate


def _prefix_usage_summary():
    summary = defaultdict(lambda: {
        'count': 0,
        'maxNumber': 0,
        'width': 2,
        'families': defaultdict(int),
        'familyLabels': {}
    })

    for item in data_manager.inventory.values():
        if not item or _is_bulk_asset(item):
            continue

        prefix, number, width = _asset_id_parts(getattr(item, 'asset_id', ''))
        if not prefix:
            continue

        normalised_prefix = _normalise_asset_id_prefix(prefix)
        if not normalised_prefix:
            continue

        family = _asset_family_key(item)
        entry = summary[normalised_prefix]
        entry['count'] += 1
        entry['maxNumber'] = max(entry['maxNumber'], number)
        entry['width'] = max(entry['width'], width or 2)
        entry['families'][family] += 1
        entry['familyLabels'].setdefault(family, (
            _clean_group_value(getattr(item, 'brand', '')),
            _clean_group_value(getattr(item, 'model_number', ''))
        ))

    return summary


def _best_existing_prefix_for_family(family_key, usage):
    candidates = []

    for prefix, entry in usage.items():
        family_count = entry['families'].get(family_key, 0)
        if family_count <= 0:
            continue

        candidates.append((
            -family_count,
            -entry['maxNumber'],
            prefix
        ))

    if not candidates:
        return None

    candidates.sort()
    return candidates[0][2]


def _asset_id_plan_for_request(data):
    data = data or {}

    brand = str(data.get('brand', '') or '').strip()
    model_number = str(data.get('model', '') or '').strip()
    description = str(data.get('description', '') or '').strip()
    department = _normalise_department_code(data.get('department'))
    is_bulk = _request_bool(data.get('isBulk'), default=False)
    quantity = _safe_int(data.get('quantity'), 0)

    if not brand:
        raise ValueError('Brand is required')

    if not model_number:
        raise ValueError('Model number is required')

    if not department:
        raise ValueError('Department is required')

    if quantity <= 0:
        raise ValueError('Quantity is required')

    quantity = min(quantity, 500)

    if is_bulk:
        return {
            'isBulk': True,
            'brand': brand,
            'model': model_number,
            'description': description,
            'department': department,
            'quantity': quantity,
            'prefix': '',
            'startNumber': None,
            'nextNumber': None,
            'ids': [],
            'serials': [],
            'secondarySerials': [],
            'existingCount': 0,
            'message': ''
        }

    family_key = _asset_family_key_from_values(brand, model_number)
    usage = _prefix_usage_summary()
    custom_prefix = _normalise_asset_id_prefix(data.get('assetIdPrefix'))

    if custom_prefix:
        prefix = custom_prefix
    else:
        existing_prefix = _best_existing_prefix_for_family(family_key, usage)

        if existing_prefix:
            prefix = existing_prefix
        else:
            model_key = _clean_group_value(model_number).lower()
            has_model_brand_collision = any(
                _clean_group_value(getattr(item, 'model_number', '')).lower() == model_key and
                _asset_family_key(item) != family_key
                for item in data_manager.inventory.values()
                if item and not _is_bulk_asset(item)
            )

            used_by_other_families = {
                used_prefix: entry
                for used_prefix, entry in usage.items()
                if family_key not in entry['families']
            }
            prefix = _default_asset_id_prefix(
                brand,
                model_number,
                used_by_other_families,
                existing_model_brand_collision=has_model_brand_collision
            )

    if not prefix:
        raise ValueError('Asset ID prefix is required')

    prefix_entry = usage.get(prefix)
    next_number = (prefix_entry or {}).get('maxNumber', 0) + 1
    width = max(2, (prefix_entry or {}).get('width', 2), len(str(next_number + quantity - 1)))
    ids = [f"{prefix}#{number:0{width}d}" for number in range(next_number, next_number + quantity)]

    collisions = [asset_id for asset_id in ids if asset_id in data_manager.inventory]
    if collisions:
        raise ValueError(f'Generated Asset ID already exists: {collisions[0]}')

    raw_serials = data.get('serials')
    if isinstance(raw_serials, list):
        serials = [str(serial or '').strip() for serial in raw_serials]
    else:
        serial = str(data.get('serial', '') or '').strip()
        serials = [serial] if serial else []

    serials = (serials + [''] * quantity)[:quantity]

    raw_secondary_serials = data.get('secondarySerials')
    if isinstance(raw_secondary_serials, list):
        secondary_serials = [str(serial or '').strip() for serial in raw_secondary_serials]
    else:
        secondary_serial = str(
            data.get('secondarySerial', data.get('serial2', '')) or ''
        ).strip()
        secondary_serials = [secondary_serial] if secondary_serial else []

    secondary_serials = (secondary_serials + [''] * quantity)[:quantity]

    existing_count = 0
    if prefix_entry:
        existing_count = prefix_entry['families'].get(family_key, 0)

    return {
        'isBulk': False,
        'brand': brand,
        'model': model_number,
        'description': description,
        'department': department,
        'quantity': quantity,
        'prefix': prefix,
        'startNumber': next_number,
        'nextNumber': next_number + quantity,
        'ids': ids,
        'serials': serials,
        'secondarySerials': secondary_serials,
        'existingCount': existing_count,
        'message': f"{prefix} continues from #{next_number:0{width}d}"
    }



def _asset_serial_count_mismatches(data, quantity, is_bulk=False):
    """Describe entered serial lists that do not match the requested quantity."""
    if is_bulk:
        return []

    data = data or {}
    groups = (
        ('primary', data.get('serials'), False),
        ('secondary', data.get('secondarySerials'), True),
    )
    mismatches = []
    for label, values, optional in groups:
        if not isinstance(values, list):
            continue
        count = sum(1 for value in values if str(value or '').strip())
        if count != quantity and not (optional and count == 0):
            mismatches.append({
                'type': label,
                'count': count,
                'quantity': quantity,
            })
    return mismatches


def _is_bulk_asset(asset):
    return bool(getattr(asset, 'is_bulk', False))


def _safe_int(value, default=0):
    try:
        return int(value)
    except (TypeError, ValueError):
        return default


def _safe_float(value, default=0.0):
    try:
        return float(value)
    except (TypeError, ValueError):
        return default


def _normalise_asset_purchase_date(value):
    raw = str(value or '').strip()
    if not raw:
        return ''

    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%Y%m%d'):
        try:
            return datetime.strptime(raw, fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue

    raise ValueError('Date of purchase must be YYYY-MM-DD')


ASSET_AUDIT_FIELD_LABELS = {
    'asset_id': 'Asset ID',
    'department': 'Department',
    'brand': 'Brand',
    'model': 'Model',
    'version': 'Version',
    'description': 'Description',
    'serial': 'Serial Number',
    'secondary_serial': 'Second Serial Number',
    'date_of_purchase': 'Date of Purchase',
    'default_location': 'Default Location',
    'current_location': 'Current Location',
    'status': 'Asset Status',
    'quantity': 'Quantity',
    'notes': 'Notes',
    'tags': 'Tags',
}


def _asset_audit_timestamp():
    return datetime.now().isoformat(timespec='seconds')


def _asset_audit_user():
    return session.get('user', 'system') if has_request_context() else 'system'


def _asset_audit_snapshot(asset):
    return {
        'asset_id': getattr(asset, 'asset_id', ''),
        'department': getattr(asset, 'department_code', ''),
        'brand': getattr(asset, 'brand', ''),
        'model': getattr(asset, 'model_number', ''),
        'version': getattr(asset, 'version', ''),
        'description': getattr(asset, 'description', ''),
        'serial': getattr(asset, 'serial_number', ''),
        'secondary_serial': getattr(asset, 'secondary_serial_number', ''),
        'date_of_purchase': getattr(asset, 'date_of_purchase', ''),
        'default_location': getattr(asset, 'default_location', ''),
        'current_location': getattr(asset, 'current_location', ''),
        'status': _asset_condition_status(asset),
        'quantity': max(1, _safe_int(getattr(asset, 'quantity', 1), 1)) if _is_bulk_asset(asset) else 1,
        'notes': getattr(asset, 'notes', ''),
        'tags': normalize_asset_tags(getattr(asset, 'tags', [])),
    }


def _asset_audit_value(value):
    if isinstance(value, bool):
        return value
    if isinstance(value, int):
        return value
    if value is None:
        return ''
    return str(value)


def _asset_audit_changes(before, after, fields=None):
    fields = fields or ASSET_AUDIT_FIELD_LABELS.keys()
    changes = []

    for field in fields:
        old_value = _asset_audit_value(before.get(field, ''))
        new_value = _asset_audit_value(after.get(field, ''))
        if old_value == new_value:
            continue

        changes.append({
            'field': field,
            'label': ASSET_AUDIT_FIELD_LABELS.get(field, field),
            'old': old_value,
            'new': new_value,
        })

    return changes


def _asset_audit_log_value(value):
    if isinstance(value, list):
        text = ', '.join(str(item) for item in value if str(item or '').strip())
    else:
        text = str(value or '').strip()
    return text or '-'


def _asset_audit_log_summary(records, limit=8):
    """Describe exact per-asset edits using the inventory audit snapshots."""
    entries = []
    for before, after in records or []:
        changes = _asset_audit_changes(before, after)
        if not changes:
            continue
        old_id = str(before.get('asset_id') or '').strip()
        new_id = str(after.get('asset_id') or '').strip()
        asset_label = (
            f'{old_id} -> {new_id}'
            if old_id and new_id and old_id != new_id
            else new_id or old_id or 'Asset'
        )
        detail = '; '.join(
            f"{change['label']}: {_asset_audit_log_value(change['old'])} -> "
            f"{_asset_audit_log_value(change['new'])}"
            for change in changes
        )
        entries.append(f'{asset_label}: {detail}')

    visible = entries[:limit]
    if len(entries) > limit:
        visible.append(f'+{len(entries) - limit} more asset(s)')
    return ' | '.join(visible)


def _append_asset_change_history(asset, changes, timestamp=None, user=None, action='updated'):
    changes = [change for change in (changes or []) if change]
    if not changes:
        return False

    timestamp = timestamp or _asset_audit_timestamp()
    user = user if user is not None else _asset_audit_user()
    history = list(getattr(asset, 'change_history', []) or [])
    history.append({
        'date': timestamp,
        'user': user,
        'action': action,
        'changes': changes,
    })
    asset.change_history = history
    asset.date_modified = timestamp
    return True


def _mark_asset_created(asset, timestamp=None, user=None):
    timestamp = timestamp or _asset_audit_timestamp()
    user = user if user is not None else _asset_audit_user()
    asset.date_added = getattr(asset, 'date_added', '') or timestamp
    asset.date_modified = getattr(asset, 'date_modified', '') or timestamp

    after = _asset_audit_snapshot(asset)
    changes = [
        {
            'field': field,
            'label': ASSET_AUDIT_FIELD_LABELS.get(field, field),
            'old': '',
            'new': _asset_audit_value(value),
        }
        for field, value in after.items()
        if _asset_audit_value(value) not in ('', 0)
    ]
    _append_asset_change_history(asset, changes, timestamp=timestamp, user=user, action='created')


def _is_degraded(asset):
    return bool(getattr(asset, 'is_degraded', False))


def _is_untagged(asset):
    return bool(getattr(asset, 'is_untagged', False))


def _is_disposed(asset):
    return bool(getattr(asset, 'is_disposed', False))


def _normalise_asset_status_name(value):
    status = str(value or '').strip().lower()
    return 'decommissioned' if status == 'disposed' else status


def _asset_inventory_quantity(asset):
    if not asset or _is_disposed(asset):
        return 0
    return max(1, _safe_int(getattr(asset, 'quantity', 1), 1)) if _is_bulk_asset(asset) else 1


def _asset_status_value(asset, assigned_assets=None):
    if not asset:
        return 'unknown'
    if _is_disposed(asset):
        return 'decommissioned'
    if getattr(asset, 'is_missing', False):
        return 'missing'
    if getattr(asset, 'is_ooc', False):
        return 'ooc'
    if assigned_assets is not None and not _is_bulk_asset(asset) and asset.asset_id in assigned_assets:
        return 'deployed'
    if _is_untagged(asset):
        return 'untagged'
    if _is_degraded(asset):
        return 'degraded'
    return 'available'


ASSET_CONDITION_STATUSES = ('ooc', 'missing', 'untagged', 'degraded', 'decommissioned')
BULK_MAINTENANCE_FAULT_SOURCE = 'bulk_maintenance_fault'
BULK_MAINTENANCE_RESOLUTION_SOURCE = 'bulk_maintenance_resolution'
CONTAINER_MAINTENANCE_SOURCE = 'container'
BULK_MAINTENANCE_STATUSES = ('ooc', 'missing', 'degraded')
BULK_MAINTENANCE_UNAVAILABLE_STATUSES = ('ooc', 'missing')


def _asset_condition_status(asset):
    """Return the asset's mutually-exclusive condition status, excluding deployment."""
    if not asset:
        return 'unknown'
    if _is_disposed(asset):
        return 'decommissioned'
    if getattr(asset, 'is_missing', False):
        return 'missing'
    if getattr(asset, 'is_ooc', False):
        return 'ooc'
    if _is_untagged(asset):
        return 'untagged'
    if _is_degraded(asset):
        return 'degraded'
    return 'ok'


def _bulk_maintenance_log_key(record, index):
    log_id = str((record or {}).get('id') or '').strip()
    return log_id or f'index:{index}'


def _bulk_maintenance_source_kind(record):
    source = (record or {}).get('source') or {}
    return str(source.get('kind') or '').strip()


def _bulk_maintenance_fault_entries(asset):
    """Return paired bulk maintenance fault/resolution entries for one bulk row."""
    faults = []
    lookup = {}

    for index, log_entry in enumerate(getattr(asset, 'maintenance_logs', []) or []):
        record = normalize_maintenance_log(log_entry)
        source = record.get('source') or {}
        kind = _bulk_maintenance_source_kind(record)

        if kind == BULK_MAINTENANCE_FAULT_SOURCE:
            status = str(source.get('bulkStatus') or '').strip().lower()
            if status not in BULK_MAINTENANCE_STATUSES:
                continue

            key = _bulk_maintenance_log_key(record, index)
            log_number = max(1, _safe_int(source.get('bulkLogNumber'), len(faults) + 1))
            quantity = max(1, _safe_int(source.get('bulkQuantity'), 1))
            entry = {
                'key': key,
                'id': str(record.get('id') or '').strip(),
                'index': index,
                'logNumber': log_number,
                'status': status,
                'quantity': quantity,
                'fault': record,
                'resolution': None,
                'resolutionIndex': None,
            }
            faults.append(entry)
            lookup[key] = entry
            if entry['id']:
                lookup[entry['id']] = entry

        elif kind == BULK_MAINTENANCE_RESOLUTION_SOURCE:
            target = str(
                source.get('bulkResolves') or
                source.get('bulkFaultLogId') or
                source.get('faultLogId') or
                ''
            ).strip()
            if not target:
                continue
            fault = lookup.get(target)
            if fault:
                fault['resolution'] = record
                fault['resolutionIndex'] = index

    return faults


def _bulk_maintenance_open_faults(asset):
    return [
        entry for entry in _bulk_maintenance_fault_entries(asset)
        if not entry.get('resolution')
    ]


def _bulk_maintenance_quantity_counts(asset):
    total = max(1, _safe_int(getattr(asset, 'quantity', 1), 1)) if _is_bulk_asset(asset) else 1
    raw_counts = {'ooc': 0, 'missing': 0, 'degraded': 0}

    for entry in _bulk_maintenance_open_faults(asset):
        status = entry.get('status')
        if status in raw_counts:
            raw_counts[status] += max(1, _safe_int(entry.get('quantity'), 1))

    remaining_quantity = total
    ooc_quantity = min(remaining_quantity, raw_counts['ooc'])
    remaining_quantity = max(remaining_quantity - ooc_quantity, 0)
    missing_quantity = min(remaining_quantity, raw_counts['missing'])
    remaining_quantity = max(remaining_quantity - missing_quantity, 0)
    degraded_quantity = min(remaining_quantity, raw_counts['degraded'])
    capped_counts = {
        'ooc': ooc_quantity,
        'missing': missing_quantity,
        'degraded': degraded_quantity,
    }
    unavailable_quantity = sum(capped_counts[status] for status in BULK_MAINTENANCE_UNAVAILABLE_STATUSES)
    return {
        'ooc': capped_counts['ooc'],
        'missing': capped_counts['missing'],
        'degraded': capped_counts['degraded'],
        'unavailable': unavailable_quantity,
        'total': unavailable_quantity + degraded_quantity,
        'rawOOC': raw_counts['ooc'],
        'rawMissing': raw_counts['missing'],
        'rawDegraded': raw_counts['degraded'],
    }


def _next_bulk_maintenance_log_number(asset):
    existing_numbers = [
        max(0, _safe_int(entry.get('logNumber'), 0))
        for entry in _bulk_maintenance_fault_entries(asset)
    ]
    return max(existing_numbers, default=0) + 1


def _bulk_maintenance_logbook_for_response(asset):
    rows = []
    for entry in _bulk_maintenance_fault_entries(asset):
        rows.append({
            'key': entry['key'],
            'id': entry['id'],
            'logNumber': entry['logNumber'],
            'status': entry['status'],
            'quantity': entry['quantity'],
            'faultIndex': entry['index'],
            'resolutionIndex': entry.get('resolutionIndex'),
            'isResolved': bool(entry.get('resolution')),
            'fault': _maintenance_log_for_response(entry.get('fault')),
            'resolution': (
                _maintenance_log_for_response(entry.get('resolution'))
                if entry.get('resolution') else None
            ),
        })
    return rows


def _maintenance_log_marks_status(record, status, action='marked'):
    target_status = str(status or '').strip().lower()
    target_action = str(action or '').strip().lower()
    for change in normalize_maintenance_log(record).get('changes', []) or []:
        kind = str(change.get('kind') or '').strip().lower()
        change_action = str(change.get('action') or '').strip().lower()
        if kind == target_status and change_action == target_action:
            return True
    return False


def _clean_warning_reason(value, max_length=240):
    reason = str(value or '').strip()
    if not reason:
        return ''
    reason = re.sub(r'\s+', ' ', reason)
    if len(reason) > max_length:
        return reason[:max_length - 1].rstrip() + '...'
    return reason


def _asset_degraded_reasons(asset, limit=3):
    if not asset:
        return []

    active_reason = ''
    for log_entry in getattr(asset, 'maintenance_logs', []) or []:
        record = normalize_maintenance_log(log_entry)
        if _maintenance_log_marks_status(record, 'degraded', 'marked'):
            active_reason = _clean_warning_reason(record.get('description'))
        if _maintenance_log_marks_status(record, 'degraded', 'cleared'):
            active_reason = ''

    return [active_reason] if active_reason else []


def _bulk_degraded_reasons(asset, limit=3):
    reasons = []

    if _is_degraded(asset):
        reasons.extend(_asset_degraded_reasons(asset, limit=limit))

    for entry in _bulk_maintenance_open_faults(asset):
        if entry.get('status') != 'degraded':
            continue
        reason = _clean_warning_reason((entry.get('fault') or {}).get('description'))
        if reason:
            reasons.append(reason)
        if len(reasons) >= limit:
            break

    return reasons[:limit]


def _warning_reason_text(reasons):
    clean_reasons = [_clean_warning_reason(reason) for reason in (reasons or [])]
    clean_reasons = [reason for reason in clean_reasons if reason]
    if not clean_reasons:
        return ''
    if len(clean_reasons) == 1:
        return f" Reason: {clean_reasons[0]}"
    return " Reasons: " + "; ".join(clean_reasons)


def _degraded_asset_warning(asset, asset_id):
    reasons = _asset_degraded_reasons(asset)
    return (
        f"Asset {asset_id} is marked as Degraded."
        f"{_warning_reason_text(reasons)} "
        "It can be used, but please verify the limitation before show."
    )


def _apply_exclusive_asset_status(asset, target_status):
    """Set one condition status on an asset. target_status='ok' clears all."""
    for attr in ('is_ooc', 'is_missing', 'is_untagged', 'is_degraded', 'is_disposed'):
        setattr(asset, attr, False)

    if target_status == 'ooc':
        asset.is_ooc = True
    elif target_status == 'missing':
        asset.is_missing = True
    elif target_status == 'untagged':
        asset.is_untagged = True
    elif target_status == 'degraded':
        asset.is_degraded = True
    elif target_status in ('disposed', 'decommissioned'):
        asset.is_disposed = True


def _normalise_asset_status_flags(asset):
    """Repair any legacy/conflicting flags to one status only."""
    _apply_exclusive_asset_status(asset, _asset_condition_status(asset))


def _status_changes_for_request(data, current_status=None):
    """Return (target_status, changes, error).

    target_status is one of: None, 'ok', 'ooc', 'missing', 'untagged', 'degraded',
    'decommissioned'.
    None means no status change requested.
    """
    data = data or {}
    current_status = _normalise_asset_status_name(current_status)
    if current_status == 'available':
        current_status = 'ok'

    def clear_current_status_change():
        if current_status in ASSET_CONDITION_STATUSES:
            return 'ok', [make_change(current_status, action='cleared')]
        return None, []

    explicit = (
        data.get('assetStatus') or
        data.get('editAssetStatus') or
        data.get('statusValue') or
        data.get('statusChange') or
        data.get('targetStatus')
    )

    if explicit is not None:
        value = str(explicit).strip().lower()
        aliases = {
            '': None,
            'none': None,
            'nochange': None,
            'no-change': None,
            'ok': 'ok',
            'okay': 'ok',
            'available': 'ok',
            'clear': 'ok',
            'cleared': 'ok',
            'normal': 'ok',
            'ooc': 'ooc',
            'out-of-commission': 'ooc',
            'out_of_commission': 'ooc',
            'missing': 'missing',
            'untagged': 'untagged',
            'degraded': 'degraded',
            'decommissioned': 'decommissioned',
            'disposed': 'decommissioned',
        }
        if value not in aliases:
            return None, [], f'Invalid asset status: {explicit}'
        target = aliases[value]
        if target is None:
            return None, [], None
        if target == 'ok':
            target, changes = clear_current_status_change()
            return target, changes, None
        return target, [make_change(target, action='marked')], None

    mark_flags = {
        'ooc': bool(data.get('markOOC', False)),
        'missing': bool(data.get('markMissing', False)),
        'untagged': bool(data.get('markUntagged', False)),
        'degraded': bool(data.get('markDegraded', False)),
        'decommissioned': bool(data.get('markDecommissioned', False) or data.get('markDisposed', False)),
    }
    marked = [kind for kind, enabled in mark_flags.items() if enabled]
    if len(marked) > 1:
        return None, [], 'Choose only one asset status at a time'
    if marked:
        target = marked[0]
        return target, [make_change(target, action='marked')], None

    clear_flags = {
        'ooc': bool(data.get('unmarkOOC', False)),
        'missing': bool(data.get('unmarkMissing', False)),
        'untagged': bool(data.get('unmarkUntagged', False)),
        'degraded': bool(data.get('unmarkDegraded', False)),
        'decommissioned': bool(data.get('unmarkDecommissioned', False) or data.get('unmarkDisposed', False)),
    }
    cleared = [kind for kind, enabled in clear_flags.items() if enabled]
    if cleared:
        if set(cleared) == set(ASSET_CONDITION_STATUSES):
            target, changes = clear_current_status_change()
            return target, changes, None
        target = 'ok' if current_status in cleared else None
        return target, [make_change(kind, action='cleared') for kind in cleared], None

    return None, [], None


def _maintenance_log_type_for_request(data, default_type=DEFAULT_MAINTENANCE_LOG_TYPE, allow_asset_check=False):
    """Return (log_type, error) for a maintenance log type submitted by the UI."""
    data = data or {}
    raw_type = None
    for key in ('logType', 'maintenanceType', 'type'):
        if key in data:
            raw_type = data.get(key)
            break

    if raw_type is None or str(raw_type).strip() == '':
        return default_type or DEFAULT_MAINTENANCE_LOG_TYPE, None

    log_type = normalize_maintenance_log_type(raw_type, allow_asset_check=allow_asset_check)
    if not log_type:
        user_options = ', '.join(USER_MAINTENANCE_LOG_TYPES)
        if str(raw_type).strip().lower() == ASSET_CHECK_LOG_TYPE.lower():
            return None, 'Asset check logs can only be created by the Asset Check function'
        return None, f'Invalid maintenance log type. Choose one of: {user_options}'

    return log_type, None


def _request_bool(value, default=False):
    if value is None:
        return default
    if isinstance(value, bool):
        return value
    if isinstance(value, (int, float)):
        return bool(value)
    return str(value).strip().lower() in ('1', 'true', 'yes', 'y', 'on')


def _validate_status_transition(asset, target_status, current_status=None):
    """Validate a requested condition status.

    Condition statuses are mutually exclusive, and applying a new one clears
    the previous one. Direct transitions such as OOC to Missing are valid.
    """
    return None


def _condition_status_before_log(asset, exclude_index, selected_date=None):
    """Calculate an asset's condition status immediately before one selected log."""
    scratch = SimpleNamespace(
        asset_id=getattr(asset, 'asset_id', ''),
        is_ooc=False,
        is_missing=False,
        is_untagged=False,
        is_degraded=False,
        is_disposed=False,
        serial_number=getattr(asset, 'serial_number', ''),
        current_location='',
    )

    logs = getattr(asset, 'maintenance_logs', []) or []
    if exclude_index < 0 or exclude_index >= len(logs):
        return _asset_condition_status(scratch)

    def log_sort_date(record):
        try:
            return datetime.strptime(record.get('date', ''), "%Y/%m/%d")
        except ValueError:
            return datetime.min

    selected_record = normalize_maintenance_log(logs[exclude_index])
    selected_sort_key = (
        log_sort_date({**selected_record, 'date': selected_date or selected_record.get('date', '')}),
        exclude_index
    )

    sorted_logs = []
    for i, log_entry in enumerate(logs):
        if i == exclude_index:
            continue
        record = normalize_maintenance_log(log_entry)
        sorted_logs.append((log_sort_date(record), i, record))

    sorted_logs.sort(key=lambda x: (x[0], x[1]))
    for date_obj, index, record in sorted_logs:
        if (date_obj, index) >= selected_sort_key:
            break
        apply_maintenance_log_changes(scratch, record)

    return _asset_condition_status(scratch)


def _status_action_label(target_status):
    return {
        'ok': 'OK',
        'ooc': 'OOC',
        'missing': 'Missing',
        'untagged': 'Untagged',
        'degraded': 'Degraded',
        'decommissioned': 'Decommissioned',
    }.get(target_status or '', '')


def _asset_prepare_block_reason(asset):
    if not asset:
        return 'Asset not found'
    if _is_disposed(asset):
        return 'Asset is decommissioned and cannot be prepared'
    if getattr(asset, 'is_missing', False):
        return 'Asset is marked as missing'
    if getattr(asset, 'is_ooc', False):
        return 'Asset is out of commission'
    return ''


def _payload_bool(data, keys, default=None):
    for key in keys:
        if key in data:
            return _request_bool(data.get(key), False)
    return default


def _prepare_scan_options(data):
    """Return options that control whether scanned extras become event demand."""
    data = data or {}
    prepare_source = str(data.get('source') or data.get('prepareSource') or '').strip().lower()
    from_container = bool(
        data.get('fromContainer') or
        data.get('isContainerBatch') or
        prepare_source in ('container', 'quick-add-container')
    )
    explicit_quick_add = _payload_bool(
        data,
        ('quickAdd', 'quick_add', 'addScannedAssetsToEvent', 'addToEvent'),
        default=None
    )

    return {
        'source': prepare_source,
        'fromContainer': from_container,
        'quickAddSpecified': explicit_quick_add is not None,
        # Existing container scans historically became part of the event. An
        # explicit quickAdd=false from the UI now overrides that legacy default.
        'addScannedAssetsToEvent': bool(from_container if explicit_quick_add is None else explicit_quick_add),
    }


def _verify_current_admin_password(password):
    username = session.get('user')
    user = data_manager.users.get(username) if data_manager else None

    if not user or not user_role_is_adminish(_effective_user_role(user)):
        return False, 'Admin privileges required'

    if not password:
        return False, 'Admin password is required'

    if hash_password(str(password), user.salt) != user.password_hash:
        return False, 'Admin password is incorrect'

    return True, ''


def _find_inventory_asset_by_identifier(identifier):
    """Find an inventory item from a scanned Asset ID or either Serial Number."""
    identifier = str(identifier or '').strip()
    if not identifier:
        return None

    if identifier in data_manager.inventory:
        return data_manager.inventory[identifier]

    identifier_lower = identifier.lower()
    for asset in data_manager.inventory.values():
        if not asset:
            continue
        if str(getattr(asset, 'asset_id', '') or '').strip().lower() == identifier_lower:
            return asset
        for serial in (
            getattr(asset, 'serial_number', ''),
            getattr(asset, 'secondary_serial_number', ''),
        ):
            serial = str(serial or '').strip()
            if serial and serial.lower() == identifier_lower:
                return asset

    return None


def _bulk_marker(bulk_id, quantity, subproject_id=''):
    marker = f"[BULK]{bulk_id}|{max(1, _safe_int(quantity, 1))}"
    clean_subproject_id = str(subproject_id or '').strip()
    return f"{marker}|{clean_subproject_id}" if clean_subproject_id else marker


def _parse_bulk_marker(value):
    if not isinstance(value, str) or not value.startswith('[BULK]'):
        return None

    raw = value[6:]
    parts = raw.split('|')
    bulk_id = parts[0]
    quantity = parts[1] if len(parts) > 1 else '1'
    subproject_id = parts[2].strip() if len(parts) > 2 else ''

    bulk_id = bulk_id.strip()
    quantity = max(1, _safe_int(quantity, 1))

    if not bulk_id:
        return None

    return {
        'bulkId': bulk_id,
        'quantity': quantity,
        'subprojectId': subproject_id,
    }


PREPARED_MODEL_PREFIX = '[PREPARED]'


def _prepared_model_marker(group, quantity):
    return (
        f"{PREPARED_MODEL_PREFIX}{group['department']}|"
        f"{group['brand']}|"
        f"{group['model']}|"
        f"{max(1, _safe_int(quantity, 1))}|"
        f"{group.get('description', '')}"
    )


def _parse_prepared_model_marker(value):
    if not isinstance(value, str) or not value.startswith(PREPARED_MODEL_PREFIX):
        return None

    parts = value[len(PREPARED_MODEL_PREFIX):].split('|')
    if len(parts) < 4:
        return None

    return {
        'department': parts[0].strip().upper(),
        'brand': parts[1].strip(),
        'model': parts[2].strip(),
        'quantity': max(1, _safe_int(parts[3], 1)),
        'description': '|'.join(parts[4:]).strip() if len(parts) > 4 else '',
    }


CUSTOM_ASSET_PREFIX = '[CUSTOM]'


def _ensure_event_custom_lists(event):
    if not hasattr(event, 'prepared_items') or event.prepared_items is None:
        event.prepared_items = []
    if not hasattr(event, 'actually_prepared') or event.actually_prepared is None:
        event.actually_prepared = []
    if not hasattr(event, 'returned_items') or event.returned_items is None:
        event.returned_items = []
    if not hasattr(event, 'extra_assets') or event.extra_assets is None:
        event.extra_assets = []
    if not hasattr(event, 'custom_collected') or event.custom_collected is None:
        event.custom_collected = []


def _remove_direct_asset_ref_from_prepared_items(event, asset_id):
    """Remove duplicated physical refs when a model row owns the requirement."""
    if not event or not asset_id:
        return 0
    if not hasattr(event, 'prepared_items') or event.prepared_items is None:
        event.prepared_items = []
        return 0

    before = len(event.prepared_items)
    event.prepared_items[:] = [ref for ref in event.prepared_items if ref != asset_id]
    return before - len(event.prepared_items)


def _normalise_custom_type(asset_type):
    value = str(asset_type or 'MISC').strip().upper()
    return 'LOAN' if value in ('LOAN', 'RENTAL', 'LOAN/RENTAL', 'RENT') else 'MISC'


def _make_custom_marker(asset_type, name, quantity=1, department='UN', company='', uid=None, description=''):
    payload = {
        'uid': str(uid or secrets.token_hex(8)),
        'type': _normalise_custom_type(asset_type),
        'name': str(name or '').strip(),
        'quantity': max(1, _safe_int(quantity, 1)),
        'department': _normalise_department_code(department) or 'UN',
        'company': str(company or '').strip(),
        'description': str(description or '').strip(),
        'version': 3
    }
    return CUSTOM_ASSET_PREFIX + json.dumps(payload, separators=(',', ':'), sort_keys=True)


def _parse_legacy_custom_marker(value):
    if not isinstance(value, str):
        return None

    raw_value = value.strip()
    lowered = raw_value.lower()

    # Very old data markers sometimes used loan|... or misc|...
    if lowered.startswith('loan|') or lowered.startswith('misc|'):
        fallback_type, remainder = raw_value.split('|', 1)
        parsed = _parse_legacy_custom_marker(remainder)
        if parsed:
            parsed['type'] = _normalise_custom_type(fallback_type)
            return parsed

    if raw_value.startswith('[MISC]'):
        asset_type = 'MISC'
        raw = raw_value[len('[MISC]'):]
    elif raw_value.startswith('[LOAN]'):
        asset_type = 'LOAN'
        raw = raw_value[len('[LOAN]'):]
    else:
        return None

    name = raw.strip()
    quantity = 1
    if ';' in raw:
        maybe_name, maybe_quantity = raw.rsplit(';', 1)
        parsed_quantity = _safe_int(maybe_quantity, 0)
        if parsed_quantity > 0:
            name = maybe_name.strip()
            quantity = parsed_quantity

    return {
        'id': value,
        'uid': '',
        'type': asset_type,
        'name': name or ('Loan/Rental Item' if asset_type == 'LOAN' else 'Misc Item'),
        'quantity': max(1, quantity),
        'department': 'UN',
        'company': '',
        'description': '',
        'version': 1,
        'legacy': True
    }


def _parse_custom_marker(value):
    if not isinstance(value, str):
        return None

    if value.startswith(CUSTOM_ASSET_PREFIX):
        try:
            payload = json.loads(value[len(CUSTOM_ASSET_PREFIX):])
        except Exception:
            return None

        asset_type = _normalise_custom_type(payload.get('type'))
        name = str(payload.get('name') or '').strip() or ('Loan/Rental Item' if asset_type == 'LOAN' else 'Misc Item')
        quantity = max(1, _safe_int(payload.get('quantity'), 1))
        department = _normalise_department_code(payload.get('department')) or 'UN'
        company = str(payload.get('company') or '').strip()
        description = str(payload.get('description') or '').strip()

        return {
            'id': value,
            'uid': str(payload.get('uid') or ''),
            'type': asset_type,
            'name': name,
            'quantity': quantity,
            'department': department,
            'company': company,
            'description': description,
            'version': _safe_int(payload.get('version'), 2),
            'legacy': False
        }

    return _parse_legacy_custom_marker(value)


def _is_custom_ref(value):
    return _parse_custom_marker(value) is not None


def _custom_display_name(custom):
    qty = max(1, _safe_int(custom.get('quantity'), 1))
    name = str(custom.get('name') or '').strip()
    return f"{qty}x {name}"


def _custom_status(event, marker):
    _ensure_event_custom_lists(event)
    custom = _parse_custom_marker(marker)
    if not custom:
        return 'assigned'

    if marker in event.returned_items:
        return 'returned'
    if marker in event.actually_prepared:
        return 'prepared'
    if custom['type'] == 'LOAN' and marker in event.custom_collected:
        return 'collected'
    return 'assigned'


def _custom_counts_for_event(event):
    _ensure_event_custom_lists(event)
    required = 0
    prepared_active = 0
    prepared_ever = 0
    returned = 0
    started = 0
    collected = 0

    for marker in event.prepared_items:
        custom = _parse_custom_marker(marker)
        if not custom:
            continue

        qty = max(1, _safe_int(custom.get('quantity'), 1))
        required += qty
        is_returned = marker in event.returned_items
        is_prepared = marker in event.actually_prepared
        is_collected = custom['type'] == 'LOAN' and marker in event.custom_collected

        if is_collected:
            collected += qty
            started += qty
        if is_prepared or is_returned:
            prepared_ever += qty
            started += qty
        if is_prepared and not is_returned:
            prepared_active += qty
        if is_returned:
            returned += qty

    return {
        'required': required,
        'preparedActive': prepared_active,
        'preparedEver': prepared_ever,
        'returned': returned,
        'started': started,
        'collected': collected
    }


PLANNING_TEMPLATES_FILENAME = 'PlanningTemplates.json'


def _planning_templates_path():
    folder = data_manager.data_folder if data_manager else './data'
    return os.path.join(folder, PLANNING_TEMPLATES_FILENAME)


def _normalise_planning_template_model(value):
    value = value if isinstance(value, dict) else {}
    department = _normalise_department_code(value.get('department')) or 'UN'
    brand = str(value.get('brand') or '').strip()
    model = str(value.get('model') or '').strip()
    description = str(value.get('description') or '').strip()
    quantity = max(1, _safe_int(value.get('quantity'), 1))
    if not brand or not model:
        return None
    return {
        'department': department,
        'brand': brand,
        'model': model,
        'description': description,
        'quantity': quantity,
    }


def _normalise_planning_template_custom(value):
    value = value if isinstance(value, dict) else {}
    asset_type = _normalise_custom_type(value.get('type'))
    name = str(value.get('name') or '').strip()
    if not name:
        return None
    return {
        'type': asset_type,
        'name': name,
        'quantity': max(1, _safe_int(value.get('quantity'), 1)),
        'department': _normalise_department_code(value.get('department')) or 'UN',
        'company': str(value.get('company') or '').strip(),
        'description': str(value.get('description') or '').strip(),
    }


def _normalise_planning_template(value):
    value = value if isinstance(value, dict) else {}
    template_id = re.sub(
        r'[^a-zA-Z0-9_-]+',
        '',
        str(value.get('id') or ''),
    )[:80] or secrets.token_hex(8)
    name = str(value.get('name') or '').strip()[:120]
    models = []
    custom_assets = []

    for row in value.get('models') or []:
        normalised = _normalise_planning_template_model(row)
        if normalised:
            models.append(normalised)

    for row in value.get('customAssets') or value.get('custom_assets') or []:
        normalised = _normalise_planning_template_custom(row)
        if normalised:
            custom_assets.append(normalised)

    return {
        'id': template_id,
        'name': name or 'Untitled Template',
        'models': models,
        'customAssets': custom_assets,
        'createdAt': str(value.get('createdAt') or value.get('created_at') or ''),
        'updatedAt': str(value.get('updatedAt') or value.get('updated_at') or ''),
    }


def _load_planning_templates():
    filepath = _planning_templates_path()
    if not os.path.exists(filepath) or os.path.getsize(filepath) == 0:
        return []

    try:
        with open(filepath, 'r', encoding='utf-8') as template_file:
            payload = json.load(template_file)
    except Exception as exc:
        logger.warning("Failed to read %s: %s", PLANNING_TEMPLATES_FILENAME, exc)
        return []

    rows = payload.get('templates', []) if isinstance(payload, dict) else payload
    if not isinstance(rows, list):
        return []

    templates = [_normalise_planning_template(row) for row in rows]
    templates.sort(key=lambda item: item['name'].lower())
    return templates


def _save_planning_templates(templates):
    filepath = _planning_templates_path()
    folder = os.path.dirname(filepath)
    if folder and not os.path.exists(folder):
        os.makedirs(folder)

    payload = {
        'version': 1,
        'templates': [_normalise_planning_template(row) for row in templates],
    }
    tmp_path = f"{filepath}.{secrets.token_hex(6)}.tmp"
    with open(tmp_path, 'w', encoding='utf-8') as template_file:
        json.dump(payload, template_file, ensure_ascii=False, indent=2)
    os.replace(tmp_path, filepath)
    return payload['templates']


def _event_planning_template_contents(event):
    model_groups = {}
    custom_groups = {}

    for ref in getattr(event, 'prepared_items', []) or []:
        marker = _parse_model_marker(ref)
        if marker:
            key = _model_key_from_parts(
                marker['department'],
                marker['brand'],
                marker['model'],
            )
            if key not in model_groups:
                model_groups[key] = {
                    'department': marker['department'],
                    'brand': marker['brand'],
                    'model': marker['model'],
                    'description': marker.get('description') or '',
                    'quantity': 0,
                }
            model_groups[key]['quantity'] += max(1, _safe_int(marker.get('quantity'), 1))
            if not model_groups[key]['description'] and marker.get('description'):
                model_groups[key]['description'] = marker['description']
            continue

        custom = _parse_custom_marker(ref)
        if not custom:
            continue
        key = (
            custom['type'],
            custom['name'].strip().lower(),
            custom['department'],
            custom.get('company', '').strip().lower(),
        )
        if key not in custom_groups:
            custom_groups[key] = {
                'type': custom['type'],
                'name': custom['name'],
                'quantity': 0,
                'department': custom['department'],
                'company': custom.get('company') or '',
            }
        custom_groups[key]['quantity'] += max(1, _safe_int(custom.get('quantity'), 1))

    models = sorted(
        model_groups.values(),
        key=lambda row: (
            row['department'],
            row['brand'].lower(),
            row['model'].lower(),
        ),
    )
    custom_assets = sorted(
        custom_groups.values(),
        key=lambda row: (
            row['department'],
            row['name'].lower(),
            row['type'],
        ),
    )
    return {'models': models, 'customAssets': custom_assets}


def _apply_planning_template_to_event(event, template, mode):
    replace = mode == 'replace'
    current_models = {}

    if not replace:
        for ref in getattr(event, 'prepared_items', []) or []:
            marker = _parse_model_marker(ref)
            if not marker:
                continue
            key = _model_key_from_parts(
                marker['department'],
                marker['brand'],
                marker['model'],
            )
            if key not in current_models:
                current_models[key] = {
                    'department': marker['department'],
                    'brand': marker['brand'],
                    'model': marker['model'],
                    'description': marker.get('description') or '',
                    'quantity': 0,
                }
            current_models[key]['quantity'] += max(
                1,
                _safe_int(marker.get('quantity'), 1),
            )

    for source_row in template.get('models') or []:
        row = _normalise_planning_template_model(source_row)
        if not row:
            continue
        key = _model_key_from_parts(
            row['department'],
            row['brand'],
            row['model'],
        )
        if key in current_models:
            current_models[key]['quantity'] += row['quantity']
            if not current_models[key]['description'] and row['description']:
                current_models[key]['description'] = row['description']
        else:
            current_models[key] = dict(row)

    prepared_items = []
    for ref in getattr(event, 'prepared_items', []) or []:
        if _parse_model_marker(ref):
            continue
        if replace and _parse_custom_marker(ref):
            continue
        prepared_items.append(ref)

    for row in sorted(
        current_models.values(),
        key=lambda item: (
            item['department'],
            item['brand'].lower(),
            item['model'].lower(),
        ),
    ):
        prepared_items.append(_make_model_marker(row, row['quantity']))

    added_custom_markers = []
    for source_row in template.get('customAssets') or []:
        row = _normalise_planning_template_custom(source_row)
        if not row:
            continue
        marker = _make_custom_marker(
            row['type'],
            row['name'],
            row['quantity'],
            row['department'],
            row['company'],
            description=row.get('description') or '',
        )
        prepared_items.append(marker)
        added_custom_markers.append(marker)

    event.prepared_items = prepared_items
    _ensure_event_custom_lists(event)

    if replace:
        event.actually_prepared = [
            ref for ref in event.actually_prepared
            if not _parse_custom_marker(ref)
        ]
        event.returned_items = [
            ref for ref in event.returned_items
            if not _parse_custom_marker(ref)
        ]
        event.extra_assets = [
            ref for ref in event.extra_assets
            if not _parse_custom_marker(ref)
        ]
        event.custom_collected = [
            ref for ref in event.custom_collected
            if not _parse_custom_marker(ref)
        ]

    update_event_state(event)
    data_manager.save_event(event)
    invalidate_cache()

    return {
        'mode': mode,
        'modelCount': len(current_models),
        'customAssetCount': len(added_custom_markers),
    }


def _event_returnable_counts(event):
    """Return quantity counts for items that can currently be returned.

    This intentionally treats collected loan/rental items as returnable even if
    they were never finally prepared, because once they are collected from a
    rental company, they may still need to be returned.
    """
    _ensure_event_custom_lists(event)

    returned_items = list(getattr(event, 'returned_items', []) or [])
    returned_values = set(returned_items)
    active_refs = []
    seen_active = set()

    def add_active(ref):
        if not isinstance(ref, str) or not ref or ref in seen_active:
            return
        # Anonymous prepared model quantities move between the active and
        # returned lists in partial amounts. Their marker text is not an ID,
        # so an equal marker in returned_items must not hide the active units.
        if ref in returned_values and not _parse_prepared_model_marker(ref):
            return
        active_refs.append(ref)
        seen_active.add(ref)

    # Anything actually prepared is returnable unless already returned.
    for ref in getattr(event, 'actually_prepared', []) or []:
        add_active(ref)

    # Loan/rental items become returnable as soon as they are collected.
    for ref in getattr(event, 'prepared_items', []) or []:
        custom = _parse_custom_marker(ref)
        if not custom:
            continue
        if custom.get('type') == 'LOAN' and ref in getattr(event, 'custom_collected', []):
            add_active(ref)

    def ref_quantity(ref):
        custom = _parse_custom_marker(ref)
        if custom:
            return max(1, _safe_int(custom.get('quantity'), 1))

        bulk = _parse_bulk_marker(ref)
        if bulk:
            return max(1, _safe_int(bulk.get('quantity'), 1))

        prepared_model = _parse_prepared_model_marker(ref)
        if prepared_model:
            return max(1, _safe_int(prepared_model.get('quantity'), 1))

        return 1

    active_quantity = sum(ref_quantity(ref) for ref in active_refs)
    returned_quantity = sum(ref_quantity(ref) for ref in returned_items)

    return {
        'returnable': active_quantity,
        'returned': returned_quantity,
        'total': active_quantity + returned_quantity,
        'refs': active_refs
    }


def _event_specific_counts(event):
    """Counts non-model, non-custom, non-bulk direct asset rows for legacy/direct workflows.

    Assets explicitly marked as extra are deliberately excluded from these totals.
    This keeps manually over-prepared assets visible without letting them raise
    the event's required count or complete an otherwise incomplete event.
    """
    _ensure_event_custom_lists(event)
    extra_assets = set(getattr(event, 'extra_assets', []) or [])
    required = 0
    prepared_active = 0
    prepared_ever = 0
    returned = 0

    for item in event.prepared_items:
        if not isinstance(item, str):
            continue
        if item in extra_assets:
            continue
        if item.startswith('[MODEL]') or _is_prepared_model_ref(item) or _is_bulk_ref(item) or _is_custom_ref(item):
            continue
        required += 1

    all_seen = set(event.actually_prepared or []) | set(event.returned_items or [])
    for item in all_seen:
        if not isinstance(item, str):
            continue
        if item in extra_assets:
            continue
        if item.startswith('[MODEL]') or _is_prepared_model_ref(item) or _is_bulk_ref(item) or _is_custom_ref(item):
            continue
        if item in event.returned_items:
            returned += 1
            prepared_ever += 1
        elif item in event.actually_prepared:
            prepared_active += 1
            prepared_ever += 1

    return {
        'required': required,
        'preparedActive': prepared_active,
        'preparedEver': prepared_ever,
        'returned': returned
    }


def _event_department_progress_payload(event, model_groups, has_model_assignments):
    """Return compact per-department progress for event overview cards."""
    _ensure_event_custom_lists(event)
    state = str(getattr(event, 'state', '') or '')
    uses_returns = state in ('Returning', 'Overdue', 'Pending Closure', 'Closed')
    uses_out = state in ('Ongoing', 'Last Day')
    totals = {}

    def add(department, required, prepared=0, returned=0):
        code = _normalise_department_code(department) or 'UN'
        row = totals.setdefault(code, {'code': code, 'done': 0, 'total': 0})
        quantity = max(0, _safe_int(required, 0))
        prepared_quantity = max(0, _safe_int(prepared, 0))
        returned_quantity = max(0, _safe_int(returned, 0))
        if uses_returns:
            done = returned_quantity
        elif uses_out:
            done = max(prepared_quantity - returned_quantity, 0)
        elif state == 'New':
            done = 0
        else:
            done = prepared_quantity
        row['done'] += min(done, quantity) if quantity else 0
        row['total'] += quantity

    for group in model_groups.values():
        add(
            group.get('department'),
            group.get('requiredQuantity'),
            group.get('countablePreparedQuantity'),
            group.get('countableReturnedQuantity'),
        )

    for marker in event.prepared_items:
        custom = _parse_custom_marker(marker)
        if not custom:
            continue
        quantity = max(1, _safe_int(custom.get('quantity'), 1))
        is_returned = marker in event.returned_items
        is_prepared = marker in event.actually_prepared
        is_collected = custom['type'] == 'LOAN' and marker in event.custom_collected
        add(
            custom.get('department'),
            quantity,
            quantity if is_prepared or is_returned or is_collected else 0,
            quantity if is_returned else 0,
        )

    if not has_model_assignments:
        extra_assets = set(getattr(event, 'extra_assets', []) or [])
        for asset_id in dict.fromkeys(event.prepared_items):
            if (
                not isinstance(asset_id, str)
                or asset_id in extra_assets
                or asset_id.startswith('[MODEL]')
                or _is_prepared_model_ref(asset_id)
                or _is_bulk_ref(asset_id)
                or _is_custom_ref(asset_id)
            ):
                continue
            asset = data_manager.inventory.get(asset_id)
            add(
                getattr(asset, 'department_code', 'UN') if asset else 'UN',
                1,
                1 if asset_id in event.actually_prepared or asset_id in event.returned_items else 0,
                1 if asset_id in event.returned_items else 0,
            )

    return sorted(
        (row for row in totals.values() if row['total'] > 0),
        key=lambda row: (-row['total'], row['code']),
    )


def _event_extra_asset_quantity(event):
    """Active manual extras for the Event Summary card.

    Returned extras are no longer active extras. Custom and bulk quantities are
    respected if they are ever marked extra. Regular physical assets count as 1.
    """
    _ensure_event_custom_lists(event)
    returned_values = set(getattr(event, 'returned_items', []) or [])
    active_values = set(getattr(event, 'actually_prepared', []) or []) | set(getattr(event, 'prepared_items', []) or [])
    total = 0

    for ref in getattr(event, 'extra_assets', []) or []:
        if ref in returned_values:
            continue
        if ref not in active_values:
            continue

        custom = _parse_custom_marker(ref)
        if custom:
            total += max(1, _safe_int(custom.get('quantity'), 1))
            continue

        bulk = _parse_bulk_marker(ref)
        if bulk:
            total += max(1, _safe_int(bulk.get('quantity'), 1))
            continue

        total += 1

    return total


def _is_bulk_ref(value):
    return _parse_bulk_marker(value) is not None


def _is_prepared_model_ref(value):
    return _parse_prepared_model_marker(value) is not None


def _model_key_from_parts(dept, brand, model, description=''):
    return (
        _clean_group_value(dept, True),
        _clean_group_value(brand),
        _clean_group_value(model),
        ''
    )


def _event_physical_ref_group_key(value):
    """Return the inventory model key represented by an event physical ref."""
    prepared_marker = _parse_prepared_model_marker(value)
    if prepared_marker:
        return _model_key_from_parts(
            prepared_marker['department'],
            prepared_marker['brand'],
            prepared_marker['model'],
        )

    marker = _parse_bulk_marker(value)
    asset_id = marker['bulkId'] if marker else value
    asset = data_manager.inventory.get(asset_id) if data_manager else None
    if not asset:
        return None
    return _asset_group_key(asset)


def _group_from_request(data):
    data = data if isinstance(data, dict) else {}
    department = _normalise_department_code(data.get('department')) or ''
    brand = str(data.get('brand') or '').strip()
    model = str(data.get('model') or '').strip()
    description = str(data.get('description') or '').strip()
    if not department or not brand or not model:
        raise ValueError('Department, brand, and model are required')
    return {
        'department': department,
        'brand': brand,
        'model': model,
        'description': description,
    }


def _event_model_group_key(group):
    return _model_key_from_parts(group['department'], group['brand'], group['model'])


def _event_model_required_quantity(event, group):
    group_key = _event_model_group_key(group)
    total = 0
    description = group.get('description') or ''
    for ref in getattr(event, 'prepared_items', []) or []:
        marker = _parse_model_marker(ref)
        if not marker:
            continue
        marker_key = _model_key_from_parts(marker['department'], marker['brand'], marker['model'])
        if marker_key != group_key:
            continue
        total += max(0, _safe_int(marker.get('quantity'), 0))
        if not description and marker.get('description'):
            description = marker['description']
    if description and not group.get('description'):
        group['description'] = description
    return total


def _event_subproject(event, subproject_id):
    """Return a mutable event subproject row when the supplied ID is valid."""
    clean_id = str(subproject_id or '').strip()
    if not clean_id:
        return None
    for row in getattr(event, 'subprojects', []) or []:
        if isinstance(row, dict) and str(row.get('id') or '').strip() == clean_id:
            row.setdefault('items', [])
            return row
    return None


def _event_initial_subproject_items(event):
    """Build a Main Room payload without changing existing event requirements."""
    items = []
    seen_model_keys = set()

    for ref in getattr(event, 'prepared_items', []) or []:
        marker = _parse_model_marker(ref)
        if marker:
            group = {
                'department': marker['department'],
                'brand': marker['brand'],
                'model': marker['model'],
                'description': marker.get('description') or '',
            }
            group_key = _event_model_group_key(group)
            if group_key in seen_model_keys:
                continue
            seen_model_keys.add(group_key)
            items.append({
                'department': group['department'],
                'departmentCode': group['department'],
                'brand': group['brand'],
                'model': group['model'],
                'description': group['description'],
                'quantity': max(0, _safe_int(marker.get('quantity'), 0)),
                'isCustom': False,
            })
            continue

        custom = _parse_custom_marker(ref)
        if custom:
            items.append({
                'department': custom.get('department') or 'UN',
                'departmentCode': custom.get('department') or 'UN',
                'brand': '',
                'model': '',
                'description': custom.get('name') or '',
                'quantity': max(1, _safe_int(custom.get('quantity'), 1)),
                'isCustom': True,
                'assetRefs': [ref],
            })

    # Very old events can retain model requirements only in asset_models.
    # Match those rows against inventory so adding rooms does not discard them.
    inventory_groups = {}
    for asset in data_manager.inventory.values():
        if not asset or _is_disposed(asset):
            continue
        group = _asset_group_from_item(asset)
        inventory_groups.setdefault(_display_model_description(group), group)

    for row in getattr(event, 'asset_models', []) or []:
        if not isinstance(row, dict):
            continue
        group = inventory_groups.get(str(
            row.get('model_description')
            or row.get('modelDescription')
            or ''
        ).strip())
        if not group:
            continue
        group_key = _event_model_group_key(group)
        if group_key in seen_model_keys:
            continue
        seen_model_keys.add(group_key)
        items.append({
            'department': group['department'],
            'departmentCode': group['department'],
            'brand': group['brand'],
            'model': group['model'],
            'description': group['description'],
            'quantity': max(0, _safe_int(row.get('quantity'), 0)),
            'isCustom': False,
        })

    return [item for item in items if item.get('quantity', 0) > 0]


def _event_allocate_existing_refs_to_initial_subproject(event, subproject):
    """Attach legacy aggregate preparation state to the initial Main Room."""
    if not subproject:
        return

    items_by_group = {}
    for item in subproject.get('items') or []:
        group = _event_subproject_item_group(item)
        if group:
            items_by_group[_event_model_group_key(group)] = item

    for ref in getattr(event, 'actually_prepared', []) or []:
        marker = _parse_prepared_model_marker(ref)
        if not marker:
            continue
        item = items_by_group.get(_event_model_group_key(marker))
        if item:
            item['preparedQuantity'] = (
                max(0, _safe_int(item.get('preparedQuantity'), 0))
                + max(1, _safe_int(marker.get('quantity'), 1))
            )

    extra_refs = subproject.setdefault('extraRefs', [])
    reference_lists = [
        values for values in _event_reference_lists(event)
        if isinstance(values, list)
    ]
    all_refs = []
    for values in reference_lists:
        for ref in values:
            if ref not in all_refs:
                all_refs.append(ref)

    for ref in all_refs:
        if _parse_model_marker(ref) or _parse_prepared_model_marker(ref):
            continue
        if _parse_custom_marker(ref):
            continue

        allocated_ref = ref
        bulk = _parse_bulk_marker(ref)
        if bulk:
            allocated_ref = _bulk_marker(
                bulk.get('bulkId'),
                bulk.get('quantity', 1),
                subproject.get('id') or 'main',
            )
            if allocated_ref != ref:
                for values in reference_lists:
                    values[:] = [
                        allocated_ref if value == ref else value
                        for value in values
                    ]
            asset = data_manager.inventory.get(bulk.get('bulkId'))
        else:
            asset = data_manager.inventory.get(ref)

        item = (
            items_by_group.get(_asset_group_key(asset))
            if asset
            else None
        )
        target_refs = item.setdefault('assetRefs', []) if item else extra_refs
        if allocated_ref not in target_refs:
            target_refs.append(allocated_ref)


def _event_subproject_refs(subproject):
    refs = list(subproject.get('extraRefs') or []) if subproject else []
    for item in subproject.get('items') or [] if subproject else []:
        if isinstance(item, dict):
            refs.extend(item.get('assetRefs') or [])
    return list(dict.fromkeys(str(ref) for ref in refs if ref))


def _event_merge_subproject(event, source, target):
    """Merge room requirements and allocations without changing event totals."""
    for source_item in source.get('items') or []:
        if not isinstance(source_item, dict):
            continue
        moving_item = copy.deepcopy(source_item)
        moving_refs = []
        for ref in moving_item.get('assetRefs') or []:
            moved_ref = ref
            bulk = _parse_bulk_marker(ref)
            if bulk:
                moved_ref = _bulk_marker(
                    bulk.get('bulkId'),
                    bulk.get('quantity', 1),
                    target.get('id') or '',
                )
                _event_replace_reference(event, ref, moved_ref)
            if moved_ref not in moving_refs:
                moving_refs.append(moved_ref)
        if moving_refs or 'assetRefs' in moving_item:
            moving_item['assetRefs'] = moving_refs

        source_group = _event_subproject_item_group(source_item)
        if not source_group:
            target.setdefault('items', []).append(moving_item)
            continue

        matches = _event_subproject_group_items(target, source_group)
        if not matches:
            target.setdefault('items', []).append(moving_item)
            continue

        target_item = matches[0]
        target_item['quantity'] = (
            max(0, _safe_int(round(_safe_float(target_item.get('quantity'), 0)), 0))
            + max(0, _safe_int(round(_safe_float(moving_item.get('quantity'), 0)), 0))
        )
        target_item['preparedQuantity'] = (
            max(0, _safe_int(target_item.get('preparedQuantity'), 0))
            + max(0, _safe_int(moving_item.get('preparedQuantity'), 0))
        )
        target_refs = target_item.setdefault('assetRefs', [])
        for moved_ref in moving_item.get('assetRefs') or []:
            if moved_ref not in target_refs:
                target_refs.append(moved_ref)

    target_extra_refs = target.setdefault('extraRefs', [])
    for ref in source.get('extraRefs') or []:
        moved_ref = ref
        bulk = _parse_bulk_marker(ref)
        if bulk:
            moved_ref = _bulk_marker(
                bulk.get('bulkId'),
                bulk.get('quantity', 1),
                target.get('id') or '',
            )
            _event_replace_reference(event, ref, moved_ref)
        if moved_ref not in target_extra_refs:
            target_extra_refs.append(moved_ref)


def _event_replace_reference(event, old_ref, new_ref):
    if old_ref == new_ref:
        return
    for values in [
        *_event_reference_lists(event),
        getattr(event, 'custom_collected', []) or [],
    ]:
        if not isinstance(values, list):
            continue
        values[:] = [new_ref if ref == old_ref else ref for ref in values]


def _event_remove_subproject_contents(event, subproject):
    """Remove one room's requirements and allocated event assets."""
    refs_to_remove = set(_event_subproject_refs(subproject))
    room_id = str(subproject.get('id') or '')
    inventory_changed = False

    for item in subproject.get('items') or []:
        group = _event_subproject_item_group(item)
        if group:
            _decrement_prepared_model_slot(
                event,
                group,
                max(0, _safe_int(item.get('preparedQuantity'), 0)),
            )

    for values in _event_reference_lists(event):
        if not isinstance(values, list):
            continue
        for ref in values:
            marker = _parse_bulk_marker(ref)
            if marker and marker.get('subprojectId') == room_id:
                refs_to_remove.add(ref)

    for values in [
        *_event_reference_lists(event),
        getattr(event, 'custom_collected', []) or [],
    ]:
        if isinstance(values, list):
            values[:] = [ref for ref in values if ref not in refs_to_remove]

    for ref in refs_to_remove:
        marker = _parse_bulk_marker(ref)
        asset_id = marker.get('bulkId') if marker else ref
        if _parse_custom_marker(ref) or _parse_prepared_model_marker(ref):
            continue
        asset = data_manager.inventory.get(asset_id)
        if asset and not _is_bulk_asset(asset):
            default_location = asset.default_location or ''
            if asset.current_location != default_location:
                asset.current_location = default_location
                inventory_changed = True

    if inventory_changed:
        data_manager.save_inventory()
    return len(refs_to_remove)


def _event_move_subproject_requirement(event, source, target, group):
    source_items = _event_subproject_group_items(source, group)
    if not source_items:
        raise ValueError('Requirement was not found in the source room')
    moving = {
        'items': source_items,
        'extraRefs': [],
    }
    _event_merge_subproject(event, moving, target)
    source_ids = {id(item) for item in source_items}
    source['items'] = [
        item for item in source.get('items') or []
        if id(item) not in source_ids
    ]


def _event_move_subproject_asset(event, source, target, asset_ref):
    source_refs = _event_subproject_refs(source)
    if asset_ref not in source_refs:
        raise ValueError('Asset was not found in the source room')

    source['extraRefs'] = [
        ref for ref in source.get('extraRefs') or [] if ref != asset_ref
    ]
    source_item = None
    for item in source.get('items') or []:
        if asset_ref in (item.get('assetRefs') or []):
            source_item = item
            item['assetRefs'] = [
                ref for ref in item.get('assetRefs') or [] if ref != asset_ref
            ]
            break

    custom = _parse_custom_marker(asset_ref)
    if custom and source_item and source_item.get('isCustom'):
        source['items'] = [
            item for item in source.get('items') or [] if item is not source_item
        ]
        target.setdefault('items', []).append(source_item)
        return asset_ref

    bulk = _parse_bulk_marker(asset_ref)
    asset = data_manager.inventory.get(
        bulk.get('bulkId') if bulk else asset_ref
    )
    group = _asset_group_from_item(asset) if asset else None
    target_item = (
        (_event_subproject_group_items(target, group) or [None])[0]
        if group
        else None
    )
    if not target_item:
        if source_item:
            raise ValueError(
                'The destination room does not require this asset model'
            )
        target_refs = target.setdefault('extraRefs', [])
    else:
        target_refs = target_item.setdefault('assetRefs', [])

    moved_ref = asset_ref
    if bulk:
        moved_ref = _bulk_marker(
            bulk.get('bulkId'),
            bulk.get('quantity', 1),
            target.get('id') or '',
        )
        _event_replace_reference(event, asset_ref, moved_ref)
    if moved_ref not in target_refs:
        target_refs.append(moved_ref)
    return moved_ref


def _event_subproject_item_group(item):
    if not isinstance(item, dict) or item.get('isCustom'):
        return None
    department = _normalise_department_code(
        item.get('departmentCode') or item.get('department')
    ) or ''
    brand = str(item.get('brand') or '').strip()
    model = str(item.get('model') or '').strip()
    if not department or not brand or not model:
        return None
    return {
        'department': department,
        'brand': brand,
        'model': model,
        'description': str(item.get('description') or '').strip(),
    }


def _event_subproject_group_items(subproject, group):
    if not subproject:
        return []
    group_key = _event_model_group_key(group)
    matches = []
    for item in subproject.get('items') or []:
        item_group = _event_subproject_item_group(item)
        if item_group and _event_model_group_key(item_group) == group_key:
            matches.append(item)
    return matches


def _event_subproject_required_quantity(subproject, group):
    return sum(
        max(0, _safe_int(round(_safe_float(item.get('quantity'), 0)), 0))
        for item in _event_subproject_group_items(subproject, group)
    )


def _event_subproject_set_group_quantity(subproject, group, quantity):
    """Set one room's model quantity while retaining quotation line metadata."""
    quantity = max(0, _safe_int(quantity, 0))
    matches = _event_subproject_group_items(subproject, group)
    if not matches and quantity <= 0:
        return
    if not matches:
        subproject.setdefault('items', []).append({
            'lineId': f"plan_{secrets.token_hex(8)}",
            'department': group['department'],
            'departmentCode': group['department'],
            'brand': group['brand'],
            'model': group['model'],
            'description': group.get('description') or '',
            'quantity': quantity,
            'isCustom': False,
            'preparedQuantity': 0,
            'assetRefs': [],
        })
        return

    primary = matches[0]
    for duplicate in matches[1:]:
        for field in ('preparedQuantity', 'returnedPreparedQuantity'):
            if field in duplicate:
                primary[field] = (
                    max(0, _safe_int(primary.get(field), 0))
                    + max(0, _safe_int(duplicate.get(field), 0))
                )
        primary_refs = primary.setdefault('assetRefs', [])
        for ref in duplicate.get('assetRefs') or []:
            if ref not in primary_refs:
                primary_refs.append(ref)

    primary['quantity'] = quantity
    if group.get('description') and not primary.get('description'):
        primary['description'] = group['description']
    duplicate_ids = {id(item) for item in matches[1:]}
    retain_zero_quantity_row = any((
        max(0, _safe_int(primary.get('preparedQuantity'), 0)) > 0,
        max(0, _safe_int(primary.get('returnedPreparedQuantity'), 0)) > 0,
        bool(primary.get('assetRefs')),
    ))
    subproject['items'] = [
        item for item in subproject.get('items') or []
        if id(item) not in duplicate_ids
        and (item is not primary or quantity > 0 or retain_zero_quantity_row)
    ]


def _sync_event_model_markers_from_subprojects(event):
    """Rebuild aggregate model markers from room requirements."""
    totals = {}
    for subproject in getattr(event, 'subprojects', []) or []:
        if not isinstance(subproject, dict):
            continue
        for item in subproject.get('items') or []:
            group = _event_subproject_item_group(item)
            if not group:
                continue
            key = _event_model_group_key(group)
            row = totals.setdefault(key, {**group, 'quantity': 0})
            row['quantity'] += max(
                0,
                _safe_int(round(_safe_float(item.get('quantity'), 0)), 0),
            )
            if not row.get('description') and group.get('description'):
                row['description'] = group['description']

    preserved = [
        ref for ref in getattr(event, 'prepared_items', []) or []
        if not _parse_model_marker(ref)
    ]
    for row in totals.values():
        if row['quantity'] > 0:
            preserved.append(_make_model_marker(row, row['quantity']))
    event.prepared_items = preserved


def _event_subproject_adjust_prepared(subproject, group, delta):
    matches = _event_subproject_group_items(subproject, group)
    if not matches:
        return 0
    item = matches[0]
    current = max(0, _safe_int(item.get('preparedQuantity'), 0))
    updated = max(0, current + _safe_int(delta, 0))
    item['preparedQuantity'] = updated
    return updated


def _event_subproject_adjust_returned_prepared(subproject, group, delta):
    matches = _event_subproject_group_items(subproject, group)
    if not matches:
        return 0
    item = matches[0]
    current = max(0, _safe_int(item.get('returnedPreparedQuantity'), 0))
    updated = max(0, current + _safe_int(delta, 0))
    item['returnedPreparedQuantity'] = updated
    return updated


def _event_subproject_anonymous_prepared_quantity(subproject, group):
    return sum(
        max(0, _safe_int(item.get('preparedQuantity'), 0))
        for item in _event_subproject_group_items(subproject, group)
    )


def _event_subproject_returned_prepared_quantity(subproject, group):
    return sum(
        max(0, _safe_int(item.get('returnedPreparedQuantity'), 0))
        for item in _event_subproject_group_items(subproject, group)
    )


def _event_subproject_prepared_quantity(event, subproject, group):
    total = _event_subproject_anonymous_prepared_quantity(subproject, group)
    returned = set(getattr(event, 'returned_items', []) or [])
    active = set(getattr(event, 'actually_prepared', []) or [])
    extra_refs = set(getattr(event, 'extra_assets', []) or [])
    extra_refs.update(subproject.get('extraRefs') or [])
    seen = set()
    for item in _event_subproject_group_items(subproject, group):
        for ref in item.get('assetRefs') or []:
            if ref in seen or ref in returned or ref not in active or ref in extra_refs:
                continue
            seen.add(ref)
            bulk = _parse_bulk_marker(ref)
            total += bulk['quantity'] if bulk else 1
    return total


def _event_subproject_assign_ref(subproject, group, asset_ref, consume_slot=False):
    matches = _event_subproject_group_items(subproject, group)
    if not matches:
        return False
    item = matches[0]
    refs = item.setdefault('assetRefs', [])
    if asset_ref not in refs:
        refs.append(asset_ref)
    if consume_slot:
        _event_subproject_adjust_prepared(subproject, group, -1)
    return True


def _event_subproject_ref_quantity(ref):
    bulk = _parse_bulk_marker(ref)
    if bulk:
        return max(1, _safe_int(bulk.get('quantity'), 1))
    prepared = _parse_prepared_model_marker(ref)
    if prepared:
        return max(1, _safe_int(prepared.get('quantity'), 1))
    custom = _parse_custom_marker(ref)
    if custom:
        return max(1, _safe_int(custom.get('quantity'), 1))
    return 1


def _reconcile_event_subproject_extras(event):
    """Make normal/extra preparation ownership authoritative per room.

    Exact references that fit a room requirement live on that requirement's
    ``assetRefs``. Surplus or unmatched references live in the same room's
    ``extraRefs`` and are mirrored into the event-wide ``extra_assets`` list for
    consolidated/legacy consumers. Increasing a requirement promotes matching
    room extras in their existing order; reducing it demotes the latest refs.
    """
    rooms = [
        room for room in (getattr(event, 'subprojects', []) or [])
        if isinstance(room, dict)
    ]
    if not rooms:
        return {'changed': False, 'promoted': [], 'demoted': []}

    _ensure_event_custom_lists(event)
    original_rooms = copy.deepcopy(rooms)
    original_extras = list(event.extra_assets)
    original_prepared_items = list(event.prepared_items)
    active_physical = set(getattr(event, 'actually_prepared', []) or [])
    active_physical.update(getattr(event, 'returned_items', []) or [])
    valid_refs = set(active_physical)
    valid_refs.update(getattr(event, 'prepared_items', []) or [])
    valid_refs.update(getattr(event, 'custom_collected', []) or [])

    promoted = []
    demoted = []
    claimed = set()

    for room in rooms:
        candidate_extras = []
        for ref in room.get('extraRefs') or []:
            if ref in valid_refs and ref not in candidate_extras and ref not in claimed:
                candidate_extras.append(ref)

        for item in room.get('items') or []:
            if not isinstance(item, dict):
                continue

            if item.get('isCustom'):
                custom_refs = []
                for ref in item.get('assetRefs') or []:
                    if ref in valid_refs and ref not in claimed and ref not in custom_refs:
                        custom_refs.append(ref)
                        claimed.add(ref)
                item['assetRefs'] = custom_refs
                continue

            group = _event_subproject_item_group(item)
            if not group:
                continue
            group_key = _event_model_group_key(group)
            required = max(0, _safe_int(round(_safe_float(item.get('quantity'), 0)), 0))
            anonymous = (
                max(0, _safe_int(item.get('preparedQuantity'), 0))
                + max(0, _safe_int(item.get('returnedPreparedQuantity'), 0))
            )
            remaining = max(0, required - anonymous)
            normal_refs = []

            for ref in item.get('assetRefs') or []:
                if ref not in active_physical or ref in claimed or ref in normal_refs:
                    continue
                if _event_physical_ref_group_key(ref) != group_key:
                    if ref not in candidate_extras:
                        candidate_extras.append(ref)
                    continue
                quantity = _event_subproject_ref_quantity(ref)
                partially_fills_bulk_requirement = bool(
                    remaining > 0 and _parse_bulk_marker(ref)
                )
                if quantity <= remaining or partially_fills_bulk_requirement:
                    normal_refs.append(ref)
                    claimed.add(ref)
                    remaining = max(0, remaining - quantity)
                else:
                    if ref not in candidate_extras:
                        candidate_extras.append(ref)
                    if ref not in demoted:
                        demoted.append(ref)

            for ref in list(candidate_extras):
                if ref not in active_physical or ref in claimed:
                    continue
                if _event_physical_ref_group_key(ref) != group_key:
                    continue
                quantity = _event_subproject_ref_quantity(ref)
                partially_fills_bulk_requirement = bool(
                    remaining > 0 and _parse_bulk_marker(ref)
                )
                if quantity > remaining and not partially_fills_bulk_requirement:
                    continue
                normal_refs.append(ref)
                claimed.add(ref)
                remaining = max(0, remaining - quantity)
                candidate_extras.remove(ref)
                if ref not in promoted:
                    promoted.append(ref)

            item['assetRefs'] = normal_refs

        room_extras = []
        for ref in candidate_extras:
            if ref not in valid_refs or ref in claimed or ref in room_extras:
                continue
            room_extras.append(ref)
            claimed.add(ref)
        room['extraRefs'] = room_extras

    room_owned_refs = set()
    room_extra_refs = []
    for room in rooms:
        for ref in room.get('extraRefs') or []:
            room_owned_refs.add(ref)
            if ref not in room_extra_refs:
                room_extra_refs.append(ref)
        for item in room.get('items') or []:
            room_owned_refs.update(item.get('assetRefs') or [])

    room_extra_ref_set = set(room_extra_refs)
    promoted = [ref for ref in promoted if ref not in room_extra_ref_set]
    demoted = [ref for ref in demoted if ref in room_extra_ref_set]

    preserved_global_extras = [
        ref for ref in event.extra_assets
        if ref not in room_owned_refs and ref in valid_refs
    ]
    event.extra_assets = list(dict.fromkeys([
        *preserved_global_extras,
        *room_extra_refs,
    ]))

    normal_room_refs = room_owned_refs - room_extra_ref_set
    for ref in normal_room_refs:
        if _is_real_asset_ref(ref) and not _is_bulk_ref(ref):
            _remove_direct_asset_ref_from_prepared_items(event, ref)

    return {
        'changed': (
            original_rooms != rooms
            or original_extras != event.extra_assets
            or original_prepared_items != event.prepared_items
        ),
        'promoted': promoted,
        'demoted': demoted,
    }


def _event_subproject_assign_custom_ref(subproject, custom, asset_ref):
    if not subproject or not custom:
        return False
    department = _normalise_department_code(custom.get('department')) or 'UN'
    name = str(custom.get('name') or '').strip().casefold()
    for item in subproject.get('items') or []:
        if not isinstance(item, dict) or not item.get('isCustom'):
            continue
        item_department = _normalise_department_code(
            item.get('departmentCode') or item.get('department')
        ) or 'UN'
        item_name = str(item.get('description') or '').strip().casefold()
        if item_department != department or item_name != name:
            continue
        refs = item.setdefault('assetRefs', [])
        if asset_ref not in refs:
            refs.append(asset_ref)
        return True
    return False


def _event_subproject_remove_ref(event, asset_ref):
    for subproject in getattr(event, 'subprojects', []) or []:
        if not isinstance(subproject, dict):
            continue
        subproject['extraRefs'] = [
            ref for ref in subproject.get('extraRefs') or [] if ref != asset_ref
        ]
        for item in subproject.get('items') or []:
            if isinstance(item, dict):
                item['assetRefs'] = [
                    ref for ref in item.get('assetRefs') or [] if ref != asset_ref
                ]


def _event_prepared_slot_quantity(event, group):
    group_key = _event_model_group_key(group)
    total = 0
    for ref in getattr(event, 'actually_prepared', []) or []:
        marker = _parse_prepared_model_marker(ref)
        if not marker:
            continue
        marker_key = _model_key_from_parts(marker['department'], marker['brand'], marker['model'])
        if marker_key == group_key:
            total += marker['quantity']
    return total


def _event_returned_prepared_slot_quantity(event, group):
    group_key = _event_model_group_key(group)
    total = 0
    for ref in getattr(event, 'returned_items', []) or []:
        marker = _parse_prepared_model_marker(ref)
        if not marker:
            continue
        marker_key = _model_key_from_parts(marker['department'], marker['brand'], marker['model'])
        if marker_key == group_key:
            total += marker['quantity']
    return total


def _event_specific_asset_quantity(event, group, include_returned=False, include_extra=True):
    group_key = _event_model_group_key(group)
    values = list(getattr(event, 'actually_prepared', []) or [])
    if include_returned:
        values.extend(getattr(event, 'returned_items', []) or [])
    extra_assets = set(getattr(event, 'extra_assets', []) or [])
    seen = set()
    total = 0
    for ref in values:
        if ref in seen:
            continue
        seen.add(ref)
        if not include_extra and ref in extra_assets:
            continue
        if _is_bulk_ref(ref) or _is_prepared_model_ref(ref) or _is_custom_ref(ref):
            continue
        asset = data_manager.inventory.get(ref) if data_manager else None
        if asset and _asset_group_key(asset) == group_key:
            total += 1
    return total


def _event_bulk_quantity_for_group(
    event,
    group,
    include_returned=False,
    subproject_id=None,
):
    group_key = _event_model_group_key(group)
    values = list(getattr(event, 'actually_prepared', []) or [])
    if include_returned:
        values.extend(getattr(event, 'returned_items', []) or [])
    if subproject_id is not None:
        values = [
            value for value in values
            if (_parse_bulk_marker(value) or {}).get('subprojectId', '') ==
                str(subproject_id or '')
        ]
    return _bulk_quantity_in_values_for_key(values, group_key)


def _event_active_prepared_quantity_for_group(event, group, include_extra=True):
    slot_qty = _event_prepared_slot_quantity(event, group)
    specific_qty = _event_specific_asset_quantity(event, group, include_returned=False, include_extra=include_extra)
    bulk_qty = _event_bulk_quantity_for_group(event, group, include_returned=False)
    return slot_qty + specific_qty + bulk_qty


def _event_prepared_open_slots(event, group):
    prepared_slots = _event_prepared_slot_quantity(event, group)
    return max(0, prepared_slots)


def _decrement_prepared_model_marker_list(event, list_name, group, quantity=1):
    remaining = max(1, _safe_int(quantity, 1))
    removed = 0
    group_key = _event_model_group_key(group)
    rebuilt = []
    for ref in getattr(event, list_name, []) or []:
        marker = _parse_prepared_model_marker(ref)
        if not marker:
            rebuilt.append(ref)
            continue
        marker_key = _model_key_from_parts(marker['department'], marker['brand'], marker['model'])
        if marker_key != group_key or remaining <= 0:
            rebuilt.append(ref)
            continue
        take = min(marker['quantity'], remaining)
        left = marker['quantity'] - take
        removed += take
        remaining -= take
        if left > 0:
            rebuilt.append(_prepared_model_marker(marker, left))
    setattr(event, list_name, rebuilt)
    return removed


def _increment_prepared_model_marker_list(event, list_name, group, quantity):
    quantity = max(1, _safe_int(quantity, 1))
    group_key = _event_model_group_key(group)
    rebuilt = []
    added = False
    for ref in getattr(event, list_name, []) or []:
        marker = _parse_prepared_model_marker(ref)
        if not marker:
            rebuilt.append(ref)
            continue
        marker_key = _model_key_from_parts(marker['department'], marker['brand'], marker['model'])
        if marker_key == group_key and not added:
            marker['quantity'] += quantity
            if not marker.get('description') and group.get('description'):
                marker['description'] = group['description']
            rebuilt.append(_prepared_model_marker(marker, marker['quantity']))
            added = True
        else:
            rebuilt.append(ref)
    if not added:
        rebuilt.append(_prepared_model_marker(group, quantity))
    setattr(event, list_name, rebuilt)
    return quantity


def _decrement_prepared_model_slot(event, group, quantity=1):
    return _decrement_prepared_model_marker_list(
        event, 'actually_prepared', group, quantity
    )


def _increment_prepared_model_slot(event, group, quantity):
    return _increment_prepared_model_marker_list(
        event, 'actually_prepared', group, quantity
    )


def _decrement_returned_prepared_model_slot(event, group, quantity=1):
    return _decrement_prepared_model_marker_list(
        event, 'returned_items', group, quantity
    )


def _increment_returned_prepared_model_slot(event, group, quantity):
    return _increment_prepared_model_marker_list(
        event, 'returned_items', group, quantity
    )


def _matching_bulk_assets_for_group(group):
    group_key = _event_model_group_key(group)
    return [
        asset for asset in (data_manager.inventory.values() if data_manager else [])
        if asset and _is_bulk_asset(asset) and _asset_group_key(asset) == group_key
    ]


def _matching_specific_assets_for_group(group):
    group_key = _event_model_group_key(group)
    return [
        asset for asset in (data_manager.inventory.values() if data_manager else [])
        if asset and not _is_bulk_asset(asset) and _asset_group_key(asset) == group_key
    ]


def _event_group_is_bulk_quantity(group):
    bulk_assets = _matching_bulk_assets_for_group(group)
    specific_assets = _matching_specific_assets_for_group(group)
    return bool(bulk_assets) and not specific_assets


def _specific_prepare_capacity_for_event(event, group):
    total = 0
    for asset in _matching_specific_assets_for_group(group):
        if _is_disposed(asset) or getattr(asset, 'is_ooc', False) or getattr(asset, 'is_missing', False):
            continue
        if _find_event_using_asset(asset.asset_id, event):
            continue
        total += 1
    return total


def _bulk_prepare_capacity_for_event(event, group):
    return sum(
        _bulk_available_quantity_for_event(asset, event)
        for asset in _matching_bulk_assets_for_group(group)
    )


def _event_prepare_capacity_for_group(event, group):
    if _event_group_is_bulk_quantity(group):
        return _bulk_prepare_capacity_for_event(event, group)
    return _specific_prepare_capacity_for_event(event, group)


def _active_bulk_quantity_for_asset(event, bulk_id, subproject_id=None):
    returned = set(getattr(event, 'returned_items', []) or [])
    total = 0
    for ref in getattr(event, 'actually_prepared', []) or []:
        if ref in returned:
            continue
        marker = _parse_bulk_marker(ref)
        if (
            marker
            and marker['bulkId'] == bulk_id
            and (
                subproject_id is None
                or marker.get('subprojectId', '') == str(subproject_id or '')
            )
        ):
            total += marker['quantity']
    return total


def _set_bulk_quantity_for_asset(event, bulk_id, quantity, subproject_id=None):
    quantity = max(0, _safe_int(quantity, 0))
    returned = set(getattr(event, 'returned_items', []) or [])
    rebuilt = []
    inserted = False
    for ref in getattr(event, 'actually_prepared', []) or []:
        marker = _parse_bulk_marker(ref)
        marker_matches_scope = (
            marker
            and marker['bulkId'] == bulk_id
            and (
                subproject_id is None
                or marker.get('subprojectId', '') == str(subproject_id or '')
            )
        )
        if not marker_matches_scope or ref in returned:
            rebuilt.append(ref)
            continue
        if not inserted and quantity > 0:
            rebuilt.append(_bulk_marker(bulk_id, quantity, subproject_id or ''))
            inserted = True
    if not inserted and quantity > 0:
        rebuilt.append(_bulk_marker(bulk_id, quantity, subproject_id or ''))
    event.actually_prepared = rebuilt


def _add_bulk_prepared_quantity(event, group, quantity, subproject_id=None):
    remaining = max(1, _safe_int(quantity, 1))
    added = 0
    for asset in sorted(_matching_bulk_assets_for_group(group), key=lambda item: item.asset_id):
        capacity = _bulk_available_quantity_for_event(asset, event)
        current = _active_bulk_quantity_for_asset(
            event,
            asset.asset_id,
            subproject_id,
        )
        current_total = _active_bulk_quantity_for_asset(event, asset.asset_id)
        room = max(0, capacity - current_total)
        if room <= 0:
            continue
        take = min(room, remaining)
        _set_bulk_quantity_for_asset(
            event,
            asset.asset_id,
            current + take,
            subproject_id,
        )
        added += take
        remaining -= take
        if remaining <= 0:
            break
    return added


def _remove_bulk_prepared_quantity(event, group, quantity, subproject_id=None):
    remaining = max(1, _safe_int(quantity, 1))
    removed = 0
    for asset in sorted(_matching_bulk_assets_for_group(group), key=lambda item: item.asset_id, reverse=True):
        current = _active_bulk_quantity_for_asset(
            event,
            asset.asset_id,
            subproject_id,
        )
        if current <= 0:
            continue
        take = min(current, remaining)
        _set_bulk_quantity_for_asset(
            event,
            asset.asset_id,
            current - take,
            subproject_id,
        )
        removed += take
        remaining -= take
        if remaining <= 0:
            break
    return removed



def _reclassify_event_model_surplus(event, group_key, required_quantity):
    """Keep over-prepared model units attached to the event as explicit extras."""
    _ensure_event_custom_lists(event)
    required_quantity = max(0, _safe_int(required_quantity, 0))
    existing_extras = set(event.extra_assets)
    candidates = []
    seen = set()

    for values in (
        getattr(event, 'actually_prepared', []) or [],
        getattr(event, 'returned_items', []) or [],
    ):
        for ref in values:
            if ref in seen or ref in existing_extras:
                continue
            if _event_physical_ref_group_key(ref) != group_key:
                continue
            seen.add(ref)
            bulk = _parse_bulk_marker(ref)
            prepared = _parse_prepared_model_marker(ref)
            quantity = (
                bulk['quantity'] if bulk
                else prepared['quantity'] if prepared
                else 1
            )
            candidates.append((ref, quantity))

    surplus = max(0, sum(quantity for _ref, quantity in candidates) - required_quantity)
    marked_units = 0
    marked_refs = 0

    # The most recently prepared/assigned references become spare first.
    for ref, quantity in reversed(candidates):
        if surplus <= 0:
            break
        # Aggregate bulk/anonymous markers stay intact when only part of their
        # quantity is surplus. Their extra count is derived from prepared minus
        # required; splitting equal markers would make their identity ambiguous.
        if quantity > surplus:
            continue
        if ref not in event.extra_assets:
            event.extra_assets.append(ref)
        marked_units += quantity
        marked_refs += 1
        surplus -= quantity

    return {
        'extraUnits': marked_units,
        'referencesMarked': marked_refs,
    }


def _bulk_quantity_in_values_for_key(values, group_key):
    total = 0
    for value in values or []:
        marker = _parse_bulk_marker(value)
        if not marker:
            continue

        bulk_asset = data_manager.inventory.get(marker['bulkId']) if data_manager else None
        if not bulk_asset or not _is_bulk_asset(bulk_asset):
            continue

        if _asset_group_key(bulk_asset) == group_key:
            total += marker['quantity']

    return total


def _bulk_quantity_for_asset_in_values(values, bulk_id):
    total = 0
    for value in values or []:
        marker = _parse_bulk_marker(value)
        if marker and marker['bulkId'] == bulk_id:
            total += marker['quantity']
    return total


def _format_event_date_for_response(date_value):
    if not date_value:
        return ''
    try:
        return format_date_output(date_value)
    except Exception:
        return str(date_value)


def _bulk_deployments_for_asset(bulk_id):
    deployments = []
    if not bulk_id or not data_manager:
        return deployments

    for event in data_manager.events.values():
        if has_request_context() and not _current_user_can_access_event(event):
            continue
        prepared_qty = _bulk_quantity_for_asset_in_values(
            getattr(event, 'actually_prepared', []) or [],
            bulk_id
        )
        returned_qty = _bulk_quantity_for_asset_in_values(
            getattr(event, 'returned_items', []) or [],
            bulk_id
        )
        deployed_qty = max(prepared_qty - returned_qty, 0)
        if deployed_qty <= 0:
            continue

        deployments.append({
            'eventId': event.event_id,
            'eventName': getattr(event, 'name', '') or f"Event {event.event_id}",
            'startDate': _format_event_date_for_response(getattr(event, 'start_date', '')),
            'endDate': _format_event_date_for_response(getattr(event, 'end_date', '')),
            'quantity': deployed_qty,
            '_sortStartDate': getattr(event, 'start_date', '') or '',
            '_sortEndDate': getattr(event, 'end_date', '') or '',
        })

    deployments.sort(key=lambda row: (row['_sortStartDate'], row['_sortEndDate'], row['eventId']))
    for row in deployments:
        row.pop('_sortStartDate', None)
        row.pop('_sortEndDate', None)

    return deployments


def _asset_usage_days(asset_id, events=None, today=None):
    """Return unique elapsed event days on which an asset was deployed."""
    manager = _current_data_manager_object()
    asset = (getattr(manager, 'inventory', {}) or {}).get(str(asset_id or ''))
    if not asset:
        return 0

    is_bulk = _is_bulk_asset(asset)
    today = today or datetime.now().date()
    intervals = []

    source_events = (
        events
        if events is not None
        else (getattr(manager, 'events', {}) or {}).values()
    )
    for event in source_events:
        if str(getattr(event, 'state', '') or '').strip().casefold() == 'cancelled':
            continue

        deployed = False
        event_refs = (
            list(getattr(event, 'actually_prepared', []) or [])
            + list(getattr(event, 'returned_items', []) or [])
        )
        for ref in event_refs:
            if is_bulk:
                marker = _parse_bulk_marker(ref)
                if marker and marker.get('bulkId') == asset.asset_id:
                    deployed = True
                    break
            elif str(ref or '').strip() == asset.asset_id:
                deployed = True
                break
        if not deployed:
            continue

        start_value = _event_date_for_input(getattr(event, 'start_date', ''))
        end_value = _event_date_for_input(
            getattr(event, 'end_date', '') or getattr(event, 'start_date', '')
        )
        if not start_value or not end_value:
            continue
        start_date = datetime.strptime(start_value, '%Y-%m-%d').date()
        end_date = datetime.strptime(end_value, '%Y-%m-%d').date()
        if end_date < start_date:
            start_date, end_date = end_date, start_date
        if start_date > today:
            continue
        intervals.append((start_date, min(end_date, today)))

    if not intervals:
        return 0

    intervals.sort()
    merged = []
    for start_date, end_date in intervals:
        if not merged or start_date > merged[-1][1] + timedelta(days=1):
            merged.append([start_date, end_date])
            continue
        merged[-1][1] = max(merged[-1][1], end_date)

    return sum((end_date - start_date).days + 1 for start_date, end_date in merged)


def _event_model_quantities_by_key(event):
    totals = defaultdict(int)
    for item in getattr(event, 'prepared_items', []) or []:
        key, quantity = _parse_model_assignment_key(item)
        if key:
            totals[key] += quantity
    return totals


def _event_active_specific_quantities_by_key(event):
    """Count specific inventory assets still tied up by one event.

    Regular asset IDs count as one unit. Bulk markers count their marker
    quantity. Returned references are ignored because those units are back in
    stock for overlapping-date availability.
    """
    totals = defaultdict(int)
    if not event:
        return totals

    returned = set(getattr(event, 'returned_items', []) or [])
    seen_regular_assets = set()
    seen_bulk_markers = set()

    for values in (
        getattr(event, 'prepared_items', []) or [],
        getattr(event, 'actually_prepared', []) or [],
    ):
        for ref in values:
            if not isinstance(ref, str) or not ref or ref in returned:
                continue

            marker = _parse_bulk_marker(ref)
            if marker:
                marker_key = (marker['bulkId'], marker['quantity'], ref)
                if marker_key in seen_bulk_markers:
                    continue
                seen_bulk_markers.add(marker_key)

                bulk_asset = data_manager.inventory.get(marker['bulkId']) if data_manager else None
                if not bulk_asset or not _is_bulk_asset(bulk_asset):
                    continue
                if getattr(bulk_asset, 'is_missing', False) or _is_disposed(bulk_asset):
                    continue
                totals[_asset_group_key(bulk_asset)] += marker['quantity']
                continue

            if ref.startswith('[MODEL]') or _is_prepared_model_ref(ref) or _is_custom_ref(ref):
                continue

            if ref in seen_regular_assets:
                continue
            seen_regular_assets.add(ref)

            asset = data_manager.inventory.get(ref) if data_manager else None
            if not asset or _is_bulk_asset(asset):
                continue
            if getattr(asset, 'is_missing', False) or _is_disposed(asset):
                continue
            totals[_asset_group_key(asset)] += 1

    return totals


def _event_reserved_quantities_by_key(event):
    model_quantities = _event_model_quantities_by_key(event)
    specific_quantities = _event_active_specific_quantities_by_key(event)
    reserved = defaultdict(int)

    for key in set(model_quantities.keys()) | set(specific_quantities.keys()):
        reserved[key] = max(model_quantities.get(key, 0), specific_quantities.get(key, 0))

    return reserved


def _active_physical_asset_refs_for_event(event):
    """Specific non-bulk asset IDs assigned/prepared for an event and not returned."""
    refs = set()
    if not event:
        return refs

    returned = set(getattr(event, 'returned_items', []) or [])
    for values in (
        getattr(event, 'prepared_items', []) or [],
        getattr(event, 'actually_prepared', []) or [],
    ):
        for ref in values:
            if not isinstance(ref, str) or not ref or ref in returned:
                continue
            if ref.startswith('[MODEL]') or _is_prepared_model_ref(ref) or _is_bulk_ref(ref) or _is_custom_ref(ref):
                continue
            if ref in data_manager.inventory:
                refs.add(ref)

    return refs


def _find_event_using_asset(asset_id, target_event, require_overlap=False):
    if not asset_id or not target_event:
        return None

    my_start = getattr(target_event, 'start_date', '')
    my_end = getattr(target_event, 'end_date', '')

    for other in data_manager.events.values():
        if not other or other.event_id == target_event.event_id:
            continue
        if require_overlap and not _ranges_overlap(my_start, my_end, getattr(other, 'start_date', ''), getattr(other, 'end_date', '')):
            continue
        if asset_id in _active_physical_asset_refs_for_event(other):
            return other

    return None


def _sum_assigned_quantity(model_group, include_extra=True):
    """Quantity assigned to a model group.

    include_extra=True is used for the model card itself, so it can show
    values such as 5/3 assigned (+2 extra). include_extra=False is used for
    event/department readiness totals, where manual extras must not complete
    missing required assets.
    """
    total = 0
    for asset in model_group.get('assignedAssets', []) or []:
        if not include_extra and asset.get('isExtra'):
            continue
        total += max(1, _safe_int(asset.get('quantity', 1), 1))
    return total


def _sum_returned_quantity(model_group, include_extra=True):
    total = 0
    for asset in model_group.get('assignedAssets', []) or []:
        if not include_extra and asset.get('isExtra'):
            continue
        if asset.get('status') == 'returned':
            total += max(1, _safe_int(asset.get('quantity', 1), 1))
    return total


def _sum_extra_prepared_quantity(model_group):
    total = 0
    for asset in model_group.get('assignedAssets', []) or []:
        if not asset.get('isExtra'):
            continue
        if asset.get('status') == 'returned':
            continue
        total += max(1, _safe_int(asset.get('quantity', 1), 1))
    return total


def _refresh_model_group_statuses(model_groups):
    for group in (model_groups or {}).values():
        required = max(0, _safe_int(group.get('requiredQuantity', 0), 0))
        prepared_slots = max(0, _safe_int(group.get('preparedSlotQuantity', 0), 0))
        returned_prepared_slots = max(
            0,
            _safe_int(group.get('returnedPreparedSlotQuantity', 0), 0),
        )
        extra_prepared_slots = max(
            0,
            _safe_int(group.get('extraPreparedSlotQuantity', 0), 0),
        )
        extra_returned_prepared_slots = max(
            0,
            _safe_int(group.get('extraReturnedPreparedSlotQuantity', 0), 0),
        )

        # Display quantities include extras so each model section can show
        # "5/3 assigned (+2 extra)" and list the extra assets under Assigned Assets.
        assigned_specific = _sum_assigned_quantity(group, include_extra=True)
        returned = (
            _sum_returned_quantity(group, include_extra=True)
            + returned_prepared_slots
            + extra_returned_prepared_slots
        )
        assigned = (
            assigned_specific
            + prepared_slots
            + returned_prepared_slots
            + extra_prepared_slots
            + extra_returned_prepared_slots
        )
        prepared = max(assigned - returned, 0)

        # Countable quantities exclude manual extras. These drive readiness,
        # event totals, and department progress totals.
        countable_assigned = (
            _sum_assigned_quantity(group, include_extra=False)
            + prepared_slots
            + returned_prepared_slots
        )
        countable_returned = (
            _sum_returned_quantity(group, include_extra=False)
            + returned_prepared_slots
        )
        countable_prepared = max(countable_assigned - countable_returned, 0)

        group['assignedQuantity'] = assigned
        group['assignedSpecificQuantity'] = assigned_specific
        group['preparedSlotQuantity'] = prepared_slots
        group['returnedPreparedSlotQuantity'] = returned_prepared_slots
        group['extraPreparedSlotQuantity'] = extra_prepared_slots
        group['extraReturnedPreparedSlotQuantity'] = extra_returned_prepared_slots
        group['isBulkQuantity'] = _event_group_is_bulk_quantity(group)
        group['returnedQuantity'] = returned
        group['preparedQuantity'] = prepared
        group['countableAssignedQuantity'] = countable_assigned
        group['countableReturnedQuantity'] = countable_returned
        group['countablePreparedQuantity'] = min(countable_prepared, required) if required > 0 else countable_prepared
        group['extraPreparedQuantity'] = (
            _sum_extra_prepared_quantity(group)
            + extra_prepared_slots
            + max(0, countable_prepared - required)
        )
        group['openPreparedSlots'] = prepared_slots

        # Status must be based only on required/countable assets. Extras should
        # never make an incomplete requirement look ready.
        if required > 0 and countable_returned >= required and countable_assigned > 0:
            group['status'] = 'returned'
        elif required > 0 and countable_prepared >= required:
            group['status'] = 'ready'
        elif countable_prepared > 0:
            group['status'] = 'partial'
        else:
            group['status'] = 'pending'


def _append_bulk_assignments_to_model_groups(model_groups, event):
    if model_groups is None:
        return

    returned_values = set(getattr(event, 'returned_items', []) or [])
    extra_values = set(getattr(event, 'extra_assets', []) or [])
    seen = set()

    for value in getattr(event, 'actually_prepared', []) or []:
        marker = _parse_bulk_marker(value)
        if not marker:
            continue

        bulk_asset = data_manager.inventory.get(marker['bulkId']) if data_manager else None
        if not bulk_asset or not _is_bulk_asset(bulk_asset):
            continue

        group_key = '|'.join(_asset_group_key(bulk_asset))
        if group_key not in model_groups:
            model_groups[group_key] = {
                'department': bulk_asset.department_code,
                'brand': bulk_asset.brand,
                'model': bulk_asset.model_number,
                'description': bulk_asset.description or '',
                'requiredQuantity': 0,
                'assignedAssets': [],
                'status': 'pending',
            }

        unique_key = (value, group_key)
        if unique_key in seen:
            continue
        seen.add(unique_key)

        model_groups[group_key]['assignedAssets'].append({
            'id': value,
            'bulkId': marker['bulkId'],
            'serial': '',
            'status': 'returned' if value in returned_values else 'prepared',
            'location': bulk_asset.current_location or bulk_asset.default_location or '',
            'tags': normalize_asset_tags(getattr(bulk_asset, 'tags', [])),
            'quantity': marker['quantity'],
            'isBulk': True,
            'isExtra': value in extra_values,
            'displayId': '',
            'name': f"{bulk_asset.brand} {bulk_asset.model_number} {bulk_asset.description}".strip()
        })


def _append_prepared_slots_to_model_groups(model_groups, event):
    if model_groups is None:
        return

    extra_values = set(getattr(event, 'extra_assets', []) or [])
    sources = (
        ('preparedSlotQuantity', getattr(event, 'actually_prepared', []) or []),
        ('returnedPreparedSlotQuantity', getattr(event, 'returned_items', []) or []),
    )
    for quantity_field, values in sources:
        for value in values:
            marker = _parse_prepared_model_marker(value)
            if not marker:
                continue

            group_key = '|'.join(_model_key_from_parts(
                marker['department'],
                marker['brand'],
                marker['model'],
            ))
            if group_key not in model_groups:
                model_groups[group_key] = {
                    'department': marker['department'],
                    'brand': marker['brand'],
                    'model': marker['model'],
                    'description': marker.get('description') or '',
                    'requiredQuantity': 0,
                    'assignedAssets': [],
                    'status': 'pending',
                }
            elif not model_groups[group_key].get('description') and marker.get('description'):
                model_groups[group_key]['description'] = marker['description']

            target_field = quantity_field
            if value in extra_values:
                target_field = (
                    'extraPreparedSlotQuantity'
                    if quantity_field == 'preparedSlotQuantity'
                    else 'extraReturnedPreparedSlotQuantity'
                )
            model_groups[group_key][target_field] = (
                max(0, _safe_int(model_groups[group_key].get(target_field, 0), 0))
                + marker['quantity']
            )


def _append_orphan_extra_assignments_to_model_groups(model_groups, event):
    """Show manual extra assets in the model requirement area.

    Manual extras should not raise the event's required quantity, but they should
    still sit beside matching model rows in the prepare modal. If the event did
    not request that model at all, create a 0-required model group so the UI can
    show values such as "1/0 assigned (+1 extra)".
    """
    if model_groups is None:
        return

    _ensure_event_custom_lists(event)
    extra_asset_ids = set(getattr(event, 'extra_assets', []) or [])
    if not extra_asset_ids:
        return

    returned_values = set(getattr(event, 'returned_items', []) or [])
    prepared_or_returned = list(getattr(event, 'actually_prepared', []) or [])
    prepared_or_returned.extend(getattr(event, 'returned_items', []) or [])

    already_grouped = set()
    for group in model_groups.values():
        for assigned in group.get('assignedAssets', []) or []:
            assigned_id = assigned.get('id') if isinstance(assigned, dict) else assigned
            if assigned_id:
                already_grouped.add(assigned_id)

    seen = set()
    for asset_id in prepared_or_returned:
        if asset_id in seen or asset_id in already_grouped:
            continue
        seen.add(asset_id)

        if asset_id not in extra_asset_ids:
            continue
        if not _is_real_asset_ref(asset_id) or _is_bulk_ref(asset_id):
            continue

        asset = data_manager.inventory.get(asset_id) if data_manager else None
        if not asset or _is_bulk_asset(asset):
            continue

        dept, brand, model, description = _asset_group_key(asset)
        model_key = f"{dept}|{brand}|{model}|{description}"

        if model_key not in model_groups:
            model_groups[model_key] = {
                'department': dept,
                'brand': brand,
                'model': model,
                'description': description,
                'requiredQuantity': 0,
                'assignedAssets': [],
                'status': 'pending'
            }

        model_groups[model_key]['assignedAssets'].append({
            'id': asset_id,
            'serial': asset.serial_number,
            'serial2': getattr(asset, 'secondary_serial_number', ''),
            'tags': normalize_asset_tags(getattr(asset, 'tags', [])),
            'status': 'returned' if asset_id in returned_values else 'prepared',
            'location': asset.current_location,
            'quantity': 1,
            'isExtra': True
        })


def _bulk_remaining_for_event_group(event, bulk_asset):
    group_key = _asset_group_key(bulk_asset)
    required = 0
    for item in getattr(event, 'prepared_items', []) or []:
        key, quantity = _parse_model_assignment_key(item)
        if key == group_key:
            required += quantity

    prepared = _bulk_quantity_in_values_for_key(getattr(event, 'actually_prepared', []) or [], group_key)
    return max(required - prepared, 0)


def _bulk_available_quantity_for_event(bulk_asset, target_event, require_overlap=False, include_degraded=True):
    if not bulk_asset or not _is_bulk_asset(bulk_asset):
        return 0

    total = max(1, _safe_int(getattr(bulk_asset, 'quantity', 1), 1))
    if getattr(bulk_asset, 'is_missing', False) or getattr(bulk_asset, 'is_ooc', False) or _is_disposed(bulk_asset):
        return 0

    busy = 0
    my_start = getattr(target_event, 'start_date', '')
    my_end = getattr(target_event, 'end_date', '')

    for other in data_manager.events.values():
        if not other or other.event_id == target_event.event_id:
            continue
        if require_overlap and not _ranges_overlap(my_start, my_end, getattr(other, 'start_date', ''), getattr(other, 'end_date', '')):
            continue

        prepared_qty = _bulk_quantity_for_asset_in_values(getattr(other, 'actually_prepared', []) or [], bulk_asset.asset_id)
        returned_qty = _bulk_quantity_for_asset_in_values(getattr(other, 'returned_items', []) or [], bulk_asset.asset_id)
        busy += max(prepared_qty - returned_qty, 0)

    fault_counts = _bulk_maintenance_quantity_counts(bulk_asset)
    unavailable_faults = fault_counts['ooc'] + fault_counts['missing']
    if not include_degraded and _is_degraded(bulk_asset):
        return 0
    if not include_degraded:
        unavailable_faults += fault_counts['degraded']

    return max(total - busy - unavailable_faults, 0)


def _bulk_asset_to_available_dict(asset, target_event=None):
    status = _asset_status_value(asset)
    fault_counts = _bulk_maintenance_quantity_counts(asset)

    if target_event is not None:
        healthy_available_quantity = _bulk_available_quantity_for_event(
            asset,
            target_event,
            include_degraded=False
        )
        preparable_quantity = _bulk_available_quantity_for_event(
            asset,
            target_event,
            include_degraded=True
        )
    else:
        total_quantity = max(1, _safe_int(getattr(asset, 'quantity', 1), 1))
        if getattr(asset, 'is_missing', False) or getattr(asset, 'is_ooc', False) or _is_disposed(asset):
            healthy_available_quantity = 0
            preparable_quantity = 0
        else:
            unavailable_quantity = fault_counts['ooc'] + fault_counts['missing']
            preparable_quantity = max(0, total_quantity - unavailable_quantity)
            healthy_available_quantity = (
                0 if _is_degraded(asset)
                else max(0, total_quantity - unavailable_quantity - fault_counts['degraded'])
            )

    if status not in ('decommissioned', 'missing', 'ooc'):
        if fault_counts['missing'] > 0:
            status = 'missing'
        elif fault_counts['ooc'] > 0:
            status = 'ooc'
        elif fault_counts['degraded'] > 0 or _is_degraded(asset):
            status = 'degraded'

    return {
        'id': asset.asset_id,
        'bulkId': asset.asset_id,
        'displayId': '',
        'brand': asset.brand,
        'model': asset.model_number,
        'version': getattr(asset, 'version', ''),
        'description': asset.description or '',
        'tags': normalize_asset_tags(getattr(asset, 'tags', [])),
        'serial': '',
        'dateOfPurchase': getattr(asset, 'date_of_purchase', ''),
        'purchaseDate': getattr(asset, 'date_of_purchase', ''),
        'dateAdded': getattr(asset, 'date_added', ''),
        'dateModified': getattr(asset, 'date_modified', ''),
        'changeHistory': getattr(asset, 'change_history', []),
        'department': asset.department_code,
        'location': asset.current_location or asset.default_location,
        'status': status,
        'isMissing': getattr(asset, 'is_missing', False),
        'isOOC': getattr(asset, 'is_ooc', False),
        'isUntagged': _is_untagged(asset),
        'isDegraded': _is_degraded(asset),
        'isDisposed': _is_disposed(asset),
        'isBulk': True,
        'quantity': max(1, _safe_int(getattr(asset, 'quantity', 1), 1)),
        'availableQuantity': preparable_quantity,
        'preparableQuantity': preparable_quantity,
        'healthyQuantity': healthy_available_quantity,
        'bulkOOCQuantity': fault_counts['ooc'],
        'bulkMissingQuantity': fault_counts['missing'],
        'bulkDegradedQuantity': fault_counts['degraded'],
        'bulkFaultQuantity': fault_counts['total'],
        'degradedReasons': _asset_degraded_reasons(asset),
        'bulkDegradedReasons': _bulk_degraded_reasons(asset),
    }

def _parse_model_assignment_key(value):
    """
    Parses:
    [MODEL]DEPT|BRAND|MODEL|QTY|DESCRIPTION

    Returns:
    (key, quantity)
    """
    if not isinstance(value, str) or not value.startswith('[MODEL]'):
        return None, 0

    parts = value[7:].split('|', 4)

    if len(parts) < 4:
        return None, 0

    try:
        quantity = int(parts[3])
    except Exception:
        quantity = 0

    key = (
        _clean_group_value(parts[0], True),
        _clean_group_value(parts[1]),
        _clean_group_value(parts[2]),
        ''
    )

    return key, quantity


def _asset_to_available_dict(asset):
    if _is_bulk_asset(asset):
        return _bulk_asset_to_available_dict(asset)

    status = _asset_status_value(asset)

    return {
        'id': asset.asset_id,
        'brand': asset.brand,
        'model': asset.model_number,
        'version': getattr(asset, 'version', ''),
        'description': asset.description or '',
        'tags': normalize_asset_tags(getattr(asset, 'tags', [])),
        'serial': asset.serial_number,
        'serial2': getattr(asset, 'secondary_serial_number', ''),
        'dateOfPurchase': getattr(asset, 'date_of_purchase', ''),
        'purchaseDate': getattr(asset, 'date_of_purchase', ''),
        'dateAdded': getattr(asset, 'date_added', ''),
        'dateModified': getattr(asset, 'date_modified', ''),
        'changeHistory': getattr(asset, 'change_history', []),
        'department': asset.department_code,
        'location': asset.current_location or asset.default_location,
        'status': status,
        'isMissing': getattr(asset, 'is_missing', False),
        'isOOC': getattr(asset, 'is_ooc', False),
        'isUntagged': _is_untagged(asset),
        'isDegraded': _is_degraded(asset),
        'isDisposed': _is_disposed(asset),
        'isBulk': False,
        'quantity': 1,
        'availableQuantity': 1,
        'degradedReasons': _asset_degraded_reasons(asset),
    }

def require_auth(f):
    """Decorator to require authentication"""
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if 'user' not in session:
            if request.path.startswith('/api/'):
                return jsonify({'error': 'Not authenticated'}), 401
            return redirect(url_for('login'))

        user = _current_user_obj()

        # If the user was deleted or deactivated after login by someone else,
        # force logout. Self-deactivation waits until the next login.
        if not user or not _current_user_effective_is_active():
            session.clear()
            if request.path.startswith('/api/'):
                return jsonify({'error': 'Account inactive'}), 401
            return redirect(url_for('login'))

        return f(*args, **kwargs)

    return decorated_function

@app.route('/api/assets/available-for-event/<int:event_id>', methods=['GET'])
@require_auth
@require_event_access
def get_available_assets_for_event(event_id):
    """
    Return event-aware assets for the prepare dropdown.

    This endpoint intentionally shows only assets that can actually be prepared
    for this event:
      - not missing
      - not decommissioned
      - not out of commission
      - not already prepared/assigned to this same event
      - not specifically out for any other event and not returned

    It does NOT reserve/hide assets simply because another overlapping event has
    an unprepared [MODEL] requirement.  Model requirements are planning demand;
    only a specific prepared asset ID means the physical unit is unavailable.
    """
    try:
        event = data_manager.events.get(event_id)
        if not event:
            return jsonify({'error': 'Event not found'}), 404

        current_event_refs = _active_physical_asset_refs_for_event(event)
        returned_event_refs = {
            ref for ref in (getattr(event, 'returned_items', []) or [])
            if isinstance(ref, str) and _is_real_asset_ref(ref)
        }
        returned_anonymous_group_keys = {
            _model_key_from_parts(
                marker['department'],
                marker['brand'],
                marker['model'],
            )
            for ref in (getattr(event, 'returned_items', []) or [])
            for marker in [_parse_prepared_model_marker(ref)]
            if marker
        }
        busy_elsewhere = set()

        for other in data_manager.events.values():
            if not other or other.event_id == event_id:
                continue

            busy_elsewhere.update(_active_physical_asset_refs_for_event(other))

        final_list = []

        for asset_id, asset in sorted(data_manager.inventory.items(), key=lambda pair: pair[0]):
            if not asset:
                continue

            if _is_bulk_asset(asset):
                # Bulk assets have quantity-based availability.  Keep this branch
                # separate so partially available bulk items can still appear.
                if getattr(asset, 'is_missing', False) or getattr(asset, 'is_ooc', False) or _is_disposed(asset):
                    continue

                available_quantity = _bulk_available_quantity_for_event(asset, event)
                if available_quantity <= 0:
                    continue

                final_list.append(_bulk_asset_to_available_dict(asset, event))
                continue

            is_returned_reconciliation_candidate = (
                _asset_group_key(asset) in returned_anonymous_group_keys
                and asset_id not in returned_event_refs
            )

            if _is_disposed(asset):
                continue
            if getattr(asset, 'is_ooc', False) and not is_returned_reconciliation_candidate:
                continue

            is_missing = bool(getattr(asset, 'is_missing', False))

            if asset_id in current_event_refs:
                continue

            if (
                not is_returned_reconciliation_candidate
                and not is_missing
                and asset_id in busy_elsewhere
            ):
                continue

            final_list.append({
                'id': asset_id,
                'brand': asset.brand,
                'model': asset.model_number,
                'description': getattr(asset, 'description', '') or '',
                'tags': normalize_asset_tags(getattr(asset, 'tags', [])),
                'department': asset.department_code,
                'serial': (getattr(asset, 'serial_number', None) or getattr(asset, 'serial', None) or ''),
                'serial2': getattr(asset, 'secondary_serial_number', ''),
                'dateOfPurchase': getattr(asset, 'date_of_purchase', ''),
                'purchaseDate': getattr(asset, 'date_of_purchase', ''),
                'dateAdded': getattr(asset, 'date_added', ''),
                'dateModified': getattr(asset, 'date_modified', ''),
                'changeHistory': getattr(asset, 'change_history', []),
                'location': asset.current_location or asset.default_location or '',
                'status': _asset_status_value(asset),
                'isMissing': getattr(asset, 'is_missing', False),
                'isOOC': getattr(asset, 'is_ooc', False),
                'isUntagged': _is_untagged(asset),
                'isDegraded': _is_degraded(asset),
                'isDisposed': _is_disposed(asset),
                'isBulk': False,
                'quantity': 1,
                'availableQuantity': 0 if is_missing else 1,
                'preparableQuantity': 0 if is_missing else 1,
                'degradedReasons': _asset_degraded_reasons(asset),
                'notAvailableReason': 'missing' if is_missing else '',
            })

        return jsonify({'success': True, 'data': final_list})
    except Exception as e:
        logger.error(f"Error computing available-for-event({event_id}): {e}", exc_info=True)
        return jsonify({'error': 'Failed to compute event-aware availability'}), 500
    
def require_admin(f):
    """Decorator to require admin privileges"""
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if 'user' not in session:
            return jsonify({'error': 'Not authenticated'}), 401

        user = _current_user_obj()

        if not user or not _current_user_effective_is_active():
            session.clear()
            return jsonify({'error': 'Account inactive'}), 401

        if not _current_user_effective_is_admin():
            return jsonify({'error': 'Admin privileges required'}), 403

        return f(*args, **kwargs)

    return decorated_function


def require_super_admin(f):
    """Decorator for global company-management actions."""
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if 'user' not in session:
            return jsonify({'error': 'Not authenticated'}), 401

        user = _current_user_obj()

        if not user or not _current_user_effective_is_active():
            session.clear()
            return jsonify({'error': 'Account inactive'}), 401

        if not _current_user_is_owner():
            return jsonify({'error': 'Administrative access required'}), 403

        return f(*args, **kwargs)

    return decorated_function


def require_sales(f):
    """Decorator for finance-only actions."""
    @wraps(f)
    def decorated_function(*args, **kwargs):
        if 'user' not in session:
            return jsonify({'error': 'Not authenticated'}), 401

        user = _current_user_obj()

        if not user or not _current_user_effective_is_active():
            session.clear()
            return jsonify({'error': 'Account inactive'}), 401

        if not _current_user_has_sales_access():
            return jsonify({'error': 'Sales access required'}), 403

        return f(*args, **kwargs)

    return decorated_function


def _current_user_obj():
    """Return the signed-in account even when a request targets another company."""
    username = session.get('user')
    if not username or not data_manager:
        return None
    user = data_manager.users.get(username)
    if user:
        return user

    test_manager = app.config.get('TEST_DATA_MANAGER')
    if app.config.get('TESTING') and test_manager is not None:
        return test_manager.users.get(username)

    assigned_company = _user_assigned_company_code(username)
    authentication_manager = _get_company_data_manager(assigned_company)
    if authentication_manager is _current_data_manager_object():
        return None
    return authentication_manager.users.get(username)


def _current_user_is_admin():
    return _current_user_effective_is_admin()


# ---------------- Manpower, transport, and worker portal ----------------

WORKER_TOKEN_MAX_AGE = 12 * 60 * 60
SUPER_ADMIN_LOG_PREFIX = '[OWNER ONLY] '
OWNER_ONLY_LOG_PREFIXES = (SUPER_ADMIN_LOG_PREFIX, '[SUPER ADMIN ONLY] ')


def _workforce_folder(manager=None):
    manager = manager or _current_data_manager_object()
    return os.path.abspath(getattr(manager, 'data_folder', '') or '')


def _worker_token_serializer():
    return URLSafeTimedSerializer(app.secret_key, salt='showbase-worker-portal-v1')


def _make_worker_token(company_code, freelancer):
    return _worker_token_serializer().dumps({
        'companyCode': _normalise_company_code(company_code, DEFAULT_COMPANY_CODE),
        'freelancerId': str(freelancer.get('id') or ''),
        'phone': normalize_phone(freelancer.get('phone')),
        'authVersion': int(freelancer.get('workerAuthVersion') or 0),
    })


def _vendor_member_proxy(vendor, member):
    """Represent a vendor as a submission subject authenticated by a member."""
    return {
        'id': str(vendor.get('id') or ''),
        'name': str(vendor.get('name') or 'Company'),
        'phone': normalize_phone(member.get('phone')),
        'email': str(member.get('email') or ''),
        'active': bool(vendor.get('active', True) and member.get('active', True)),
        'workerPasswordSalt': member.get('workerPasswordSalt'),
        'workerPasswordHash': member.get('workerPasswordHash'),
        'workerCredentialType': member.get('workerCredentialType'),
        'workerAuthVersion': int(member.get('workerAuthVersion') or 0),
        'workerCredentialsSetAt': member.get('workerCredentialsSetAt'),
        'workerLastLoginAt': member.get('workerLastLoginAt'),
        'loginPersonId': str(member.get('id') or ''),
        'isVendor': True,
    }


def _worker_secret_is_valid(secret, credential_type):
    value = str(secret or '')
    kind = str(credential_type or 'password').strip().lower()
    if kind == 'pin':
        return value.isdigit() and 4 <= len(value) <= 8
    return 8 <= len(value) <= 128


def _worker_secret_matches(freelancer, secret):
    salt = str(freelancer.get('workerPasswordSalt') or '')
    expected = str(freelancer.get('workerPasswordHash') or '')
    return bool(
        salt
        and expected
        and hash_password(str(secret or ''), salt) == expected
    )


def _set_worker_secret(freelancer, secret, credential_type):
    salt = secrets.token_hex(16)
    freelancer.update({
        'workerPasswordSalt': salt,
        'workerPasswordHash': hash_password(str(secret), salt),
        'workerCredentialType': (
            'pin'
            if str(credential_type).lower() == 'pin'
            else 'password'
        ),
        'workerCredentialsSetAt': now_iso(),
        'workerAuthVersion': int(
            freelancer.get('workerAuthVersion') or 0
        ) + 1,
        'updatedAt': now_iso(),
    })
    freelancer.pop('workerLoginResetAt', None)


def _worker_matches_for_phone(phone):
    normalized = normalize_phone(phone)
    test_manager = app.config.get('TEST_DATA_MANAGER')
    if app.config.get('TESTING') and test_manager is not None:
        company_managers = [(_current_company_code(), test_manager)]
    else:
        company_managers = [
            (company_code, _get_company_data_manager(company_code))
            for company_code in sorted(_all_company_records())
        ]
    matches = []
    for company_code, manager in company_managers:
        workforce = load_workforce(_workforce_folder(manager))
        for freelancer in workforce.get('freelancers', []):
            if (
                isinstance(freelancer, dict)
                and freelancer.get('active', True)
                and normalize_phone(freelancer.get('phone')) == normalized
            ):
                freelancer_id = str(freelancer.get('id') or '')
                has_personal_assignment = any(
                    str(row.get('freelancerId') or '') == freelancer_id
                    for rows in (workforce.get('assignments') or {}).values()
                    for row in (rows if isinstance(rows, list) else [])
                    if isinstance(row, dict)
                )
                vendor_ids = {
                    str(vendor.get('id') or '')
                    for vendor in workforce.get('vendors', [])
                    if (
                        isinstance(vendor, dict)
                        and vendor.get('active', True)
                        and freelancer_id in {
                            str(value) for value in vendor.get('memberIds', [])
                        }
                    )
                }
                has_vendor_assignment = any(
                    str(row.get('freelancerId') or row.get('vendorId') or '')
                    in vendor_ids
                    for rows in (workforce.get('assignments') or {}).values()
                    for row in (rows if isinstance(rows, list) else [])
                    if isinstance(row, dict)
                )
                if has_personal_assignment or has_vendor_assignment:
                    matches.append((
                        company_code,
                        manager,
                        workforce,
                        freelancer,
                    ))
    return matches


def _worker_portal_payload(matches):
    companies = []
    seen = set()
    for company_code, manager, _workforce, freelancer in matches:
        match_key = (company_code, str(freelancer.get('id') or ''))
        if match_key in seen:
            continue
        seen.add(match_key)
        workforce = load_workforce(_workforce_folder(manager))
        current = find_by_id(
            workforce.get('freelancers'), freelancer.get('id')
        )
        if not current:
            continue
        payload = _worker_company_payload_for_member(
            company_code, manager, current, workforce
        )
        if payload['events']:
            companies.append(payload)
    return {'companies': companies}


def _worker_token_data(token):
    try:
        payload = _worker_token_serializer().loads(
            str(token or ''),
            max_age=WORKER_TOKEN_MAX_AGE,
        )
    except SignatureExpired as exc:
        raise ValueError('Your worker session has expired. Enter your phone number again.') from exc
    except BadSignature as exc:
        raise ValueError('Invalid worker session. Enter your phone number again.') from exc
    if not isinstance(payload, dict):
        raise ValueError('Invalid worker session')
    company_code = _normalise_company_code(payload.get('companyCode'))
    freelancer_id = str(payload.get('freelancerId') or '')
    phone = normalize_phone(payload.get('phone'))
    if not company_code or not freelancer_id or not phone:
        raise ValueError('Invalid worker session')
    try:
        auth_version = int(payload.get('authVersion') or 0)
    except (TypeError, ValueError):
        auth_version = 0
    return company_code, freelancer_id, phone, auth_version


def _bind_public_company_manager(company_code):
    test_manager = app.config.get('TEST_DATA_MANAGER')
    if app.config.get('TESTING') and test_manager is not None:
        manager = test_manager
    else:
        manager = _get_company_data_manager(company_code)
    current = _current_data_manager_object()
    if manager is not current and hasattr(manager, 'acquire_write_request'):
        manager.acquire_write_request()
        locks = getattr(g, 'data_manager_write_locks', None)
        if locks is None:
            locks = []
            g.data_manager_write_locks = locks
        locks.append(manager)
    _bind_request_data_manager(manager)
    return manager


def _event_date_for_worker(value):
    try:
        return format_date_output(value)
    except Exception:
        return str(value or '')


def _event_date_for_input(value):
    raw = str(value or '').strip()
    for format_string in ('%Y%m%d', '%Y-%m-%d', '%d/%m/%Y'):
        try:
            return datetime.strptime(raw, format_string).strftime('%Y-%m-%d')
        except ValueError:
            continue
    return ''


def _public_submission_rows(rows, token):
    result = {'invoices': [], 'claims': []}
    for kind in ('invoices', 'claims'):
        for row in rows.get(kind, []) if isinstance(rows, dict) else []:
            if not isinstance(row, dict):
                continue
            status = str(row.get('status') or 'Pending Review')
            processing_state = str(row.get('processingState') or 'Complete')
            submission_stage = str(row.get('submissionStage') or 'Submitted')
            payment_confirmed = bool(row.get('paymentConfirmedAt'))
            submission_id = quote(str(row.get('id') or ''))
            if processing_state == 'Processing':
                public_status = 'Processing'
            elif submission_stage == 'Details Required':
                public_status = 'Details Required'
            elif payment_confirmed:
                public_status = 'Payment Confirmed'
            else:
                public_status = status
            result[kind].append({
                'id': str(row.get('id') or ''),
                'submittedAt': str(row.get('submittedAt') or ''),
                'status': public_status,
                'adminStatus': status,
                'processingState': processing_state,
                'submissionStage': submission_stage,
                'needsDetails': submission_stage == 'Details Required',
                'denialReason': (
                    str(row.get('denialReason') or '')
                    if status == 'Denied'
                    else ''
                ),
                'originalName': str(row.get('originalName') or ''),
                'amount': row.get('amount'),
                'claimDate': str(row.get('claimDate') or ''),
                'category': str(row.get('category') or ''),
                'description': str(row.get('description') or ''),
                'notes': str(row.get('notes') or row.get('description') or ''),
                'department': str(row.get('department') or ''),
                'contentType': str(row.get('contentType') or ''),
                'paymentConfirmedAt': str(
                    row.get('paymentConfirmedAt') or ''
                ),
                'canEdit': status in {'Pending Review', 'Denied'},
                'canConfirmPayment': (
                    status == 'Paid' and not payment_confirmed
                ),
                'fileUrl': (
                    f'/api/worker/submissions/{submission_id}/file'
                    f'?token={quote(str(token or ""))}'
                ),
            })
    return result


def _worker_upload_limits(workforce, event_id, freelancer_id):
    event_allowances = (
        (workforce.get('uploadAllowances') or {}).get(str(event_id), {})
        or {}
    )
    allowance = event_allowances.get(str(freelancer_id), {}) or {}
    try:
        extra_invoices = max(0, int(allowance.get('extraInvoices') or 0))
    except (TypeError, ValueError):
        extra_invoices = 0
    try:
        extra_claims = max(0, int(allowance.get('extraClaims') or 0))
    except (TypeError, ValueError):
        extra_claims = 0
    rows = worker_submissions(workforce, event_id, freelancer_id)
    active_invoices = [
        row for row in rows.get('invoices', [])
        if isinstance(row, dict) and row.get('status') != 'Denied'
    ]
    active_claim_rows = active_claims(rows)
    invoice_limit = 1 + extra_invoices
    claim_limit = 5 + extra_claims
    return {
        'invoiceLimit': invoice_limit,
        'claimLimit': claim_limit,
        'activeInvoices': len(active_invoices),
        'activeClaims': len(active_claim_rows),
        'invoiceSlotsRemaining': max(0, invoice_limit - len(active_invoices)),
        'claimSlotsRemaining': max(0, claim_limit - len(active_claim_rows)),
        'extraInvoices': extra_invoices,
        'extraClaims': extra_claims,
    }


def _worker_company_payload(company_code, manager, freelancer, workforce):
    freelancer_id = str(freelancer.get('id') or '')
    token = _make_worker_token(company_code, freelancer)
    department_rows = _department_codes_for_manager(manager)
    departments_by_code = {
        row['code']: row for row in department_rows
    }
    assignments_by_event = defaultdict(list)
    for event_id, rows in (workforce.get('assignments') or {}).items():
        for assignment in rows if isinstance(rows, list) else []:
            if (
                isinstance(assignment, dict)
                and str(assignment.get('freelancerId') or '') == freelancer_id
            ):
                assignments_by_event[str(event_id)].append(assignment)

    events_payload = []
    for raw_event_id, assignments in assignments_by_event.items():
        try:
            event_id = int(raw_event_id)
        except (TypeError, ValueError):
            continue
        event = manager.events.get(event_id)
        if not event:
            continue
        subproject_options = _workforce_subproject_options(event)
        departments = []
        assignment_payload = []
        for assignment in assignments:
            assignment_with_room = _workforce_row_with_subproject(
                assignment, event, subproject_options
            )
            department = str(assignment.get('department') or 'Unassigned')
            department_details = (
                departments_by_code.get(_normalise_department_code(department))
                or _department_record(department)
            )
            if department not in departments:
                departments.append(department)
            assignment_payload.append({
                'id': str(assignment.get('id') or ''),
                'subprojectId': assignment_with_room['subprojectId'],
                'subprojectName': assignment_with_room['subprojectName'],
                'department': department,
                'departmentName': department_details['name'],
                'departmentColor': department_details['color'],
                'departmentTextColor': department_details['textColor'],
                'role': str(assignment.get('roleName') or 'Worker'),
                'days': int(assignment.get('days') or 0),
                'providerType': str(
                    assignment.get('providerType') or ''
                ),
                'pax': int(assignment.get('pax') or 0),
            })
        rows = worker_submissions(workforce, event_id, freelancer_id)
        public_rows = _public_submission_rows(rows, token)
        payable_rows = [
            row
            for kind in ('invoices', 'claims')
            for row in rows.get(kind, [])
            if isinstance(row, dict) and row.get('status') != 'Denied'
        ]
        payment_complete = bool(payable_rows) and all(
            row.get('status') == 'Paid' and row.get('paymentConfirmedAt')
            for row in payable_rows
        )
        invoice_total = round(sum(
            money(row.get('amount'), 0.0) or 0.0
            for row in rows.get('invoices', [])
            if isinstance(row, dict) and row.get('status') != 'Denied'
        ), 2)
        claim_total = round(sum(
            money(row.get('amount'), 0.0) or 0.0
            for row in rows.get('claims', [])
            if (
                isinstance(row, dict)
                and row.get('status') != 'Denied'
                and (
                    'detailsComplete' not in row
                    or row.get('detailsComplete')
                )
            )
        ), 2)
        limits = _worker_upload_limits(
            workforce, event_id, freelancer_id
        )
        events_payload.append({
            'id': event_id,
            'subjectId': freelancer_id,
            'subjectName': str(freelancer.get('name') or 'Worker'),
            'subjectType': 'vendor' if freelancer.get('isVendor') else 'worker',
            'token': token,
            'name': event.name,
            'location': getattr(event, 'location', '') or '',
            'startDate': _event_date_for_worker(event.start_date),
            'endDate': _event_date_for_worker(event.end_date),
            'isPast': payment_complete,
            'paymentComplete': payment_complete,
            'invoiceTotal': invoice_total,
            'claimTotal': claim_total,
            'assignments': assignment_payload,
            'subprojects': subproject_options,
            'departments': departments,
            'submissions': public_rows,
            'canUploadInvoice': limits['invoiceSlotsRemaining'] > 0,
            **limits,
        })
    events_payload.sort(key=lambda row: (row['isPast'], row['startDate'], row['id']))
    company = _company_payload(company_code)
    return {
        'code': company['code'],
        'name': company['name'],
        'logoUrl': company.get('logoUrl', ''),
        'token': token,
        'freelancer': {
            'id': freelancer_id,
            'name': str(freelancer.get('name') or ''),
            'phone': str(freelancer.get('phone') or ''),
            'email': str(freelancer.get('email') or ''),
            'credentialType': str(
                freelancer.get('workerCredentialType') or 'password'
            ),
        },
        'events': events_payload,
    }


def _worker_company_payload_for_member(
    company_code, manager, member, workforce
):
    """Merge a person's private and vendor assignments into one portal company."""
    payload = _worker_company_payload(
        company_code, manager, member, workforce
    )
    member_id = str(member.get('id') or '')
    merged_events = list(payload.get('events') or [])
    for vendor in workforce.get('vendors', []):
        if (
            not isinstance(vendor, dict)
            or not vendor.get('active', True)
            or member_id not in {
                str(value) for value in vendor.get('memberIds', [])
            }
        ):
            continue
        proxy = _vendor_member_proxy(vendor, member)
        vendor_payload = _worker_company_payload(
            company_code, manager, proxy, workforce
        )
        for event in vendor_payload.get('events', []):
            merged_events.append(event)
    merged_events.sort(
        key=lambda row: (
            row.get('isPast', False),
            row.get('startDate', ''),
            row.get('id', 0),
            row.get('subjectName', ''),
        )
    )
    payload['events'] = merged_events
    return payload


def _worker_company_payload_for_context(
    company_code, manager, subject, workforce
):
    member_id = str(
        subject.get('loginPersonId') or subject.get('id') or ''
    )
    member = find_by_id(workforce.get('freelancers'), member_id)
    if not member:
        return _worker_company_payload(
            company_code, manager, subject, workforce
        )
    return _worker_company_payload_for_member(
        company_code, manager, member, workforce
    )


def _find_worker_context(token, event_id=None):
    company_code, freelancer_id, phone, auth_version = _worker_token_data(token)
    manager = _bind_public_company_manager(company_code)
    workforce = load_workforce(_workforce_folder(manager))
    freelancer = find_by_id(workforce.get('freelancers'), freelancer_id)
    if not freelancer:
        vendor = find_by_id(workforce.get('vendors'), freelancer_id)
        member = next(
            (
                row for row in workforce.get('freelancers', [])
                if (
                    isinstance(row, dict)
                    and str(row.get('id') or '') in {
                        str(value) for value in (
                            vendor.get('memberIds', []) if vendor else []
                        )
                    }
                    and normalize_phone(row.get('phone')) == phone
                )
            ),
            None,
        )
        if vendor and member:
            freelancer = _vendor_member_proxy(vendor, member)
    if (
        not freelancer
        or normalize_phone(freelancer.get('phone')) != phone
        or not freelancer.get('active', True)
    ):
        raise ValueError('Worker profile is no longer available')
    if int(freelancer.get('workerAuthVersion') or 0) != auth_version:
        raise ValueError(
            'Your worker login was reset. Set a new PIN or password.'
        )
    if event_id is not None:
        assigned = any(
            str(row.get('freelancerId') or row.get('vendorId') or '')
            == freelancer_id
            for row in event_assignments(workforce, event_id)
            if isinstance(row, dict)
        )
        if not assigned or int(event_id) not in manager.events:
            raise ValueError('You are not assigned to this event')
    return company_code, manager, workforce, freelancer


def _department_codes_for_manager(manager):
    departments = getattr(manager, 'departments', {}) or {}
    if not departments and hasattr(manager, 'load_departments'):
        departments = manager.load_departments()
    if not departments:
        filepath = os.path.join(
            getattr(manager, 'data_folder', '') or '', 'Departments.csv'
        )
        if os.path.exists(filepath) and os.path.getsize(filepath) > 0:
            with open(filepath, 'r', newline='', encoding='utf-8-sig') as handle:
                for row in csv.DictReader(handle):
                    code = _normalise_department_code(row.get('Code'))
                    if code:
                        departments[code] = _department_record(
                            code,
                            row.get('Name'),
                            row.get('Color'),
                            row.get('TextColor'),
                        )
    if not departments:
        departments = {
            code: dict(row) for code, row in DEFAULT_DEPARTMENTS.items()
        }
    payload = []
    for code, record in departments.items():
        if isinstance(record, dict):
            name = record.get('name') or record.get('Name') or code
            colour = record.get('color') or record.get('Color')
            text_colour = record.get('textColor') or record.get('TextColor')
        else:
            name = getattr(record, 'name', '') or code
            colour = getattr(record, 'color', '')
            text_colour = getattr(record, 'text_color', '')
        payload.append(_department_record(
            code, name, colour, text_colour
        ))
    return sorted(payload, key=lambda row: row['name'].lower())


def _event_asset_department_codes(event, manager):
    """Return department codes represented by the event's asset requirements."""
    codes = set()
    inventory = getattr(manager, 'inventory', {}) or {}

    def add_code(value):
        code = _normalise_department_code(value)
        if code:
            codes.add(code)

    def inspect_reference(value):
        if not isinstance(value, str):
            return
        model_marker = _parse_model_marker(value)
        if model_marker:
            add_code(model_marker.get('department'))
            return
        custom_marker = _parse_custom_marker(value)
        if custom_marker:
            add_code(custom_marker.get('department'))
            return
        bulk_marker = _parse_bulk_marker(value)
        asset_id = bulk_marker.get('bulkId') if bulk_marker else value
        asset = inventory.get(asset_id)
        if asset:
            add_code(getattr(asset, 'department_code', ''))

    for values in _event_reference_lists(event):
        if isinstance(values, list):
            for value in values:
                inspect_reference(value)

    for row in getattr(event, 'asset_models', []) or []:
        if not isinstance(row, dict):
            continue
        add_code(
            row.get('department')
            or row.get('departmentCode')
            or row.get('DepartmentCode')
        )
        description = str(
            row.get('model_description')
            or row.get('modelDescription')
            or ''
        ).strip()
        match = re.match(r'^\[([^\]]+)\]', description)
        if match:
            add_code(match.group(1))

    return codes


def _event_workforce_departments(event_id, event, manager, workforce):
    configured_rows = _department_codes_for_manager(manager)
    configured = {row['code']: row for row in configured_rows}
    active_codes = _event_asset_department_codes(event, manager)

    for assignment in event_assignments(workforce, event_id):
        if isinstance(assignment, dict):
            code = _normalise_department_code(assignment.get('department'))
            if code:
                active_codes.add(code)

    manual_rows = (
        (workforce.get('manualDepartments') or {}).get(str(event_id), [])
        or []
    )
    manual_by_code = {}
    for row in manual_rows:
        if not isinstance(row, dict):
            continue
        code = _normalise_department_code(row.get('code'))
        if not code:
            continue
        manual_by_code[code] = {
            'code': code,
            'name': str(row.get('name') or code).strip() or code,
            'color': (configured.get(code) or {}).get('color'),
            'textColor': (configured.get(code) or {}).get('textColor'),
            'source': 'manual',
        }
        active_codes.add(code)

    hidden_codes = {
        _normalise_department_code(code)
        for code in (
            (workforce.get('hiddenDepartments') or {}).get(str(event_id), [])
            or []
        )
    }
    assigned_codes = {
        _normalise_department_code(row.get('department'))
        for row in event_assignments(workforce, event_id)
        if isinstance(row, dict)
    }
    active_codes = {
        code for code in active_codes
        if code not in hidden_codes or code in assigned_codes or code in manual_by_code
    }

    active_rows = []
    for code in sorted(active_codes):
        base = manual_by_code.get(code) or configured.get(code) or {
            'code': code,
            'name': code,
        }
        active_rows.append({
            'code': code,
            'name': base.get('name') or code,
            'color': _normalise_hex_colour(base.get('color')),
            'textColor': _normalise_hex_colour(
                base.get('textColor')
                or _best_text_colour(base.get('color')),
                _best_text_colour(base.get('color')),
            ),
            'source': (
                'manual'
                if code in manual_by_code
                else 'event-assets'
            ),
        })
    return active_rows, configured_rows


def _workforce_submission_expectation(workforce, event_id, subject_id):
    breakdown = []
    estimate_complete = True
    for assignment in event_assignments(workforce, event_id):
        if not isinstance(assignment, dict):
            continue
        assigned_subject_id = str(
            assignment.get('freelancerId')
            or assignment.get('vendorId')
            or ''
        )
        if assigned_subject_id != str(subject_id):
            continue
        try:
            days = max(1, int(assignment.get('days') or 1))
        except (TypeError, ValueError):
            days = 1
        provider_type = str(
            assignment.get('providerType') or ''
        ).strip().lower()
        role_name = str(
            assignment.get('serviceName')
            or assignment.get('roleName')
            or 'Role not set'
        ).strip()
        if provider_type == 'service':
            rate = money(assignment.get('serviceCost'), 0.0) or 0.0
            pax = None
            amount = round(rate, 2)
            calculation = f'${rate:,.2f} service total'
        elif provider_type == 'manpower':
            try:
                pax = max(1, int(assignment.get('pax') or 1))
            except (TypeError, ValueError):
                pax = 1
            rate = money(
                assignment.get('ratePerPax'),
                money(assignment.get('dailyRate'), 0.0),
            ) or 0.0
            amount = round(pax * rate * days, 2)
            calculation = f'{pax} pax x {days} day(s) x ${rate:,.2f}'
        else:
            pax = None
            rate = money(assignment.get('dailyRate'))
            if rate is None:
                amount = None
                calculation = 'Rate not set'
                estimate_complete = False
            else:
                amount = round(rate * days, 2)
                calculation = f'{days} day(s) x ${rate:,.2f}'
        breakdown.append({
            'assignmentId': str(assignment.get('id') or ''),
            'role': role_name,
            'department': str(assignment.get('department') or ''),
            'providerType': provider_type or 'worker',
            'days': days,
            'pax': pax,
            'rate': round(rate, 2) if rate is not None else None,
            'amount': amount,
            'calculation': calculation,
        })
    return {
        'expectedAmount': (
            round(sum(row['amount'] for row in breakdown), 2)
            if breakdown and estimate_complete else None
        ),
        'expectedAmountBreakdown': breakdown,
    }


def _admin_file_payload(
    record, event_id, freelancer_id, kind, expectation=None
):
    payload = dict(record)
    submission_id = quote(str(record.get('id') or ''))
    payload['previewUrl'] = f'/api/workforce/submissions/{submission_id}/file'
    payload['downloadUrl'] = f'/api/workforce/submissions/{submission_id}/file?download=1'
    payload['kind'] = kind
    payload['eventId'] = int(event_id)
    payload['freelancerId'] = str(freelancer_id)
    if isinstance(expectation, dict):
        payload.update(expectation)
    return payload


def _admin_submission_display_status(record):
    """Return the operational status shown in admin submission queues."""
    processing_state = str(record.get('processingState') or '').strip()
    submission_stage = str(record.get('submissionStage') or '').strip()
    if processing_state == 'Queued' or submission_stage == 'Queued':
        return 'queued', 'Queued'
    if processing_state == 'Processing' or submission_stage == 'Processing':
        return 'processing', 'Processing'
    if submission_stage == 'Details Required':
        return 'details-required', 'Details required'
    if record.get('paymentConfirmedAt'):
        return 'payment-confirmed', 'Payment Confirmed'

    status = str(record.get('status') or 'Pending Review')
    return {
        'Pending Review': ('to-review', 'Pending Review'),
        'Approved': ('to-pay', 'Approved'),
        'Paid': ('awaiting-confirmation', 'Paid'),
        'Denied': ('denied', 'Denied'),
    }.get(status, ('to-review', 'Pending Review'))


def _query_values(name):
    values = []
    for raw_value in request.args.getlist(name):
        values.extend(str(raw_value or '').split(','))
    return {
        value.strip().lower()
        for value in values
        if value.strip()
    }


def _admin_submission_rows(manager=None, workforce=None):
    manager = manager or _current_data_manager_object()
    workforce = workforce or load_workforce(_workforce_folder(manager))
    department_by_code = {
        str(row.get('code') or '').upper(): row
        for row in _department_codes_for_manager(manager)
        if isinstance(row, dict) and row.get('code')
    }
    subjects = {}
    for subject_type, collection in (
        ('worker', workforce.get('freelancers', [])),
        ('vendor', workforce.get('vendors', [])),
    ):
        for subject in collection:
            if not isinstance(subject, dict) or not subject.get('id'):
                continue
            subjects[str(subject['id'])] = (subject, subject_type)

    context_cache = {}

    def submission_context(event_id, event, subject_id):
        cache_key = (int(event_id), str(subject_id))
        if cache_key in context_cache:
            return context_cache[cache_key]
        subject, subject_type = subjects.get(
            str(subject_id),
            ({'name': 'Former worker or vendor'}, 'unknown'),
        )
        assignment_departments = sorted({
            str(assignment.get('department') or '').strip()
            for assignment in event_assignments(workforce, event_id)
            if (
                isinstance(assignment, dict)
                and str(
                    assignment.get('freelancerId')
                    or assignment.get('vendorId')
                    or ''
                ) == str(subject_id)
                and str(assignment.get('department') or '').strip()
            )
        })
        department_details = [
            {
                'code': code,
                'name': str(
                    (department_by_code.get(code.upper()) or {}).get('name')
                    or code
                ),
                'color': _normalise_hex_colour(
                    (department_by_code.get(code.upper()) or {}).get('color')
                ),
                'textColor': _normalise_hex_colour(
                    (department_by_code.get(code.upper()) or {}).get('textColor')
                    or _best_text_colour(
                        (department_by_code.get(code.upper()) or {}).get('color')
                    ),
                    _best_text_colour(
                        (department_by_code.get(code.upper()) or {}).get('color')
                    ),
                ),
            }
            for code in assignment_departments
        ]
        context = {
            'subject': {
                'id': str(subject_id),
                'name': str(subject.get('name') or 'Unknown'),
                'type': subject_type,
                'company': str(subject.get('company') or ''),
            },
            'departments': assignment_departments,
            'departmentDetails': department_details,
            'event': {
                'id': event_id,
                'name': str(event.name or f'Event {event_id}'),
                'location': str(getattr(event, 'location', '') or ''),
                'startDate': _event_date_for_worker(event.start_date),
                'endDate': _event_date_for_worker(event.end_date),
                'startDateValue': _event_date_for_input(event.start_date),
                'endDateValue': _event_date_for_input(event.end_date),
                'state': str(event.state or 'New'),
                'tag': str(getattr(event, 'tag', 'events') or 'events'),
            },
            **_workforce_submission_expectation(
                workforce, event_id, subject_id
            ),
        }
        context_cache[cache_key] = context
        return context

    rows = []
    for raw_event_id, event_subjects in (workforce.get('submissions') or {}).items():
        try:
            event_id = int(raw_event_id)
        except (TypeError, ValueError):
            continue
        event = manager.events.get(event_id)
        if not event or not isinstance(event_subjects, dict):
            continue
        for subject_id, submissions in event_subjects.items():
            if not isinstance(submissions, dict):
                continue
            context = submission_context(event_id, event, subject_id)
            for collection_name, kind in (
                ('invoices', 'invoice'),
                ('claims', 'claim'),
            ):
                for record in submissions.get(collection_name, []):
                    if not isinstance(record, dict) or not record.get('id'):
                        continue
                    status_key, status_label = _admin_submission_display_status(record)
                    payload = _admin_file_payload(
                        record, event_id, subject_id, kind
                    )
                    payload.update({
                        'statusKey': status_key,
                        'statusLabel': status_label,
                        **context,
                    })
                    rows.append(payload)

    for raw_event_id, assignments in (workforce.get('assignments') or {}).items():
        try:
            event_id = int(raw_event_id)
        except (TypeError, ValueError):
            continue
        event = manager.events.get(event_id)
        if not event or not isinstance(assignments, list):
            continue
        assigned_subject_ids = {
            str(
                assignment.get('freelancerId')
                or assignment.get('vendorId')
                or ''
            )
            for assignment in assignments
            if isinstance(assignment, dict)
        }
        for subject_id in sorted(assigned_subject_ids):
            if not subject_id or subject_id not in subjects:
                continue
            submissions = worker_submissions(workforce, event_id, subject_id)
            active_invoices = [
                record
                for record in submissions.get('invoices', [])
                if (
                    isinstance(record, dict)
                    and str(record.get('status') or '') != 'Denied'
                )
            ]
            if active_invoices:
                continue
            rows.append({
                'id': f'awaiting-upload:{event_id}:{subject_id}',
                'kind': 'invoice',
                'eventId': event_id,
                'freelancerId': subject_id,
                'status': 'Awaiting Upload',
                'statusKey': 'awaiting-upload',
                'statusLabel': 'Awaiting upload',
                'isAwaitingUpload': True,
                'originalName': '',
                'submittedAt': '',
                'amount': None,
                **submission_context(event_id, event, subject_id),
            })

    def sort_key(row):
        date_digits = re.sub(
            r'\D', '', str(row['event'].get('startDateValue') or '')
        )
        date_value = int(date_digits or 0)
        return (
            -date_value,
            str(row['subject'].get('name') or '').casefold(),
            str(row['event'].get('name') or '').casefold(),
            str(row.get('originalName') or '').casefold(),
        )

    rows.sort(key=sort_key)
    return rows


def _admin_freelancer_payload(freelancer):
    hidden_fields = {
        'workerPasswordSalt',
        'workerPasswordHash',
    }
    payload = {
        key: value
        for key, value in (freelancer or {}).items()
        if key not in hidden_fields
    }
    payload['workerLoginConfigured'] = bool(
        (freelancer or {}).get('workerPasswordHash')
    )
    return payload


def _freelancer_admin_submission_summary(workforce, freelancer_id):
    freelancer_id = str(freelancer_id or '')
    assigned_event_ids = {
        str(event_id)
        for event_id, assignments in (workforce.get('assignments') or {}).items()
        if any(
            isinstance(row, dict)
            and str(row.get('freelancerId') or '') == freelancer_id
            for row in (assignments if isinstance(assignments, list) else [])
        )
    }
    summary = {
        'needsInvoice': 0,
        'needsReview': 0,
        'needsPayment': 0,
        'needsReceipt': 0,
    }
    for event_id in assigned_event_ids:
        rows = worker_submissions(workforce, event_id, freelancer_id)
        active_invoices = [
            row for row in rows.get('invoices', [])
            if isinstance(row, dict) and row.get('status') != 'Denied'
        ]
        if not active_invoices:
            summary['needsInvoice'] += 1
        for kind in ('invoices', 'claims'):
            for row in rows.get(kind, []):
                if not isinstance(row, dict):
                    continue
                status = str(row.get('status') or 'Pending Review')
                if (
                    status == 'Pending Review'
                    and row.get('processingState') != 'Processing'
                    and row.get('submissionStage') != 'Details Required'
                ):
                    summary['needsReview'] += 1
                elif status == 'Approved':
                    summary['needsPayment'] += 1
                elif status == 'Paid' and not row.get('paymentConfirmedAt'):
                    summary['needsReceipt'] += 1
    return summary


def _admin_freelancer_with_summary(freelancer, workforce):
    payload = _admin_freelancer_payload(freelancer)
    payload['submissionSummary'] = _freelancer_admin_submission_summary(
        workforce, payload.get('id')
    )
    return payload


def _admin_vendor_payload(vendor, workforce):
    member_ids = {
        str(value) for value in (vendor or {}).get('memberIds', [])
    }
    members = [
        _admin_freelancer_payload(row)
        for row in workforce.get('freelancers', [])
        if isinstance(row, dict) and str(row.get('id') or '') in member_ids
    ]
    login_members = [row for row in members if row.get('workerLastLoginAt')]

    def login_timestamp(member):
        try:
            value = str(member.get('workerLastLoginAt') or '').replace(
                'Z', '+00:00'
            )
            return datetime.fromisoformat(value).timestamp()
        except (TypeError, ValueError, OverflowError):
            return float('-inf')

    latest_login = max(login_members, key=login_timestamp, default=None)
    return {
        **(vendor or {}),
        'memberIds': sorted(member_ids),
        'members': members,
        'workerLastLoginAt': (
            latest_login.get('workerLastLoginAt') if latest_login else None
        ),
        'workerLastLoginBy': (
            latest_login.get('name') if latest_login else None
        ),
        'workerLastLoginById': (
            latest_login.get('id') if latest_login else None
        ),
        'submissionSummary': _freelancer_admin_submission_summary(
            workforce, (vendor or {}).get('id')
        ),
    }


def _workforce_subject(workforce, subject_id):
    worker = find_by_id(workforce.get('freelancers'), subject_id)
    if worker:
        return worker, 'worker'
    vendor = find_by_id(workforce.get('vendors'), subject_id)
    if vendor:
        return vendor, 'vendor'
    return None, ''


def _transport_profiles_for_response(workforce):
    profiles = [
        dict(row)
        for row in workforce.get('transportVendors', [])
        if isinstance(row, dict)
    ]
    latest_by_vendor = {}
    for rows in (workforce.get('transportBookings') or {}).values():
        for booking in rows if isinstance(rows, list) else []:
            if (
                not isinstance(booking, dict)
                or str(booking.get('sourceType') or 'external') != 'external'
                or not booking.get('vendorId')
            ):
                continue
            timestamp = str(
                booking.get('updatedAt')
                or booking.get('createdAt')
                or ''
            )
            vendor_id = str(booking.get('vendorId'))
            previous = latest_by_vendor.get(vendor_id)
            if previous is None or timestamp >= previous['timestamp']:
                latest_by_vendor[vendor_id] = {
                    'timestamp': timestamp,
                    'cost': money(booking.get('cost'), 0.0) or 0.0,
                }
    for profile in profiles:
        latest = latest_by_vendor.get(str(profile.get('id') or ''))
        profile['lastCost'] = latest['cost'] if latest else None
        profile['lastUsedAt'] = latest['timestamp'] if latest else ''
    return profiles


def _workforce_subproject_options(event):
    """Return the event rooms available to workforce and transport records."""
    options = []
    for row in getattr(event, 'subprojects', []) or []:
        if not isinstance(row, dict):
            continue
        subproject_id = str(row.get('id') or '').strip()
        if not subproject_id:
            continue
        options.append({
            'id': subproject_id,
            'name': str(row.get('name') or 'Room').strip() or 'Room',
        })
    return options


def _workforce_subproject_details(event, requested_id=None):
    """Validate a room ID and return its canonical ID and display name."""
    options = _workforce_subproject_options(event)
    requested = str(requested_id or '').strip()
    if not options:
        if requested:
            raise ValueError('This event does not have sub-projects')
        return '', ''
    if not requested:
        return options[0]['id'], options[0]['name']
    selected = next(
        (row for row in options if row['id'] == requested),
        None,
    )
    if not selected:
        raise ValueError('Choose a valid event room')
    return selected['id'], selected['name']


def _workforce_row_with_subproject(row, event, options=None):
    """Add effective room details without mutating legacy stored records."""
    payload = dict(row)
    options = options if isinstance(options, list) else (
        _workforce_subproject_options(event)
    )
    room_id = str(payload.get('subprojectId') or '').strip()
    selected = next(
        (option for option in options if option['id'] == room_id),
        None,
    )
    if selected is None and options:
        selected = options[0]
    payload['subprojectId'] = selected['id'] if selected else ''
    payload['subprojectName'] = selected['name'] if selected else ''
    return payload


def _admin_workforce_payload(event_id, manager=None):
    manager = manager or _current_data_manager_object()
    event = manager.events.get(int(event_id))
    if not event:
        raise LookupError('Event not found')
    workforce = load_workforce(_workforce_folder(manager))
    departments, all_departments = _event_workforce_departments(
        event_id, event, manager, workforce
    )
    submissions = {}
    event_submission_rows = (
        (workforce.get('submissions') or {}).get(str(event_id), {}) or {}
    )
    for freelancer_id, rows in event_submission_rows.items():
        rows = rows if isinstance(rows, dict) else {}
        expectation = _workforce_submission_expectation(
            workforce, event_id, freelancer_id
        )
        submissions[str(freelancer_id)] = {
            'invoices': [
                _admin_file_payload(
                    row, event_id, freelancer_id, 'invoice', expectation
                )
                for row in rows.get('invoices', [])
                if isinstance(row, dict)
            ],
            'claims': [
                _admin_file_payload(
                    row, event_id, freelancer_id, 'claim', expectation
                )
                for row in rows.get('claims', [])
                if isinstance(row, dict)
            ],
        }

    subprojects = _workforce_subproject_options(event)
    assignments = [
        _workforce_row_with_subproject(row, event, subprojects)
        for row in event_assignments(workforce, event_id)
        if isinstance(row, dict)
    ]
    bookings = []
    for booking in event_bookings(workforce, event_id):
        if not isinstance(booking, dict):
            continue
        row = _workforce_row_with_subproject(
            booking, event, subprojects
        )
        invoice = row.get('invoice')
        if isinstance(invoice, dict) and invoice.get('id'):
            submission_id = quote(str(invoice['id']))
            invoice = dict(invoice)
            invoice['previewUrl'] = f'/api/workforce/submissions/{submission_id}/file'
            invoice['downloadUrl'] = f'/api/workforce/submissions/{submission_id}/file?download=1'
            row['invoice'] = invoice
        bookings.append(row)

    upload_allowances = {}
    freelancer_ids = {
        str(row.get('freelancerId') or row.get('vendorId') or '')
        for row in assignments
        if (
            isinstance(row, dict)
            and (row.get('freelancerId') or row.get('vendorId'))
        )
    }
    freelancer_ids.update(str(key) for key in event_submission_rows)
    for freelancer_id in freelancer_ids:
        upload_allowances[freelancer_id] = _worker_upload_limits(
            workforce, event_id, freelancer_id
        )

    return {
        'company': _company_payload(_current_company_code()),
        'event': {
            'id': event.event_id,
            'name': event.name,
            'location': getattr(event, 'location', '') or '',
            'startDate': _event_date_for_worker(event.start_date),
            'endDate': _event_date_for_worker(event.end_date),
            'startDateValue': _event_date_for_input(event.start_date),
            'endDateValue': _event_date_for_input(event.end_date),
            'state': event.state,
            'tag': getattr(event, 'tag', 'events'),
            'subprojects': subprojects,
        },
        'freelancers': [
            _admin_freelancer_with_summary(row, workforce)
            for row in workforce.get('freelancers', [])
            if isinstance(row, dict)
        ],
        'vendors': [
            _admin_vendor_payload(row, workforce)
            for row in workforce.get('vendors', [])
            if isinstance(row, dict)
        ],
        'roles': workforce.get('roles', []),
        'assignments': assignments,
        'subprojects': subprojects,
        'transportVendors': _transport_profiles_for_response(workforce),
        'transportLocations': workforce.get('transportLocations', []),
        'vehicles': workforce.get('vehicles', []),
        'transportBookings': bookings,
        'submissions': submissions,
        'uploadAllowances': upload_allowances,
        'departments': departments,
        'allDepartments': all_departments,
        'totals': submission_totals(workforce, event_id),
        'updatedAt': workforce.get('updatedAt', ''),
    }


def _workforce_financial_closure_complete(
    event_id, manager=None, event=None, workforce=None
):
    """Return whether every assigned worker/vendor has settled submissions."""
    manager = manager or _current_data_manager_object()
    if manager is None:
        return True

    managed_event = getattr(manager, 'events', {}).get(int(event_id))
    if managed_event is None or (event is not None and managed_event is not event):
        return True

    workforce = (
        workforce
        if isinstance(workforce, dict)
        else load_workforce(_workforce_folder(manager))
    )
    subject_ids = {
        str(row.get('freelancerId') or row.get('vendorId') or '')
        for row in event_assignments(workforce, event_id)
        if (
            isinstance(row, dict)
            and (row.get('freelancerId') or row.get('vendorId'))
        )
    }
    if not subject_ids:
        return True

    for subject_id in subject_ids:
        rows = worker_submissions(workforce, event_id, subject_id)
        invoices = [
            row
            for row in rows.get('invoices', [])
            if isinstance(row, dict) and row.get('status') != 'Denied'
        ]
        if not invoices:
            return False

        payable_rows = invoices + [
            row
            for row in rows.get('claims', [])
            if isinstance(row, dict) and row.get('status') != 'Denied'
        ]
        if any(row.get('status') != 'Paid' for row in payable_rows):
            return False
    return True


def _workforce_changed(event_id, action):
    manager = _current_data_manager_object()
    event = getattr(manager, 'events', {}).get(int(event_id)) if manager else None
    if event:
        old_state = normalize_event_state(getattr(event, 'state', 'New'))
        update_event_state(event)
        if event.state != old_state:
            manager.save_event(event)
            invalidate_cache()
            mark_realtime_change('events', {
                'eventId': int(event_id),
                'action': 'state-updated',
                'oldState': old_state,
                'newState': event.state,
            })
    mark_realtime_change(
        'workforce',
        {'eventId': int(event_id), 'action': str(action or 'updated')},
    )


