@app.route(
    '/api/workforce/freelancers/<freelancer_id>/history',
    methods=['GET'],
)
@app.route(
    '/api/workforce/subjects/<freelancer_id>/history',
    methods=['GET'],
)
@require_admin
def workforce_freelancer_history(freelancer_id):
    manager = _current_data_manager_object()
    workforce = load_workforce(_workforce_folder(manager))
    freelancer, subject_type = _workforce_subject(workforce, freelancer_id)
    if not freelancer:
        return jsonify({'error': 'Worker or vendor not found'}), 404
    events = []
    for raw_event_id, assignments in (workforce.get('assignments') or {}).items():
        matching = [
            row for row in assignments
            if (
                isinstance(row, dict)
                and str(
                    row.get('freelancerId') or row.get('vendorId') or ''
                ) == str(freelancer_id)
            )
        ] if isinstance(assignments, list) else []
        if not matching:
            continue
        try:
            event_id = int(raw_event_id)
        except (TypeError, ValueError):
            continue
        event = data_manager.events.get(event_id)
        if not event:
            continue
        rows = worker_submissions(workforce, event_id, freelancer_id)
        expectation = _workforce_submission_expectation(
            workforce, event_id, freelancer_id
        )
        invoices = [
            _admin_file_payload(
                row, event_id, freelancer_id, 'invoice', expectation
            )
            for row in rows.get('invoices', [])
            if isinstance(row, dict)
        ]
        claims = [
            _admin_file_payload(
                row, event_id, freelancer_id, 'claim', expectation
            )
            for row in rows.get('claims', [])
            if isinstance(row, dict)
        ]
        limits = _worker_upload_limits(
            workforce, event_id, freelancer_id
        )
        events.append({
            'id': event_id,
            'name': event.name,
            'location': getattr(event, 'location', '') or '',
            'startDate': _event_date_for_worker(event.start_date),
            'endDate': _event_date_for_worker(event.end_date),
            'roles': [
                {
                    'id': str(row.get('id') or ''),
                    'department': str(row.get('department') or ''),
                    'role': str(
                        row.get('serviceName')
                        or row.get('roleName')
                        or (
                            f"{int(row.get('pax') or 0)} pax manpower"
                            if row.get('providerType') == 'manpower'
                            else 'Vendor service'
                        )
                    ),
                    'days': int(row.get('days') or 0),
                    'dailyRate': row.get('dailyRate'),
                    'workDates': list(row.get('workDates') or []),
                    'providerType': str(row.get('providerType') or ''),
                    'pax': int(row.get('pax') or 0),
                    'ratePerPax': row.get('ratePerPax'),
                    'serviceName': str(row.get('serviceName') or ''),
                    'serviceCost': row.get('serviceCost'),
                }
                for row in matching
            ],
            'invoices': invoices,
            'claims': claims,
            'invoiceTotal': round(sum(
                money(row.get('amount'), 0.0) or 0.0
                for row in invoices
                if row.get('status') != 'Denied'
            ), 2),
            'claimTotal': round(sum(
                money(row.get('amount'), 0.0) or 0.0
                for row in claims
                if row.get('status') != 'Denied'
            ), 2),
            **limits,
        })
    events.sort(
        key=lambda row: (row['startDate'], row['id']),
        reverse=True,
    )
    return jsonify({
        'success': True,
        'data': {
            'company': _company_payload(_current_company_code()),
            'subjectType': subject_type,
            'subject': (
                _admin_vendor_payload(freelancer, workforce)
                if subject_type == 'vendor'
                else _admin_freelancer_with_summary(freelancer, workforce)
            ),
            'freelancer': (
                _admin_vendor_payload(freelancer, workforce)
                if subject_type == 'vendor'
                else _admin_freelancer_with_summary(freelancer, workforce)
            ),
            'freelancers': sorted(
                [
                    _admin_freelancer_with_summary(row, workforce)
                    for row in workforce.get('freelancers', [])
                    if isinstance(row, dict)
                ],
                key=lambda row: str(row.get('name') or '').casefold(),
            ),
            'subjects': sorted(
                [
                    {
                        **_admin_freelancer_with_summary(row, workforce),
                        'subjectType': 'worker',
                    }
                    for row in workforce.get('freelancers', [])
                    if isinstance(row, dict) and not row.get('personnelOnly')
                ] + [
                    {
                        **_admin_vendor_payload(row, workforce),
                        'subjectType': 'vendor',
                    }
                    for row in workforce.get('vendors', [])
                    if isinstance(row, dict)
                ],
                key=lambda row: str(row.get('name') or '').casefold(),
            ),
            'departments': _department_codes_for_manager(manager),
            'events': events,
        },
    })


@app.route(
    '/api/workforce/freelancers/<freelancer_id>/reset-login',
    methods=['POST'],
)
@require_admin
def reset_workforce_freelancer_login(freelancer_id):
    manager = _current_data_manager_object()
    loaded = load_workforce(_workforce_folder(manager))
    freelancer = find_by_id(loaded.get('freelancers'), freelancer_id)
    if not freelancer:
        return jsonify({'error': 'Worker not found'}), 404
    phone = normalize_phone(freelancer.get('phone'))
    if not phone:
        return jsonify({
            'error': 'Add a phone number before resetting worker login'
        }), 400

    targets = _worker_matches_for_phone(phone)
    current_key = (_current_company_code(), str(freelancer_id))
    if not any(
        (company_code, str(row.get('id') or '')) == current_key
        for company_code, _manager, _workforce, row in targets
    ):
        targets.append((
            _current_company_code(), manager, loaded, freelancer
        ))

    reset_count = 0
    seen = set()
    for company_code, target_manager, _loaded, target in targets:
        key = (company_code, str(target.get('id') or ''))
        if key in seen:
            continue
        seen.add(key)
        with mutate_workforce(
            _workforce_folder(target_manager)
        ) as workforce:
            current = find_by_id(
                workforce.get('freelancers'), target.get('id')
            )
            if not current:
                continue
            for field in (
                'workerPasswordSalt',
                'workerPasswordHash',
                'workerCredentialType',
                'workerCredentialsSetAt',
            ):
                current.pop(field, None)
            current['workerAuthVersion'] = int(
                current.get('workerAuthVersion') or 0
            ) + 1
            current['workerLoginResetAt'] = now_iso()
            current['updatedAt'] = now_iso()
            reset_count += 1

    log_action(f"Reset worker login for {freelancer.get('name') or phone}")
    mark_realtime_change('workforce', {
        'action': 'worker-login-reset',
        'phone': phone,
    })
    return jsonify({
        'success': True,
        'message': 'Worker login reset',
        'data': {'profilesReset': reset_count},
    })


@app.route('/api/workforce/roles', methods=['POST'])
@require_admin
def create_workforce_role():
    payload = request.get_json(silent=True) or {}
    name = str(payload.get('name') or '').strip()
    department = _normalise_department_code(payload.get('department'))
    if not name:
        return jsonify({'error': 'Role name is required'}), 400
    with mutate_workforce(_workforce_folder()) as workforce:
        existing = next(
            (
                row for row in workforce.get('roles', [])
                if isinstance(row, dict)
                and str(row.get('name') or '').lower() == name.lower()
                and str(row.get('department') or '') == department
            ),
            None,
        )
        if existing:
            role = existing
        else:
            role = {
                'id': new_id('role'),
                'name': name,
                'department': department,
                'createdAt': now_iso(),
            }
            workforce.setdefault('roles', []).append(role)
    return jsonify({'success': True, 'data': role})


@app.route(
    '/api/events/<int:event_id>/workforce/departments',
    methods=['POST'],
)
@require_admin
def add_event_workforce_department(event_id):
    event = data_manager.events.get(event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    payload = request.get_json(silent=True) or {}
    code = _normalise_department_code(payload.get('code'))
    if not code:
        return jsonify({'error': 'Department code is required'}), 400
    configured = _load_departments()
    configured_row = configured.get(code) or {}
    name = str(
        payload.get('name')
        or configured_row.get('name')
        or code
    ).strip() or code

    with mutate_workforce(_workforce_folder()) as workforce:
        hidden = workforce.setdefault('hiddenDepartments', {}).setdefault(
            str(event_id), []
        )
        hidden[:] = [
            existing_code for existing_code in hidden
            if _normalise_department_code(existing_code) != code
        ]
        rows = workforce.setdefault('manualDepartments', {}).setdefault(
            str(event_id), []
        )
        existing = next(
            (
                row for row in rows
                if isinstance(row, dict)
                and _normalise_department_code(row.get('code')) == code
            ),
            None,
        )
        if existing:
            existing['name'] = name
        else:
            rows.append({'code': code, 'name': name, 'createdAt': now_iso()})

    log_action(f"Added manual department {code} to event {event_id}")
    _workforce_changed(event_id, 'department-added')
    return jsonify({'success': True, 'data': _admin_workforce_payload(event_id)})


@app.route(
    '/api/events/<int:event_id>/workforce/departments/<department_code>',
    methods=['DELETE'],
)
@require_admin
def delete_event_workforce_department(event_id, department_code):
    if event_id not in data_manager.events:
        return jsonify({'error': 'Event not found'}), 404
    code = _normalise_department_code(department_code)
    with mutate_workforce(_workforce_folder()) as workforce:
        if any(
            _normalise_department_code(row.get('department')) == code
            for row in event_assignments(workforce, event_id)
            if isinstance(row, dict)
        ):
            return jsonify({
                'error': 'Remove the workers and companies in this department first'
            }), 409
        manual = workforce.setdefault('manualDepartments', {}).setdefault(
            str(event_id), []
        )
        manual[:] = [
            row for row in manual
            if (
                not isinstance(row, dict)
                or _normalise_department_code(row.get('code')) != code
            )
        ]
        hidden = workforce.setdefault('hiddenDepartments', {}).setdefault(
            str(event_id), []
        )
        if code not in {
            _normalise_department_code(value) for value in hidden
        }:
            hidden.append(code)
    log_action(f"Removed department {code} from event {event_id}")
    _workforce_changed(event_id, 'department-removed')
    return jsonify({'success': True, 'data': _admin_workforce_payload(event_id)})


@app.route('/api/events/<int:event_id>/workforce/assignments', methods=['POST'])
@require_admin
def create_workforce_assignment(event_id):
    if event_id not in data_manager.events:
        return jsonify({'error': 'Event not found'}), 404
    payload = request.get_json(silent=True) or {}
    freelancer_id = str(
        payload.get('freelancerId') or payload.get('vendorId') or ''
    )
    requested_vendor = bool(payload.get('vendorId'))
    department = _normalise_department_code(payload.get('department'))
    role_id = str(payload.get('roleId') or '').strip()
    custom_role = str(payload.get('customRole') or '').strip()
    work_dates = [
        str(value or '').strip()
        for value in payload.get('workDates', [])
        if str(value or '').strip()
    ] if isinstance(payload.get('workDates'), list) else []
    try:
        days = len(work_dates) or int(payload.get('days') or 0)
    except (TypeError, ValueError):
        days = 0
    daily_rate = money(payload.get('dailyRate'))
    if not freelancer_id or not department or days <= 0:
        return jsonify({
            'error': 'Worker or vendor, department and working dates are required'
        }), 400
    event = data_manager.events[event_id]
    try:
        subproject_id, subproject_name = _workforce_subproject_details(
            event, payload.get('subprojectId')
        )
    except ValueError as exc:
        return jsonify({'error': str(exc)}), 400
    start_date = _event_date_for_input(event.start_date)
    end_date = _event_date_for_input(event.end_date)
    if work_dates and any(
        value < start_date or value > end_date for value in work_dates
    ):
        return jsonify({'error': 'Choose working dates within the event'}), 400

    with mutate_workforce(_workforce_folder()) as workforce:
        allowed_departments, _all_departments = _event_workforce_departments(
            event_id,
            data_manager.events[event_id],
            _current_data_manager_object(),
            workforce,
        )
        if department not in {row['code'] for row in allowed_departments}:
            return jsonify({
                'error': 'Choose an event asset department or add one manually'
            }), 400
        freelancer = find_by_id(workforce.get('freelancers'), freelancer_id)
        vendor = find_by_id(workforce.get('vendors'), freelancer_id)
        if requested_vendor or vendor:
            if not vendor:
                return jsonify({'error': 'Vendor not found'}), 404
            provider_type = str(
                payload.get('providerType') or ''
            ).strip().lower()
            if provider_type not in {'manpower', 'service'}:
                return jsonify({
                    'error': 'Choose whether the vendor provides manpower or a service'
                }), 400
            assignment = {
                'id': new_id('assignment'),
                'freelancerId': freelancer_id,
                'vendorId': freelancer_id,
                'subjectType': 'vendor',
                'department': department,
                'subprojectId': subproject_id,
                'providerType': provider_type,
                'days': days,
                'workDates': sorted(set(work_dates)),
                'createdAt': now_iso(),
            }
            if provider_type == 'manpower':
                try:
                    pax = int(payload.get('pax') or 0)
                except (TypeError, ValueError):
                    pax = 0
                rate_per_pax = money(payload.get('ratePerPax'))
                if pax <= 0 or rate_per_pax is None:
                    return jsonify({
                        'error': 'Number of pax and rate per pax are required'
                    }), 400
                assignment.update({
                    'pax': pax,
                    'ratePerPax': rate_per_pax,
                    'dailyRate': rate_per_pax,
                    'roleName': f'{pax} pax manpower',
                })
            else:
                service_name = str(
                    payload.get('serviceName') or ''
                ).strip()
                service_cost = money(payload.get('serviceCost'))
                if not service_name or service_cost is None:
                    return jsonify({
                        'error': 'Service name and cost are required'
                    }), 400
                assignment.update({
                    'serviceName': service_name,
                    'serviceCost': service_cost,
                    'dailyRate': service_cost,
                    'roleName': service_name,
                })
            workforce.setdefault('assignments', {}).setdefault(
                str(event_id), []
            ).append(assignment)
            subject_name = vendor.get('name')
            log_message = (
                f"Assigned vendor {subject_name} to event {event_id} "
                f"as {provider_type}"
                f"{f' in {subproject_name}' if subproject_name else ''}"
            )
        else:
            if not freelancer:
                return jsonify({'error': 'Worker not found'}), 404
            role = find_by_id(workforce.get('roles'), role_id) if role_id else None
            role_name = custom_role or (str(role.get('name')) if role else '')
            if custom_role and bool(payload.get('saveRole', True)):
                duplicate = next(
                    (
                        row for row in workforce.get('roles', [])
                        if isinstance(row, dict)
                        and str(row.get('name') or '').lower() == custom_role.lower()
                        and str(row.get('department') or '') == department
                    ),
                    None,
                )
                if duplicate:
                    role_id = str(duplicate.get('id') or '')
                else:
                    saved_role = {
                        'id': new_id('role'),
                        'name': custom_role,
                        'department': department,
                        'createdAt': now_iso(),
                    }
                    workforce.setdefault('roles', []).append(saved_role)
                    role_id = saved_role['id']
            assignment = {
                'id': new_id('assignment'),
                'freelancerId': freelancer_id,
                'subjectType': 'worker',
                'department': department,
                'subprojectId': subproject_id,
                'roleId': role_id,
                'roleName': role_name,
                'days': days,
                'workDates': sorted(set(work_dates)),
                'dailyRate': daily_rate,
                'notes': str(payload.get('notes') or '').strip(),
                'createdAt': now_iso(),
            }
            workforce.setdefault('assignments', {}).setdefault(
                str(event_id), []
            ).append(assignment)
            subject_name = freelancer.get('name')
            log_message = (
                f"Assigned worker {subject_name} to event {event_id}"
                f"{f' as {role_name}' if role_name else ''}"
                f"{f' in {subproject_name}' if subproject_name else ''}"
            )
    log_action(log_message)
    _workforce_changed(event_id, 'assignment-created')
    return jsonify({'success': True, 'data': _admin_workforce_payload(event_id)})


@app.route(
    '/api/events/<int:event_id>/workforce/assignments/<assignment_id>',
    methods=['PUT'],
)
@require_admin
def update_workforce_assignment(event_id, assignment_id):
    payload = request.get_json(silent=True) or {}
    department = _normalise_department_code(payload.get('department'))
    role_name = str(payload.get('customRole') or '').strip()
    daily_rate = money(payload.get('dailyRate'))
    work_dates = [
        str(value or '').strip()
        for value in payload.get('workDates', [])
        if str(value or '').strip()
    ] if isinstance(payload.get('workDates'), list) else []
    try:
        days = len(work_dates) or int(payload.get('days') or 0)
    except (TypeError, ValueError):
        days = 0
    if not department or days <= 0:
        return jsonify({
            'error': 'Department and working dates are required'
        }), 400
    event = data_manager.events.get(event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    try:
        subproject_id, subproject_name = _workforce_subproject_details(
            event, payload.get('subprojectId')
        )
    except ValueError as exc:
        return jsonify({'error': str(exc)}), 400
    start_date = _event_date_for_input(event.start_date)
    end_date = _event_date_for_input(event.end_date)
    if work_dates and any(
        value < start_date or value > end_date for value in work_dates
    ):
        return jsonify({'error': 'Choose working dates within the event'}), 400
    with mutate_workforce(_workforce_folder()) as workforce:
        assignment = find_by_id(
            event_assignments(workforce, event_id), assignment_id
        )
        if not assignment:
            return jsonify({'error': 'Assignment not found'}), 404
        if assignment.get('vendorId') or assignment.get('subjectType') == 'vendor':
            provider_type = str(
                payload.get('providerType')
                or assignment.get('providerType')
                or ''
            ).strip().lower()
            if provider_type not in {'manpower', 'service'}:
                return jsonify({
                    'error': 'Choose whether the vendor provides manpower or a service'
                }), 400
            updates = {
                'department': department,
                'subprojectId': subproject_id,
                'providerType': provider_type,
                'days': days,
                'workDates': sorted(set(work_dates)),
                'updatedAt': now_iso(),
            }
            if provider_type == 'manpower':
                try:
                    pax = int(payload.get('pax') or 0)
                except (TypeError, ValueError):
                    pax = 0
                rate_per_pax = money(payload.get('ratePerPax'))
                if pax <= 0 or rate_per_pax is None:
                    return jsonify({
                        'error': 'Number of pax and rate per pax are required'
                    }), 400
                updates.update({
                    'pax': pax,
                    'ratePerPax': rate_per_pax,
                    'dailyRate': rate_per_pax,
                    'roleName': f'{pax} pax manpower',
                    'serviceName': '',
                    'serviceCost': None,
                })
            else:
                service_name = str(
                    payload.get('serviceName') or ''
                ).strip()
                service_cost = money(payload.get('serviceCost'))
                if not service_name or service_cost is None:
                    return jsonify({
                        'error': 'Service name and cost are required'
                    }), 400
                updates.update({
                    'serviceName': service_name,
                    'serviceCost': service_cost,
                    'dailyRate': service_cost,
                    'roleName': service_name,
                    'pax': 0,
                    'ratePerPax': None,
                })
            assignment.update(updates)
        else:
            assignment.update({
                'department': department,
                'subprojectId': subproject_id,
                'roleName': role_name,
                'days': days,
                'workDates': sorted(set(work_dates)),
                'dailyRate': daily_rate,
                'updatedAt': now_iso(),
            })
    log_action(
        f"Updated workforce assignment for event {event_id}"
        f"{f' in {subproject_name}' if subproject_name else ''}"
    )
    _workforce_changed(event_id, 'assignment-updated')
    return jsonify({'success': True, 'data': _admin_workforce_payload(event_id)})


@app.route(
    '/api/events/<int:event_id>/workforce/assignments/<assignment_id>',
    methods=['DELETE'],
)
@require_admin
def delete_workforce_assignment(event_id, assignment_id):
    data_folder = _workforce_folder()
    delete_uploads_confirmed = str(
        request.args.get('deleteUploads') or ''
    ).strip().lower() in {'1', 'true', 'yes'}
    with mutate_workforce(data_folder) as workforce:
        rows = event_assignments(workforce, event_id)
        assignment = find_by_id(rows, assignment_id)
        if not assignment:
            return jsonify({'error': 'Assignment not found'}), 404
        subject_id = str(
            assignment.get('freelancerId') or assignment.get('vendorId') or ''
        )
        kept_rows = [
            row for row in rows
            if not isinstance(row, dict) or str(row.get('id')) != str(assignment_id)
        ]
        still_assigned = any(
            str(row.get('freelancerId') or row.get('vendorId') or '') == subject_id
            for row in kept_rows
            if isinstance(row, dict)
        )
        subject_submissions = worker_submissions(workforce, event_id, subject_id)
        upload_records = [
            record
            for bucket in ('invoices', 'claims')
            for record in (
                subject_submissions.get(bucket, [])
                if isinstance(subject_submissions.get(bucket, []), list)
                else []
            )
            if isinstance(record, dict)
        ]
        if upload_records and not still_assigned and not delete_uploads_confirmed:
            return jsonify({
                'requiresUploadRemovalConfirmation': True,
                'uploadCount': len(upload_records),
                'error': (
                    'This worker or vendor has uploaded files for this event. '
                    'Confirm removal to delete those files before removing them.'
                ),
            }), 409

        rows[:] = kept_rows
        removed_upload_count = 0
        if not still_assigned:
            allowances = workforce.setdefault('uploadAllowances', {}).get(
                str(event_id)
            )
            if isinstance(allowances, dict):
                allowances.pop(subject_id, None)
            event_submissions = (workforce.get('submissions') or {}).get(
                str(event_id)
            )
            if isinstance(event_submissions, dict):
                removed_rows = event_submissions.pop(subject_id, {}) or {}
                for bucket in ('invoices', 'claims'):
                    records = (
                        removed_rows.get(bucket, [])
                        if isinstance(removed_rows, dict)
                        else []
                    )
                    for record in records if isinstance(records, list) else []:
                        if isinstance(record, dict):
                            delete_upload(data_folder, record)
                            removed_upload_count += 1
                if not event_submissions:
                    (workforce.get('submissions') or {}).pop(str(event_id), None)
    log_action(f"Removed workforce assignment from event {event_id}")
    _workforce_changed(
        event_id,
        'assignment-deleted-files-removed'
        if removed_upload_count else 'assignment-deleted',
    )
    return jsonify({'success': True, 'data': _admin_workforce_payload(event_id)})


@app.route(
    '/api/events/<int:event_id>/workforce/allowances/<freelancer_id>',
    methods=['POST'],
)
@require_admin
def add_workforce_upload_allowance(event_id, freelancer_id):
    if event_id not in data_manager.events:
        return jsonify({'error': 'Event not found'}), 404
    payload = request.get_json(silent=True) or {}
    kind = str(payload.get('kind') or '').strip().lower()
    if kind not in {'invoice', 'claim'}:
        return jsonify({'error': 'Choose invoice or claim allowance'}), 400
    try:
        delta = max(-20, min(20, int(payload.get('delta', payload.get('count', 1)))))
    except (TypeError, ValueError):
        delta = 1
    if delta == 0:
        return jsonify({'error': 'Upload slot change cannot be zero'}), 400

    with mutate_workforce(_workforce_folder()) as workforce:
        freelancer, subject_type = _workforce_subject(
            workforce, freelancer_id
        )
        if not freelancer:
            return jsonify({'error': 'Worker or vendor not found'}), 404
        assigned = any(
            str(row.get('freelancerId') or '') == str(freelancer_id)
            for row in event_assignments(workforce, event_id)
            if isinstance(row, dict)
        )
        if not assigned:
            return jsonify({'error': 'Worker or vendor is not assigned to this event'}), 400
        allowance = workforce.setdefault('uploadAllowances', {}).setdefault(
            str(event_id), {}
        ).setdefault(str(freelancer_id), {
            'extraInvoices': 0,
            'extraClaims': 0,
        })
        key = 'extraInvoices' if kind == 'invoice' else 'extraClaims'
        limits = _worker_upload_limits(workforce, event_id, freelancer_id)
        active_count = (
            limits['activeInvoices'] if kind == 'invoice'
            else limits['activeClaims']
        )
        base_limit = 1 if kind == 'invoice' else 5
        minimum_extra = max(0, active_count - base_limit)
        current_extra = max(0, int(allowance.get(key) or 0))
        allowance[key] = max(minimum_extra, current_extra + delta)
        allowance['updatedAt'] = now_iso()

    log_action(
        f"Changed {kind} upload allowance by {delta} for "
        f"{freelancer.get('name')} on event {event_id}"
    )
    _workforce_changed(event_id, f'{kind}-allowance-changed')
    return jsonify({'success': True, 'data': _admin_workforce_payload(event_id)})


@app.route(
    '/api/events/<int:event_id>/workforce/submissions/<freelancer_id>',
    methods=['POST'],
)
@require_admin
def admin_upload_workforce_submission(event_id, freelancer_id):
    if event_id not in data_manager.events:
        return jsonify({'error': 'Event not found'}), 404
    kind = str(request.form.get('kind') or '').strip().lower()
    if kind not in {'invoice', 'claim'}:
        return jsonify({'error': 'Choose invoice or claim'}), 400
    uploaded_files = [
        item for item in (
            request.files.getlist('files') or request.files.getlist('file')
        )
        if item and item.filename
    ]
    if not uploaded_files:
        return jsonify({'error': 'Choose a file to upload'}), 400

    saved_records = []
    try:
        manager = _current_data_manager_object()
        data_folder = _workforce_folder(manager)
        record_ids = []
        with mutate_workforce(data_folder) as workforce:
            freelancer, subject_type = _workforce_subject(
                workforce, freelancer_id
            )
            if not freelancer:
                return jsonify({'error': 'Worker or vendor not found'}), 404
            assignments = [
                row for row in event_assignments(workforce, event_id)
                if (
                    isinstance(row, dict)
                    and str(row.get('freelancerId') or '') == str(freelancer_id)
                )
            ]
            if not assignments:
                return jsonify({'error': 'Worker is not assigned to this event'}), 400
            limits = _worker_upload_limits(workforce, event_id, freelancer_id)
            remaining_key = (
                'invoiceSlotsRemaining'
                if kind == 'invoice'
                else 'claimSlotsRemaining'
            )
            if limits[remaining_key] < len(uploaded_files):
                return jsonify({
                    'error': (
                        f"Only {limits[remaining_key]} {kind} upload slot"
                        f"{' is' if limits[remaining_key] == 1 else 's are'} available."
                    )
                }), 409
            rows = worker_submissions(
                workforce, event_id, freelancer_id, create=True
            )
            entered_amount = money(request.form.get('amount'))
            claim_date = str(request.form.get('claimDate') or '').strip()
            category = str(request.form.get('category') or '').strip()
            if category == 'Other':
                category = str(request.form.get('otherCategory') or '').strip()
            description = str(
                request.form.get('notes')
                or request.form.get('description')
                or ''
            ).strip()
            department = _normalise_department_code(
                request.form.get('department')
            ) or _normalise_department_code(
                assignments[0].get('department')
            )
            for uploaded_file in uploaded_files:
                saved_record = save_upload(
                    data_folder,
                    uploaded_file,
                    event_id,
                    freelancer_id,
                    kind,
                )
                saved_records.append(saved_record)
                record = {
                    'id': new_id('sub'),
                    **saved_record,
                    'submittedAt': now_iso(),
                    'status': 'Pending Review',
                    'denialReason': '',
                    'processingState': 'Queued',
                    'submissionStage': 'Queued',
                    'amount': entered_amount,
                    'reviewHistory': [{
                        'at': now_iso(),
                        'by': session.get('user', ''),
                        'from': '',
                        'to': 'Pending Review',
                        'action': 'Admin upload',
                    }],
                }
                if kind == 'invoice':
                    record['allocations'] = []
                    rows.setdefault('invoices', []).append(record)
                else:
                    record.update({
                        'claimDate': claim_date,
                        'category': category,
                        'description': description,
                        'notes': description,
                        'department': department or 'Unassigned',
                        'detailsComplete': True,
                    })
                    rows.setdefault('claims', []).append(record)
                record_ids.append(record['id'])

        log_action(
            f"Admin uploaded {len(saved_records)} {kind} file(s) for {freelancer.get('name')} "
            f"on event {event_id}"
        )
        _workforce_changed(event_id, f'admin-{kind}-uploaded')
        for record_id in record_ids:
            args = (
                manager, data_folder, event_id, freelancer_id, record_id, kind
            )
            _queue_worker_submission_processing(args)
        return jsonify({
            'success': True,
            'data': _admin_workforce_payload(event_id),
        })
    except ValueError as exc:
        for saved_record in saved_records:
            delete_upload(_workforce_folder(), saved_record)
        return jsonify({'error': str(exc)}), 400
    except Exception as exc:
        for saved_record in saved_records:
            delete_upload(_workforce_folder(), saved_record)
        logger.error(
            'Admin workforce upload failed: %s', exc, exc_info=True
        )
        return jsonify({'error': 'The upload could not be completed'}), 500


def _transport_vendor_payload(raw):
    payload = raw if isinstance(raw, dict) else {}
    return {
        'vehicleType': str(payload.get('vehicleType') or '').strip(),
        'company': str(payload.get('company') or '').strip(),
        'driver': str(
            payload.get('driver') or payload.get('name') or ''
        ).strip(),
        'contactNumber': normalize_phone(payload.get('contactNumber')),
        'vehicleNumber': str(payload.get('vehicleNumber') or '').strip(),
    }


def _transport_payload(raw):
    payload = raw if isinstance(raw, dict) else {}
    source_type = str(payload.get('sourceType') or 'external').strip().lower()
    if source_type not in {'fleet', 'external'}:
        source_type = 'external'
    trip_type = str(payload.get('tripType') or 'depart').strip().lower()
    if trip_type not in {'depart', 'return'}:
        trip_type = 'depart'
    return {
        'subprojectId': str(payload.get('subprojectId') or '').strip(),
        'vendorId': str(payload.get('vendorId') or '').strip(),
        'vehicleId': str(payload.get('vehicleId') or '').strip(),
        'sourceType': source_type,
        'tripType': trip_type,
        'driver': str(payload.get('driver') or '').strip(),
        'driverContact': normalize_phone(payload.get('driverContact')),
        'locationFrom': str(payload.get('locationFrom') or '').strip(),
        'locationTo': str(payload.get('locationTo') or '').strip(),
        'twoWay': bool(payload.get('twoWay')),
        'departDate': str(payload.get('departDate') or '').strip(),
        'departTime': str(payload.get('departTime') or '').strip(),
        'useEndDate': str(payload.get('useEndDate') or '').strip(),
        'useEndTime': str(payload.get('useEndTime') or '').strip(),
        'returnDate': str(payload.get('returnDate') or '').strip(),
        'returnTime': str(payload.get('returnTime') or '').strip(),
        'cost': money(payload.get('cost'), 0.0) or 0.0,
        'status': (
            str(payload.get('status'))
            if str(payload.get('status')) in VALID_STATUSES
            else 'Pending Review'
        ),
    }


def _vehicle_payload(raw, existing=None):
    payload = raw if isinstance(raw, dict) else {}
    current = existing if isinstance(existing, dict) else {}
    registration = str(
        payload.get('registrationNumber', current.get('registrationNumber', ''))
        or ''
    ).strip().upper()
    vehicle_type = str(
        payload.get('vehicleType', current.get('vehicleType', '')) or ''
    ).strip()
    display_name = str(
        payload.get('name', current.get('name', '')) or ''
    ).strip()
    return {
        'name': display_name or vehicle_type or registration,
        'registrationNumber': registration,
        'vehicleType': vehicle_type,
        'notes': str(
            payload.get('notes', current.get('notes', '')) or ''
        ).strip(),
        'active': _request_bool(
            payload.get('active'),
            bool(current.get('active', True)),
        ),
    }


def _vehicle_window(date_value, start_time, end_date_value, end_time):
    date_text = str(date_value or '').strip()
    start_text = str(start_time or '').strip()
    end_date_text = str(end_date_value or date_text).strip()
    end_text = str(end_time or '').strip()
    try:
        start = datetime.strptime(
            f'{date_text} {start_text}', '%Y-%m-%d %H:%M'
        )
        end = datetime.strptime(
            f'{end_date_text} {end_text}', '%Y-%m-%d %H:%M'
        )
    except ValueError as exc:
        raise ValueError('Enter a valid booking date and time') from exc
    if end <= start:
        raise ValueError('Vehicle return time must be after its departure time')
    return start, end


def _vehicle_window_for_row(row):
    if not isinstance(row, dict):
        return None
    try:
        if str(row.get('sourceType') or '').lower() == 'fleet':
            return _vehicle_window(
                row.get('departDate'),
                row.get('departTime'),
                row.get('useEndDate') or row.get('departDate'),
                row.get('useEndTime'),
            )
        return _vehicle_window(
            row.get('date'),
            row.get('startTime'),
            row.get('endDate') or row.get('date'),
            row.get('endTime'),
        )
    except ValueError:
        return None


def _vehicle_booking_entries(workforce):
    entries = []
    for row in workforce.get('vehicleBookings', []):
        if not isinstance(row, dict):
            continue
        window = _vehicle_window_for_row(row)
        if window and row.get('vehicleId'):
            entries.append({
                'row': row,
                'eventId': None,
                'kind': 'standalone',
                'start': window[0],
                'end': window[1],
            })
    for event_key, rows in (workforce.get('transportBookings') or {}).items():
        for row in rows if isinstance(rows, list) else []:
            if (
                not isinstance(row, dict)
                or str(row.get('sourceType') or '').lower() != 'fleet'
                or not row.get('vehicleId')
            ):
                continue
            window = _vehicle_window_for_row(row)
            if not window:
                continue
            entries.append({
                'row': row,
                'eventId': _safe_int(event_key, 0) or None,
                'kind': 'event',
                'start': window[0],
                'end': window[1],
            })
    return entries


def _vehicle_conflicts(
    workforce,
    vehicle_id,
    start,
    end,
    exclude_booking_id='',
):
    conflicts = []
    for entry in _vehicle_booking_entries(workforce):
        row = entry['row']
        if (
            str(row.get('vehicleId') or '') != str(vehicle_id)
            or str(row.get('id') or '') == str(exclude_booking_id or '')
            or entry['start'] >= end
            or entry['end'] <= start
        ):
            continue
        conflicts.append(entry)
    return conflicts


def _vehicle_booking_conflict_message(conflicts):
    if not conflicts:
        return ''
    entry = conflicts[0]
    row = entry['row']
    label = str(row.get('purpose') or '').strip()
    if entry.get('eventId'):
        event = data_manager.events.get(int(entry['eventId']))
        label = f"event #{entry['eventId']} {getattr(event, 'name', '')}".strip()
    return (
        f"Vehicle is already booked for {label or 'another purpose'} from "
        f"{entry['start'].strftime('%d %b %Y, %H:%M')} to "
        f"{entry['end'].strftime('%d %b %Y, %H:%M')}"
    )


def _vehicle_day_payload(workforce, selected_date):
    try:
        day_start = datetime.strptime(selected_date, '%Y-%m-%d')
    except ValueError:
        selected_date = datetime.now().strftime('%Y-%m-%d')
        day_start = datetime.strptime(selected_date, '%Y-%m-%d')
    day_end = day_start + timedelta(days=1)
    vehicles = [
        dict(row)
        for row in workforce.get('vehicles', [])
        if isinstance(row, dict)
    ]
    vehicle_by_id = {
        str(row.get('id') or ''): row
        for row in vehicles
        if row.get('id')
    }
    bookings = []
    for entry in _vehicle_booking_entries(workforce):
        if entry['start'] >= day_end or entry['end'] <= day_start:
            continue
        row = entry['row']
        event_id = entry.get('eventId')
        event = data_manager.events.get(int(event_id)) if event_id else None
        bookings.append({
            'id': str(row.get('id') or ''),
            'vehicleId': str(row.get('vehicleId') or ''),
            'vehicle': vehicle_by_id.get(str(row.get('vehicleId') or ''), {}),
            'kind': entry['kind'],
            'eventId': event_id,
            'eventName': getattr(event, 'name', '') if event else '',
            'eventState': getattr(event, 'state', '') if event else '',
            'purpose': (
                f"{str(row.get('tripType') or 'depart').title()} trip"
                if event_id else str(row.get('purpose') or '')
            ),
            'direction': str(row.get('tripType') or ''),
            'driver': str(row.get('driver') or ''),
            'locationFrom': str(row.get('locationFrom') or ''),
            'locationTo': str(row.get('locationTo') or ''),
            'start': entry['start'].isoformat(timespec='minutes'),
            'end': entry['end'].isoformat(timespec='minutes'),
            'notes': str(row.get('notes') or ''),
            'canDelete': entry['kind'] == 'standalone',
        })
    bookings.sort(key=lambda row: (row['start'], row['vehicleId'], row['id']))
    vehicles.sort(key=lambda row: (
        not bool(row.get('active', True)),
        str(row.get('registrationNumber') or '').casefold(),
    ))
    return {
        'date': selected_date,
        'vehicles': vehicles,
        'bookings': bookings,
        'updatedAt': str(workforce.get('updatedAt') or ''),
    }


@app.route('/api/vehicles', methods=['GET', 'POST'])
@require_admin
def company_vehicles():
    if request.method == 'GET':
        workforce = load_workforce(_workforce_folder())
        selected_date = str(
            request.args.get('date') or datetime.now().strftime('%Y-%m-%d')
        ).strip()
        return jsonify({
            'success': True,
            'data': _vehicle_day_payload(workforce, selected_date),
        })

    payload = _vehicle_payload(request.get_json(silent=True) or {})
    if not payload['registrationNumber'] or not payload['vehicleType']:
        return jsonify({
            'error': 'Registration number and vehicle type are required'
        }), 400
    with mutate_workforce(_workforce_folder()) as workforce:
        duplicate = next((
            row for row in workforce.get('vehicles', [])
            if isinstance(row, dict)
            and str(row.get('registrationNumber') or '').casefold()
            == payload['registrationNumber'].casefold()
        ), None)
        if duplicate:
            return jsonify({'error': 'A vehicle with this registration already exists'}), 409
        vehicle = {
            'id': new_id('vehicle'),
            **payload,
            'createdAt': now_iso(),
            'updatedAt': now_iso(),
        }
        workforce.setdefault('vehicles', []).append(vehicle)
    log_action(f"Added fleet vehicle {vehicle['registrationNumber']}")
    mark_realtime_change('vehicles', {'action': 'vehicle-created', 'vehicleId': vehicle['id']})
    return jsonify({'success': True, 'data': vehicle}), 201


@app.route('/api/vehicles/availability', methods=['GET'])
@require_admin
def vehicle_availability():
    workforce = load_workforce(_workforce_folder())
    vehicles = [
        dict(row)
        for row in workforce.get('vehicles', [])
        if isinstance(row, dict) and row.get('active', True)
    ]
    required = (
        request.args.get('date'),
        request.args.get('startTime'),
        request.args.get('endDate'),
        request.args.get('endTime'),
    )
    if not all(required):
        return jsonify({
            'success': True,
            'data': {
                'complete': False,
                'vehicles': [],
            },
        })
    try:
        start, end = _vehicle_window(*required)
    except ValueError as exc:
        return jsonify({'error': str(exc)}), 400
    exclude_booking_id = str(
        request.args.get('excludeBookingId') or ''
    ).strip()
    result = []
    for vehicle in vehicles:
        conflicts = _vehicle_conflicts(
            workforce,
            vehicle.get('id'),
            start,
            end,
            exclude_booking_id=exclude_booking_id,
        )
        result.append({
            **vehicle,
            'available': not conflicts,
            'conflict': (
                _vehicle_booking_conflict_message(conflicts)
                if conflicts else ''
            ),
        })
    result.sort(key=lambda row: (
        not row['available'],
        str(row.get('registrationNumber') or '').casefold(),
    ))
    return jsonify({
        'success': True,
        'data': {
            'complete': True,
            'start': start.isoformat(timespec='minutes'),
            'end': end.isoformat(timespec='minutes'),
            'vehicles': result,
        },
    })


@app.route('/api/vehicles/<vehicle_id>', methods=['PUT', 'DELETE'])
@require_admin
def company_vehicle(vehicle_id):
    with mutate_workforce(_workforce_folder()) as workforce:
        vehicles = workforce.setdefault('vehicles', [])
        vehicle = find_by_id(vehicles, vehicle_id)
        if not vehicle:
            return jsonify({'error': 'Vehicle not found'}), 404
        if request.method == 'DELETE':
            is_referenced = any(
                str(entry['row'].get('vehicleId') or '') == str(vehicle_id)
                for entry in _vehicle_booking_entries(workforce)
            )
            if is_referenced:
                return jsonify({
                    'error': 'This vehicle has bookings. Mark it inactive instead.'
                }), 409
            vehicles.remove(vehicle)
            action = 'vehicle-deleted'
            registration = str(vehicle.get('registrationNumber') or '')
        else:
            payload = _vehicle_payload(
                request.get_json(silent=True) or {},
                vehicle,
            )
            if not payload['registrationNumber'] or not payload['vehicleType']:
                return jsonify({
                    'error': 'Registration number and vehicle type are required'
                }), 400
            duplicate = next((
                row for row in vehicles
                if (
                    isinstance(row, dict)
                    and str(row.get('id')) != str(vehicle_id)
                    and str(row.get('registrationNumber') or '').casefold()
                    == payload['registrationNumber'].casefold()
                )
            ), None)
            if duplicate:
                return jsonify({'error': 'A vehicle with this registration already exists'}), 409
            vehicle.update({**payload, 'updatedAt': now_iso()})
            action = 'vehicle-updated'
            registration = vehicle['registrationNumber']
    log_action(f"{'Deleted' if request.method == 'DELETE' else 'Updated'} fleet vehicle {registration}")
    mark_realtime_change('vehicles', {'action': action, 'vehicleId': str(vehicle_id)})
    return jsonify({'success': True, 'data': vehicle if request.method == 'PUT' else None})


@app.route('/api/vehicles/bookings', methods=['POST'])
@require_admin
def create_vehicle_booking():
    payload = request.get_json(silent=True) or {}
    vehicle_id = str(payload.get('vehicleId') or '').strip()
    purpose = str(payload.get('purpose') or '').strip()
    try:
        start, end = _vehicle_window(
            payload.get('date'),
            payload.get('startTime'),
            payload.get('endDate') or payload.get('date'),
            payload.get('endTime'),
        )
    except ValueError as exc:
        return jsonify({'error': str(exc)}), 400
    if not vehicle_id or not purpose:
        return jsonify({'error': 'Vehicle and purpose are required'}), 400
    with mutate_workforce(_workforce_folder()) as workforce:
        vehicle = find_by_id(workforce.get('vehicles'), vehicle_id)
        if not vehicle or not vehicle.get('active', True):
            return jsonify({'error': 'Choose an active fleet vehicle'}), 404
        conflicts = _vehicle_conflicts(workforce, vehicle_id, start, end)
        if conflicts:
            return jsonify({
                'error': _vehicle_booking_conflict_message(conflicts)
            }), 409
        booking = {
            'id': new_id('vehicle_booking'),
            'vehicleId': vehicle_id,
            'purpose': purpose,
            'date': start.strftime('%Y-%m-%d'),
            'startTime': start.strftime('%H:%M'),
            'endDate': end.strftime('%Y-%m-%d'),
            'endTime': end.strftime('%H:%M'),
            'notes': str(payload.get('notes') or '').strip(),
            'createdAt': now_iso(),
            'updatedAt': now_iso(),
        }
        workforce.setdefault('vehicleBookings', []).append(booking)
    log_action(f"Booked fleet vehicle {vehicle.get('registrationNumber')} for {purpose}")
    mark_realtime_change('vehicles', {'action': 'booking-created', 'vehicleId': vehicle_id})
    return jsonify({'success': True, 'data': booking}), 201


@app.route('/api/vehicles/bookings/<booking_id>', methods=['PUT', 'DELETE'])
@require_admin
def update_vehicle_booking(booking_id):
    payload = request.get_json(silent=True) or {}
    selected_date = str(payload.get('selectedDate') or payload.get('date') or '').strip()
    changed_event_id = None
    changed_vehicle_id = ''
    changed_registration = ''
    changed_purpose = ''
    with mutate_workforce(_workforce_folder()) as workforce:
        standalone = find_by_id(workforce.get('vehicleBookings'), booking_id)
        event_booking = None
        event_id = None
        if not standalone:
            for event_key, rows in (workforce.get('transportBookings') or {}).items():
                event_booking = find_by_id(rows, booking_id)
                if event_booking:
                    event_id = _safe_int(event_key, 0) or None
                    break
        booking = standalone or event_booking
        if not booking:
            return jsonify({'error': 'Vehicle booking not found'}), 404
        if request.method == 'DELETE':
            if event_booking:
                return jsonify({
                    'error': 'Event vehicle trips must be removed from Manpower & Transport'
                }), 400
            workforce.setdefault('vehicleBookings', []).remove(standalone)
            changed_vehicle_id = str(standalone.get('vehicleId') or '')
            deleted_vehicle = find_by_id(
                workforce.get('vehicles'), changed_vehicle_id
            )
            changed_registration = str(
                (deleted_vehicle or {}).get('registrationNumber') or ''
            )
            changed_purpose = str(standalone.get('purpose') or '')
        else:
            vehicle_id = str(
                payload.get('vehicleId') or booking.get('vehicleId') or ''
            ).strip()
            vehicle = find_by_id(workforce.get('vehicles'), vehicle_id)
            if not vehicle or not vehicle.get('active', True):
                return jsonify({'error': 'Choose an active fleet vehicle'}), 404
            date_value = payload.get('date') or (
                booking.get('departDate') if event_booking else booking.get('date')
            )
            start_time = payload.get('startTime') or (
                booking.get('departTime') if event_booking else booking.get('startTime')
            )
            end_date = payload.get('endDate') or (
                booking.get('useEndDate') if event_booking else booking.get('endDate')
            ) or date_value
            end_time = payload.get('endTime') or (
                booking.get('useEndTime') if event_booking else booking.get('endTime')
            )
            try:
                start, end = _vehicle_window(
                    date_value, start_time, end_date, end_time
                )
            except ValueError as exc:
                return jsonify({'error': str(exc)}), 400
            conflicts = _vehicle_conflicts(
                workforce,
                vehicle_id,
                start,
                end,
                exclude_booking_id=booking_id,
            )
            if conflicts:
                return jsonify({
                    'error': _vehicle_booking_conflict_message(conflicts)
                }), 409
            if event_booking:
                event_booking.update({
                    'vehicleId': vehicle_id,
                    'vehicleType': str(vehicle.get('vehicleType') or ''),
                    'vehicleNumber': str(vehicle.get('registrationNumber') or ''),
                    'departDate': start.strftime('%Y-%m-%d'),
                    'departTime': start.strftime('%H:%M'),
                    'useEndDate': end.strftime('%Y-%m-%d'),
                    'useEndTime': end.strftime('%H:%M'),
                    'updatedAt': now_iso(),
                })
                changed_event_id = event_id
            else:
                purpose = str(
                    payload.get('purpose', standalone.get('purpose', ''))
                    or ''
                ).strip()
                if not purpose:
                    return jsonify({'error': 'Booking purpose is required'}), 400
                standalone.update({
                    'vehicleId': vehicle_id,
                    'purpose': purpose,
                    'date': start.strftime('%Y-%m-%d'),
                    'startTime': start.strftime('%H:%M'),
                    'endDate': end.strftime('%Y-%m-%d'),
                    'endTime': end.strftime('%H:%M'),
                    'notes': str(
                        payload.get('notes', standalone.get('notes', ''))
                        or ''
                    ).strip(),
                    'updatedAt': now_iso(),
                })
            changed_vehicle_id = vehicle_id
            changed_registration = str(
                vehicle.get('registrationNumber') or ''
            )
            changed_purpose = str(
                booking.get('purpose')
                or booking.get('tripType')
                or 'booking'
            )
        response_payload = _vehicle_day_payload(
            workforce,
            selected_date or datetime.now().strftime('%Y-%m-%d'),
        )
    if changed_event_id:
        log_action(
            f"Rescheduled fleet vehicle {changed_registration} "
            f"for {changed_purpose} on event {changed_event_id}"
        )
        _workforce_changed(changed_event_id, 'fleet-booking-updated')
    else:
        log_action(
            f"{'Deleted' if request.method == 'DELETE' else 'Updated'} "
            f"fleet vehicle booking {changed_registration} "
            f"for {changed_purpose}"
        )
    mark_realtime_change('vehicles', {
        'action': (
            'booking-deleted'
            if request.method == 'DELETE'
            else 'booking-updated'
        ),
        'vehicleId': changed_vehicle_id,
        **({'eventId': changed_event_id} if changed_event_id else {}),
    })
    return jsonify({'success': True, 'data': response_payload})


def _transport_location_parts(name, address=''):
    location_name = str(name or '').strip()
    location_address = str(address or '').strip()
    if not location_address:
        match = re.match(r'^(.*?)\s*\(([^()]+)\)\s*$', location_name)
        if match:
            location_name = match.group(1).strip()
            location_address = match.group(2).strip()
    return location_name, location_address


def _remember_transport_location(workforce, name, address=''):
    location_name, location_address = _transport_location_parts(
        name, address
    )
    if not location_name:
        return None
    existing = next((
        row for row in workforce.get('transportLocations', [])
        if isinstance(row, dict)
        and str(row.get('name') or '').casefold() == location_name.casefold()
        and str(row.get('address') or '').casefold() == location_address.casefold()
    ), None)
    if existing:
        return existing
    location = {
        'id': new_id('location'),
        'name': location_name,
        'address': location_address,
        'createdAt': now_iso(),
    }
    workforce.setdefault('transportLocations', []).append(location)
    return location


