@app.route('/api/companies', methods=['POST'])
@require_super_admin
def create_company():
    """Owner: create a segregated company folder and optional first admin."""
    try:
        data = request.get_json() or {}
        name = str(data.get('name') or '').strip()
        raw_code = data.get('code') or name
        code = _normalise_company_code(raw_code)
        first_admin_username = str(data.get('firstAdminUsername') or '').strip()
        first_admin_password = data.get('firstAdminPassword') or ''

        if not code:
            return jsonify({'error': 'Company code is required'}), 400

        if not name:
            name = code

        if not first_admin_username:
            return jsonify({
                'error': 'A first admin username is required for every company'
            }), 400

        registry = _load_company_registry()
        if code in registry['companies']:
            return jsonify({'error': f'Company {code} already exists'}), 409

        existing_first_admin = data_manager.users.get(first_admin_username)
        if _is_owner_username(first_admin_username):
            return jsonify({
                'error': 'This protected account cannot be assigned as a company admin'
            }), 400
        if not existing_first_admin and not first_admin_password:
            return jsonify({'error': 'First admin user does not exist. Provide a password to create it.'}), 400
        if existing_first_admin:
            source_company = _normalise_company_code(
                _user_assigned_company_code(first_admin_username),
                DEFAULT_COMPANY_CODE,
            )
            if (
                _effective_user_role(existing_first_admin) == 'admin'
                and getattr(existing_first_admin, 'is_active', True)
                and len(_active_company_admin_usernames(source_company)) <= 1
            ):
                return jsonify({
                    'error': _last_company_admin_error(source_company)
                }), 409

        record = _new_company_record(
            code,
            name,
            created_by=session.get('user', ''),
            requires_branding_setup=True
        )
        registry['companies'][code] = record
        registry = _save_company_registry(registry)

        company_manager = _get_company_data_manager(code)
        settings_path = os.path.join(_company_record_backend_folder(record), 'PdfSettings.json')
        if not os.path.exists(settings_path):
            with open(settings_path, 'w', encoding='utf-8') as f:
                json.dump(_pdf_settings_defaults(), f, ensure_ascii=False, indent=2)

        if first_admin_username:
            user = existing_first_admin
            if not user:
                salt = secrets.token_hex(16)
                user = User(
                    username=first_admin_username,
                    password_hash=hash_password(first_admin_password, salt),
                    salt=salt,
                    is_admin=True,
                    is_active=True,
                    role='admin',
                )
                company_manager.users[first_admin_username] = user

            user.is_admin = True
            user.role = 'admin'
            user.is_active = True
            if first_admin_username in company_manager.users:
                company_manager.save_users()
            else:
                data_manager.save_users()
            _reload_users_for_all_company_managers()
            _assign_user_to_company(first_admin_username, code)

        _invalidate_company_storage_cache(code)
        mark_realtime_change('company-management', {'companyCode': code})
        log_action(f"Created company {code} ({name})")

        return jsonify({
            'success': True,
            'message': 'Company created successfully',
            'data': _company_payload(code)
        })
    except Exception as e:
        logger.error(f"Error creating company: {e}", exc_info=True)
        return jsonify({'error': 'Failed to create company'}), 500


@app.route('/api/companies/<path:company_code>', methods=['PUT'])
@require_super_admin
def update_company(company_code):
    """Owner: update a company's code and display name without breaking references."""
    global _active_company_code
    try:
        code = _normalise_company_code(unquote_plus(company_code))
        data = request.get_json() or {}
        new_code = _normalise_company_code(data.get('code') or data.get('companyCode') or code)
        name = str(data.get('name') or '').strip()
        registry = _load_company_registry()

        if not code or code not in registry['companies']:
            return jsonify({'error': 'Company not found'}), 404

        if not new_code:
            return jsonify({'error': 'Company code is required'}), 400

        if not name:
            return jsonify({'error': 'Company name is required'}), 400

        if new_code != code and new_code in registry['companies']:
            return jsonify({'error': f'Company {new_code} already exists'}), 409

        record = dict(registry['companies'][code])
        old_name = record.get('name') or code
        old_record = dict(record)

        company_manager = _company_data_managers.get(code)
        database_url = _database_url_for_runtime()
        if company_manager is None and database_url:
            company_manager = _get_company_data_manager(code)

        if new_code != code:
            _validate_company_rename_folder(code, new_code, record)

            if (
                company_manager is not None
                and hasattr(company_manager, 'rename_company_data')
                and database_url
            ):
                company_manager.rename_company_data(new_code, name)

            record = _safe_company_rename_record(code, new_code, record)
            registry['companies'].pop(code, None)
            registry['companies'][new_code] = record

            if _normalise_company_code(registry.get('defaultCompany'), DEFAULT_COMPANY_CODE) == code:
                registry['defaultCompany'] = new_code

            for username, assigned_company in list(registry.get('userCompanies', {}).items()):
                if _normalise_company_code(assigned_company, DEFAULT_COMPANY_CODE) == code:
                    registry['userCompanies'][username] = new_code
            for username, memberships in list(
                registry.get('userCompanyMemberships', {}).items()
            ):
                registry['userCompanyMemberships'][username] = [
                    new_code if _normalise_company_code(item) == code else item
                    for item in memberships
                ]

            _company_data_managers.pop(code, None)
            _company_data_managers.pop(new_code, None)

            if _normalise_company_code(_active_company_code, DEFAULT_COMPANY_CODE) == code:
                _active_company_code = new_code
            if session.get('company_code') and _normalise_company_code(session.get('company_code'), DEFAULT_COMPANY_CODE) == code:
                session['company_code'] = new_code
        else:
            record['code'] = code
            registry['companies'][code] = record

        record['name'] = name
        record['updatedAt'] = datetime.now().isoformat(timespec='seconds')
        registry['companies'][new_code] = record
        _save_company_registry(registry)
        _invalidate_company_storage_cache(code, new_code)

        if new_code != code and _normalise_company_code(_current_company_code(), DEFAULT_COMPANY_CODE) == new_code:
            manager = _activate_company(new_code)
            _bind_request_data_manager(manager)

        mark_realtime_change(
            'company-management',
            {'companyCode': new_code, 'previousCompanyCode': code, 'updated': True}
        )
        if new_code == code:
            log_action(f"Updated company {code} name from {old_name} to {name}")
        else:
            log_action(f"Renamed company {code} to {new_code}; name changed from {old_name} to {name}")

        return jsonify({
            'success': True,
            'message': 'Company updated successfully',
            'data': {
                **_company_payload(new_code),
                'previousCode': code,
                'previousBackendFolder': old_record.get('backendFolder') or '',
                'previousFrontendFolder': old_record.get('frontendFolder') or '',
            }
        })
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        logger.error(f"Error updating company {company_code}: {e}", exc_info=True)
        return jsonify({'error': 'Failed to update company'}), 500


@app.route('/api/companies/<path:company_code>', methods=['DELETE'])
@require_super_admin
def delete_company(company_code):
    """Owner: delete a company and its segregated company assets."""
    try:
        code = _normalise_company_code(unquote_plus(company_code))
        registry = _load_company_registry()

        if not code or code not in registry['companies']:
            return jsonify({'error': 'Company not found'}), 404

        if len(registry['companies']) <= 1:
            return jsonify({'error': 'At least one company must remain'}), 400

        if code == _normalise_company_code(_current_company_code(), DEFAULT_COMPANY_CODE):
            return jsonify({'error': 'Switch to another company before deleting the active company'}), 400

        record = registry['companies'][code]
        company_folder = _safe_company_delete_folder(code, record)
        remaining_codes = sorted(company_code for company_code in registry['companies'] if company_code != code)
        new_default_company = registry.get('defaultCompany')
        if new_default_company == code or new_default_company not in remaining_codes:
            new_default_company = remaining_codes[0]

        removed_users = []
        reassigned_protected_users = []
        users_changed = False
        for username, assigned_company in list(registry.get('userCompanies', {}).items()):
            if _normalise_company_code(assigned_company, DEFAULT_COMPANY_CODE) != code:
                continue

            if _is_owner_username(username):
                registry['userCompanies'][username] = new_default_company
                reassigned_protected_users.append(username)
            else:
                registry['userCompanies'].pop(username, None)
                if username in data_manager.users:
                    data_manager.users.pop(username, None)
                    removed_users.append(username)
                    users_changed = True

        for username, memberships in list(
            registry.get('userCompanyMemberships', {}).items()
        ):
            remaining_memberships = [
                item for item in memberships
                if _normalise_company_code(item) != code
            ]
            if len(remaining_memberships) > 1:
                registry['userCompanyMemberships'][username] = remaining_memberships
                continue
            registry['userCompanyMemberships'].pop(username, None)
            if remaining_memberships:
                registry['userCompanies'][username] = remaining_memberships[0]
            else:
                registry['userCompanies'].pop(username, None)

        company_manager = _company_data_managers.get(code)
        database_url = _database_url_for_runtime()
        if company_manager is None and database_url:
            company_manager = _get_company_data_manager(code)
        if (
            company_manager is not None
            and hasattr(company_manager, 'delete_company_data')
            and database_url
        ):
            company_manager.delete_company_data()
        _company_data_managers.pop(code, None)
        if os.path.exists(company_folder):
            shutil.rmtree(company_folder)

        registry['companies'].pop(code, None)
        registry['defaultCompany'] = new_default_company
        registry = _save_company_registry(registry)
        _invalidate_company_storage_cache(code)

        if users_changed:
            data_manager.save_users()
            _reload_users_for_all_company_managers()

        mark_realtime_change('company-management', {'companyCode': code, 'deleted': True})
        log_action(f"Deleted company {code} ({record.get('name') or code})")

        return jsonify({
            'success': True,
            'message': 'Company deleted successfully',
            'data': {
                'deletedCompanyCode': code,
                'newDefaultCompany': new_default_company,
                'removedUsers': sorted(removed_users, key=lambda value: value.lower()),
                'reassignedSuperAdmins': sorted(
                    reassigned_protected_users,
                    key=lambda value: value.lower(),
                ),
            }
        })
    except ValueError as e:
        return jsonify({'error': str(e)}), 400
    except Exception as e:
        logger.error(f"Error deleting company {company_code}: {e}", exc_info=True)
        return jsonify({'error': 'Failed to delete company'}), 500


