def _finance_owner_username():
    registry = _load_company_registry()
    for username in registry.get('superAdmins', [SUPER_ADMIN_USERNAME]):
        if str(username or '').strip():
            return str(username).strip()
    return SUPER_ADMIN_USERNAME


def _finance_current_username():
    if not has_request_context():
        return _finance_owner_username()
    return str(session.get('user') or '').strip()


def _finance_current_user_display_name():
    username = _finance_current_username()
    user = data_manager.users.get(username) if username and data_manager else None
    display_name = str(getattr(user, 'name', '') or '').strip()
    return display_name or username


def _finance_salesperson_phone(document):
    username = str((document or {}).get('salespersonUsername') or '').strip()
    user = data_manager.users.get(username) if username and data_manager else None
    if not user:
        salesperson = str((document or {}).get('salesperson') or '').strip().casefold()
        if salesperson and data_manager:
            user = next((
                candidate for candidate in data_manager.users.values()
                if salesperson in {
                    str(candidate.username or '').strip().casefold(),
                    str(getattr(candidate, 'name', '') or '').strip().casefold(),
                }
            ), None)
    return getattr(user, 'phone', '') or '' if user else ''


def _finance_document_owner_username(document):
    """Resolve quotation ownership from its selected salesperson account."""
    return str(
        (document or {}).get('salespersonUsername')
        or (document or {}).get('createdBy')
        or ''
    ).strip()


def _finance_user_can_access(document):
    if _current_user_is_owner():
        return True
    if (
        _effective_user_role(_finance_current_username()) == 'admin'
        and _current_user_has_sales_access()
    ):
        return True
    return (
        _finance_document_owner_username(document).lower()
        == _finance_current_username().lower()
    )


def _finance_department_details(value, code_hint=''):
    raw = re.sub(r'\s+', ' ', str(value or '').strip())
    departments = _load_departments()
    hinted_code = _normalise_department_code(code_hint)
    raw_code = _normalise_department_code(raw)
    match = None
    lowered = re.sub(r'\s+(?:department|system)$', '', raw.lower()).strip()
    hinted = departments.get(hinted_code)
    hinted_name = str((hinted or {}).get('name') or '').strip().lower()
    if hinted and (
        not raw
        or raw.upper() == hinted_code
        or lowered == re.sub(r'\s+(?:department|system)$', '', hinted_name).strip()
    ):
        match = hinted
    elif raw_code in departments and raw.upper() == raw_code:
        match = departments[raw_code]
    else:
        match = next(
            (
                row for row in departments.values()
                if re.sub(
                    r'\s+(?:department|system)$',
                    '',
                    str(row.get('name') or '').strip().lower(),
                ).strip() == lowered
            ),
            None,
        )

    if match:
        name = str(match.get('name') or match.get('code') or '').strip()
        name = re.sub(r'\s+(?:department|system)$', '', name, flags=re.IGNORECASE).strip()
        if name.lower() == 'manpower':
            return 'Manpower', 'MANPOWER'
        if name.lower() in {'transport', 'transportation'}:
            return 'Transportation', 'TRANSPORTATION'
        return (f"{name} Department" if name else 'Unknown Department'), match.get('code') or 'UN'

    if not raw:
        return 'Unknown Department', 'UN'
    if raw.lower() == 'manpower':
        return 'Manpower', 'MANPOWER'
    if raw.lower() in {'transport', 'transportation'}:
        return 'Transportation', 'TRANSPORTATION'
    return raw, hinted_code or raw_code or 'UN'


def _finance_system_name(department, value=''):
    custom = re.sub(r'\s+', ' ', str(value or '').strip())
    if custom:
        return custom[:200]
    name = re.sub(r'\s+', ' ', str(department or '').strip())
    base_name = re.sub(
        r'\s+(?:department|system)$',
        '',
        name,
        flags=re.IGNORECASE,
    ).strip()
    if base_name.lower() == 'manpower':
        return 'Manpower'
    if base_name.lower() in {'transport', 'transportation'}:
        return 'Transportation'
    return (f'{base_name} System' if base_name else 'Unknown System')[:200]


def _finance_adjustment_system_name(value):
    name = re.sub(r'\s+', ' ', str(value or '').strip())
    if not name:
        return 'Unknown System'
    base_name = re.sub(
        r'\s+(?:department|system)$',
        '',
        name,
        flags=re.IGNORECASE,
    ).strip()
    if base_name.lower() == 'manpower':
        return 'Manpower'
    if base_name.lower() in {'transport', 'transportation'}:
        return 'Transportation'
    if re.search(r'\s+department$', name, flags=re.IGNORECASE):
        return re.sub(
            r'\s+department$',
            ' System',
            name,
            flags=re.IGNORECASE,
        )[:200]
    return name[:200]


def _finance_format_number(prefix, year, sequence, revision):
    return f"{prefix}-{year}-{max(1, int(sequence)):03d}-{min(99, max(1, int(revision))):02d}"


def _finance_number_with_revision(number, revision):
    base = re.sub(r'-\d{2}$', '', str(number or '').strip()) or 'QT'
    return f"{base}-{min(99, max(1, int(revision))):02d}"


def _finance_active_departments(lines):
    departments = []
    for line in lines or []:
        if not isinstance(line, dict):
            continue
        name, _code = _finance_department_details(
            line.get('department'),
            line.get('departmentCode'),
        )
        name = _finance_system_name(name, line.get('systemName'))
        if name and name not in departments:
            departments.append(name)
    return departments


def _finance_parse_number(number, fallback_sequence=1):
    value = str(number or '').strip().upper()
    match = re.match(r'^([A-Z0-9_-]+)-(\d{4})-(\d+)(?:-(\d{2}))?$', value)
    if not match:
        return 'QT', datetime.now().year, fallback_sequence, 1
    return (
        match.group(1),
        _safe_int(match.group(2), datetime.now().year),
        max(1, _safe_int(match.group(3), fallback_sequence)),
        max(1, _safe_int(match.group(4), 1)),
    )


def _finance_date_days(start_value, end_value):
    try:
        start = datetime.strptime(str(start_value or ''), '%Y-%m-%d')
        end = datetime.strptime(str(end_value or ''), '%Y-%m-%d')
    except ValueError:
        return 1
    return max(1, (end.date() - start.date()).days + 1)


def _finance_payment_term_days(value, default=30):
    text = str(value or '').strip().lower()
    if any(label in text for label in ('due on receipt', 'on receipt', 'immediate', 'cod')):
        return 0
    match = re.search(r'\b(\d{1,4})\b', text)
    if not match:
        return max(0, _safe_int(default, 30))
    amount = max(0, min(3650, _safe_int(match.group(1), default)))
    if 'week' in text:
        return min(3650, amount * 7)
    if 'month' in text:
        return min(3650, amount * 30)
    return amount


def _finance_payment_due_date(sent_date, payment_terms, default_days=30):
    try:
        sent = datetime.strptime(str(sent_date or '')[:10], '%Y-%m-%d').date()
    except ValueError:
        sent = datetime.now().date()
    days = _finance_payment_term_days(payment_terms, default_days)
    return (sent + timedelta(days=days)).strftime('%Y-%m-%d'), days


def _migrate_finance_data(data):
    changed = _safe_int(data.get('version'), 1) < FINANCE_VERSION
    owner = _finance_owner_username()
    settings = _load_pdf_settings()
    quote_prefix = str(settings.get('quotationPrefix') or 'QT').upper()
    documents = data.get('documents') or []

    profit_loss = data.get('profitLoss')
    if not isinstance(profit_loss, dict):
        data['profitLoss'] = {'expenses': {}, 'commissions': {}, 'manualRevenue': {}}
        changed = True
    elif not isinstance(profit_loss.get('expenses'), dict):
        profit_loss['expenses'] = {}
        changed = True
    if isinstance(data.get('profitLoss'), dict) and not isinstance(data['profitLoss'].get('commissions'), dict):
        data['profitLoss']['commissions'] = {}
        changed = True
    if isinstance(data.get('profitLoss'), dict) and not isinstance(data['profitLoss'].get('manualRevenue'), dict):
        data['profitLoss']['manualRevenue'] = {}
        changed = True

    accounting = data.get('accounting')
    if not isinstance(accounting, dict):
        data['accounting'] = _accounting_defaults()
        changed = True
    else:
        defaults = _accounting_defaults()
        if not isinstance(accounting.get('settings'), dict):
            accounting['settings'] = defaults['settings']
            changed = True
        else:
            for key, default in defaults['settings'].items():
                if key not in accounting['settings']:
                    accounting['settings'][key] = default
                    changed = True
        if not isinstance(accounting.get('accounts'), list):
            accounting['accounts'] = defaults['accounts']
            changed = True
        if not isinstance(accounting.get('journals'), list):
            accounting['journals'] = []
            changed = True
        if not isinstance(accounting.get('bankTransactions'), list):
            accounting['bankTransactions'] = []
            changed = True

    for index, document in enumerate(documents, start=1):
        if not isinstance(document, dict):
            continue
        if not str(document.get('createdBy') or '').strip():
            document['createdBy'] = owner
            changed = True
        if document.get('type') != 'quotation':
            continue

        if str(document.get('status') or '').strip().lower() == 'declined':
            document['status'] = 'cancelled'
            changed = True

        invoice_sent_date = str(
            document.get('invoiceSentDate')
            or document.get('invoicedAt')
            or ''
        )[:10]
        payment_terms = document.get('paymentTerms') or settings.get(
            'defaultPaymentTerms', '30 Days'
        )
        payment_due_date, payment_term_days = _finance_payment_due_date(
            invoice_sent_date,
            payment_terms,
        )
        for key, value in (
            ('invoiceSentDate', invoice_sent_date),
            ('paymentTermDays', payment_term_days),
            (
                'paymentDueDate',
                payment_due_date if invoice_sent_date else '',
            ),
        ):
            if key not in document:
                document[key] = value
                changed = True

        parsed_prefix, year, sequence, revision = _finance_parse_number(
            document.get('number'),
            index,
        )
        sequence = max(1, _safe_int(document.get('baseSequence'), sequence))
        revision = max(1, _safe_int(document.get('revision'), revision))
        number = (
            _finance_number_with_revision(document.get('number'), revision)
            if document.get('customNumber')
            else _finance_format_number(
                quote_prefix or parsed_prefix,
                year,
                sequence,
                revision,
            )
        )
        if document.get('number') != number:
            document['number'] = number
            changed = True
        for key, value in (
            ('baseSequence', sequence),
            ('revision', revision),
            ('projectName', document.get('projectName') or document.get('title') or ''),
            ('revisions', document.get('revisions') or []),
            ('invoicedAt', document.get('invoicedAt') or ''),
            ('paidAt', document.get('paidAt') or ''),
            ('statusChangedAt', document.get('statusChangedAt') or document.get('updatedAt') or ''),
            ('showUnitPrices', bool(document.get('showUnitPrices', False))),
            ('showDepartmentDiscounts', bool(document.get('showDepartmentDiscounts', False))),
            ('showDepartmentSubtotals', document.get('showDepartmentSubtotals', True) is not False),
            ('summaryBySubproject', document.get('summaryBySubproject', True) is not False),
            ('showSignOff', bool(document.get('showSignOff', False))),
            ('totalLocked', bool(document.get('totalLocked', False))),
            ('lockedPreTaxTotal', document.get('lockedPreTaxTotal')),
            ('totalDiscountLabel', document.get('totalDiscountLabel') or ''),
            ('setupDate', document.get('setupDate') or ''),
            ('setupTime', document.get('setupTime') or ''),
            ('additionalSetups', document.get('additionalSetups') or []),
            ('rehearsalDate', document.get('rehearsalDate') or ''),
            ('rehearsalTime', document.get('rehearsalTime') or ''),
            ('additionalRehearsals', document.get('additionalRehearsals') or []),
            ('showDate', document.get('showDate') or document.get('eventDate') or ''),
            ('showTime', document.get('showTime') or ''),
            ('teardownDate', document.get('teardownDate') or ''),
            ('teardownTime', document.get('teardownTime') or ''),
            ('additionalShows', document.get('additionalShows') or []),
            ('additionalTeardowns', document.get('additionalTeardowns') or []),
        ):
            if key not in document:
                document[key] = value
                changed = True

        quote_date = document.get('quotationDate')
        valid_until = document.get('validUntil')
        validity_days = _finance_date_days(quote_date, valid_until) - 1
        if 'validityDays' not in document:
            document['validityDays'] = max(
                1,
                validity_days or _safe_int(settings.get('defaultValidityDays'), 30),
            )
            changed = True

        department_names = []
        for line in document.get('lineItems') or []:
            if not isinstance(line, dict):
                continue
            name, code = _finance_department_details(
                line.get('department'),
                line.get('departmentCode'),
            )
            if line.get('department') != name or line.get('departmentCode') != code:
                line['department'] = name
                line['departmentCode'] = code
                changed = True
            system_name = _finance_system_name(name, line.get('systemName'))
            if line.get('systemName') != system_name:
                line['systemName'] = system_name
                changed = True
            if line.get('uom') == 'pcs':
                line['uom'] = 'units'
                changed = True
            if system_name not in department_names:
                department_names.append(system_name)

        normalised_subprojects = _normalise_finance_subprojects(
            document.get('subprojects'),
            document.get('lineItems') or [],
        )
        if document.get('subprojects') != normalised_subprojects:
            document['subprojects'] = normalised_subprojects
            changed = True
        for adjustment in document.get('adjustments') or []:
            if not isinstance(adjustment, dict):
                continue
            if not adjustment.get('subprojectId'):
                adjustment['subprojectId'] = normalised_subprojects[0]['id']
                changed = True
            if adjustment.get('scope') == 'department':
                system_name = _finance_adjustment_system_name(
                    adjustment.get('department')
                )
                if adjustment.get('department') != system_name:
                    adjustment['department'] = system_name
                    changed = True

        if document.get('departments') != department_names:
            document['departments'] = department_names
            changed = True
        active_departments = set(department_names)
        cleaned_adjustments = [
            row for row in document.get('adjustments') or []
            if not isinstance(row, dict)
            or row.get('scope') != 'department'
            or row.get('department') in active_departments
        ]
        if cleaned_adjustments != (document.get('adjustments') or []):
            document['adjustments'] = cleaned_adjustments
            changed = True

    if data.get('version') != FINANCE_VERSION:
        data['version'] = FINANCE_VERSION
        changed = True
    return changed


def _load_finance_data():
    manager = _current_data_manager_object()
    if manager is not None and hasattr(manager, 'load_company_document'):
        try:
            loaded = manager.load_company_document('finance', None)
        except Exception as exc:
            logger.warning("Failed to read finance data from PostgreSQL: %s", exc)
            loaded = None
        if not isinstance(loaded, dict):
            return _finance_defaults()
    else:
        filepath = _finance_path()
        if not os.path.exists(filepath) or os.path.getsize(filepath) == 0:
            return _finance_defaults()
        try:
            with open(filepath, 'r', encoding='utf-8') as finance_file:
                loaded = json.load(finance_file)
        except Exception as exc:
            logger.warning("Failed to read %s: %s", FINANCE_FILENAME, exc)
            return _finance_defaults()

    data = _finance_defaults()
    if isinstance(loaded, dict):
        if isinstance(loaded.get('documents'), list):
            data['documents'] = loaded['documents']
        if isinstance(loaded.get('priceBook'), dict):
            data['priceBook'] = loaded['priceBook']
        if isinstance(loaded.get('profitLoss'), dict):
            data['profitLoss'] = loaded['profitLoss']
        if isinstance(loaded.get('accounting'), dict):
            data['accounting'] = loaded['accounting']
        data['version'] = loaded.get('version', 1)
    if _migrate_finance_data(data):
        _save_finance_data(data)
    return data


def _save_finance_data(data):
    payload = {
        'version': FINANCE_VERSION,
        'documents': data.get('documents') or [],
        'priceBook': data.get('priceBook') or {},
        'profitLoss': data.get('profitLoss') if isinstance(data.get('profitLoss'), dict) else {
            'expenses': {},
            'commissions': {},
            'manualRevenue': {},
        },
        'accounting': data.get('accounting') if isinstance(data.get('accounting'), dict) else _accounting_defaults(),
    }
    manager = _current_data_manager_object()
    if manager is not None and hasattr(manager, 'save_company_document'):
        manager.save_company_document('finance', payload)
        return payload
    filepath = _finance_path()
    folder = os.path.dirname(filepath)
    if folder and not os.path.exists(folder):
        os.makedirs(folder)
    temp_path = f"{filepath}.{secrets.token_hex(6)}.tmp"
    with open(temp_path, 'w', encoding='utf-8') as finance_file:
        json.dump(payload, finance_file, ensure_ascii=False, indent=2)
    os.replace(temp_path, filepath)
    return payload


def _finance_catalog_key(department='', brand='', model='', description=''):
    parts = [
        _normalise_department_code(department) or 'UN',
        str(brand or '').strip(),
        str(model or '').strip(),
    ]
    return 'inventory:' + '|'.join(parts).lower()


def _finance_display_description(brand='', model='', description=''):
    identity = ' '.join(
        value for value in (
            str(brand or '').strip(),
            str(model or '').strip(),
        )
        if value
    )
    description = str(description or '').strip()
    if identity and (
        description.casefold() == identity.casefold()
        or description.casefold().startswith(f"{identity} ".casefold())
    ):
        return description
    return ' '.join(value for value in (identity, description) if value)


def _finance_line_matches_inventory_group(line, catalog_key, group, target_asset_ids):
    if not isinstance(line, dict) or line.get('isCustom'):
        return False
    line_ids = {
        str(asset_id or '').strip().lower()
        for asset_id in (line.get('sourceAssetIds') or [])
        if str(asset_id or '').strip()
    }
    if target_asset_ids and line_ids.intersection(target_asset_ids):
        return True
    if str(line.get('catalogKey') or '').strip().lower() == catalog_key:
        return True
    line_department, line_code = _finance_department_details(
        line.get('department'),
        line.get('departmentCode'),
    )
    group_department, group_code = _finance_department_details(
        group.get('department'),
        group.get('department'),
    )
    return (
        _normalise_department_code(line_code or line_department)
        == _normalise_department_code(group_code or group_department)
        and str(line.get('brand') or '').strip().lower()
        == str(group.get('brand') or '').strip().lower()
        and str(line.get('model') or '').strip().lower()
        == str(group.get('model') or '').strip().lower()
    )


def _finance_sync_inventory_edit(
    old_asset_id,
    new_asset_id,
    old_group,
    new_group,
    target_asset_ids=None,
    apply_group_change=False,
):
    """Keep linked quotation lines aligned with intentional all-similar inventory edits."""
    id_mapping = {}
    old_asset_id = str(old_asset_id or '').strip()
    new_asset_id = str(new_asset_id or '').strip()
    if old_asset_id and new_asset_id and old_asset_id != new_asset_id:
        id_mapping[old_asset_id] = new_asset_id

    old_department, old_department_code = _finance_department_details(
        old_group.get('department'),
        old_group.get('department'),
    )
    new_department, new_department_code = _finance_department_details(
        new_group.get('department'),
        new_group.get('department'),
    )
    old_catalog_key = _finance_catalog_key(
        old_department_code,
        old_group.get('brand'),
        old_group.get('model'),
        old_group.get('description'),
    )
    new_catalog_key = _finance_catalog_key(
        new_department_code,
        new_group.get('brand'),
        new_group.get('model'),
        new_group.get('description'),
    )
    target_ids = {
        str(asset_id or '').strip().lower()
        for asset_id in (target_asset_ids or [])
        if str(asset_id or '').strip()
    }
    target_ids.update(str(value or '').strip().lower() for value in id_mapping.values())
    if old_asset_id:
        target_ids.add(old_asset_id.lower())

    changed = False
    with _finance_lock:
        finance_data = _load_finance_data()
        price_book = finance_data.setdefault('priceBook', {})

        if id_mapping:
            for document in finance_data.get('documents') or []:
                document_changed = False
                for line in document.get('lineItems') or []:
                    source_ids = list(line.get('sourceAssetIds') or [])
                    replaced = [
                        id_mapping.get(str(asset_id or '').strip(), str(asset_id or '').strip())
                        for asset_id in source_ids
                        if str(asset_id or '').strip()
                    ]
                    if replaced != source_ids:
                        line['sourceAssetIds'] = replaced
                        document_changed = True
                if document_changed:
                    document['updatedAt'] = datetime.now().isoformat(timespec='seconds')
                    document['updatedBy'] = _finance_current_username()
                    changed = True

            for price_key, payload in list(price_book.items()):
                for old_id, replacement_id in id_mapping.items():
                    if price_key.endswith(f"::asset:{old_id.lower()}"):
                        prefix = price_key[: -len(f"asset:{old_id.lower()}")]
                        price_book[f"{prefix}asset:{replacement_id.lower()}"] = payload
                        changed = True

        if apply_group_change and old_group != new_group:
            new_description = _finance_display_description(
                new_group.get('brand'),
                new_group.get('model'),
                new_group.get('description'),
            ) or str(new_group.get('model') or '').strip() or 'Inventory item'
            for document in finance_data.get('documents') or []:
                document_changed = False
                for line in document.get('lineItems') or []:
                    if not _finance_line_matches_inventory_group(
                        line,
                        old_catalog_key,
                        old_group,
                        target_ids,
                    ):
                        continue
                    line['catalogKey'] = new_catalog_key
                    line['department'] = new_department
                    line['departmentCode'] = new_department_code
                    line['brand'] = str(new_group.get('brand') or '').strip()
                    line['model'] = str(new_group.get('model') or '').strip()
                    line['description'] = new_description
                    document_changed = True
                if document_changed:
                    document['departments'] = _finance_active_departments(document.get('lineItems') or [])
                    document['updatedAt'] = datetime.now().isoformat(timespec='seconds')
                    document['updatedBy'] = _finance_current_username()
                    _recalculate_finance_adjustments(document)
                    _apply_locked_total_adjustment(document)
                    document['totals'] = _finance_totals(document)
                    changed = True

            for price_key, payload in list(price_book.items()):
                base_key = str(price_key).split('::', 1)[-1]
                if base_key != old_catalog_key:
                    continue
                prefix = price_key[: -len(base_key)]
                updated_payload = dict(payload or {})
                updated_payload.update({
                    'description': new_description,
                    'department': new_department,
                    'uom': updated_payload.get('uom') or 'units',
                    'updatedAt': datetime.now().isoformat(timespec='seconds'),
                })
                price_book[f"{prefix}{new_catalog_key}"] = updated_payload
                changed = True

        if changed:
            _save_finance_data(finance_data)
    return changed


def _finance_custom_price_key(description):
    compact = re.sub(r'\s+', ' ', str(description or '').strip().lower())
    return f"custom:{compact}"


def _normalise_finance_salutation(value):
    salutation = str(value or '').strip()
    return salutation if salutation in {'Mr.', 'Ms.', 'Mrs.', 'Mdm.'} else ''


def _normalise_finance_client(value):
    value = value if isinstance(value, dict) else {}
    return {
        'salutation': _normalise_finance_salutation(value.get('salutation')),
        'name': str(value.get('name') or '').strip()[:160],
        'company': str(value.get('company') or '').strip()[:200],
        'contactPerson': str(value.get('contactPerson') or '').strip()[:160],
        'email': str(value.get('email') or '').strip()[:200],
        'phone': str(value.get('phone') or '').strip()[:80],
        'taxNumber': str(value.get('taxNumber') or '').strip()[:100],
        'address1': str(value.get('address1') or '').strip()[:240],
        'address2': str(value.get('address2') or '').strip()[:240],
        'address3': str(value.get('address3') or '').strip()[:240],
        'postalCode': str(value.get('postalCode') or '').strip()[:40],
    }


def _normalise_finance_line(value):
    value = value if isinstance(value, dict) else {}
    quantity = max(0, _safe_float(value.get('quantity'), 1))
    days = max(0, _safe_float(value.get('days'), 1))
    unit_price = max(0, _safe_float(value.get('unitPrice'), 0))
    discount = max(-9999, min(100, _safe_float(value.get('discountPercent'), 0)))
    gross = quantity * days * unit_price
    total = gross * (1 - discount / 100)
    department, department_code = _finance_department_details(
        value.get('department'),
        value.get('departmentCode'),
    )
    raw_uom = str(value.get('uom') or '').strip().lower()
    if raw_uom in {'pax', 'person', 'people'} or (
        not raw_uom
        and _normalise_department_code(department_code or department) == 'MANPOWER'
    ):
        uom = 'pax'
    elif raw_uom in {'lot', 'lots'}:
        uom = 'lot'
    elif raw_uom in {'sqm', 'm2', 'm²'}:
        uom = 'sqm'
    else:
        uom = 'units'
    source_asset_ids = [
        str(asset_id).strip()
        for asset_id in (value.get('sourceAssetIds') or [])
        if str(asset_id or '').strip()
    ]
    catalog_key = str(value.get('catalogKey') or '').strip()[:500]
    legacy_parts = catalog_key.split('|')
    brand = str(value.get('brand') or (legacy_parts[1] if len(legacy_parts) > 2 else '')).strip()
    model = str(value.get('model') or (legacy_parts[2] if len(legacy_parts) > 2 else '')).strip()
    return {
        'id': re.sub(r'[^A-Za-z0-9_-]+', '', str(value.get('id') or ''))[:80] or secrets.token_hex(6),
        'catalogKey': catalog_key,
        'sourceAssetIds': source_asset_ids,
        'brand': brand[:240],
        'model': model[:240],
        'description': str(value.get('description') or '').strip()[:1000],
        'department': department[:200],
        'departmentCode': department_code,
        'systemName': _finance_system_name(department, value.get('systemName')),
        'days': round(days, 4),
        'quantity': round(quantity, 4),
        'uom': uom,
        'unitPrice': round(unit_price, 2),
        'discountPercent': round(discount, 4),
        'total': round(total, 2),
        'isCustom': bool(value.get('isCustom') or not catalog_key),
        'customType': (
            _normalise_custom_type(value.get('customType'))
            if value.get('customType')
            else ''
        ),
        'customCompany': str(value.get('customCompany') or '').strip()[:200],
        'subprojectId': re.sub(
            r'[^A-Za-z0-9_-]+', '', str(value.get('subprojectId') or '')
        )[:80] or 'main',
    }


def _normalise_finance_subprojects(value, lines):
    rows = value if isinstance(value, list) else []
    result = []
    seen = set()
    for index, row in enumerate(rows[:40]):
        if not isinstance(row, dict):
            continue
        subproject_id = re.sub(
            r'[^A-Za-z0-9_-]+', '', str(row.get('id') or '')
        )[:80] or f'room_{index + 1}'
        if subproject_id in seen:
            continue
        seen.add(subproject_id)
        result.append({
            'id': subproject_id,
            'name': str(row.get('name') or '').strip()[:160] or f'Room {index + 1}',
        })
    if not result:
        result = [{'id': 'main', 'name': 'Main Room'}]
    valid_ids = {row['id'] for row in result}
    fallback_id = result[0]['id']
    for line in lines:
        if line.get('subprojectId') not in valid_ids:
            line['subprojectId'] = fallback_id
    return result


def _normalise_finance_schedule_rows(value):
    rows = value if isinstance(value, list) else []
    result = []
    for row in rows[:40]:
        if not isinstance(row, dict):
            continue
        result.append({
            'id': re.sub(r'[^A-Za-z0-9_-]+', '', str(row.get('id') or ''))[:80] or secrets.token_hex(6),
            'date': str(row.get('date') or '').strip()[:20],
            'time': str(row.get('time') or '').strip()[:20],
        })
    return result


def _normalise_finance_adjustment(value):
    value = value if isinstance(value, dict) else {}
    scope = 'department' if value.get('scope') == 'department' else 'total'
    department = _finance_adjustment_system_name(value.get('department'))
    adjustment_id = re.sub(r'[^A-Za-z0-9_-]+', '', str(value.get('id') or ''))[:80] or secrets.token_hex(6)
    locked_total_adjustment = (
        bool(value.get('lockedTotalAdjustment'))
        or adjustment_id.startswith('locked_total_')
        or _finance_is_generated_total_adjustment(value)
    )
    calculation_mode = str(value.get('calculationMode') or '').strip().lower()
    if calculation_mode not in {'percent', 'amount'}:
        calculation_mode = 'percent' if _safe_float(value.get('percent'), 0) else 'amount'
    return {
        'id': adjustment_id,
        'scope': scope,
        'department': department if scope == 'department' else '',
        'label': str(value.get('label') or 'Discount').strip()[:300] or 'Discount',
        'amount': round(_safe_float(value.get('amount'), 0), 2),
        'percent': round(max(0, _safe_float(value.get('percent'), 0)), 4),
        'calculationMode': calculation_mode,
        'kind': 'discount' if str(value.get('kind') or '').lower() == 'discount' or _safe_float(value.get('amount'), 0) < 0 else 'adjustment',
        'lockedTotalAdjustment': locked_total_adjustment,
        'subprojectId': re.sub(
            r'[^A-Za-z0-9_-]+', '', str(value.get('subprojectId') or '')
        )[:80] or 'main',
    }


def _finance_is_locked_adjustment(adjustment):
    return (
        bool((adjustment or {}).get('lockedTotalAdjustment'))
        or str((adjustment or {}).get('id') or '').startswith('locked_total_')
        or _finance_is_generated_total_adjustment(adjustment)
    )


def _finance_is_generated_total_adjustment(adjustment):
    if not isinstance(adjustment, dict) or adjustment.get('scope') != 'total':
        return False
    label = str(adjustment.get('label') or '').strip().lower()
    return bool(re.match(r'^\d+(?:\.\d+)?% (?:overall|total) (?:discount|adjustment)$', label))


def _finance_locked_adjustment_id(document):
    return f"locked_total_{document.get('id') or 'current'}"


def _recalculate_finance_adjustments(document):
    lines = document.get('lineItems') or []
    adjustments = document.get('adjustments') or []
    for adjustment in adjustments:
        if _finance_is_locked_adjustment(adjustment):
            continue
        if adjustment.get('calculationMode') != 'percent':
            continue
        percent = max(0, _safe_float(adjustment.get('percent'), 0))
        if not percent:
            continue
        if adjustment.get('scope') == 'department':
            department = adjustment.get('department')
            subproject_id = adjustment.get('subprojectId') or 'main'
            base = sum(
                _safe_float(line.get('total'), 0)
                for line in lines
                if _finance_system_name(
                    line.get('department'),
                    line.get('systemName'),
                ) == department
                and (line.get('subprojectId') or 'main') == subproject_id
            )
        else:
            base = sum(_safe_float(line.get('total'), 0) for line in lines)
            base += sum(
                _safe_float(row.get('amount'), 0)
                for row in adjustments
                if row.get('scope') == 'department'
            )
        sign = -1 if adjustment.get('kind') == 'discount' else 1
        adjustment['amount'] = round(sign * base * percent / 100, 2)


def _apply_locked_total_adjustment(document):
    adjustments = list(document.get('adjustments') or [])
    unlocked_adjustments = [
        row for row in adjustments
        if not _finance_is_locked_adjustment(row)
    ]
    if not document.get('totalLocked'):
        document['adjustments'] = unlocked_adjustments
        document['lockedPreTaxTotal'] = None
        return

    subtotal = round(
        sum(_safe_float(line.get('total'), 0) for line in document.get('lineItems') or []),
        2,
    )
    adjustment_base = round(
        subtotal + sum(_safe_float(row.get('amount'), 0) for row in unlocked_adjustments),
        2,
    )
    locked_raw = document.get('lockedPreTaxTotal')
    locked_target = (
        adjustment_base
        if locked_raw in (None, '')
        else round(max(0, _safe_float(locked_raw, adjustment_base)), 2)
    )
    document['lockedPreTaxTotal'] = locked_target
    difference = round(locked_target - adjustment_base, 2)
    if abs(difference) < 0.005:
        document['adjustments'] = unlocked_adjustments
        return

    percent = round((abs(difference) / adjustment_base * 100) if adjustment_base else 0, 4)
    label_percent = f"{percent:.2f}".rstrip('0').rstrip('.') or '0'
    locked_adjustment = {
        'id': _finance_locked_adjustment_id(document),
        'scope': 'total',
        'department': '',
        'label': str(document.get('totalDiscountLabel') or '').strip() or (
            f"{label_percent}% total discount"
            if difference < 0
            else f"{label_percent}% total adjustment"
        ),
        'amount': difference,
        'percent': percent,
        'calculationMode': 'amount',
        'kind': 'discount' if difference < 0 else 'adjustment',
        'lockedTotalAdjustment': True,
    }
    document['adjustments'] = [*unlocked_adjustments, locked_adjustment]


def _finance_totals(document):
    subtotal = round(sum(_safe_float(line.get('total'), 0) for line in document.get('lineItems') or []), 2)
    adjustment_total = round(sum(_safe_float(row.get('amount'), 0) for row in document.get('adjustments') or []), 2)
    net_subtotal = round(subtotal + adjustment_total, 2)
    tax_rate = max(0, min(100, _safe_float(document.get('taxRate'), 0)))
    tax = round(max(0, net_subtotal) * tax_rate / 100, 2)
    total_locked = bool(document.get('totalLocked'))
    locked_value = (
        round(max(0, _safe_float(document.get('lockedPreTaxTotal'), net_subtotal)), 2)
        if total_locked else None
    )
    return {
        'subtotal': subtotal,
        'adjustments': adjustment_total,
        'discount': round(sum(abs(min(0, _safe_float(row.get('amount'), 0))) for row in document.get('adjustments') or []), 2),
        'netSubtotal': net_subtotal,
        'calculatedPreTax': net_subtotal,
        'lockedPreTax': locked_value,
        'lockDifference': round(net_subtotal - locked_value, 2) if locked_value is not None else 0,
        'tax': tax,
        'total': round(net_subtotal + tax, 2),
    }


def _normalise_finance_document(value, document_type='quotation', existing=None):
    value = value if isinstance(value, dict) else {}
    existing = existing if isinstance(existing, dict) else {}
    is_read_normalisation = value is existing and bool(existing)
    settings = _load_pdf_settings()
    now = datetime.now()
    today = now.strftime('%Y-%m-%d')
    validity_days = max(1, _safe_int(settings.get('defaultValidityDays'), 30))
    valid_until = (now + timedelta(days=validity_days)).strftime('%Y-%m-%d')
    allowed_statuses = (
        set(FINANCE_QUOTATION_STATUSES)
        if document_type == 'quotation'
        else {'draft', 'sent', 'paid', 'overdue', 'void'}
    )
    status = str(value.get('status') or existing.get('status') or 'draft').strip().lower()
    if status == 'declined':
        status = 'cancelled'
    if status not in allowed_statuses:
        status = 'draft'

    lines = [
        _normalise_finance_line(row)
        for row in (value.get('lineItems') if 'lineItems' in value else existing.get('lineItems') or [])
        if isinstance(row, dict)
    ]
    subprojects = _normalise_finance_subprojects(
        value.get('subprojects')
        if 'subprojects' in value
        else existing.get('subprojects'),
        lines,
    )
    adjustments = [
        _normalise_finance_adjustment(row)
        for row in (value.get('adjustments') if 'adjustments' in value else existing.get('adjustments') or [])
        if isinstance(row, dict)
    ]
    date_key = 'quotationDate' if document_type == 'quotation' else 'invoiceDate'
    secondary_date_key = 'validUntil' if document_type == 'quotation' else 'dueDate'
    validity_unit = str(
        value.get('validityUnit')
        if 'validityUnit' in value
        else 'days'
        if 'validityDays' in value and 'validityAmount' not in value
        else existing.get('validityUnit') or 'days'
    ).strip().lower()
    if validity_unit not in {'days', 'weeks', 'months'}:
        validity_unit = 'days'
    validity_multiplier = {'days': 1, 'weeks': 7, 'months': 30}[validity_unit]
    validity_amount_source = (
        value.get('validityAmount')
        if 'validityAmount' in value
        else value.get('validityDays')
        if 'validityDays' in value
        else existing.get('validityAmount')
        if existing.get('validityAmount') not in (None, '')
        else existing.get('validityDays')
    )
    validity_amount = max(1, min(365, _safe_int(
        validity_amount_source,
        validity_days,
    )))
    validity_total_days = max(1, min(3650, validity_amount * validity_multiplier))
    current_username = _finance_current_username()
    prefix, number_year, parsed_sequence, parsed_revision = _finance_parse_number(
        existing.get('number') or value.get('number'),
        1,
    )
    base_sequence = max(
        1,
        _safe_int(
            existing.get('baseSequence', value.get('baseSequence')),
            parsed_sequence,
        ),
    )
    revision = max(
        1,
        _safe_int(existing.get('revision', value.get('revision')), parsed_revision),
    )
    project_name = str(
        value.get('projectName')
        if 'projectName' in value
        else value.get('title')
        if 'title' in value
        else existing.get('projectName') or existing.get('title') or ''
    ).strip()[:500]
    departments = _finance_active_departments(lines)
    active_department_names = set(departments)
    adjustments = [
        row for row in adjustments
        if row.get('scope') != 'department' or row.get('department') in active_department_names
    ]
    total_locked = bool(value.get('totalLocked') if 'totalLocked' in value else existing.get('totalLocked', False))
    locked_raw = (
        value.get('lockedPreTaxTotal')
        if 'lockedPreTaxTotal' in value
        else existing.get('lockedPreTaxTotal')
    )
    locked_pre_tax_total = (
        None
        if not total_locked or locked_raw in (None, '')
        else round(max(0, _safe_float(locked_raw, 0)), 2)
    )
    event_id_source = (
        value.get('eventId')
        if 'eventId' in value
        else existing.get('eventId')
    )

    document = {
        'id': existing.get('id') or re.sub(r'[^A-Za-z0-9_-]+', '', str(value.get('id') or ''))[:80] or secrets.token_hex(12),
        'type': document_type,
        'number': (
            str(value.get('number')).strip()[:80]
            if 'number' in value and str(value.get('number') or '').strip()
            else existing.get('number') or ''
        ),
        'customNumber': bool(value.get('customNumber') if 'customNumber' in value else existing.get('customNumber', False)),
        'baseSequence': base_sequence,
        'revision': revision,
        'status': status,
        'client': _normalise_finance_client(value.get('client') if 'client' in value else existing.get('client')),
        date_key: str(value.get(date_key) or existing.get(date_key) or today).strip()[:20],
        secondary_date_key: str(value.get(secondary_date_key) or existing.get(secondary_date_key) or valid_until).strip()[:20],
        'projectName': project_name,
        'title': project_name,
        'reference': str(value.get('reference') if 'reference' in value else existing.get('reference') or '').strip()[:300],
        'eventReference': str(value.get('eventReference') if 'eventReference' in value else existing.get('eventReference') or '').strip()[:300],
        'salesperson': str(value.get('salesperson') if 'salesperson' in value else existing.get('salesperson') or _finance_current_user_display_name()).strip()[:160],
        'salespersonUsername': str(
            value.get('salespersonUsername')
            if 'salespersonUsername' in value
            else (
                existing.get('salespersonUsername')
                or ('' if existing else _finance_current_username())
            )
        ).strip()[:160],
        'paymentTerms': str(value.get('paymentTerms') if 'paymentTerms' in value else existing.get('paymentTerms') or settings.get('defaultPaymentTerms', '30 Days')).strip()[:300],
        'paymentTermDays': max(0, min(3650, _safe_int(
            value.get('paymentTermDays')
            if 'paymentTermDays' in value
            else existing.get('paymentTermDays'),
            _finance_payment_term_days(
                value.get('paymentTerms')
                if 'paymentTerms' in value
                else existing.get('paymentTerms')
                or settings.get('defaultPaymentTerms', '30 Days')
            ),
        ))),
        'invoiceSentDate': str(
            value.get('invoiceSentDate')
            if 'invoiceSentDate' in value
            else existing.get('invoiceSentDate')
            or ''
        ).strip()[:10],
        'paymentDueDate': str(
            value.get('paymentDueDate')
            if 'paymentDueDate' in value
            else existing.get('paymentDueDate')
            or ''
        ).strip()[:10],
        'eventLocation': str(value.get('eventLocation') if 'eventLocation' in value else existing.get('eventLocation') or '').strip()[:600],
        'setupDate': str(value.get('setupDate') if 'setupDate' in value else existing.get('setupDate') or '').strip()[:20],
        'setupTime': str(value.get('setupTime') if 'setupTime' in value else existing.get('setupTime') or '').strip()[:20],
        'additionalSetups': _normalise_finance_schedule_rows(
            value.get('additionalSetups') if 'additionalSetups' in value else existing.get('additionalSetups')
        ),
        'rehearsalDate': str(value.get('rehearsalDate') if 'rehearsalDate' in value else existing.get('rehearsalDate') or '').strip()[:20],
        'rehearsalTime': str(value.get('rehearsalTime') if 'rehearsalTime' in value else existing.get('rehearsalTime') or '').strip()[:20],
        'additionalRehearsals': _normalise_finance_schedule_rows(
            value.get('additionalRehearsals') if 'additionalRehearsals' in value else existing.get('additionalRehearsals')
        ),
        'showDate': str(value.get('showDate') if 'showDate' in value else existing.get('showDate') or existing.get('eventDate') or '').strip()[:20],
        'showTime': str(value.get('showTime') if 'showTime' in value else existing.get('showTime') or '').strip()[:20],
        'teardownDate': str(value.get('teardownDate') if 'teardownDate' in value else existing.get('teardownDate') or '').strip()[:20],
        'teardownTime': str(value.get('teardownTime') if 'teardownTime' in value else existing.get('teardownTime') or '').strip()[:20],
        'additionalShows': _normalise_finance_schedule_rows(
            value.get('additionalShows') if 'additionalShows' in value else existing.get('additionalShows')
        ),
        'additionalTeardowns': _normalise_finance_schedule_rows(
            value.get('additionalTeardowns') if 'additionalTeardowns' in value else existing.get('additionalTeardowns')
        ),
        'validityAmount': validity_amount,
        'validityUnit': validity_unit,
        'validityDays': validity_total_days,
        'currency': str(value.get('currency') if 'currency' in value else existing.get('currency') or settings.get('currency', 'SGD')).strip().upper()[:6] or 'SGD',
        'taxRate': round(max(0, min(100, _safe_float(value.get('taxRate') if 'taxRate' in value else existing.get('taxRate', settings.get('taxRate', 0)), 0))), 4),
        'notes': str(value.get('notes') if 'notes' in value else existing.get('notes') or '').strip()[:5000],
        'terms': str(value.get('terms') if 'terms' in value else existing.get('terms') or settings.get('defaultTerms', DEFAULT_FINANCE_TERMS)).strip()[:10000],
        'lineItems': lines,
        'subprojects': subprojects,
        'adjustments': adjustments,
        'departments': departments,
        'showUnitPrices': bool(value.get('showUnitPrices') if 'showUnitPrices' in value else existing.get('showUnitPrices', False)),
        'showDepartmentDiscounts': bool(value.get('showDepartmentDiscounts') if 'showDepartmentDiscounts' in value else existing.get('showDepartmentDiscounts', False)),
        'showDepartmentSubtotals': (value.get('showDepartmentSubtotals') if 'showDepartmentSubtotals' in value else existing.get('showDepartmentSubtotals', True)) is not False,
        'summaryBySubproject': (value.get('summaryBySubproject') if 'summaryBySubproject' in value else existing.get('summaryBySubproject', True)) is not False,
        'showLineNumbers': (value.get('showLineNumbers') if 'showLineNumbers' in value else existing.get('showLineNumbers', True)) is not False,
        'showSignOff': bool(value.get('showSignOff') if 'showSignOff' in value else existing.get('showSignOff', False)),
        'totalLocked': total_locked,
        'lockedPreTaxTotal': locked_pre_tax_total,
        'totalDiscountLabel': str(
            value.get('totalDiscountLabel')
            if 'totalDiscountLabel' in value
            else existing.get('totalDiscountLabel') or ''
        ).strip()[:300],
        'revisions': list(existing.get('revisions') or value.get('revisions') or []),
        'sentAt': str(value.get('sentAt') or existing.get('sentAt') or '').strip()[:40],
        'acceptedAt': str(value.get('acceptedAt') or existing.get('acceptedAt') or '').strip()[:40],
        'invoicedAt': str(value.get('invoicedAt') or existing.get('invoicedAt') or '').strip()[:40],
        'paidAt': str(value.get('paidAt') or existing.get('paidAt') or '').strip()[:40],
        'statusChangedAt': str(value.get('statusChangedAt') or existing.get('statusChangedAt') or '').strip()[:40],
        'eventId': _safe_int(event_id_source, 0) or None,
        'eventManagedByQuotation': bool(value.get('eventManagedByQuotation') if 'eventManagedByQuotation' in value else existing.get('eventManagedByQuotation', False)),
        'eventSyncFingerprint': str(value.get('eventSyncFingerprint') if 'eventSyncFingerprint' in value else existing.get('eventSyncFingerprint') or '').strip()[:200],
        'sourceQuotationId': str(value.get('sourceQuotationId') or existing.get('sourceQuotationId') or '').strip()[:80],
        'sourceQuotationNumber': str(value.get('sourceQuotationNumber') or existing.get('sourceQuotationNumber') or '').strip()[:80],
        'createdAt': existing.get('createdAt') or now.isoformat(timespec='seconds'),
        'createdBy': existing.get('createdBy') or current_username,
        'updatedAt': existing.get('updatedAt') if is_read_normalisation else now.isoformat(timespec='seconds'),
        'updatedBy': existing.get('updatedBy', '') if is_read_normalisation else current_username,
    }
    if document_type == 'quotation':
        quote_prefix = str(settings.get('quotationPrefix') or prefix or 'QT').upper()
        if not document.get('customNumber'):
            document['number'] = _finance_format_number(
                quote_prefix,
                number_year or now.year,
                base_sequence,
                revision,
            )
        else:
            document['number'] = _finance_number_with_revision(
                document.get('number'), revision
            )
        if not document.get('eventId'):
            document['eventManagedByQuotation'] = False
            document['eventSyncFingerprint'] = ''
    if document.get('invoiceSentDate') and not document.get('paymentDueDate'):
        payment_due_date, payment_term_days = _finance_payment_due_date(
            document['invoiceSentDate'],
            document.get('paymentTerms'),
            document.get('paymentTermDays', 30),
        )
        document['paymentDueDate'] = payment_due_date
        document['paymentTermDays'] = payment_term_days
    range_start, range_end = _finance_event_date_range(document)
    document['eventDays'] = _finance_date_days(range_start, range_end)
    _recalculate_finance_adjustments(document)
    _apply_locked_total_adjustment(document)
    document['totals'] = _finance_totals(document)

    def hydrate_user_names(value):
        if isinstance(value, list):
            for item in value:
                hydrate_user_names(item)
        elif isinstance(value, dict):
            salesperson_username = str(
                value.get('salespersonUsername') or ''
            ).strip()
            if salesperson_username:
                value['salesperson'] = _user_display_name(salesperson_username)
            created_by = str(value.get('createdBy') or '').strip()
            if created_by:
                value['createdByName'] = _user_display_name(created_by)
            updated_by = str(value.get('updatedBy') or '').strip()
            if updated_by:
                value['updatedByName'] = _user_display_name(updated_by)
            for item in value.values():
                if isinstance(item, (dict, list)):
                    hydrate_user_names(item)

    hydrate_user_names(document)
    return document


def _next_finance_number(documents, document_type):
    settings = _load_pdf_settings()
    prefix = settings.get('quotationPrefix' if document_type == 'quotation' else 'invoicePrefix')
    prefix = str(prefix or ('QT' if document_type == 'quotation' else 'INV')).upper()
    year = datetime.now().year
    if document_type == 'quotation':
        sequence = max(
            [
                _safe_int(row.get('baseSequence'), _finance_parse_number(row.get('number'))[2])
                for row in documents
                if row.get('type') == 'quotation'
            ],
            default=0,
        ) + 1
        return _finance_format_number(prefix, year, sequence, 1)
    pattern = re.compile(rf'^{re.escape(prefix)}-{year}-(\d+)$', re.IGNORECASE)
    values = []
    for row in documents:
        match = pattern.match(str(row.get('number') or ''))
        if match:
            values.append(_safe_int(match.group(1), 0))
    return f"{prefix}-{year}-{max(values, default=0) + 1:04d}"


def _finance_revision_payload(document):
    omitted = {
        'revisions', 'totals', 'updatedAt', 'updatedBy', 'status',
        'sentAt', 'acceptedAt', 'eventId',
        'eventManagedByQuotation', 'eventSyncFingerprint',
    }
    return {
        key: value
        for key, value in document.items()
        if key not in omitted
    }


def _finance_revision_fingerprint(document):
    return json.dumps(
        _finance_revision_payload(document),
        ensure_ascii=False,
        sort_keys=True,
        separators=(',', ':'),
    )


def _finance_revision_is_snapshotted(document):
    revision = _safe_int(document.get('revision'), 1)
    return any(
        _safe_int(row.get('revision'), 0) == revision
        for row in document.get('revisions') or []
        if isinstance(row, dict)
    )


def _finance_snapshot_revision(document):
    revision = _safe_int(document.get('revision'), 1)
    revisions = document.setdefault('revisions', [])
    existing = next(
        (
            row for row in revisions
            if isinstance(row, dict) and _safe_int(row.get('revision'), 0) == revision
        ),
        None,
    )
    snapshot = {
        'revision': revision,
        'number': document.get('number'),
        'sentAt': document.get('sentAt'),
        'acceptedAt': document.get('acceptedAt'),
        'validUntil': document.get('validUntil'),
        'validityAmount': document.get('validityAmount'),
        'validityUnit': document.get('validityUnit'),
        'validityDays': document.get('validityDays'),
        'fingerprint': _finance_revision_fingerprint(document),
        'snapshot': copy.deepcopy(_finance_revision_payload(document)),
    }
    if existing:
        existing.update(snapshot)
    else:
        revisions.append(snapshot)


def _finance_reset_to_draft_revision(document):
    prefix, year, sequence, _revision = _finance_parse_number(document.get('number'))
    document['revision'] = 1
    if not document.get('customNumber'):
        document['number'] = _finance_format_number(prefix, year, sequence, 1)
    document['status'] = 'draft'
    document['sentAt'] = ''
    document['acceptedAt'] = ''
    document['invoicedAt'] = ''
    document['invoiceSentDate'] = ''
    document['paymentDueDate'] = ''
    document['paidAt'] = ''
    document['statusChangedAt'] = datetime.now().isoformat(timespec='seconds')
    document['revisions'] = []
    document['validUntil'] = ''


def _finance_expire_sent_documents(finance_data):
    today = datetime.now().date()
    changed = False
    for document in finance_data.get('documents') or []:
        if document.get('type') != 'quotation':
            continue
        status = str(document.get('status') or '').strip().lower()
        automatic_status = ''
        if status == 'sent':
            try:
                valid_until = datetime.strptime(
                    str(document.get('validUntil') or ''),
                    '%Y-%m-%d',
                ).date()
            except ValueError:
                valid_until = None
            if valid_until and valid_until < today:
                automatic_status = 'expired'
        elif status == 'invoiced':
            try:
                due_date = datetime.strptime(
                    str(document.get('paymentDueDate') or ''),
                    '%Y-%m-%d',
                ).date()
            except ValueError:
                due_date = None
            if due_date and due_date < today:
                automatic_status = 'overdue'
        if automatic_status:
            changed_at = datetime.now().isoformat(timespec='seconds')
            document['status'] = automatic_status
            document['statusChangedAt'] = changed_at
            document['updatedAt'] = changed_at
            changed = True
    return changed


def _finance_export_error(document):
    if not str(document.get('projectName') or '').strip():
        return 'Project Name is required'
    return ''


def _finance_event_date_range(document):
    setup_dates = [
        document.get('setupDate'),
        *[row.get('date') for row in document.get('additionalSetups') or [] if isinstance(row, dict)],
    ]
    setup_dates = [value for value in setup_dates if value]
    candidates = [
        *setup_dates,
        document.get('rehearsalDate'),
        *[row.get('date') for row in document.get('additionalRehearsals') or [] if isinstance(row, dict)],
        document.get('showDate'),
        document.get('teardownDate'),
        *[row.get('date') for row in document.get('additionalShows') or [] if isinstance(row, dict)],
        *[row.get('date') for row in document.get('additionalTeardowns') or [] if isinstance(row, dict)],
    ]
    candidates = [value for value in candidates if value]
    if not candidates:
        fallback = document.get('quotationDate') or datetime.now().strftime('%Y-%m-%d')
        return fallback, fallback
    start = min(setup_dates) if setup_dates else min(candidates)
    end = max(candidates)
    if end < start:
        end = start
    return start, end


def _finance_line_is_non_prepare_department(line):
    name, code = _finance_department_details(
        (line or {}).get('department'),
        (line or {}).get('departmentCode'),
    )
    clean_name = str(name or '').strip().lower().removesuffix(' department').strip()
    clean_code = _normalise_department_code(code)
    return clean_code in {'MANPOWER', 'TRANSPORT', 'TRANSPORTATION'} or clean_name in {
        'manpower',
        'transport',
        'transportation',
    }


def _finance_inventory_group_from_line(line):
    if not isinstance(line, dict) or _finance_line_is_non_prepare_department(line):
        return None

    for asset_id in line.get('sourceAssetIds') or []:
        asset = data_manager.inventory.get(str(asset_id or '').strip())
        if not asset or _is_disposed(asset):
            continue
        return {
            'department': _normalise_department_code(getattr(asset, 'department_code', 'UN')) or 'UN',
            'brand': str(getattr(asset, 'brand', '') or '').strip(),
            'model': str(getattr(asset, 'model_number', '') or '').strip(),
            'description': str(getattr(asset, 'description', '') or '').strip(),
        }

    catalog_key = str(line.get('catalogKey') or '').strip().lower()
    if catalog_key:
        for asset in data_manager.inventory.values():
            if _is_disposed(asset):
                continue
            asset_department = (
                _normalise_department_code(
                    getattr(asset, 'department_code', 'UN')
                )
                or 'UN'
            )
            asset_brand = str(getattr(asset, 'brand', '') or '').strip()
            asset_model = str(getattr(asset, 'model_number', '') or '').strip()
            asset_description = str(getattr(asset, 'description', '') or '').strip()
            if _finance_catalog_key(
                asset_department,
                asset_brand,
                asset_model,
                asset_description,
            ).lower() == catalog_key:
                return {
                    'department': asset_department,
                    'brand': asset_brand,
                    'model': asset_model,
                    'description': asset_description,
                }

    if line.get('isCustom'):
        return None

    brand = str(line.get('brand') or '').strip()
    model = str(line.get('model') or '').strip()
    if not brand or not model:
        return None

    return {
        'department': _normalise_department_code(line.get('departmentCode')) or 'UN',
        'brand': brand,
        'model': model,
        'description': str(line.get('description') or '').strip(),
    }


def _finance_custom_marker_from_line(line, quantity):
    if not isinstance(line, dict) or _finance_line_is_non_prepare_department(line):
        return None
    if not line.get('isCustom'):
        return None
    description = str(line.get('description') or '').strip()
    if not description:
        return None
    department_code = _normalise_department_code(line.get('departmentCode')) or 'UN'
    line_id = re.sub(r'[^A-Za-z0-9_-]+', '', str(line.get('id') or ''))[:80]
    uid = f"finance_{line_id}"[:80] if line_id else None
    return _make_custom_marker('MISC', description, quantity, department_code, uid=uid)


def _finance_event_prepared_items(document):
    prepared_items = []
    for line in document.get('lineItems') or []:
        quantity = max(1, _safe_int(round(_safe_float(line.get('quantity'), 1)), 1))
        group = _finance_inventory_group_from_line(line)
        if group:
            _add_or_increment_model_marker(
                prepared_items,
                group,
                quantity,
            )
            continue
        custom_marker = _finance_custom_marker_from_line(line, quantity)
        if custom_marker:
            prepared_items.append(custom_marker)
    return prepared_items


def _finance_event_subprojects(document):
    result = []
    for subproject in document.get('subprojects') or [{'id': 'main', 'name': 'Main Room'}]:
        subproject_id = str(subproject.get('id') or 'main')
        items = []
        for line in document.get('lineItems') or []:
            if str(line.get('subprojectId') or 'main') != subproject_id:
                continue
            quantity = max(0, _safe_float(line.get('quantity'), 0))
            custom_ref = _finance_custom_marker_from_line(
                line,
                max(1, _safe_int(round(quantity), 1)),
            )
            inventory_group = _finance_inventory_group_from_line(line)
            item = {
                'lineId': line.get('id'),
                'department': (
                    line.get('department')
                    if not inventory_group
                    else _finance_department_details(
                        inventory_group.get('department'),
                        inventory_group.get('department'),
                    )[0]
                ),
                'departmentCode': (
                    line.get('departmentCode')
                    if not inventory_group
                    else inventory_group.get('department')
                ),
                'brand': (
                    line.get('brand')
                    if not inventory_group
                    else inventory_group.get('brand')
                ),
                'model': (
                    line.get('model')
                    if not inventory_group
                    else inventory_group.get('model')
                ),
                'description': (
                    line.get('description')
                    if not inventory_group
                    else inventory_group.get('description')
                ),
                'quantity': quantity,
                'isCustom': bool(line.get('isCustom')),
            }
            if custom_ref:
                item['assetRefs'] = [custom_ref]
            items.append(item)
        result.append({
            'id': subproject_id,
            'name': str(subproject.get('name') or 'Room').strip() or 'Room',
            'items': items,
        })
    return result


def _finance_event_asset_fingerprint(event):
    payload = {
        'assetModels': getattr(event, 'asset_models', []) or [],
        'preparedItems': getattr(event, 'prepared_items', []) or [],
        'actuallyPrepared': getattr(event, 'actually_prepared', []) or [],
        'returnedItems': getattr(event, 'returned_items', []) or [],
        'extraAssets': getattr(event, 'extra_assets', []) or [],
        'customCollected': getattr(event, 'custom_collected', []) or [],
        'subprojects': getattr(event, 'subprojects', []) or [],
    }
    return hashlib.sha256(json.dumps(
        payload,
        ensure_ascii=False,
        sort_keys=True,
        separators=(',', ':'),
    ).encode('utf-8')).hexdigest()


def _finance_clear_event_link(document):
    document['eventId'] = None
    document['eventManagedByQuotation'] = False
    document['eventSyncFingerprint'] = ''


def _finance_remove_deleted_event_references(event_id):
    """Remove finance records that must not follow a reused event ID."""
    event_id = _safe_int(event_id, 0)
    if not event_id:
        return {'documentLinks': 0, 'profitLossRows': 0, 'files': 0}

    with _finance_lock:
        finance_data = _load_finance_data()
        document_links = 0
        for document in finance_data.get('documents') or []:
            if not isinstance(document, dict):
                continue
            if _safe_int(document.get('eventId'), 0) != event_id:
                continue
            _finance_clear_event_link(document)
            document_links += 1

        event_key = str(event_id)
        store = _finance_profit_loss_store(finance_data)
        removed_expenses = store.get('expenses', {}).pop(event_key, []) or []
        removed_commissions = store.get('commissions', {}).pop(event_key, []) or []
        removed_manual_revenue = store.get('manualRevenue', {}).pop(event_key, None)
        profit_loss_rows = (
            len(removed_expenses) if isinstance(removed_expenses, list) else 0
        ) + (
            len(removed_commissions) if isinstance(removed_commissions, list) else 0
        ) + (1 if removed_manual_revenue is not None else 0)
        if document_links or profit_loss_rows:
            _save_finance_data(finance_data)

        files_removed = 0
        for expense in removed_expenses if isinstance(removed_expenses, list) else []:
            attachment = expense.get('attachment') if isinstance(expense, dict) else None
            if isinstance(attachment, dict):
                delete_upload(_workforce_folder(), attachment)
                files_removed += 1

    return {
        'documentLinks': document_links,
        'profitLossRows': profit_loss_rows,
        'files': files_removed,
    }


def _finance_can_adopt_legacy_created_event(document, event):
    if document.get('eventManagedByQuotation') or document.get('eventSyncFingerprint'):
        return False
    expected_note = f"Created from quotation {document.get('number')}"
    if str(getattr(event, 'notes', '') or '').strip() != expected_note:
        return False
    return not any((
        getattr(event, 'actually_prepared', []) or [],
        getattr(event, 'returned_items', []) or [],
        getattr(event, 'extra_assets', []) or [],
        getattr(event, 'custom_collected', []) or [],
        getattr(event, 'asset_models', []) or [],
        getattr(event, 'subprojects', []) or [],
    ))


def _finance_sync_managed_event(document):
    event_id = _safe_int(document.get('eventId'), 0)
    if not event_id:
        _finance_clear_event_link(document)
        return None

    event = data_manager.events.get(event_id)
    if not event:
        _finance_clear_event_link(document)
        return None

    if not document.get('eventManagedByQuotation'):
        if not _finance_can_adopt_legacy_created_event(document, event):
            return event_id
        document['eventManagedByQuotation'] = True
        document['eventSyncFingerprint'] = _finance_event_asset_fingerprint(event)

    previous_fingerprint = str(document.get('eventSyncFingerprint') or '').strip()
    if previous_fingerprint and _finance_event_asset_fingerprint(event) != previous_fingerprint:
        document['eventManagedByQuotation'] = False
        document['eventSyncFingerprint'] = ''
        return event_id

    event.asset_models = []
    event.prepared_items = _finance_event_prepared_items(document)
    event.subprojects = _finance_event_subprojects(document)
    data_manager.save_event(event)
    invalidate_cache()
    document['eventSyncFingerprint'] = _finance_event_asset_fingerprint(event)
    return event_id


def _finance_create_event(document):
    if _safe_int(document.get('eventId'), 0):
        document['acceptedAt'] = document.get('acceptedAt') or datetime.now().isoformat(timespec='seconds')
        return _finance_sync_managed_event(document) or _safe_int(document.get('eventId'), 0)

    start_date, end_date = _finance_event_date_range(document)
    prepared_items = _finance_event_prepared_items(document)

    assigned_users = [
        document.get('createdBy')
    ] if document.get('createdBy') in data_manager.users else []

    def build_event(event_id):
        return Event(
            event_id=event_id,
            name=document.get('projectName') or document.get('number'),
            location=document.get('eventLocation') or '',
            start_date=datetime.strptime(start_date, '%Y-%m-%d').strftime('%Y%m%d'),
            end_date=datetime.strptime(end_date, '%Y-%m-%d').strftime('%Y%m%d'),
            asset_models=[],
            prepared_items=prepared_items,
            returned_items=[],
            actually_prepared=[],
            extra_assets=[],
            state='New',
            tag='event',
            assigned_users=assigned_users,
            notes=f"Created from quotation {document.get('number')}",
            subprojects=_finance_event_subprojects(document),
        )

    event = _create_event_with_available_id(build_event)
    event_id = event.event_id
    invalidate_cache()
    document['eventId'] = event_id
    document['acceptedAt'] = datetime.now().isoformat(timespec='seconds')
    document['eventManagedByQuotation'] = True
    document['eventSyncFingerprint'] = _finance_event_asset_fingerprint(event)
    return event_id


def _finance_line_price_signature(line):
    return (
        str((line or {}).get('catalogKey') or '').strip().casefold(),
        str((line or {}).get('description') or '').strip().casefold(),
        str((line or {}).get('brand') or '').strip().casefold(),
        str((line or {}).get('model') or '').strip().casefold(),
        str((line or {}).get('department') or '').strip().casefold(),
        str((line or {}).get('departmentCode') or '').strip().casefold(),
        str((line or {}).get('uom') or 'units').strip().casefold(),
        round(_safe_float((line or {}).get('unitPrice'), 0), 2),
        tuple(sorted(
            str(asset_id or '').strip().casefold()
            for asset_id in ((line or {}).get('sourceAssetIds') or [])
            if str(asset_id or '').strip()
        )),
    )


def _remember_finance_prices(finance_data, document, previous_document=None):
    price_book = finance_data.setdefault('priceBook', {})
    owner = (
        _finance_document_owner_username(document)
        or _finance_current_username()
    ).lower()
    previous_lines = {
        str(line.get('id') or ''): line
        for line in ((previous_document or {}).get('lineItems') or [])
        if isinstance(line, dict) and str(line.get('id') or '')
    }
    for line in document.get('lineItems') or []:
        previous_line = previous_lines.get(str(line.get('id') or ''))
        if (
            previous_document is not None
            and previous_line is not None
            and _finance_line_price_signature(previous_line)
            == _finance_line_price_signature(line)
        ):
            continue
        description = str(line.get('description') or '').strip()
        unit_price = _safe_float(line.get('unitPrice'), 0)
        if not description or unit_price <= 0:
            continue
        key = str(line.get('catalogKey') or '').strip() or _finance_custom_price_key(description)
        payload = {
            'description': description,
            'brand': str(line.get('brand') or '').strip()[:240],
            'model': str(line.get('model') or '').strip()[:240],
            'unitPrice': round(unit_price, 2),
            'department': line.get('department') or 'UN',
            'departmentCode': line.get('departmentCode') or '',
            'uom': line.get('uom') or 'units',
            'owner': owner,
            'updatedAt': document.get('updatedAt'),
        }
        price_book[f"{owner}::{key}"] = payload
        for asset_id in line.get('sourceAssetIds') or []:
            price_book[f"{owner}::asset:{str(asset_id).lower()}"] = payload


def _finance_price_book_key_is_visible(key):
    raw = str(key or '')
    if '::' not in raw or _current_user_is_owner():
        return True
    return raw.split('::', 1)[0].strip().lower() == _finance_current_username().lower()


def _finance_rate_card_rows(finance_data):
    rows = {}
    inventory_rows = {}

    for asset_id, asset in (data_manager.inventory.items() if data_manager else []):
        if not asset or _is_disposed(asset):
            continue
        department, department_code = _finance_department_details(
            getattr(asset, 'department_code', ''),
            getattr(asset, 'department_code', ''),
        )
        brand = str(getattr(asset, 'brand', '') or '').strip()
        model = str(getattr(asset, 'model_number', '') or '').strip()
        description = str(getattr(asset, 'description', '') or '').strip()
        catalog_key = _finance_catalog_key(department_code, brand, model, description)
        canonical = inventory_rows.setdefault(catalog_key.lower(), {
            'catalogKey': catalog_key,
            'brand': brand,
            'model': model,
            'description': description,
            'department': department,
            'departmentCode': department_code,
            'sourceAssetIds': [],
            'searchTags': [],
        })
        canonical['sourceAssetIds'].append(str(asset_id))
        canonical['searchTags'] = normalize_asset_tags(
            canonical['searchTags'] + normalize_asset_tags(getattr(asset, 'tags', []))
        )

    inventory_signatures = {
        (
            _normalise_department_code(row.get('departmentCode') or row.get('department')),
            str(row.get('brand') or '').casefold(),
            str(row.get('model') or '').casefold(),
        ): row
        for row in inventory_rows.values()
    }

    def resolve_inventory(line, catalog_key):
        canonical = inventory_rows.get(str(catalog_key or '').lower())
        if not canonical:
            canonical = inventory_signatures.get((
                _normalise_department_code(line.get('departmentCode') or line.get('department')),
                str(line.get('brand') or '').casefold(),
                str(line.get('model') or '').casefold(),
            ))
        if canonical:
            return canonical['catalogKey'], canonical
        return catalog_key, None

    def add_row(source, key_hint=''):
        if not isinstance(source, dict):
            return
        line = _normalise_finance_line(source)
        if line.get('unitPrice', 0) <= 0 or not line.get('description'):
            return
        key_hint = str(key_hint or '').strip()
        catalog_key = str(line.get('catalogKey') or '').strip()
        if not catalog_key and key_hint and not key_hint.startswith('custom:'):
            catalog_key = key_hint
        catalog_key, canonical = resolve_inventory(line, catalog_key)
        if canonical:
            line.update(canonical)
        identity = catalog_key.lower() or (
            f"custom:{line.get('department', '').strip().lower()}::"
            f"{line.get('description', '').strip().lower()}"
        )
        rows[identity] = {
            'id': identity,
            'catalogKey': catalog_key,
            'sourceAssetIds': line.get('sourceAssetIds') or [],
            'brand': line.get('brand') or '',
            'model': line.get('model') or '',
            'description': line.get('description') or '',
            'department': line.get('department') or 'Unknown Department',
            'departmentCode': line.get('departmentCode') or '',
            'unitPrice': line.get('unitPrice') or 0,
            'uom': line.get('uom') or 'units',
            'isCustom': bool(line.get('isCustom') or not catalog_key),
            'searchTags': line.get('searchTags') or [],
        }

    for document in finance_data.get('documents') or []:
        if document.get('type') != 'quotation' or not _finance_user_can_access(document):
            continue
        for line in document.get('lineItems') or []:
            add_row(line)

    for stored_key, payload in (finance_data.get('priceBook') or {}).items():
        if not _finance_price_book_key_is_visible(stored_key):
            continue
        base_key = str(stored_key).split('::', 1)[-1]
        if base_key.startswith('asset:') or not isinstance(payload, dict):
            continue
        catalog_key = '' if base_key.startswith('custom:') else base_key
        tombstone_line = _normalise_finance_line({
            'catalogKey': catalog_key,
            'description': payload.get('description') or base_key.removeprefix('custom:'),
            'department': payload.get('department') or 'Unknown Department',
            'departmentCode': payload.get('departmentCode') or '',
            'brand': payload.get('brand') or '',
            'model': payload.get('model') or '',
        })
        catalog_key, _ = resolve_inventory(tombstone_line, catalog_key)
        identity = catalog_key.lower() or (
            f"custom:{str(payload.get('department') or 'Unknown Department').strip().lower()}::"
            f"{str(payload.get('description') or base_key.removeprefix('custom:')).strip().lower()}"
        )
        if payload.get('deleted'):
            rows.pop(identity, None)
            continue
        add_row({
            'catalogKey': catalog_key,
            'description': payload.get('description') or base_key.removeprefix('custom:'),
            'department': payload.get('department') or 'Unknown Department',
            'departmentCode': payload.get('departmentCode') or '',
            'brand': payload.get('brand') or '',
            'model': payload.get('model') or '',
            'unitPrice': payload.get('unitPrice'),
            'uom': payload.get('uom') or 'units',
            'isCustom': base_key.startswith('custom:'),
        }, base_key)

    return sorted(rows.values(), key=lambda row: (
        str(row.get('department') or '').casefold(),
        ' '.join((
            str(row.get('brand') or ''),
            str(row.get('model') or ''),
            str(row.get('description') or ''),
        )).casefold(),
    ))


def _finance_remembered_price(price_book, catalog_key, asset_ids):
    username = _finance_current_username().lower()
    owner_prefixes = (
        [username]
        if not _current_user_is_owner()
        else [username, _finance_owner_username().lower()]
    )
    for owner in owner_prefixes:
        for asset_id in asset_ids:
            remembered = price_book.get(f"{owner}::asset:{str(asset_id).lower()}")
            if remembered and not remembered.get('deleted'):
                return remembered
        remembered = price_book.get(f"{owner}::{catalog_key}")
        if remembered and not remembered.get('deleted'):
            return remembered
    remembered = price_book.get(catalog_key)
    if remembered and not remembered.get('deleted'):
        return remembered
    legacy_prefix = str(catalog_key or '').removeprefix('inventory:') + '|'
    for key, value in reversed(list(price_book.items())):
        raw_key = str(key or '')
        if '::' in raw_key and raw_key.split('::', 1)[0].strip().lower() not in owner_prefixes:
            continue
        base_key = str(key).split('::', 1)[-1]
        if base_key.startswith(legacy_prefix) and isinstance(value, dict) and not value.get('deleted'):
            return value
    return {}


def _finance_find_document(data, document_id, document_type):
    return next(
        (
            row for row in data.get('documents') or []
            if str(row.get('id')) == str(document_id) and row.get('type') == document_type
        ),
        None,
    )


def _finance_profit_loss_store(data):
    store = data.get('profitLoss')
    if not isinstance(store, dict):
        store = {'expenses': {}, 'commissions': {}, 'manualRevenue': {}}
        data['profitLoss'] = store
    if not isinstance(store.get('expenses'), dict):
        store['expenses'] = {}
    if not isinstance(store.get('commissions'), dict):
        store['commissions'] = {}
    if not isinstance(store.get('manualRevenue'), dict):
        store['manualRevenue'] = {}
    return store


def _finance_profit_loss_event_expenses(data, event_id, create=False):
    expenses = _finance_profit_loss_store(data).setdefault('expenses', {})
    key = str(int(event_id))
    if create:
        return expenses.setdefault(key, [])
    return expenses.get(key, []) if isinstance(expenses.get(key), list) else []


def _finance_profit_loss_manual_revenue(data, event_id):
    values = _finance_profit_loss_store(data).setdefault('manualRevenue', {})
    stored = values.get(str(int(event_id)))
    if stored is None:
        return None
    record = stored if isinstance(stored, dict) else {'amount': stored}
    amount = money(record.get('amount'), None)
    if amount is None:
        return None
    return {
        'amount': amount,
        'updatedAt': str(record.get('updatedAt') or ''),
        'updatedBy': str(record.get('updatedBy') or ''),
    }


def _normalise_profit_loss_commission(value, revenue=0):
    value = value if isinstance(value, dict) else {}
    mode = str(value.get('calculationMode') or value.get('mode') or 'percent').strip().lower()
    if mode not in {'percent', 'amount'}:
        mode = 'percent'
    percent = round(max(0, min(100, _safe_float(value.get('percent'), 0))), 4)
    entered_amount = round(max(0, _safe_float(value.get('amount'), 0)), 2)
    amount = round(revenue * percent / 100, 2) if mode == 'percent' else entered_amount
    if mode == 'amount':
        percent = round((amount / revenue * 100) if revenue else 0, 4)
    return {
        'id': re.sub(r'[^A-Za-z0-9_-]+', '', str(value.get('id') or ''))[:80] or new_id('commission'),
        'recipient': str(value.get('recipient') or value.get('payee') or '').strip()[:180],
        'calculationMode': mode,
        'percent': percent,
        'amount': amount,
    }


def _finance_profit_loss_event_commissions(data, event_id, revenue=0, create=False):
    commissions = _finance_profit_loss_store(data).setdefault('commissions', {})
    key = str(int(event_id))
    if create:
        rows = commissions.setdefault(key, [])
    else:
        rows = commissions.get(key, []) if isinstance(commissions.get(key), list) else []
    return [
        _normalise_profit_loss_commission(row, revenue)
        for row in rows
        if isinstance(row, dict)
    ]


def _finance_profit_loss_expense_bucket(category):
    text = re.sub(r'\s+', ' ', str(category or '').strip()).casefold()
    if any(term in text for term in ('transport', 'lorry', 'cab', 'taxi', 'grab', 'vehicle')):
        return 'transport'
    if any(term in text for term in ('meal', 'food', 'refreshment')):
        return 'meal'
    return 'other'


def _finance_profit_loss_category_label(category, source='manual'):
    label = re.sub(r'\s+', ' ', str(category or '').strip())
    if label:
        return label[:80]
    return 'Worker Claims' if source == 'worker-claim' else 'Other Expenses'


def _finance_normalise_iso_date(value):
    raw = str(value or '').strip()
    if not raw:
        return ''
    for fmt in ('%Y-%m-%d', '%Y/%m/%d', '%d/%m/%Y', '%d-%m-%Y', '%Y%m%d'):
        try:
            return datetime.strptime(raw[:10] if fmt == '%Y-%m-%d' else raw, fmt).strftime('%Y-%m-%d')
        except ValueError:
            continue
    try:
        return datetime.fromisoformat(raw[:10]).strftime('%Y-%m-%d')
    except ValueError:
        return ''


def _normalise_profit_loss_expense(value, event_id):
    value = value if isinstance(value, dict) else {}
    attachment = value.get('attachment') if isinstance(value.get('attachment'), dict) else None
    amount = money(value.get('amount'), 0.0)
    return {
        'id': re.sub(r'[^A-Za-z0-9_-]+', '', str(value.get('id') or ''))[:80] or new_id('expense'),
        'eventId': int(event_id),
        'description': str(value.get('description') or 'Other expense').strip()[:300] or 'Other expense',
        'category': str(value.get('category') or 'Miscellaneous').strip()[:120] or 'Miscellaneous',
        'department': str(value.get('department') or '').strip()[:120],
        'vendor': str(value.get('vendor') or value.get('payee') or '').strip()[:180],
        'amount': round(amount if amount is not None else 0.0, 2),
        'expenseDate': _finance_normalise_iso_date(value.get('expenseDate') or value.get('date')),
        'notes': str(value.get('notes') or '').strip()[:1000],
        'attachment': attachment,
        'extraction': value.get('extraction') if isinstance(value.get('extraction'), dict) else {},
        'createdAt': str(value.get('createdAt') or now_iso()),
        'createdBy': str(value.get('createdBy') or _finance_current_username()).strip(),
        'updatedAt': str(value.get('updatedAt') or now_iso()),
        'updatedBy': str(value.get('updatedBy') or _finance_current_username()).strip(),
    }


def _profit_loss_expense_payload(expense):
    row = dict(expense or {})
    row.setdefault('source', 'manual')
    row.setdefault('sourceLabel', 'Added expense')
    row.setdefault('readOnly', False)
    row.setdefault('department', '')
    row['categoryKey'] = _finance_profit_loss_expense_bucket(row.get('category'))
    row['categoryLabel'] = _finance_profit_loss_category_label(row.get('category'), row.get('source'))
    attachment = row.get('attachment') if isinstance(row.get('attachment'), dict) else None
    if attachment:
        expense_id = quote(str(row.get('id') or ''))
        row['attachment'] = {
            **attachment,
            'previewUrl': f'/api/finance/profit-loss/expenses/{expense_id}/file',
            'downloadUrl': f'/api/finance/profit-loss/expenses/{expense_id}/file?download=1',
        }
    return row


def _finance_event_brief(event):
    return {
        'id': int(getattr(event, 'event_id', 0) or 0),
        'name': str(getattr(event, 'name', '') or ''),
        'location': str(getattr(event, 'location', '') or ''),
        'startDate': format_date_output(getattr(event, 'start_date', '') or ''),
        'endDate': format_date_output(getattr(event, 'end_date', '') or ''),
        'startDateValue': _event_date_for_input(getattr(event, 'start_date', '') or ''),
        'endDateValue': _event_date_for_input(getattr(event, 'end_date', '') or ''),
        'state': str(getattr(event, 'state', '') or ''),
        'tag': str(getattr(event, 'tag', '') or 'event'),
    }


def _finance_quotations_for_event(finance_data, event_id, accessible_only=True):
    rows = []
    for document in finance_data.get('documents') or []:
        if document.get('type') != 'quotation':
            continue
        if _safe_int(document.get('eventId'), 0) != int(event_id):
            continue
        if accessible_only and not _finance_user_can_access(document):
            continue
        rows.append(_normalise_finance_document(document, 'quotation', document))
    rows.sort(key=lambda row: (row.get('updatedAt', ''), row.get('number', '')), reverse=True)
    return rows


def _finance_profit_loss_can_use_quotation(document):
    role = _effective_user_role(session.get('user'))
    if role in {'owner', 'admin'}:
        return True
    return (
        role == 'manager'
        and _finance_document_owner_username(document).casefold()
        == str(session.get('user') or '').strip().casefold()
    )


def _finance_profit_loss_access(finance_data, event_id):
    linked = [
        row for row in finance_data.get('documents') or []
        if isinstance(row, dict)
        and row.get('type') == 'quotation'
        and _safe_int(row.get('eventId'), 0) == int(event_id)
    ]
    role = _effective_user_role(session.get('user'))
    can_view = (
        role in {'owner', 'admin'}
        or (
            role == 'manager'
            and any(_finance_profit_loss_can_use_quotation(row) for row in linked)
        )
    )
    return {
        'canViewFinancials': can_view,
        'canEditFinancials': can_view,
        'isCensored': not can_view,
        'reason': (
            ''
            if can_view
            else 'Financial details are restricted to administrators and the manager responsible for the linked quotation.'
        ),
    }


def _finance_profit_loss_expense_access_denied():
    return jsonify({'error': "You do not have access to this event's financial details"}), 403


def _finance_profit_loss_line_bucket(line):
    name, code = _finance_department_details(
        (line or {}).get('department'),
        (line or {}).get('departmentCode'),
    )
    clean_code = _normalise_department_code(code)
    clean_name = re.sub(
        r'\s+(?:department|system)$',
        '',
        str(name or '').strip().casefold(),
    )
    if clean_code == 'MANPOWER' or clean_name == 'manpower':
        return 'manpower'
    if clean_code in {'TRANSPORT', 'TRANSPORTATION'} or clean_name in {
        'transport',
        'transportation',
    }:
        return 'transport'
    return 'other'


def _finance_profit_loss_quotation_budgets(quotation):
    budgets = {'manpower': 0.0, 'transport': 0.0}
    if not quotation:
        return budgets
    system_buckets = {}
    for line in quotation.get('lineItems') or []:
        bucket = _finance_profit_loss_line_bucket(line)
        if bucket not in budgets:
            continue
        budgets[bucket] += _safe_float(line.get('total'), 0)
        system_name = _finance_system_name(
            line.get('department'),
            line.get('systemName'),
        )
        system_buckets.setdefault(system_name, set()).add(bucket)
    for adjustment in quotation.get('adjustments') or []:
        if not isinstance(adjustment, dict) or adjustment.get('scope') != 'department':
            continue
        buckets = system_buckets.get(str(adjustment.get('department') or ''), set())
        if len(buckets) == 1:
            budgets[next(iter(buckets))] += _safe_float(adjustment.get('amount'), 0)
    return {
        key: round(max(0, value), 2)
        for key, value in budgets.items()
    }


def _finance_profit_loss_assignment_estimate(assignment):
    if not isinstance(assignment, dict):
        return 0.0
    days = max(1, _safe_int(assignment.get('days'), 1))
    provider_type = str(assignment.get('providerType') or '').strip().lower()
    if provider_type == 'service':
        return round(money(assignment.get('serviceCost'), 0.0) or 0.0, 2)
    if provider_type == 'manpower':
        pax = max(1, _safe_int(assignment.get('pax'), 1))
        rate = money(assignment.get('ratePerPax'), money(assignment.get('dailyRate'), 0.0)) or 0.0
        return round(pax * rate * days, 2)
    rate = money(assignment.get('dailyRate'), 0.0) or 0.0
    return round(rate * days, 2)


def _finance_profit_loss_workforce_costs(event_id):
    workforce = load_workforce(_workforce_folder())
    totals = submission_totals(workforce, event_id)
    assignment_department_estimates = {}
    for assignment in event_assignments(workforce, event_id):
        if not isinstance(assignment, dict):
            continue
        department = str(assignment.get('department') or 'Unassigned')
        assignment_department_estimates[department] = round(
            assignment_department_estimates.get(department, 0)
            + _finance_profit_loss_assignment_estimate(assignment),
            2,
        )
    assignment_estimate = round(
        sum(assignment_department_estimates.values()),
        2,
    )
    invoice_total = round(_safe_float(totals.get('invoice'), 0), 2)
    if invoice_total > 0:
        manpower_departments = {
            str(department or 'Unassigned'): round(
                _safe_float((row or {}).get('invoice'), 0),
                2,
            )
            for department, row in (totals.get('departments') or {}).items()
            if _safe_float((row or {}).get('invoice'), 0) > 0
        }
    else:
        manpower_departments = assignment_department_estimates
    return {
        'manpowerCost': invoice_total if invoice_total > 0 else assignment_estimate,
        'manpowerInvoiceCost': invoice_total,
        'manpowerEstimatedCost': assignment_estimate,
        'manpowerDepartments': manpower_departments,
        'workerClaimsCost': round(_safe_float(totals.get('claims'), 0), 2),
        'transportCost': round(_safe_float(totals.get('transport'), 0), 2),
        'rawTotals': totals,
    }


def _finance_profit_loss_subject_name(workforce, subject_id):
    subject_id = str(subject_id or '')
    for bucket in ('freelancers', 'vendors'):
        rows = workforce.get(bucket) if isinstance(workforce, dict) else []
        bucket_rows = rows if isinstance(rows, list) else []
        for row in bucket_rows:
            if not isinstance(row, dict) or str(row.get('id') or '') != subject_id:
                continue
            return (
                str(
                    row.get('name')
                    or row.get('company')
                    or row.get('companyName')
                    or row.get('contactPerson')
                    or subject_id
                ).strip()
                or subject_id
            )
    return subject_id


def _finance_profit_loss_worker_submission_expenses(workforce, event_id):
    submissions = workforce.get('submissions') if isinstance(workforce, dict) else {}
    event_rows = (
        (submissions or {}).get(str(event_id), {})
        if isinstance(submissions, dict)
        else {}
    )
    subject_departments = {}
    for assignment in event_assignments(workforce, event_id):
        if not isinstance(assignment, dict):
            continue
        subject_id = str(
            assignment.get('freelancerId')
            or assignment.get('vendorId')
            or ''
        )
        department = str(assignment.get('department') or '').strip()
        if not subject_id or not department:
            continue
        departments = subject_departments.setdefault(subject_id, [])
        if department not in departments:
            departments.append(department)

    def resolved_department(subject_id, explicit=''):
        explicit = str(explicit or '').strip()
        if explicit:
            return explicit
        departments = subject_departments.get(str(subject_id), [])
        return departments[0] if len(departments) == 1 else 'Unallocated'

    result = []
    event_items = event_rows.items() if isinstance(event_rows, dict) else []
    for subject_id, rows in event_items:
        if not isinstance(rows, dict):
            continue
        subject_name = _finance_profit_loss_subject_name(workforce, subject_id)
        invoices = rows.get('invoices') if isinstance(rows.get('invoices'), list) else []
        for invoice in invoices:
            if not isinstance(invoice, dict) or invoice.get('status') == 'Denied':
                continue
            amount = money(invoice.get('amount'), 0.0) or 0.0
            if amount <= 0:
                continue
            invoice_id = str(invoice.get('id') or '')
            submission_id = quote(invoice_id)
            original_name = str(invoice.get('originalName') or '').strip()
            attachment = None
            if original_name or invoice.get('storedPath'):
                attachment = {
                    'originalName': original_name or 'Invoice file',
                    'contentType': str(invoice.get('contentType') or ''),
                    'previewUrl': f'/api/workforce/submissions/{submission_id}/file',
                    'downloadUrl': f'/api/workforce/submissions/{submission_id}/file?download=1',
                }
            allocations = [
                row for row in invoice.get('allocations') or []
                if isinstance(row, dict) and str(row.get('department') or '').strip()
            ]
            departments = list(dict.fromkeys(
                str(row.get('department') or '').strip()
                for row in allocations
                if str(row.get('department') or '').strip()
            ))
            if not departments:
                departments = [resolved_department(subject_id)]
            result.append({
                'id': f'worker-invoice-{subject_id}-{invoice_id}'[:120],
                'sourceId': invoice_id,
                'source': 'worker-invoice',
                'sourceLabel': 'Invoice',
                'readOnly': True,
                'eventId': int(event_id),
                'description': f'{subject_name} - Invoice'[:300],
                'category': 'Manpower',
                'categoryKey': 'manpower',
                'categoryLabel': 'Manpower',
                'department': ', '.join(departments) or 'Unallocated',
                'vendor': subject_name,
                'amount': round(amount, 2),
                'expenseDate': _finance_normalise_iso_date(
                    invoice.get('invoiceDate')
                    or invoice.get('date')
                    or invoice.get('submittedAt')
                ),
                'attachment': attachment,
                'status': str(invoice.get('status') or 'Pending Review'),
                'createdAt': str(invoice.get('submittedAt') or ''),
                'createdBy': subject_name,
                'updatedAt': str(
                    invoice.get('detailsCompletedAt')
                    or invoice.get('submittedAt')
                    or ''
                ),
                'updatedBy': subject_name,
            })
        claims = rows.get('claims') if isinstance(rows.get('claims'), list) else []
        for claim in claims:
            if not isinstance(claim, dict) or claim.get('status') == 'Denied':
                continue
            if 'detailsComplete' in claim and not claim.get('detailsComplete'):
                continue
            amount = money(claim.get('amount'), 0.0) or 0.0
            if amount <= 0:
                continue
            claim_id = str(claim.get('id') or '')
            submission_id = quote(claim_id)
            original_name = str(claim.get('originalName') or '').strip()
            attachment = None
            if original_name or claim.get('storedPath'):
                attachment = {
                    'originalName': original_name or 'Claim file',
                    'contentType': str(claim.get('contentType') or ''),
                    'previewUrl': f'/api/workforce/submissions/{submission_id}/file',
                    'downloadUrl': f'/api/workforce/submissions/{submission_id}/file?download=1',
                }
            category = str(claim.get('category') or 'Worker Claims').strip()
            category_key = _finance_profit_loss_expense_bucket(category)
            if category_key == 'meal':
                claim_label = 'Meal claim'
            elif category_key == 'transport':
                claim_label = 'Transport claim'
            else:
                claim_label = _finance_profit_loss_category_label(
                    category,
                    'worker-claim',
                )
                if not re.search(r'\bclaims?$', claim_label, re.IGNORECASE):
                    claim_label = f'{claim_label} claim'
            result.append({
                'id': f'worker-claim-{subject_id}-{claim_id}'[:120],
                'sourceId': claim_id,
                'source': 'worker-claim',
                'sourceLabel': 'Claim',
                'readOnly': True,
                'eventId': int(event_id),
                'description': f'{subject_name} - {claim_label}'[:300],
                'category': category[:120],
                'categoryKey': category_key,
                'categoryLabel': _finance_profit_loss_category_label(category, 'worker-claim'),
                'department': resolved_department(
                    subject_id,
                    claim.get('department'),
                ),
                'vendor': subject_name,
                'amount': round(amount, 2),
                'expenseDate': _finance_normalise_iso_date(claim.get('claimDate') or claim.get('date')),
                'attachment': attachment,
                'status': str(claim.get('status') or 'Pending Review'),
                'createdAt': str(claim.get('submittedAt') or ''),
                'createdBy': subject_name,
                'updatedAt': str(claim.get('detailsCompletedAt') or claim.get('submittedAt') or ''),
                'updatedBy': subject_name,
            })
    result.sort(key=lambda row: (row.get('expenseDate') or '', row.get('createdAt') or ''), reverse=True)
    return result


def _finance_profit_loss_worker_claim_expenses(workforce, event_id):
    return [
        row for row in _finance_profit_loss_worker_submission_expenses(
            workforce,
            event_id,
        )
        if row.get('source') == 'worker-claim'
    ]


def _finance_profit_loss_payload(event, finance_data):
    event_id = int(event.event_id)
    quotations = [
        row for row in _finance_quotations_for_event(
            finance_data,
            event_id,
            accessible_only=False,
        )
        if _finance_profit_loss_can_use_quotation(row)
    ]
    quotation = quotations[0] if quotations else None
    manual_revenue = _finance_profit_loss_manual_revenue(finance_data, event_id)
    revenue = round(
        _safe_float(
            (quotation or {}).get('totals', {}).get('netSubtotal')
            if quotation
            else (manual_revenue or {}).get('amount'),
            0,
        ),
        2,
    )
    available_quotations = []
    for document in finance_data.get('documents') or []:
        if (
            not isinstance(document, dict)
            or document.get('type') != 'quotation'
            or _safe_int(document.get('eventId'), 0)
            or not _finance_profit_loss_can_use_quotation(document)
        ):
            continue
        row = _normalise_finance_document(document, 'quotation', document)
        available_quotations.append({
            'id': row.get('id'),
            'number': row.get('number'),
            'projectName': row.get('projectName'),
            'status': row.get('status'),
            'client': row.get('client') or {},
            'amount': round(_safe_float((row.get('totals') or {}).get('netSubtotal'), 0), 2),
            'updatedAt': row.get('updatedAt'),
        })
    available_quotations.sort(
        key=lambda row: (str(row.get('updatedAt') or ''), str(row.get('number') or '')),
        reverse=True,
    )
    expenses = [
        _normalise_profit_loss_expense(row, event_id)
        for row in _finance_profit_loss_event_expenses(finance_data, event_id)
        if isinstance(row, dict)
    ]
    workforce = load_workforce(_workforce_folder())
    worker_submission_expenses = _finance_profit_loss_worker_submission_expenses(
        workforce,
        event_id,
    )
    worker_claim_expenses = [
        row for row in worker_submission_expenses
        if row.get('source') == 'worker-claim'
    ]
    manual_transport_expenses = round(sum(
        _safe_float(row.get('amount'), 0)
        for row in expenses
        if _finance_profit_loss_expense_bucket(row.get('category')) == 'transport'
    ), 2)
    manual_meal_expenses = round(sum(
        _safe_float(row.get('amount'), 0)
        for row in expenses
        if _finance_profit_loss_expense_bucket(row.get('category')) == 'meal'
    ), 2)
    manual_other_expenses = round(sum(
        _safe_float(row.get('amount'), 0)
        for row in expenses
        if _finance_profit_loss_expense_bucket(row.get('category')) == 'other'
    ), 2)
    crew_transport_claims = round(sum(
        _safe_float(row.get('amount'), 0)
        for row in worker_claim_expenses
        if row.get('categoryKey') == 'transport'
    ), 2)
    worker_meal_claims = round(sum(
        _safe_float(row.get('amount'), 0)
        for row in worker_claim_expenses
        if row.get('categoryKey') == 'meal'
    ), 2)
    worker_other_claims = round(sum(
        _safe_float(row.get('amount'), 0)
        for row in worker_claim_expenses
        if row.get('categoryKey') == 'other'
    ), 2)
    workforce_costs = _finance_profit_loss_workforce_costs(event_id)
    manpower_cost = round(
        workforce_costs['manpowerCost']
        + crew_transport_claims
        + worker_meal_claims
        + manual_meal_expenses,
        2,
    )
    transport_cost = round(
        workforce_costs['transportCost'] + manual_transport_expenses,
        2,
    )
    other_expenses = round(worker_other_claims + manual_other_expenses, 2)
    direct_costs = round(manpower_cost + transport_cost, 2)
    before_commission = round(revenue - direct_costs - other_expenses, 2)
    commissions = _finance_profit_loss_event_commissions(finance_data, event_id, revenue)
    commission = round(sum(_safe_float(row.get('amount'), 0) for row in commissions), 2)
    commission_rate = round((commission / revenue * 100) if revenue else 0, 4)
    net_profit = round(before_commission - commission, 2)
    profit_margin = round((net_profit / revenue * 100) if revenue else 0, 2)
    expense_category_totals = {}

    def add_expense_category(row):
        amount = round(_safe_float(row.get('amount'), 0), 2)
        if amount <= 0:
            return
        key = str(row.get('categoryLabel') or row.get('category') or 'Other Expenses')
        entry = expense_category_totals.setdefault(key, {
            'label': key,
            'amount': 0.0,
            'source': row.get('source') or 'manual',
        })
        entry['amount'] = round(entry['amount'] + amount, 2)

    for row in worker_claim_expenses:
        if row.get('categoryKey') == 'other':
            add_expense_category(row)
    for row in expenses:
        payload_row = _profit_loss_expense_payload(row)
        if payload_row.get('categoryKey') == 'other':
            add_expense_category(payload_row)

    expense_categories = sorted(
        expense_category_totals.values(),
        key=lambda row: (-_safe_float(row.get('amount'), 0), str(row.get('label') or '')),
    )
    quotation_budgets = _finance_profit_loss_quotation_budgets(quotation)
    manpower_department_totals = {
        str(department or 'Unallocated'): round(_safe_float(amount, 0), 2)
        for department, amount in (workforce_costs.get('manpowerDepartments') or {}).items()
        if _safe_float(amount, 0) > 0
    }

    def add_manpower_department_cost(department, amount):
        amount = round(_safe_float(amount, 0), 2)
        if amount <= 0:
            return
        department = str(department or '').strip() or 'Unallocated'
        manpower_department_totals[department] = round(
            manpower_department_totals.get(department, 0) + amount,
            2,
        )

    for row in worker_claim_expenses:
        if row.get('categoryKey') in {'transport', 'meal'}:
            add_manpower_department_cost(row.get('department'), row.get('amount'))
    for row in expenses:
        if _finance_profit_loss_expense_bucket(row.get('category')) == 'meal':
            add_manpower_department_cost(row.get('department'), row.get('amount'))

    manpower_department_rows = []
    for department, amount in sorted(
        manpower_department_totals.items(),
        key=lambda row: str(row[0]).casefold(),
    ):
        amount = round(_safe_float(amount, 0), 2)
        if amount <= 0:
            continue
        code = _normalise_department_code(department)
        label = (
            _department_payload(code).get('name')
            if code and code not in {'UNALLOCATED', 'UNASSIGNED'}
            else str(department or 'Unallocated')
        )
        manpower_department_rows.append({
            'department': str(department or 'Unallocated'),
            'label': str(label or department or 'Unallocated'),
            'amount': amount,
        })

    profit_chart = []
    for row in manpower_department_rows:
        profit_chart.append({
            'key': f"manpower-{_normalise_department_code(row['department']).lower()}",
            'group': 'manpower',
            'department': row['department'],
            'label': f"Manpower - {row['label']}",
            'amount': row['amount'],
        })
    if transport_cost > 0:
        profit_chart.append({
            'key': 'transport',
            'group': 'transport',
            'label': 'Transport',
            'amount': transport_cost,
        })
    for row in expense_categories:
        category_key = re.sub(
            r'[^a-z0-9]+',
            '-',
            str(row.get('label') or 'expense').casefold(),
        ).strip('-') or 'expense'
        profit_chart.append({
            'key': f'other-{category_key}',
            'group': 'other',
            'label': str(row.get('label') or 'Other expense'),
            'amount': round(_safe_float(row.get('amount'), 0), 2),
        })
    if commission > 0:
        profit_chart.append({
            'key': 'commission',
            'group': 'commission',
            'label': 'Commission',
            'amount': commission,
        })
    if net_profit > 0:
        profit_chart.append({
            'key': 'net-profit',
            'group': 'profit',
            'label': 'Net Profit',
            'amount': net_profit,
        })

    breakdown = {
        'manpower': manpower_cost,
        'manpowerInvoicesOrEstimate': workforce_costs['manpowerCost'],
        'workerTransportClaims': crew_transport_claims,
        'workerMealClaims': worker_meal_claims,
        'manualMealExpenses': manual_meal_expenses,
        'transportBookings': workforce_costs['transportCost'],
        'crewTransportClaims': crew_transport_claims,
        'manualTransportExpenses': manual_transport_expenses,
        'transport': transport_cost,
        'workerClaims': round(
            crew_transport_claims + worker_meal_claims + worker_other_claims,
            2,
        ),
        'workerMealClaims': worker_meal_claims,
        'workerOtherClaims': worker_other_claims,
        'manualOtherExpenses': manual_other_expenses,
        'commission': commission,
    }
    return {
        'event': _finance_event_brief(event),
        'quotation': ({
            'id': quotation.get('id'),
            'number': quotation.get('number'),
            'projectName': quotation.get('projectName'),
            'client': quotation.get('client') or {},
            'totals': quotation.get('totals') or {},
        } if quotation else None),
        'quotations': [
            {
                'id': row.get('id'),
                'number': row.get('number'),
                'projectName': row.get('projectName'),
            }
            for row in quotations
        ],
        'availableQuotations': available_quotations,
        'manualRevenue': manual_revenue,
        'revenueSource': 'quotation' if quotation else 'manual' if manual_revenue else 'none',
        'summary': {
            'revenue': revenue,
            'directCosts': direct_costs,
            'manpowerCost': manpower_cost,
            'manpowerInvoiceCost': workforce_costs['manpowerInvoiceCost'],
            'manpowerEstimatedCost': workforce_costs['manpowerEstimatedCost'],
            'workerMealClaimsCost': worker_meal_claims,
            'manualMealExpenses': manual_meal_expenses,
            'manpowerBudget': quotation_budgets['manpower'],
            'manpowerBudgetVariance': round(
                quotation_budgets['manpower'] - manpower_cost,
                2,
            ),
            'transportBookingCost': workforce_costs['transportCost'],
            'crewTransportClaimsCost': crew_transport_claims,
            'manualTransportExpenses': manual_transport_expenses,
            'transportCost': transport_cost,
            'transportBudget': quotation_budgets['transport'],
            'transportBudgetVariance': round(
                quotation_budgets['transport'] - transport_cost,
                2,
            ),
            'workerClaimsCost': round(
                crew_transport_claims + worker_meal_claims + worker_other_claims,
                2,
            ),
            'workerOtherClaimsCost': worker_other_claims,
            'manualOtherExpenses': manual_other_expenses,
            'otherExpenses': other_expenses,
            'beforeCommission': before_commission,
            'commissionRate': commission_rate,
            'commission': commission,
            'netProfit': net_profit,
            'profitMargin': profit_margin,
        },
        'breakdown': breakdown,
        'manpowerDepartments': manpower_department_rows,
        'expenses': worker_submission_expenses + [
            _profit_loss_expense_payload(row)
            for row in expenses
        ],
        'commissions': commissions,
        'expenseCategories': expense_categories,
        'profitChart': profit_chart,
        'activity': _event_activity_logs_for_response(event)[-8:][::-1],
    }


ACCOUNTING_TAX_CODES = {
    'SR9': {'name': 'Standard-rated supply 9%', 'kind': 'sale', 'rate': 9.0},
    'ZR': {'name': 'Zero-rated supply', 'kind': 'sale', 'rate': 0.0},
    'ES': {'name': 'Exempt supply', 'kind': 'sale', 'rate': 0.0},
    'TX9': {'name': 'Taxable purchase 9%', 'kind': 'purchase', 'rate': 9.0},
    'TX0': {'name': 'Zero-rated taxable purchase', 'kind': 'purchase', 'rate': 0.0},
    'BL': {'name': 'Blocked input tax', 'kind': 'purchase', 'rate': 0.0},
    'OP': {'name': 'Out of scope', 'kind': 'other', 'rate': 0.0},
}
ACCOUNTING_ACCOUNT_TYPES = {'asset', 'liability', 'equity', 'revenue', 'expense'}


def _accounting_store(finance_data):
    store = finance_data.get('accounting')
    if not isinstance(store, dict):
        store = _accounting_defaults()
        finance_data['accounting'] = store
    defaults = _accounting_defaults()
    settings = store.get('settings')
    if not isinstance(settings, dict):
        settings = {}
        store['settings'] = settings
    for key, value in defaults['settings'].items():
        settings.setdefault(key, value)
    accounts = store.get('accounts')
    if not isinstance(accounts, list):
        accounts = []
        store['accounts'] = accounts
    existing_codes = {
        str(row.get('code') or '').strip()
        for row in accounts
        if isinstance(row, dict)
    }
    for account in defaults['accounts']:
        if account['code'] not in existing_codes:
            accounts.append(account)
    for account in accounts:
        if (
            isinstance(account, dict)
            and str(account.get('code') or '') == '3000'
            and str(account.get('name') or '').strip().casefold() == 'owner capital'
        ):
            account['name'] = 'Share Capital'
    if not isinstance(store.get('journals'), list):
        store['journals'] = []
    if not isinstance(store.get('bankTransactions'), list):
        store['bankTransactions'] = []
    return store


def _accounting_money(value, default=0.0):
    return round(_safe_float(value, default), 2)


def _accounting_date(value, fallback=None):
    raw = str(value or '').strip()[:10]
    try:
        return datetime.strptime(raw, '%Y-%m-%d').strftime('%Y-%m-%d')
    except ValueError:
        return fallback if fallback is not None else datetime.now().strftime('%Y-%m-%d')


def _accounting_account_map(store):
    return {
        str(row.get('code') or '').strip(): row
        for row in store.get('accounts') or []
        if isinstance(row, dict) and str(row.get('code') or '').strip()
    }


def _accounting_next_journal_number(store):
    year = datetime.now().year
    pattern = re.compile(rf'^JE-{year}-(\d+)$', re.IGNORECASE)
    values = []
    for row in store.get('journals') or []:
        match = pattern.match(str((row or {}).get('number') or ''))
        if match:
            values.append(_safe_int(match.group(1), 0))
    return f"JE-{year}-{max(values, default=0) + 1:05d}"


def _accounting_normalise_line(value, account_map):
    value = value if isinstance(value, dict) else {}
    account_code = str(value.get('accountCode') or '').strip()[:30]
    if account_code not in account_map:
        raise ValueError(f'Unknown account code: {account_code or "blank"}')
    debit = max(0.0, _accounting_money(value.get('debit')))
    credit = max(0.0, _accounting_money(value.get('credit')))
    if debit and credit:
        raise ValueError('A journal line cannot contain both a debit and a credit')
    if not debit and not credit:
        raise ValueError('Each journal line requires a debit or credit amount')
    tax_code = str(value.get('taxCode') or 'OP').strip().upper()
    if tax_code not in ACCOUNTING_TAX_CODES:
        raise ValueError(f'Unknown GST tax code: {tax_code}')
    return {
        'id': str(value.get('id') or secrets.token_hex(6))[:40],
        'accountCode': account_code,
        'description': str(value.get('description') or '').strip()[:500],
        'debit': debit,
        'credit': credit,
        'taxCode': tax_code,
        'taxBase': _accounting_money(value.get('taxBase')),
        'gstAmount': _accounting_money(value.get('gstAmount')),
        'contact': str(value.get('contact') or '').strip()[:200],
        'eventId': _safe_int(value.get('eventId'), 0) or None,
    }


def _accounting_normalise_journal(value, store, existing=None):
    value = value if isinstance(value, dict) else {}
    existing = existing if isinstance(existing, dict) else {}
    account_map = _accounting_account_map(store)
    raw_lines = value.get('lines') if 'lines' in value else existing.get('lines') or []
    lines = [
        _accounting_normalise_line(row, account_map)
        for row in raw_lines
        if isinstance(row, dict)
    ]
    if len(lines) < 2:
        raise ValueError('A journal entry requires at least two lines')
    debit_total = _accounting_money(sum(row['debit'] for row in lines))
    credit_total = _accounting_money(sum(row['credit'] for row in lines))
    status = str(value.get('status') or existing.get('status') or 'draft').strip().lower()
    if status not in {'draft', 'posted'}:
        status = 'draft'
    if status == 'posted' and abs(debit_total - credit_total) >= 0.005:
        raise ValueError('Posted journals must balance: total debits must equal total credits')
    entry_date = _accounting_date(value.get('date') or existing.get('date'))
    lock_date = _accounting_date(
        store.get('settings', {}).get('periodLockDate'),
        '',
    )
    if lock_date and entry_date <= lock_date and value.get('_allowLocked') is not True:
        raise ValueError(f'The accounting period is locked through {lock_date}')
    now_value = now_iso()
    history = list(existing.get('history') or [])
    if existing:
        history.append({
            'at': now_value,
            'by': _finance_current_username(),
            'action': 'updated',
            'previousStatus': existing.get('status'),
            'previousDebit': existing.get('debitTotal'),
            'previousCredit': existing.get('creditTotal'),
        })
    return {
        'id': str(existing.get('id') or value.get('id') or secrets.token_hex(12))[:80],
        'number': str(existing.get('number') or value.get('number') or _accounting_next_journal_number(store)).strip()[:80],
        'date': entry_date,
        'description': str(value.get('description') if 'description' in value else existing.get('description') or '').strip()[:500],
        'reference': str(value.get('reference') if 'reference' in value else existing.get('reference') or '').strip()[:200],
        'status': status,
        'sourceKey': str(existing.get('sourceKey') or value.get('sourceKey') or '').strip()[:200],
        'sourceType': str(existing.get('sourceType') or value.get('sourceType') or 'manual').strip()[:80],
        'lines': lines,
        'debitTotal': debit_total,
        'creditTotal': credit_total,
        'createdAt': existing.get('createdAt') or now_value,
        'createdBy': existing.get('createdBy') or _finance_current_username(),
        'updatedAt': now_value,
        'updatedBy': _finance_current_username(),
        'postedAt': (
            existing.get('postedAt')
            or (now_value if status == 'posted' else '')
        ),
        'reversedJournalId': str(existing.get('reversedJournalId') or '')[:80],
        'reversalOf': str(existing.get('reversalOf') or value.get('reversalOf') or '')[:80],
        'history': history[-100:],
    }


def _accounting_expense_account(category):
    lowered = str(category or '').strip().casefold()
    mappings = (
        (('manpower', 'crew', 'salary', 'wage'), '6000'),
        (('transport', 'lorry', 'vehicle', 'taxi', 'parking'), '6100'),
        (('rental', 'hire'), '6200'),
        (('repair', 'maintenance'), '6300'),
        (('office', 'admin', 'stationery'), '6400'),
        (('professional', 'legal', 'accounting'), '6500'),
        (('marketing', 'advertising'), '6600'),
        (('bank', 'finance charge'), '6700'),
        (('commission',), '6900'),
    )
    for keywords, code in mappings:
        if any(keyword in lowered for keyword in keywords):
            return code
    return '6800'


def _accounting_source_documents(finance_data):
    sources = []
    quotations = {
        str(row.get('id')): row
        for row in finance_data.get('documents') or []
        if isinstance(row, dict) and row.get('type') == 'quotation'
    }
    for raw in finance_data.get('documents') or []:
        if not isinstance(raw, dict) or raw.get('type') != 'invoice':
            continue
        invoice = _normalise_finance_document(raw, 'invoice', raw)
        totals = invoice.get('totals') or _finance_totals(invoice)
        client = invoice.get('client') or {}
        source_key = f"sales-invoice:{invoice.get('id')}"
        sources.append({
            'key': source_key,
            'kind': 'sales-invoice',
            'date': _accounting_date(invoice.get('invoiceDate')),
            'dueDate': _accounting_date(invoice.get('dueDate'), ''),
            'number': invoice.get('number') or 'Invoice',
            'contact': client.get('company') or client.get('name') or '',
            'description': invoice.get('projectName') or invoice.get('number') or 'Sales invoice',
            'status': invoice.get('status') or 'draft',
            'net': _accounting_money(totals.get('netSubtotal')),
            'gst': _accounting_money(totals.get('tax')),
            'gross': _accounting_money(totals.get('total')),
            'eventId': invoice.get('eventId'),
            'accountCode': '4000',
        })
        quotation = quotations.get(str(invoice.get('sourceQuotationId') or ''))
        paid_at = str((quotation or {}).get('paidAt') or invoice.get('paidAt') or '')
        if paid_at or str((quotation or {}).get('status') or invoice.get('status')).lower() == 'paid':
            sources.append({
                'key': f"sales-payment:{invoice.get('id')}",
                'kind': 'sales-payment',
                'date': _accounting_date(paid_at),
                'dueDate': '',
                'number': f"Payment - {invoice.get('number') or 'Invoice'}",
                'contact': client.get('company') or client.get('name') or '',
                'description': f"Payment received for {invoice.get('number') or 'invoice'}",
                'status': 'paid',
                'net': _accounting_money(totals.get('total')),
                'gst': 0.0,
                'gross': _accounting_money(totals.get('total')),
                'eventId': invoice.get('eventId'),
                'accountCode': '1000',
            })

    expenses_store = _finance_profit_loss_store(finance_data).get('expenses') or {}
    for event_id, rows in expenses_store.items():
        for raw in rows if isinstance(rows, list) else []:
            if not isinstance(raw, dict):
                continue
            expense = _normalise_profit_loss_expense(raw, _safe_int(event_id, 0))
            amount = _accounting_money(expense.get('amount'))
            if amount <= 0:
                continue
            category = expense.get('category') or 'Other Expenses'
            sources.append({
                'key': f"expense:{expense.get('id')}",
                'kind': 'expense',
                'date': _accounting_date(expense.get('expenseDate') or expense.get('createdAt')),
                'dueDate': '',
                'number': expense.get('reference') or expense.get('id') or 'Expense',
                'contact': expense.get('vendor') or '',
                'description': expense.get('description') or category,
                'status': 'recorded',
                'net': amount,
                'gst': 0.0,
                'gross': amount,
                'eventId': _safe_int(event_id, 0) or None,
                'category': category,
                'accountCode': _accounting_expense_account(category),
            })

    workforce = load_workforce(_workforce_folder())
    submissions = workforce.get('submissions') if isinstance(workforce, dict) else {}
    for event_id, event_rows in (submissions.items() if isinstance(submissions, dict) else []):
        for subject_id, rows in (event_rows.items() if isinstance(event_rows, dict) else []):
            if not isinstance(rows, dict):
                continue
            contact = _finance_profit_loss_subject_name(workforce, subject_id)
            for kind, label, account_code in (
                ('invoices', 'Manpower invoice', '6000'),
                ('claims', 'Worker claim', '6800'),
            ):
                for record in rows.get(kind) if isinstance(rows.get(kind), list) else []:
                    if not isinstance(record, dict) or record.get('status') == 'Denied':
                        continue
                    if kind == 'claims' and 'detailsComplete' in record and not record.get('detailsComplete'):
                        continue
                    amount = _accounting_money(record.get('amount'))
                    if amount <= 0:
                        continue
                    record_id = str(record.get('id') or secrets.token_hex(6))
                    category = record.get('category') or label
                    sources.append({
                        'key': f"workforce-{kind[:-1]}:{record_id}",
                        'kind': f"workforce-{kind[:-1]}",
                        'date': _accounting_date(record.get('claimDate') or record.get('submittedAt')),
                        'dueDate': '',
                        'number': record.get('originalName') or record_id,
                        'contact': contact,
                        'description': record.get('description') or category,
                        'status': record.get('status') or 'recorded',
                        'net': amount,
                        'gst': 0.0,
                        'gross': amount,
                        'eventId': _safe_int(event_id, 0) or None,
                        'category': category,
                        'accountCode': account_code if kind == 'invoices' else _accounting_expense_account(category),
                    })

    posted_keys = {
        str(row.get('sourceKey') or '')
        for row in _accounting_store(finance_data).get('journals') or []
        if isinstance(row, dict) and row.get('status') == 'posted'
    }
    for source in sources:
        source['posted'] = source['key'] in posted_keys
    sources.sort(key=lambda row: (row.get('date') or '', row.get('number') or ''), reverse=True)
    return sources


def _accounting_post_source(finance_data, source_key, options=None):
    options = options if isinstance(options, dict) else {}
    store = _accounting_store(finance_data)
    if any(
        row.get('sourceKey') == source_key and row.get('status') == 'posted'
        for row in store.get('journals') or []
        if isinstance(row, dict)
    ):
        raise ValueError('This source document has already been posted')
    source = next(
        (row for row in _accounting_source_documents(finance_data) if row['key'] == source_key),
        None,
    )
    if not source:
        raise ValueError('Source document not found')
    settings = store.get('settings') or {}
    description = source.get('description') or source.get('number') or 'Source document'
    contact = source.get('contact') or ''
    event_id = source.get('eventId')
    if source['kind'] == 'sales-invoice':
        gross = _accounting_money(source.get('gross'))
        net = _accounting_money(source.get('net'))
        gst = _accounting_money(source.get('gst'))
        lines = [
            {'accountCode': settings.get('defaultReceivableAccount', '1100'), 'debit': gross, 'credit': 0, 'description': description, 'contact': contact, 'eventId': event_id},
            {'accountCode': source.get('accountCode') or '4000', 'debit': 0, 'credit': net, 'description': description, 'contact': contact, 'eventId': event_id, 'taxCode': 'SR9' if gst else 'OP', 'taxBase': net, 'gstAmount': gst},
        ]
        if gst:
            lines.append({'accountCode': '2100', 'debit': 0, 'credit': gst, 'description': 'Output GST', 'taxCode': 'OP'})
    elif source['kind'] == 'sales-payment':
        gross = _accounting_money(source.get('gross'))
        lines = [
            {'accountCode': options.get('bankAccount') or settings.get('defaultBankAccount', '1000'), 'debit': gross, 'credit': 0, 'description': description, 'contact': contact, 'eventId': event_id},
            {'accountCode': settings.get('defaultReceivableAccount', '1100'), 'debit': 0, 'credit': gross, 'description': description, 'contact': contact, 'eventId': event_id},
        ]
    else:
        gross = _accounting_money(source.get('gross'))
        tax_code = str(options.get('taxCode') or 'OP').upper()
        if tax_code not in {'TX9', 'TX0', 'BL', 'OP'}:
            tax_code = 'OP'
        rate = _accounting_money(settings.get('gstRate'), ACCOUNTING_GST_RATE)
        claim_gst = bool(settings.get('gstRegistered')) and tax_code == 'TX9'
        net = _accounting_money(gross / (1 + rate / 100)) if claim_gst and rate else gross
        gst = _accounting_money(gross - net) if claim_gst else 0.0
        expense_account = str(options.get('accountCode') or source.get('accountCode') or '6800')
        counter_account = str(options.get('counterAccount') or settings.get('defaultPayableAccount', '2000'))
        lines = [
            {'accountCode': expense_account, 'debit': net, 'credit': 0, 'description': description, 'contact': contact, 'eventId': event_id, 'taxCode': tax_code, 'taxBase': net if tax_code in {'TX9', 'TX0'} else 0, 'gstAmount': gst},
            {'accountCode': counter_account, 'debit': 0, 'credit': gross, 'description': description, 'contact': contact, 'eventId': event_id},
        ]
        if gst:
            lines.insert(1, {'accountCode': '1200', 'debit': gst, 'credit': 0, 'description': 'Input GST', 'taxCode': 'OP'})
    journal = _accounting_normalise_journal({
        'date': options.get('date') or source.get('date'),
        'description': description,
        'reference': source.get('number'),
        'status': 'posted',
        'sourceKey': source_key,
        'sourceType': source.get('kind'),
        'lines': lines,
    }, store)
    store['journals'].append(journal)
    return journal


def _accounting_bank_date(value):
    raw = str(value or '').strip()
    for date_format in ('%Y-%m-%d', '%d/%m/%Y', '%d-%m-%Y', '%d %b %Y', '%d %B %Y'):
        try:
            return datetime.strptime(raw, date_format).strftime('%Y-%m-%d')
        except ValueError:
            continue
    raise ValueError(f'Invalid bank transaction date: {raw or "blank"}')


def _accounting_bank_fingerprint(value):
    raw = '|'.join((
        str(value.get('date') or ''),
        f"{_accounting_money(value.get('amount')):.2f}",
        str(value.get('description') or '').strip().casefold(),
        str(value.get('reference') or '').strip().casefold(),
        str(value.get('bankAccount') or '1000'),
    ))
    return hashlib.sha1(raw.encode('utf-8')).hexdigest()


def _accounting_normalise_bank_transaction(value, store):
    value = value if isinstance(value, dict) else {}
    bank_account = str(
        value.get('bankAccount')
        or store.get('settings', {}).get('defaultBankAccount')
        or '1000'
    )
    if bank_account not in _accounting_account_map(store):
        raise ValueError('Bank account is not in the chart of accounts')
    transaction = {
        'id': str(value.get('id') or secrets.token_hex(12))[:80],
        'date': _accounting_bank_date(value.get('date')),
        'description': str(value.get('description') or '').strip()[:500],
        'reference': str(value.get('reference') or '').strip()[:200],
        'amount': _accounting_money(value.get('amount')),
        'bankAccount': bank_account,
        'status': 'matched' if value.get('status') == 'matched' else 'unmatched',
        'journalId': str(value.get('journalId') or '')[:80],
        'importedAt': str(value.get('importedAt') or now_iso()),
        'importedBy': str(value.get('importedBy') or _finance_current_username()),
    }
    if not transaction['description']:
        transaction['description'] = transaction['reference'] or 'Bank transaction'
    if not transaction['amount']:
        raise ValueError('Bank transaction amount cannot be zero')
    transaction['fingerprint'] = _accounting_bank_fingerprint(transaction)
    return transaction


def _accounting_match_bank_transaction(finance_data, transaction_id, options):
    store = _accounting_store(finance_data)
    transaction = next(
        (row for row in store.get('bankTransactions') or [] if str((row or {}).get('id')) == str(transaction_id)),
        None,
    )
    if not transaction:
        raise ValueError('Bank transaction not found')
    if transaction.get('status') == 'matched':
        raise ValueError('Bank transaction is already matched')
    account_map = _accounting_account_map(store)
    counter_account = str(options.get('accountCode') or '')
    if counter_account not in account_map:
        raise ValueError('Choose a valid matching account')
    amount = _accounting_money(transaction.get('amount'))
    gross = abs(amount)
    tax_code = str(options.get('taxCode') or 'OP').upper()
    if tax_code not in ACCOUNTING_TAX_CODES:
        tax_code = 'OP'
    settings = store.get('settings') or {}
    rate = _accounting_money(settings.get('gstRate'), ACCOUNTING_GST_RATE)
    description = str(options.get('description') or transaction.get('description') or 'Bank transaction')[:500]
    lines = []
    if amount < 0 and tax_code == 'TX9' and settings.get('gstRegistered') and rate:
        net = _accounting_money(gross / (1 + rate / 100))
        gst = _accounting_money(gross - net)
        lines.extend([
            {'accountCode': counter_account, 'debit': net, 'credit': 0, 'description': description, 'taxCode': 'TX9', 'taxBase': net, 'gstAmount': gst},
            {'accountCode': '1200', 'debit': gst, 'credit': 0, 'description': 'Input GST'},
            {'accountCode': transaction.get('bankAccount') or '1000', 'debit': 0, 'credit': gross, 'description': description},
        ])
    elif amount > 0 and tax_code == 'SR9' and settings.get('gstRegistered') and rate:
        net = _accounting_money(gross / (1 + rate / 100))
        gst = _accounting_money(gross - net)
        lines.extend([
            {'accountCode': transaction.get('bankAccount') or '1000', 'debit': gross, 'credit': 0, 'description': description},
            {'accountCode': counter_account, 'debit': 0, 'credit': net, 'description': description, 'taxCode': 'SR9', 'taxBase': net, 'gstAmount': gst},
            {'accountCode': '2100', 'debit': 0, 'credit': gst, 'description': 'Output GST'},
        ])
    elif amount > 0:
        lines.extend([
            {'accountCode': transaction.get('bankAccount') or '1000', 'debit': gross, 'credit': 0, 'description': description},
            {'accountCode': counter_account, 'debit': 0, 'credit': gross, 'description': description, 'taxCode': tax_code},
        ])
    else:
        lines.extend([
            {'accountCode': counter_account, 'debit': gross, 'credit': 0, 'description': description, 'taxCode': tax_code},
            {'accountCode': transaction.get('bankAccount') or '1000', 'debit': 0, 'credit': gross, 'description': description},
        ])
    journal = _accounting_normalise_journal({
        'date': transaction.get('date'),
        'description': description,
        'reference': transaction.get('reference'),
        'status': 'posted',
        'sourceKey': f"bank:{transaction.get('id')}",
        'sourceType': 'bank-transaction',
        'lines': lines,
    }, store)
    store['journals'].append(journal)
    transaction['status'] = 'matched'
    transaction['journalId'] = journal['id']
    transaction['matchedAt'] = now_iso()
    transaction['matchedBy'] = _finance_current_username()
    return journal, transaction


def _accounting_period(request_args):
    today = datetime.now().date()
    default_start = today.replace(month=1, day=1).strftime('%Y-%m-%d')
    start = _accounting_date(request_args.get('from'), default_start)
    end = _accounting_date(request_args.get('to'), today.strftime('%Y-%m-%d'))
    if start > end:
        start, end = end, start
    return start, end


def _accounting_reports(store, start, end):
    account_map = _accounting_account_map(store)
    posted = [
        row for row in store.get('journals') or []
        if isinstance(row, dict) and row.get('status') == 'posted' and row.get('date') <= end
    ]
    period_journals = [row for row in posted if start <= row.get('date', '') <= end]
    balances = {code: 0.0 for code in account_map}
    period_balances = {code: 0.0 for code in account_map}
    transactions = []
    for journal in posted:
        for line in journal.get('lines') or []:
            code = str(line.get('accountCode') or '')
            net = _accounting_money(line.get('debit')) - _accounting_money(line.get('credit'))
            balances[code] = _accounting_money(balances.get(code, 0) + net)
            if start <= journal.get('date', '') <= end:
                period_balances[code] = _accounting_money(period_balances.get(code, 0) + net)
                transactions.append({
                    'journalId': journal.get('id'),
                    'number': journal.get('number'),
                    'date': journal.get('date'),
                    'description': line.get('description') or journal.get('description'),
                    'reference': journal.get('reference'),
                    'accountCode': code,
                    'accountName': (account_map.get(code) or {}).get('name') or code,
                    'debit': _accounting_money(line.get('debit')),
                    'credit': _accounting_money(line.get('credit')),
                    'taxCode': line.get('taxCode') or 'OP',
                    'contact': line.get('contact') or '',
                    'eventId': line.get('eventId'),
                })
    transactions.sort(key=lambda row: (row['date'], row['number'], row['accountCode']), reverse=True)
    trial_balance = []
    for code, account in sorted(account_map.items()):
        balance = _accounting_money(balances.get(code))
        if not balance:
            continue
        trial_balance.append({
            'code': code,
            'name': account.get('name'),
            'type': account.get('type'),
            'debit': balance if balance > 0 else 0.0,
            'credit': abs(balance) if balance < 0 else 0.0,
        })
    pnl_rows = []
    revenue_total = 0.0
    expense_total = 0.0
    for code, account in sorted(account_map.items()):
        account_type = account.get('type')
        raw = _accounting_money(period_balances.get(code))
        if account_type == 'revenue':
            amount = _accounting_money(-raw)
            revenue_total = _accounting_money(revenue_total + amount)
        elif account_type == 'expense':
            amount = raw
            expense_total = _accounting_money(expense_total + amount)
        else:
            continue
        if amount:
            pnl_rows.append({'code': code, 'name': account.get('name'), 'type': account_type, 'amount': amount})
    balance_sheet = {'assets': [], 'liabilities': [], 'equity': []}
    for code, account in sorted(account_map.items()):
        account_type = account.get('type')
        if account_type not in balance_sheet:
            continue
        raw = _accounting_money(balances.get(code))
        amount = raw if account_type == 'asset' else -raw
        if amount:
            balance_sheet[account_type].append({'code': code, 'name': account.get('name'), 'amount': amount})
    current_earnings = _accounting_money(revenue_total - expense_total)
    if current_earnings:
        balance_sheet['equity'].append({'code': 'CURRENT', 'name': 'Current period earnings', 'amount': current_earnings})
    gst = {f'box{number}': 0.0 for number in range(1, 18)}
    for journal in period_journals:
        for line in journal.get('lines') or []:
            code = str(line.get('taxCode') or 'OP').upper()
            base = _accounting_money(line.get('taxBase'))
            tax = _accounting_money(line.get('gstAmount'))
            if code == 'SR9':
                gst['box1'] = _accounting_money(gst['box1'] + base)
                gst['box6'] = _accounting_money(gst['box6'] + tax)
            elif code == 'ZR':
                gst['box2'] = _accounting_money(gst['box2'] + base)
            elif code == 'ES':
                gst['box3'] = _accounting_money(gst['box3'] + base)
            elif code in {'TX9', 'TX0'}:
                gst['box5'] = _accounting_money(gst['box5'] + base)
                if code == 'TX9':
                    gst['box7'] = _accounting_money(gst['box7'] + tax)
    gst['box4'] = _accounting_money(gst['box1'] + gst['box2'] + gst['box3'])
    gst['box8'] = _accounting_money(gst['box6'] - gst['box7'])
    gst['box13'] = revenue_total
    return {
        'transactions': transactions,
        'trialBalance': trial_balance,
        'profitLoss': {
            'rows': pnl_rows,
            'revenue': revenue_total,
            'expenses': expense_total,
            'netProfit': current_earnings,
        },
        'balanceSheet': balance_sheet,
        'gst': gst,
        'summary': {
            'cash': _accounting_money(balances.get('1000')),
            'receivables': _accounting_money(balances.get('1100')),
            'payables': _accounting_money(-balances.get('2000', 0)),
            'revenue': revenue_total,
            'expenses': expense_total,
            'netProfit': current_earnings,
            'gstPayable': gst['box8'],
        },
    }


def _accounting_payload(finance_data, request_args):
    store = _accounting_store(finance_data)
    start, end = _accounting_period(request_args)
    reports = _accounting_reports(store, start, end)
    sources = _accounting_source_documents(finance_data)
    bank_transactions = sorted(
        [row for row in store.get('bankTransactions') or [] if isinstance(row, dict)],
        key=lambda row: (row.get('date') or '', row.get('importedAt') or ''),
        reverse=True,
    )
    default_bank = str(store.get('settings', {}).get('defaultBankAccount') or '1000')
    statement_total = _accounting_money(sum(
        _accounting_money(row.get('amount'))
        for row in bank_transactions
        if row.get('bankAccount') == default_bank
        and start <= str(row.get('date') or '') <= end
    ))
    ledger_total = _accounting_money(sum(
        _accounting_money(row.get('debit')) - _accounting_money(row.get('credit'))
        for row in reports['transactions']
        if row.get('accountCode') == default_bank
    ))
    return {
        'period': {'from': start, 'to': end},
        'settings': store.get('settings') or {},
        'taxCodes': [
            {'code': code, **details}
            for code, details in ACCOUNTING_TAX_CODES.items()
        ],
        'accounts': sorted(
            [row for row in store.get('accounts') or [] if isinstance(row, dict)],
            key=lambda row: str(row.get('code') or ''),
        ),
        'journals': sorted(
            [row for row in store.get('journals') or [] if isinstance(row, dict)],
            key=lambda row: (row.get('date') or '', row.get('number') or ''),
            reverse=True,
        ),
        'sourceDocuments': sources,
        'unpostedCount': sum(1 for row in sources if not row.get('posted')),
        'bankTransactions': bank_transactions,
        'bankSummary': {
            'statementMovement': statement_total,
            'ledgerMovement': ledger_total,
            'difference': _accounting_money(statement_total - ledger_total),
            'unmatchedCount': sum(1 for row in bank_transactions if row.get('status') != 'matched'),
        },
        **reports,
    }


