@app.route('/api/finance/accounting/export.csv', methods=['GET'])
@require_super_admin
def accounting_export_csv():
    from io import StringIO

    report_name = str(request.args.get('report') or 'transactions').strip().lower()
    with _finance_lock:
        finance_data = _load_finance_data()
        payload = _accounting_payload(finance_data, request.args)
    output = StringIO()
    writer = csv.writer(output)
    if report_name == 'trial-balance':
        writer.writerow(['Account code', 'Account name', 'Type', 'Debit', 'Credit'])
        for row in payload['trialBalance']:
            writer.writerow([row['code'], row['name'], row['type'], row['debit'], row['credit']])
    elif report_name == 'profit-loss':
        writer.writerow(['Account code', 'Account name', 'Type', 'Amount'])
        for row in payload['profitLoss']['rows']:
            writer.writerow([row['code'], row['name'], row['type'], row['amount']])
        writer.writerow([])
        writer.writerow(['Net profit', payload['profitLoss']['netProfit']])
    elif report_name == 'balance-sheet':
        writer.writerow(['Section', 'Account code', 'Account name', 'Amount'])
        for section in ('assets', 'liabilities', 'equity'):
            for row in payload['balanceSheet'][section]:
                writer.writerow([section.title(), row['code'], row['name'], row['amount']])
    elif report_name == 'gst':
        writer.writerow(['GST return box', 'Amount (SGD)'])
        for number in range(1, 18):
            writer.writerow([f'Box {number}', payload['gst'][f'box{number}']])
    else:
        writer.writerow(['Date', 'Journal', 'Reference', 'Account code', 'Account name', 'Description', 'Contact', 'Event', 'Debit', 'Credit', 'GST code'])
        for row in payload['transactions']:
            writer.writerow([row['date'], row['number'], row['reference'], row['accountCode'], row['accountName'], row['description'], row['contact'], row['eventId'] or '', row['debit'], row['credit'], row['taxCode']])
    filename = f"accounting-{report_name}-{payload['period']['from']}-to-{payload['period']['to']}.csv"
    return Response(
        output.getvalue(),
        mimetype='text/csv',
        headers={'Content-Disposition': f'attachment; filename="{filename}"'},
    )


def _finance_compare_identity_key(identity):
    clean = {
        key: (
            _normalise_department_code(value)
            if key == 'department'
            else re.sub(r'\s+', ' ', str(value or '').strip()).casefold()
        )
        for key, value in (identity or {}).items()
        if key in {'kind', 'department', 'brand', 'model', 'name', 'type', 'company'}
    }
    return hashlib.sha1(
        json.dumps(clean, sort_keys=True, separators=(',', ':')).encode('utf-8')
    ).hexdigest()[:18]


def _finance_compare_model_identity(department='', brand='', model=''):
    return {
        'kind': 'model',
        'department': _normalise_department_code(department) or 'UN',
        'brand': str(brand or '').strip(),
        'model': str(model or '').strip(),
    }


def _finance_compare_custom_identity(asset_type='MISC', name='', department='UN', company=''):
    return {
        'kind': 'custom',
        'type': _normalise_custom_type(asset_type),
        'name': str(name or '').strip(),
        'department': _normalise_department_code(department) or 'UN',
        'company': str(company or '').strip(),
    }


def _finance_compare_department_name(code):
    code = _normalise_department_code(code) or 'UN'
    row = _load_departments().get(code)
    return str((row or {}).get('name') or code)


def _finance_compare_add_item(items, identity, quantity, details=None, line_id=None, ref=None):
    quantity = max(0, _safe_int(round(_safe_float(quantity, 0)), 0))
    if quantity <= 0:
        return
    key = _finance_compare_identity_key(identity)
    row = items.setdefault(key, {
        'key': key,
        'identity': dict(identity),
        'quantity': 0,
        'lineIds': [],
        'refs': [],
        'title': '',
        'subtitle': '',
        'department': '',
        'departmentCode': identity.get('department') or 'UN',
        'uom': 'units',
        'description': '',
    })
    row['quantity'] += quantity
    if line_id and line_id not in row['lineIds']:
        row['lineIds'].append(str(line_id))
    if ref and ref not in row['refs']:
        row['refs'].append(str(ref))
    for field, value in (details or {}).items():
        if value not in (None, '') and not row.get(field):
            row[field] = value


def _finance_compare_item_from_line(line):
    if not isinstance(line, dict) or _finance_line_is_non_prepare_department(line):
        return None
    quantity = max(0, _safe_int(round(_safe_float(line.get('quantity'), 0)), 0))
    if quantity <= 0:
        return None
    group = _finance_inventory_group_from_line(line)
    if group:
        identity = _finance_compare_model_identity(
            group.get('department'),
            group.get('brand'),
            group.get('model'),
        )
        title = _finance_display_description(
            group.get('brand'),
            group.get('model'),
            group.get('description'),
        ) or str(line.get('description') or '').strip()
        details = {
            'title': title,
            'subtitle': str(group.get('description') or '').strip(),
            'department': _finance_compare_department_name(group.get('department')),
            'departmentCode': group.get('department') or 'UN',
            'uom': str(line.get('uom') or 'units'),
            'description': str(group.get('description') or line.get('description') or '').strip(),
        }
        return identity, quantity, details
    description = str(line.get('description') or '').strip()
    if not description:
        return None
    department = _normalise_department_code(line.get('departmentCode')) or 'UN'
    identity = _finance_compare_custom_identity(
        line.get('customType') or 'MISC',
        description,
        department,
        line.get('customCompany') or '',
    )
    return identity, quantity, {
        'title': description,
        'subtitle': 'Custom item',
        'department': _finance_compare_department_name(department),
        'departmentCode': department,
        'uom': str(line.get('uom') or 'units'),
        'description': description,
    }


def _finance_compare_quote_items(document):
    items = {}
    for line in (document or {}).get('lineItems') or []:
        parsed = _finance_compare_item_from_line(line)
        if not parsed:
            continue
        identity, quantity, details = parsed
        _finance_compare_add_item(
            items,
            identity,
            quantity,
            details,
            line_id=(line or {}).get('id'),
        )
    return items


def _finance_compare_item_from_event_ref(ref):
    marker = _parse_model_marker(ref)
    if marker:
        identity = _finance_compare_model_identity(
            marker.get('department'),
            marker.get('brand'),
            marker.get('model'),
        )
        description = str(marker.get('description') or '').strip()
        return identity, max(1, _safe_int(marker.get('quantity'), 1)), {
            'title': _finance_display_description(marker.get('brand'), marker.get('model'), description),
            'subtitle': description,
            'department': _finance_compare_department_name(marker.get('department')),
            'departmentCode': marker.get('department') or 'UN',
            'uom': 'units',
            'description': description,
        }
    custom = _parse_custom_marker(ref)
    if custom:
        identity = _finance_compare_custom_identity(
            custom.get('type'),
            custom.get('name'),
            custom.get('department'),
            custom.get('company'),
        )
        return identity, max(1, _safe_int(custom.get('quantity'), 1)), {
            'title': str(custom.get('name') or '').strip(),
            'subtitle': str(custom.get('company') or custom.get('type') or 'Custom item'),
            'department': _finance_compare_department_name(custom.get('department')),
            'departmentCode': custom.get('department') or 'UN',
            'uom': 'units',
            'description': str(custom.get('name') or '').strip(),
        }
    bulk = _parse_bulk_marker(ref)
    if bulk:
        asset = data_manager.inventory.get(bulk.get('bulkId')) if data_manager else None
        quantity = max(1, _safe_int(bulk.get('quantity'), 1))
    else:
        asset = data_manager.inventory.get(str(ref or '')) if data_manager else None
        quantity = 1
    if not asset:
        return None
    group = _asset_group_from_item(asset)
    identity = _finance_compare_model_identity(
        group.get('department'),
        group.get('brand'),
        group.get('model'),
    )
    return identity, quantity, {
        'title': _finance_display_description(group.get('brand'), group.get('model'), group.get('description')),
        'subtitle': str(group.get('description') or '').strip(),
        'department': _finance_compare_department_name(group.get('department')),
        'departmentCode': group.get('department') or 'UN',
        'uom': 'units',
        'description': str(group.get('description') or '').strip(),
    }


def _finance_compare_event_items(event):
    items = {}
    for ref in getattr(event, 'prepared_items', []) or []:
        parsed = _finance_compare_item_from_event_ref(ref)
        if not parsed:
            continue
        identity, quantity, details = parsed
        _finance_compare_add_item(items, identity, quantity, details, ref=ref)
    return items


def _finance_compare_display_item(item):
    if not item:
        return {
            'key': '',
            'title': 'Not included',
            'subtitle': '',
            'department': '',
            'departmentCode': '',
            'quantity': 0,
            'uom': '',
            'identity': {},
            'lineIds': [],
            'refs': [],
        }
    return {
        'key': item.get('key') or _finance_compare_identity_key(item.get('identity') or {}),
        'title': item.get('title') or item.get('description') or 'Untitled item',
        'subtitle': item.get('subtitle') or '',
        'department': item.get('department') or _finance_compare_department_name(item.get('departmentCode')),
        'departmentCode': item.get('departmentCode') or (item.get('identity') or {}).get('department') or 'UN',
        'quantity': max(0, _safe_int(item.get('quantity'), 0)),
        'uom': item.get('uom') or 'units',
        'identity': item.get('identity') or {},
        'lineIds': item.get('lineIds') or [],
        'refs': item.get('refs') or [],
        'description': item.get('description') or '',
    }


def _finance_compare_rows(event, quotation):
    quote_items = _finance_compare_quote_items(quotation)
    event_items = _finance_compare_event_items(event)
    rows = []
    counts = {
        'matched': 0,
        'missingInEvent': 0,
        'extraInEvent': 0,
        'qtyMismatch': 0,
    }
    for key in sorted(set(quote_items) | set(event_items), key=lambda value: (
        (quote_items.get(value) or event_items.get(value) or {}).get('departmentCode', ''),
        (quote_items.get(value) or event_items.get(value) or {}).get('title', ''),
    )):
        quote_item = _finance_compare_display_item(quote_items.get(key))
        event_item = _finance_compare_display_item(event_items.get(key))
        quote_qty = quote_item.get('quantity') or 0
        event_qty = event_item.get('quantity') or 0
        if quote_qty and event_qty and quote_qty == event_qty:
            status = 'matched'
            counts['matched'] += 1
        elif quote_qty and not event_qty:
            status = 'missing_in_event'
            counts['missingInEvent'] += 1
        elif event_qty and not quote_qty:
            status = 'extra_in_event'
            counts['extraInEvent'] += 1
        else:
            status = 'qty_mismatch'
            counts['qtyMismatch'] += 1
        rows.append({
            'key': key,
            'status': status,
            'quotationItem': quote_item,
            'eventItem': event_item,
            'quantityDelta': event_qty - quote_qty,
        })
    return rows, counts, quote_items, event_items


def _finance_compare_can_read_quotation(document, event_id):
    if not document or document.get('type') != 'quotation':
        return False
    if _safe_int(document.get('eventId'), 0) != int(event_id):
        return False
    return _current_user_effective_is_admin() or _finance_user_can_access(document)


def _finance_compare_quotations_for_event(finance_data, event_id):
    rows = []
    for document in finance_data.get('documents') or []:
        if _finance_compare_can_read_quotation(document, event_id):
            normalised = _normalise_finance_document(document, 'quotation', document)
            rows.append({
                'id': normalised.get('id'),
                'number': normalised.get('number'),
                'projectName': normalised.get('projectName'),
                'client': normalised.get('client') or {},
                'updatedAt': normalised.get('updatedAt'),
            })
    rows.sort(key=lambda row: (row.get('updatedAt', ''), row.get('number', '')), reverse=True)
    return rows


def _finance_compare_payload(event, finance_data, quotation_id=''):
    quotation = None
    if quotation_id:
        candidate = _finance_find_document(finance_data, quotation_id, 'quotation')
        if candidate and _finance_compare_can_read_quotation(candidate, event.event_id):
            quotation = _normalise_finance_document(candidate, 'quotation', candidate)
    if quotation is None:
        candidates = [
            row for row in finance_data.get('documents') or []
            if _finance_compare_can_read_quotation(row, event.event_id)
        ]
        candidates.sort(key=lambda row: (row.get('updatedAt', ''), row.get('number', '')), reverse=True)
        if candidates:
            quotation = _normalise_finance_document(candidates[0], 'quotation', candidates[0])
    rows, counts, quote_items, event_items = _finance_compare_rows(event, quotation or {})
    return {
        'event': _finance_event_brief(event),
        'quotation': ({
            'id': quotation.get('id'),
            'number': quotation.get('number'),
            'projectName': quotation.get('projectName'),
            'client': quotation.get('client') or {},
        } if quotation else None),
        'quotations': _finance_compare_quotations_for_event(finance_data, event.event_id),
        'rows': rows,
        'counts': {
            **counts,
            'quotationItems': len(quote_items),
            'eventItems': len(event_items),
        },
        'permissions': {
            'canEditEvent': _current_user_effective_is_admin(),
            'canEditQuotation': bool(quotation and _current_user_has_sales_access() and _finance_user_can_access(quotation)),
        },
    }


def _finance_compare_row_for_action(event, document, row_key):
    rows, _counts, _quote_items, _event_items = _finance_compare_rows(event, document or {})
    return next((row for row in rows if row.get('key') == row_key), None)


def _finance_compare_ref_matches_identity(ref, identity):
    parsed = _finance_compare_item_from_event_ref(ref)
    if not parsed:
        return False
    ref_identity, _quantity, _details = parsed
    return _finance_compare_identity_key(ref_identity) == _finance_compare_identity_key(identity)


def _finance_compare_set_event_quantity(event, identity, target_quantity, display_item=None):
    target_quantity = max(0, _safe_int(round(_safe_float(target_quantity, 0)), 0))
    _ensure_event_custom_lists(event)
    kind = (identity or {}).get('kind')
    if kind == 'custom':
        matching_refs = {
            ref for ref in list(event.prepared_items or [])
            if _finance_compare_ref_matches_identity(ref, identity)
        }
        event.prepared_items = [
            ref for ref in event.prepared_items
            if ref not in matching_refs
        ]
        event.actually_prepared = [
            ref for ref in event.actually_prepared
            if ref not in matching_refs
        ]
        event.returned_items = [
            ref for ref in event.returned_items
            if ref not in matching_refs
        ]
        event.extra_assets = [
            ref for ref in event.extra_assets
            if ref not in matching_refs
        ]
        event.custom_collected = [
            ref for ref in event.custom_collected
            if ref not in matching_refs
        ]
        if target_quantity > 0:
            event.prepared_items.append(_make_custom_marker(
                identity.get('type') or 'MISC',
                identity.get('name') or (display_item or {}).get('title') or 'Custom item',
                target_quantity,
                identity.get('department') or 'UN',
                identity.get('company') or '',
            ))
        return

    matching_physical_refs = set()
    for ref in list(event.prepared_items or []):
        if _finance_compare_ref_matches_identity(ref, identity):
            matching_physical_refs.add(ref)
    for ref in list(event.extra_assets or []):
        if _finance_compare_ref_matches_identity(ref, identity):
            matching_physical_refs.add(ref)
    event.prepared_items = [
        ref for ref in event.prepared_items
        if ref not in matching_physical_refs
    ]
    if target_quantity > 0:
        group = {
            'department': identity.get('department') or 'UN',
            'brand': identity.get('brand') or '',
            'model': identity.get('model') or '',
            'description': (display_item or {}).get('description') or (display_item or {}).get('subtitle') or '',
        }
        event.prepared_items.append(_make_model_marker(group, target_quantity))
    if target_quantity == 0:
        event.actually_prepared = [
            ref for ref in event.actually_prepared
            if ref not in matching_physical_refs
        ]
        event.returned_items = [
            ref for ref in event.returned_items
            if ref not in matching_physical_refs
        ]
        event.extra_assets = [
            ref for ref in event.extra_assets
            if ref not in matching_physical_refs
        ]


def _finance_compare_add_to_event(event, row):
    quote_item = row.get('quotationItem') or {}
    event_item = row.get('eventItem') or {}
    quote_qty = max(0, _safe_int(quote_item.get('quantity'), 0))
    event_qty = max(0, _safe_int(event_item.get('quantity'), 0))
    if quote_qty <= event_qty:
        raise ValueError('This item is already covered in the event')
    identity = quote_item.get('identity') or {}
    if not identity:
        raise ValueError('Quotation item cannot be added to the event')
    if identity.get('kind') == 'custom':
        event.prepared_items.append(_make_custom_marker(
            identity.get('type') or 'MISC',
            identity.get('name') or quote_item.get('title') or 'Custom item',
            quote_qty - event_qty,
            identity.get('department') or quote_item.get('departmentCode') or 'UN',
            identity.get('company') or '',
        ))
    else:
        _add_or_increment_model_marker(event.prepared_items, {
            'department': identity.get('department') or quote_item.get('departmentCode') or 'UN',
            'brand': identity.get('brand') or '',
            'model': identity.get('model') or '',
            'description': quote_item.get('description') or quote_item.get('subtitle') or '',
        }, quote_qty - event_qty)


def _finance_compare_line_from_event_item(event_item, quantity, event, finance_data=None):
    identity = event_item.get('identity') or {}
    department_name, department_code = _finance_department_details(
        event_item.get('departmentCode') or identity.get('department') or 'UN',
        event_item.get('departmentCode') or identity.get('department') or 'UN',
    )
    days = _finance_date_days(
        _event_date_for_input(getattr(event, 'start_date', '')),
        _event_date_for_input(getattr(event, 'end_date', '')),
    )
    raw_description = event_item.get('description') or event_item.get('title') or 'Event item'
    description = str(raw_description).strip()
    remembered = {}
    if identity.get('kind') == 'custom':
        for document in reversed((finance_data or {}).get('documents') or []):
            remembered = next((
                line for line in reversed(document.get('lineItems') or [])
                if str(line.get('description') or '').strip().casefold() == description.casefold()
                and _safe_float(line.get('unitPrice'), 0) > 0
            ), {})
            if remembered:
                break
        return _normalise_finance_line({
            'id': secrets.token_hex(6),
            'catalogKey': '',
            'description': description,
            'department': department_name,
            'departmentCode': department_code,
            'days': days,
            'quantity': quantity,
            'uom': event_item.get('uom') or 'units',
            'unitPrice': _safe_float(remembered.get('unitPrice'), 0),
            'discountPercent': 0,
            'isCustom': True,
            'customType': identity.get('type') or 'MISC',
            'customCompany': identity.get('company') or '',
        })
    brand = identity.get('brand') or ''
    model = identity.get('model') or ''
    description = _finance_display_description(brand, model, description)
    catalog_key = _finance_catalog_key(department_code, brand, model, description)
    remembered = _finance_remembered_price(
        (finance_data or {}).get('priceBook') or {},
        catalog_key,
        event_item.get('sourceAssetIds') or [],
    )
    return _normalise_finance_line({
        'id': secrets.token_hex(6),
        'catalogKey': catalog_key,
        'sourceAssetIds': [],
        'brand': brand,
        'model': model,
        'description': description,
        'department': department_name,
        'departmentCode': department_code,
        'days': days,
        'quantity': quantity,
        'uom': 'units',
        'unitPrice': _safe_float(remembered.get('unitPrice'), 0),
        'discountPercent': 0,
        'isCustom': False,
    })


def _finance_compare_apply_to_quotation(finance_data, quotation, event, row):
    event_item = row.get('eventItem') or {}
    quote_item = row.get('quotationItem') or {}
    event_qty = max(0, _safe_int(event_item.get('quantity'), 0))
    quote_qty = max(0, _safe_int(quote_item.get('quantity'), 0))
    delta = event_qty - quote_qty
    if delta <= 0:
        raise ValueError('The quotation already covers this item')
    line_ids = quote_item.get('lineIds') or []
    if line_ids:
        target_line_id = str(line_ids[0])
        for line in quotation.get('lineItems') or []:
            if str(line.get('id')) == target_line_id:
                line['quantity'] = round(_safe_float(line.get('quantity'), 0) + delta, 4)
                identity = event_item.get('identity') or {}
                if identity.get('kind') == 'model':
                    brand = str(identity.get('brand') or '').strip()
                    model = str(identity.get('model') or '').strip()
                    raw_description = str(
                        event_item.get('description')
                        or event_item.get('subtitle')
                        or line.get('description')
                        or ''
                    ).strip()
                    description = _finance_display_description(
                        brand, model, raw_description
                    )
                    department_code = _normalise_department_code(
                        event_item.get('departmentCode')
                        or identity.get('department')
                        or line.get('departmentCode')
                    ) or 'UN'
                    department_name, department_code = _finance_department_details(
                        event_item.get('department') or department_code,
                        department_code,
                    )
                    line.update({
                        'brand': brand,
                        'model': model,
                        'description': description,
                        'department': department_name,
                        'departmentCode': department_code,
                        'catalogKey': _finance_catalog_key(
                            department_code, brand, model, description
                        ),
                        'isCustom': False,
                    })
                break
    else:
        quotation.setdefault('lineItems', []).append(
            _finance_compare_line_from_event_item(
                event_item, delta, event, finance_data
            )
        )


def _finance_compare_add_to_quotation(finance_data, quotation, event, row):
    previous = copy.deepcopy(quotation)
    _finance_compare_apply_to_quotation(finance_data, quotation, event, row)
    updated = _normalise_finance_document(quotation, 'quotation', quotation)
    _remember_finance_prices(finance_data, updated, previous)
    for index, document in enumerate(finance_data.get('documents') or []):
        if str(document.get('id')) == str(updated.get('id')):
            finance_data['documents'][index] = updated
            return updated
    raise LookupError('Quotation not found')


def _finance_list_or_create(document_type):
    with _finance_lock:
        finance_data = _load_finance_data()
        if _finance_expire_sent_documents(finance_data):
            _save_finance_data(finance_data)
        if request.method == 'GET':
            query = str(request.args.get('query') or '').strip().lower()
            mine_only = str(request.args.get('mine') or '').strip().lower() in {
                '1', 'true', 'yes', 'on',
            }
            linked_invoices = {}
            for document in finance_data.get('documents') or []:
                if document.get('type') != 'invoice':
                    continue
                quotation_id = str(document.get('sourceQuotationId') or '').strip()
                if quotation_id and _finance_user_can_access(document):
                    linked_invoices[quotation_id] = document
            rows = [
                _normalise_finance_document(row, document_type, row)
                for row in finance_data.get('documents') or []
                if row.get('type') == document_type and _finance_user_can_access(row)
            ]
            if mine_only:
                current_username = _finance_current_username().lower()
                rows = [
                    row for row in rows
                    if _finance_document_owner_username(row).lower() == current_username
                ]
            if document_type == 'quotation':
                for row in rows:
                    invoice = linked_invoices.get(str(row.get('id') or ''))
                    row['invoiceId'] = str((invoice or {}).get('id') or '')
                    row['invoiceNumber'] = str((invoice or {}).get('number') or '')
                    event = data_manager.events.get(_safe_int(row.get('eventId'), 0))
                    row['eventState'] = str(getattr(event, 'state', '') or '')
                    row['eventName'] = str(getattr(event, 'name', '') or '')
                    row['eventMissing'] = bool(row.get('eventId') and not event)
            if query:
                rows = [
                    row for row in rows
                    if query in ' '.join((
                        row.get('number', ''),
                        row.get('title', ''),
                        row.get('reference', ''),
                        row.get('invoiceNumber', ''),
                        row.get('eventState', ''),
                        row.get('eventName', ''),
                        row.get('salesperson', ''),
                        row.get('createdBy', ''),
                        (row.get('client') or {}).get('name', ''),
                        (row.get('client') or {}).get('company', ''),
                    )).lower()
                ]
            rows.sort(key=lambda row: (row.get('updatedAt', ''), row.get('number', '')), reverse=True)
            return jsonify({'success': True, 'data': rows})

        document = _normalise_finance_document(request.get_json() or {}, document_type)
        document['number'] = _next_finance_number(finance_data.get('documents') or [], document_type)
        if document_type == 'quotation':
            _prefix, year, sequence, revision = _finance_parse_number(document['number'])
            document['baseSequence'] = sequence
            document['revision'] = revision
            document['number'] = _finance_format_number(
                str(_load_pdf_settings().get('quotationPrefix') or 'QT').upper(),
                year,
                sequence,
                revision,
            )
        _remember_finance_prices(finance_data, document)
        finance_data.setdefault('documents', []).append(document)
        _save_finance_data(finance_data)
        log_action(f"Created {document_type} {document['number']}")
        return jsonify({'success': True, 'data': document}), 201


def _finance_get_update_delete(document_id, document_type):
    with _finance_lock:
        finance_data = _load_finance_data()
        if _finance_expire_sent_documents(finance_data):
            _save_finance_data(finance_data)
        existing = _finance_find_document(finance_data, document_id, document_type)
        if not existing or not _finance_user_can_access(existing):
            return jsonify({'error': f'{document_type.title()} not found'}), 404
        if request.method == 'GET':
            return jsonify({'success': True, 'data': _normalise_finance_document(existing, document_type, existing)})
        if request.method == 'DELETE':
            finance_data['documents'] = [
                row for row in finance_data.get('documents') or []
                if str(row.get('id')) != str(document_id)
            ]
            _save_finance_data(finance_data)
            log_action(f"Deleted {document_type} {existing.get('number', document_id)}")
            return jsonify({'success': True})

        request_data = request.get_json() or {}
        raw_requested_status = str(request_data.get('status') or '').strip().lower()
        if document_type == 'quotation' and raw_requested_status == 'declined':
            return jsonify({'error': 'Declined is no longer a quotation status'}), 400
        if (
            document_type == 'quotation'
            and raw_requested_status == 'expired'
            and str(existing.get('status') or '').strip().lower() != 'expired'
        ):
            return jsonify({'error': 'Expired status is set automatically'}), 400
        updated = _normalise_finance_document(request_data, document_type, existing)
        previous_document = _normalise_finance_document(
            existing,
            document_type,
            existing,
        )
        if any(
            str(row.get('id')) != str(document_id)
            and row.get('type') == document_type
            and str(row.get('number') or '').strip().casefold() == str(updated.get('number') or '').strip().casefold()
            for row in finance_data.get('documents') or []
            if isinstance(row, dict)
        ):
            return jsonify({'error': f'{document_type.title()} number is already in use'}), 409
        if document_type == 'quotation':
            status_workflow_fields = {'status'}
            if raw_requested_status == 'sent':
                status_workflow_fields.update({
                    'validityAmount', 'validityUnit', 'validityDays',
                })
            elif raw_requested_status == 'invoiced':
                status_workflow_fields.update({
                    'invoiceSentDate', 'paymentTerms',
                    'paymentTermDays', 'paymentDueDate',
                })
            status_workflow_only = (
                raw_requested_status in FINANCE_QUOTATION_STATUSES
                and set(request_data).issubset(status_workflow_fields)
            )
            missing_link_cleared = False
            if updated.get('eventId') and ('eventId' in request_data or str(request_data.get('status') or '').strip().lower() == 'accepted'):
                linked_event = data_manager.events.get(_safe_int(updated.get('eventId'), 0))
                if not linked_event:
                    _finance_clear_event_link(updated)
                    missing_link_cleared = True
                elif not _current_user_can_access_event(linked_event):
                    return jsonify({'error': 'You are not assigned to this event'}), 403

            existing_normalised = previous_document
            content_changed = (
                _finance_revision_fingerprint(updated)
                != _finance_revision_fingerprint(existing_normalised)
            )
            revision_locked = (
                existing_normalised.get('status') == 'sent'
                or _finance_revision_is_snapshotted(existing_normalised)
            )
            if content_changed and revision_locked and not status_workflow_only:
                if _safe_int(existing_normalised.get('revision'), 1) >= 99:
                    return jsonify({
                        'error': 'This quotation has reached the maximum of 99 revisions'
                    }), 409
                updated['revision'] = _safe_int(existing_normalised.get('revision'), 1) + 1
                if updated.get('customNumber'):
                    updated['number'] = _finance_number_with_revision(
                        existing_normalised.get('number'),
                        updated['revision'],
                    )
                else:
                    prefix, year, sequence, _revision = _finance_parse_number(
                        existing_normalised.get('number')
                    )
                    updated['number'] = _finance_format_number(
                        prefix,
                        year,
                        sequence,
                        updated['revision'],
                    )
                updated['status'] = 'draft'
                updated['sentAt'] = ''

            requested_status = str(request_data.get('status') or '').strip().lower()
            if requested_status == 'sent' and updated.get('status') == 'sent':
                sent_at = datetime.now()
                updated['sentAt'] = sent_at.isoformat(timespec='seconds')
                updated['statusChangedAt'] = updated['sentAt']
                updated['validUntil'] = (
                    sent_at + timedelta(days=max(1, _safe_int(updated.get('validityDays'), 30)))
                ).strftime('%Y-%m-%d')
                _finance_snapshot_revision(updated)
            elif requested_status == 'accepted' and updated.get('status') == 'accepted':
                export_error = _finance_export_error(updated)
                if export_error:
                    return jsonify({'error': export_error}), 400
                updated['acceptedAt'] = (
                    updated.get('acceptedAt')
                    if existing_normalised.get('status') == 'accepted' and updated.get('acceptedAt')
                    else datetime.now().isoformat(timespec='seconds')
                )
                updated['statusChangedAt'] = updated['acceptedAt']
                if (
                    existing_normalised.get('status') == 'draft'
                    and not _finance_revision_is_snapshotted(updated)
                ):
                    _finance_snapshot_revision(updated)
                if not missing_link_cleared:
                    _finance_create_event(updated)
            elif requested_status == 'invoiced' and updated.get('status') == 'invoiced':
                invoice_sent_date = str(
                    request_data.get('invoiceSentDate')
                    or updated.get('invoiceSentDate')
                    or datetime.now().strftime('%Y-%m-%d')
                )[:10]
                try:
                    invoice_sent = datetime.strptime(invoice_sent_date, '%Y-%m-%d')
                except ValueError:
                    return jsonify({'error': 'Enter a valid invoice sent date'}), 400
                payment_terms = str(
                    request_data.get('paymentTerms')
                    if 'paymentTerms' in request_data
                    else updated.get('paymentTerms')
                    or _load_pdf_settings().get('defaultPaymentTerms', '30 Days')
                ).strip()[:300]
                payment_due_date, payment_term_days = _finance_payment_due_date(
                    invoice_sent_date,
                    payment_terms,
                )
                updated['paymentTerms'] = payment_terms
                updated['paymentTermDays'] = payment_term_days
                updated['invoiceSentDate'] = invoice_sent_date
                updated['paymentDueDate'] = payment_due_date
                updated['invoicedAt'] = invoice_sent.isoformat(timespec='seconds')
                updated['statusChangedAt'] = updated['invoicedAt']
            elif requested_status == 'paid' and updated.get('status') == 'paid':
                updated['paidAt'] = (
                    updated.get('paidAt')
                    if existing_normalised.get('status') == 'paid' and updated.get('paidAt')
                    else datetime.now().isoformat(timespec='seconds')
                )
                updated['statusChangedAt'] = updated['paidAt']
            elif requested_status in FINANCE_QUOTATION_STATUSES:
                updated['statusChangedAt'] = datetime.now().isoformat(timespec='seconds')
            elif updated.get('eventId'):
                _finance_sync_managed_event(updated)
            if updated.get('status') in {'draft', 'sent'} and updated.get('eventId'):
                _finance_sync_managed_event(updated)

        for index, row in enumerate(finance_data.get('documents') or []):
            if str(row.get('id')) == str(document_id):
                finance_data['documents'][index] = updated
                break
        _remember_finance_prices(finance_data, updated, previous_document)
        _save_finance_data(finance_data)
        if document_type == 'quotation':
            previous_status = str(existing_normalised.get('status') or 'draft')
            current_status = str(updated.get('status') or 'draft')
            previous_revision = _safe_int(existing_normalised.get('revision'), 1)
            current_revision = _safe_int(updated.get('revision'), 1)
            significant_changes = []
            if current_revision != previous_revision:
                significant_changes.append(
                    f"created version {current_revision:02d} from version {previous_revision:02d}"
                )
            if current_status != previous_status:
                significant_changes.append(
                    f"status changed from {previous_status.title()} to {current_status.title()}"
                )
            if significant_changes:
                log_action(
                    f"Updated quotation {updated['number']}: "
                    f"{'; '.join(significant_changes)}"
                )
        else:
            log_action(f"Updated {document_type} {updated['number']}")
        return jsonify({'success': True, 'data': updated})


@app.route('/api/finance/catalog', methods=['GET'])
@require_sales
def finance_catalog():
    query = str(request.args.get('query') or '').strip().lower()
    with _finance_lock:
        finance_data = _load_finance_data()
        price_book = finance_data.get('priceBook') or {}
        finance_documents = list(finance_data.get('documents') or [])

    department_cache = {}

    def catalog_department(value, code_hint=''):
        cache_key = (str(value or ''), str(code_hint or ''))
        if cache_key not in department_cache:
            department_cache[cache_key] = _finance_department_details(value, code_hint)
        return department_cache[cache_key]

    grouped = {}
    for asset in data_manager.inventory.values():
        if _is_disposed(asset):
            continue
        department_code = _normalise_department_code(getattr(asset, 'department_code', 'UN')) or 'UN'
        department, department_code = catalog_department(
            department_code,
            department_code,
        )
        brand = str(getattr(asset, 'brand', '') or '').strip()
        model = str(getattr(asset, 'model_number', '') or '').strip()
        description = str(getattr(asset, 'description', '') or '').strip()
        display = ' '.join(value for value in (brand, model, description) if value)
        tag_text = ' '.join(normalize_asset_tags(getattr(asset, 'tags', [])))
        haystack = f"{display} {department} {department_code} {tag_text}".lower()
        if query and query not in haystack:
            continue
        key = _finance_catalog_key(department_code, brand, model, description)
        if key not in grouped:
            grouped[key] = {
                'catalogKey': key,
                'description': display or model or description or 'Inventory item',
                'department': department,
                'departmentCode': department_code,
                'brand': brand,
                'model': model,
                'availableQuantity': 0,
                'sourceAssetIds': [],
                'unitPrice': 0,
                'uom': 'units',
                'isCustom': False,
            }
        grouped[key]['sourceAssetIds'].append(asset.asset_id)
        grouped[key]['availableQuantity'] += _asset_inventory_quantity(asset)

    for container in getattr(data_manager, 'containers', {}).values():
        container_id = str(getattr(container, 'container_id', '') or '').strip()
        if not container_id:
            continue
        serial_number = _container_serial_number(container)
        container_items = {}
        haystack_parts = [container_id, serial_number]
        for asset_id in getattr(container, 'asset_ids', []) or []:
            asset = data_manager.inventory.get(asset_id)
            if not asset or _is_disposed(asset):
                continue
            department_code = _normalise_department_code(getattr(asset, 'department_code', 'UN')) or 'UN'
            department, department_code = catalog_department(department_code, department_code)
            brand = str(getattr(asset, 'brand', '') or '').strip()
            model = str(getattr(asset, 'model_number', '') or '').strip()
            description = str(getattr(asset, 'description', '') or '').strip()
            display = _finance_display_description(brand, model, description) or model or description or asset_id
            haystack_parts.extend(normalize_asset_tags(getattr(asset, 'tags', [])))
            key = _finance_catalog_key(department_code, brand, model, description)
            if key not in container_items:
                container_items[key] = {
                    'catalogKey': key,
                    'description': display or 'Container item',
                    'department': department,
                    'departmentCode': department_code,
                    'brand': brand,
                    'model': model,
                    'availableQuantity': 0,
                    'sourceAssetIds': [],
                    'unitPrice': 0,
                    'uom': 'units',
                    'isCustom': False,
                    'containerId': container_id,
                    'containerSerial': serial_number,
                    'containerQuantity': 0,
                }
            container_items[key]['sourceAssetIds'].append(asset_id)
            quantity = _asset_inventory_quantity(asset)
            container_items[key]['availableQuantity'] += quantity
            container_items[key]['containerQuantity'] += quantity

        if not container_items:
            continue
        if query and query not in ' '.join(haystack_parts).lower():
            continue
        item_rows = sorted(
            container_items.values(),
            key=lambda row: (row['department'], row['description'].lower()),
        )
        for row in item_rows:
            remembered = _finance_remembered_price(
                price_book,
                row['catalogKey'],
                row['sourceAssetIds'],
            )
            row['unitPrice'] = _safe_float(remembered.get('unitPrice'), 0)
            row['uom'] = remembered.get('uom') if remembered.get('uom') in ('units', 'pax', 'lot', 'sqm') else 'units'
        grouped[f"container:{container_id.lower()}"] = {
            'catalogKey': f"container:{container_id}",
            'description': f"Container {container_id}",
            'department': 'Container',
            'departmentCode': 'CONTAINER',
            'brand': '',
            'model': '',
            'availableQuantity': sum(_safe_float(row.get('containerQuantity'), 0) for row in item_rows),
            'sourceAssetIds': [],
            'unitPrice': 0,
            'uom': 'units',
            'isCustom': False,
            'isContainer': True,
            'containerId': container_id,
            'containerSerial': serial_number,
            'containerItems': item_rows,
        }

    custom_seen = set()
    for document in finance_documents:
        if document.get('type') != 'quotation' or not _finance_user_can_access(document):
            continue
        for source in document.get('lineItems') or []:
            if not isinstance(source, dict) or not source.get('isCustom'):
                continue
            description = str(source.get('description') or '').strip()
            if not description:
                continue
            department, department_code = catalog_department(
                source.get('department'),
                source.get('departmentCode'),
            )
            if query and query not in f"{description} {department}".lower():
                continue
            custom_key = _finance_custom_price_key(description)
            if custom_key in custom_seen:
                continue
            custom_seen.add(custom_key)
            grouped[f"custom:{len(custom_seen)}"] = {
                'catalogKey': '',
                'description': description,
                'department': department,
                'departmentCode': department_code,
                'brand': '',
                'model': '',
                'availableQuantity': None,
                'sourceAssetIds': [],
                'unitPrice': _safe_float(source.get('unitPrice'), 0),
                'uom': source.get('uom') if source.get('uom') in ('units', 'pax', 'lot', 'sqm') else 'units',
                'isCustom': True,
            }

    rows = sorted(
        grouped.values(),
        key=lambda row: (
            0 if row.get('isContainer') else 1,
            row['department'],
            row['description'].lower(),
        ),
    )[:30]
    for row in rows:
        if row.get('isCustom') or row.get('isContainer'):
            continue
        remembered = _finance_remembered_price(
            price_book,
            row['catalogKey'],
            row['sourceAssetIds'],
        )
        row['unitPrice'] = _safe_float(remembered.get('unitPrice'), 0)
        row['uom'] = remembered.get('uom') if remembered.get('uom') in ('units', 'pax', 'lot', 'sqm') else 'units'
    return jsonify({'success': True, 'data': rows})


@app.route('/api/finance/rate-card', methods=['GET', 'POST', 'DELETE'])
@require_sales
def finance_rate_card():
    with _finance_lock:
        finance_data = _load_finance_data()
        if request.method == 'GET':
            query = str(request.args.get('query') or '').strip().casefold()
            rows = _finance_rate_card_rows(finance_data)
            if query:
                rows = [
                    row for row in rows
                    if query in ' '.join((
                        str(row.get('department') or ''),
                        str(row.get('brand') or ''),
                        str(row.get('model') or ''),
                        str(row.get('description') or ''),
                        ' '.join(normalize_asset_tags(row.get('searchTags') or [])),
                    )).casefold()
                ]
            return jsonify({'success': True, 'data': rows[:500]})

        payload = request.get_json(silent=True) or {}
        description = str(payload.get('description') or '').strip()[:1000]
        department, department_code = _finance_department_details(
            payload.get('department'), payload.get('departmentCode')
        )
        if not description:
            return jsonify({'error': 'Description is required'}), 400
        catalog_key = str(payload.get('catalogKey') or '').strip()[:500]
        if not catalog_key:
            catalog_key = _finance_custom_price_key(description)
        matched_assets = []
        if payload.get('brand') and payload.get('model'):
            target_department = _normalise_department_code(
                payload.get('departmentCode') or payload.get('department')
            )
            target_brand = str(payload.get('brand') or '').strip().casefold()
            target_model = str(payload.get('model') or '').strip().casefold()
            matched_assets = [
                (asset_id, asset)
                for asset_id, asset in (data_manager.inventory.items() if data_manager else [])
                if asset and not _is_disposed(asset)
                and _normalise_department_code(getattr(asset, 'department_code', '')) == target_department
                and str(getattr(asset, 'brand', '') or '').strip().casefold() == target_brand
                and str(getattr(asset, 'model_number', '') or '').strip().casefold() == target_model
            ]
        if matched_assets:
            _, canonical_asset = matched_assets[0]
            canonical_department, canonical_department_code = _finance_department_details(
                getattr(canonical_asset, 'department_code', ''),
                getattr(canonical_asset, 'department_code', ''),
            )
            payload = {
                **payload,
                'brand': str(getattr(canonical_asset, 'brand', '') or '').strip(),
                'model': str(getattr(canonical_asset, 'model_number', '') or '').strip(),
                'description': str(getattr(canonical_asset, 'description', '') or '').strip(),
                'department': canonical_department,
                'departmentCode': canonical_department_code,
                'sourceAssetIds': [str(asset_id) for asset_id, _ in matched_assets],
            }
            description = payload['description']
            catalog_key = _finance_catalog_key(
                canonical_department_code,
                payload['brand'],
                payload['model'],
                description,
            )
        owner = _finance_current_username().lower()
        price_book = finance_data.setdefault('priceBook', {})
        owner_prefix = f'{owner}::'
        target_key = f'{owner_prefix}{catalog_key}'
        source_asset_ids = {
            str(asset_id).strip().lower()
            for asset_id in (payload.get('sourceAssetIds') or [])
            if str(asset_id or '').strip()
        }

        if request.method == 'DELETE':
            for stored_key in list(price_book):
                if stored_key.lower() == target_key.lower() or (
                    stored_key.lower().startswith(f'{owner_prefix}asset:')
                    and stored_key.rsplit(':', 1)[-1].lower() in source_asset_ids
                ):
                    price_book.pop(stored_key, None)
            price_book[target_key] = {
                'deleted': True,
                'description': description,
                'department': str(payload.get('department') or 'Unknown Department').strip(),
                'departmentCode': str(payload.get('departmentCode') or '').strip(),
                'brand': str(payload.get('brand') or '').strip()[:240],
                'model': str(payload.get('model') or '').strip()[:240],
                'owner': owner,
                'updatedAt': datetime.now().isoformat(timespec='seconds'),
            }
            _save_finance_data(finance_data)
            rows = _finance_rate_card_rows(finance_data)
            action = f"Deleted rate card item {description}"
        else:
            unit_price = round(max(0, _safe_float(payload.get('unitPrice'), 0)), 2)
            if unit_price <= 0:
                return jsonify({'error': 'Rate must be greater than zero'}), 400
            uom = str(payload.get('uom') or 'units').strip().lower()
            if uom not in {'units', 'pax', 'lot', 'sqm'}:
                uom = 'units'
            department, department_code = _finance_department_details(
                payload.get('department'), payload.get('departmentCode')
            )
            stored = {
                'description': description,
                'department': department,
                'departmentCode': department_code,
                'brand': str(payload.get('brand') or '').strip()[:240],
                'model': str(payload.get('model') or '').strip()[:240],
                'unitPrice': unit_price,
                'uom': uom,
                'owner': owner,
                'updatedAt': datetime.now().isoformat(timespec='seconds'),
            }
            for stored_key in list(price_book):
                if stored_key.lower() == target_key.lower():
                    price_book.pop(stored_key, None)
            price_book[target_key] = stored
            for asset_id in source_asset_ids:
                price_book[f'{owner_prefix}asset:{asset_id}'] = stored
            _save_finance_data(finance_data)
            rows = _finance_rate_card_rows(finance_data)
            action = f"Updated rate card item {description}"

    log_action(action)
    return jsonify({'success': True, 'data': rows})


@app.route('/api/finance/price-suggestion', methods=['GET'])
@require_sales
def finance_price_suggestion():
    description = str(request.args.get('description') or '').strip()
    remembered = {}
    with _finance_lock:
        finance_data = _load_finance_data()
        for document in reversed(finance_data.get('documents') or []):
            if document.get('type') != 'quotation' or not _finance_user_can_access(document):
                continue
            remembered = next(
                (
                    _normalise_finance_line(row)
                    for row in reversed(document.get('lineItems') or [])
                    if str(row.get('description') or '').strip().lower() == description.lower()
                ),
                {},
            )
            if remembered:
                break
    return jsonify({'success': True, 'data': remembered or {}})


@app.route('/api/finance/profit-loss/<int:event_id>', methods=['GET'])
@require_auth
def finance_profit_loss_event(event_id):
    event = data_manager.events.get(event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    if not _current_user_can_access_event(event):
        return _event_access_denied_response()
    with _finance_lock:
        finance_data = _load_finance_data()
        permissions = _finance_profit_loss_access(finance_data, event_id)
        payload = (
            _finance_profit_loss_payload(event, finance_data)
            if permissions['canViewFinancials']
            else {
                'event': _finance_event_brief(event),
                'censored': True,
            }
        )
        payload['permissions'] = permissions
    return jsonify({'success': True, 'data': payload})


@app.route('/api/finance/profit-loss/<int:event_id>/revenue', methods=['PUT'])
@require_auth
def finance_profit_loss_update_revenue(event_id):
    event = data_manager.events.get(event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    if not _current_user_can_access_event(event):
        return _event_access_denied_response()

    request_data = request.get_json(silent=True) or {}
    quotation_id = str(request_data.get('quotationId') or '').strip()
    has_manual_amount = 'manualAmount' in request_data
    if bool(quotation_id) == bool(has_manual_amount):
        return jsonify({'error': 'Choose a quotation or enter a manual amount'}), 400

    with _finance_lock:
        finance_data = _load_finance_data()
        permissions = _finance_profit_loss_access(finance_data, event_id)
        linked_quotations = _finance_quotations_for_event(
            finance_data,
            event_id,
            accessible_only=False,
        )
        store = _finance_profit_loss_store(finance_data)
        manual_values = store.setdefault('manualRevenue', {})
        event_key = str(event_id)

        if quotation_id:
            quotation = _finance_find_document(finance_data, quotation_id, 'quotation')
            if not quotation or not _finance_profit_loss_can_use_quotation(quotation):
                return jsonify({'error': 'Quotation not found'}), 404
            linked_event_id = _safe_int(quotation.get('eventId'), 0)
            if linked_event_id and linked_event_id != event_id:
                return jsonify({'error': f'Quotation is already paired to Event #{linked_event_id}'}), 409
            if any(str(row.get('id')) != quotation_id for row in linked_quotations):
                return jsonify({'error': 'This event already has a paired quotation'}), 409

            updated = _normalise_finance_document(
                {'eventId': event_id},
                'quotation',
                quotation,
            )
            for index, document in enumerate(finance_data.get('documents') or []):
                if str(document.get('id')) == quotation_id:
                    finance_data['documents'][index] = updated
                    break
            manual_values.pop(event_key, None)
            action = f"Paired quotation {updated.get('number') or quotation_id} to event {event_id} for Profit and Loss"
            realtime_action = 'profit-loss-quotation-paired'
            realtime_quotation_id = quotation_id
        else:
            if not permissions['canEditFinancials']:
                return _finance_profit_loss_expense_access_denied()
            if linked_quotations:
                return jsonify({'error': 'This event already has a paired quotation'}), 409
            amount = money(request_data.get('manualAmount'), None)
            if amount is None:
                return jsonify({'error': 'Enter a valid revenue amount'}), 400
            manual_values[event_key] = {
                'amount': amount,
                'updatedAt': now_iso(),
                'updatedBy': _finance_current_username(),
            }
            action = f"Set manual revenue to ${amount:,.2f} for event {event_id}"
            realtime_action = 'profit-loss-manual-revenue-updated'
            realtime_quotation_id = ''

        _save_finance_data(finance_data)
        response_payload = _finance_profit_loss_payload(event, finance_data)
        response_payload['permissions'] = _finance_profit_loss_access(
            finance_data,
            event_id,
        )

    log_action(action)
    mark_realtime_change('finance', {
        'eventId': event_id,
        'quotationId': realtime_quotation_id,
        'action': realtime_action,
    })
    return jsonify({'success': True, 'data': response_payload})


@app.route('/api/finance/profit-loss/<int:event_id>/commissions', methods=['PUT'])
@require_auth
def finance_profit_loss_update_commissions(event_id):
    event = data_manager.events.get(event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    if not _current_user_can_access_event(event):
        return _event_access_denied_response()
    payload = request.get_json(silent=True) or {}
    rows = payload.get('commissions')
    if not isinstance(rows, list):
        return jsonify({'error': 'Commissions must be a list'}), 400

    with _finance_lock:
        finance_data = _load_finance_data()
        if not _finance_profit_loss_access(
            finance_data,
            event_id,
        )['canEditFinancials']:
            return _finance_profit_loss_expense_access_denied()
        quotation_rows = _finance_quotations_for_event(
            finance_data,
            event_id,
            accessible_only=False,
        )
        quotation_rows = [
            row for row in quotation_rows
            if _finance_profit_loss_can_use_quotation(row)
        ]
        revenue = round(_safe_float((quotation_rows[0] if quotation_rows else {}).get('totals', {}).get('netSubtotal'), 0), 2)
        normalised = [
            _normalise_profit_loss_commission(row, revenue)
            for row in rows[:50]
            if isinstance(row, dict)
        ]
        store = _finance_profit_loss_store(finance_data).setdefault('commissions', {})
        store[str(event_id)] = normalised
        _save_finance_data(finance_data)
        response_payload = _finance_profit_loss_payload(event, finance_data)
        response_payload['permissions'] = _finance_profit_loss_access(
            finance_data,
            event_id,
        )

    log_action(f"Updated {len(normalised)} commission row(s) for event {event_id}")
    mark_realtime_change('finance', {'eventId': event_id, 'action': 'profit-loss-commissions-updated'})
    return jsonify({'success': True, 'data': response_payload})


@app.route('/api/finance/profit-loss/<int:event_id>/expenses', methods=['POST'])
@require_auth
def finance_profit_loss_add_expense(event_id):
    event = data_manager.events.get(event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    if not _current_user_can_access_event(event):
        return _event_access_denied_response()
    with _finance_lock:
        access_data = _load_finance_data()
        if not _finance_profit_loss_access(
            access_data,
            event_id,
        )['canEditFinancials']:
            return _finance_profit_loss_expense_access_denied()

    is_multipart = request.content_type and request.content_type.startswith('multipart/form-data')
    payload = request.form.to_dict() if is_multipart else (request.get_json(silent=True) or {})
    uploaded_file = request.files.get('file') if is_multipart else None
    attachment = None
    extraction = {}
    amount = payload.get('amount')
    expense_date = payload.get('expenseDate') or payload.get('date')

    if uploaded_file and getattr(uploaded_file, 'filename', ''):
        try:
            attachment = save_upload(
                _workforce_folder(),
                uploaded_file,
                event_id,
                'profit-loss',
                'claim',
            )
            absolute_path = upload_absolute_path(_workforce_folder(), attachment.get('storedPath'))
            extraction = extract_claim_amount(
                absolute_path,
                attachment.get('contentType', ''),
                attachment.get('originalName', ''),
            ) if absolute_path else {}
            if amount in (None, '') and extraction.get('amount') is not None:
                amount = extraction.get('amount')
            if not expense_date and extraction.get('date'):
                expense_date = extraction.get('date')
        except ValueError as exc:
            return jsonify({'error': str(exc)}), 400
        except Exception as exc:
            logger.error('Profit and Loss upload failed: %s', exc, exc_info=True)
            if attachment:
                delete_upload(_workforce_folder(), attachment)
            return jsonify({'error': 'The upload could not be completed'}), 500

    expense = _normalise_profit_loss_expense({
        **payload,
        'amount': amount,
        'expenseDate': expense_date,
        'description': (
            payload.get('description')
            or (attachment or {}).get('originalName')
            or 'Other expense'
        ),
        'attachment': attachment,
        'extraction': extraction,
    }, event_id)
    if expense['amount'] <= 0:
        if attachment:
            delete_upload(_workforce_folder(), attachment)
        return jsonify({'error': 'Expense amount is required'}), 400

    with _finance_lock:
        finance_data = _load_finance_data()
        if not _finance_profit_loss_access(
            finance_data,
            event_id,
        )['canEditFinancials']:
            if attachment:
                delete_upload(_workforce_folder(), attachment)
            return _finance_profit_loss_expense_access_denied()
        _finance_profit_loss_event_expenses(finance_data, event_id, create=True).append(expense)
        _save_finance_data(finance_data)
        payload = _finance_profit_loss_payload(event, finance_data)
        payload['permissions'] = _finance_profit_loss_access(
            finance_data,
            event_id,
        )
    log_action(f"Added Profit and Loss expense {expense['description']} to event {event_id}")
    mark_realtime_change('finance', {'eventId': event_id, 'action': 'profit-loss-expense-added'})
    return jsonify({'success': True, 'data': payload, 'expense': _profit_loss_expense_payload(expense)}), 201


@app.route('/api/finance/profit-loss/<int:event_id>/expenses/<expense_id>', methods=['PUT', 'DELETE'])
@require_auth
def finance_profit_loss_update_expense(event_id, expense_id):
    event = data_manager.events.get(event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    if not _current_user_can_access_event(event):
        return _event_access_denied_response()

    with _finance_lock:
        finance_data = _load_finance_data()
        if not _finance_profit_loss_access(
            finance_data,
            event_id,
        )['canEditFinancials']:
            return _finance_profit_loss_expense_access_denied()
        expenses = _finance_profit_loss_event_expenses(finance_data, event_id, create=True)
        existing = next((row for row in expenses if str(row.get('id')) == str(expense_id)), None)
        if not existing:
            return jsonify({'error': 'Expense not found'}), 404
        if request.method == 'DELETE':
            if isinstance(existing.get('attachment'), dict):
                delete_upload(_workforce_folder(), existing['attachment'])
            expenses[:] = [row for row in expenses if str(row.get('id')) != str(expense_id)]
            _save_finance_data(finance_data)
            payload = _finance_profit_loss_payload(event, finance_data)
            payload['permissions'] = _finance_profit_loss_access(
                finance_data,
                event_id,
            )
            log_action(f"Deleted Profit and Loss expense from event {event_id}")
            mark_realtime_change('finance', {'eventId': event_id, 'action': 'profit-loss-expense-deleted'})
            return jsonify({'success': True, 'data': payload})

        incoming = request.get_json(silent=True) or {}
        updated = _normalise_profit_loss_expense({
            **existing,
            **incoming,
            'id': existing.get('id'),
            'eventId': event_id,
            'attachment': existing.get('attachment'),
            'createdAt': existing.get('createdAt'),
            'createdBy': existing.get('createdBy'),
            'updatedAt': now_iso(),
            'updatedBy': _finance_current_username(),
        }, event_id)
        for index, row in enumerate(expenses):
            if str(row.get('id')) == str(expense_id):
                expenses[index] = updated
                break
        _save_finance_data(finance_data)
        payload = _finance_profit_loss_payload(event, finance_data)
        payload['permissions'] = _finance_profit_loss_access(
            finance_data,
            event_id,
        )
    log_action(f"Updated Profit and Loss expense for event {event_id}")
    mark_realtime_change('finance', {'eventId': event_id, 'action': 'profit-loss-expense-updated'})
    return jsonify({'success': True, 'data': payload, 'expense': _profit_loss_expense_payload(updated)})


@app.route('/api/finance/profit-loss/expenses/<expense_id>/file', methods=['GET'])
@require_auth
def finance_profit_loss_expense_file(expense_id):
    found = None
    found_event_id = None
    with _finance_lock:
        finance_data = _load_finance_data()
        expenses = _finance_profit_loss_store(finance_data).get('expenses') or {}
        for event_key, rows in expenses.items():
            if not isinstance(rows, list):
                continue
            for row in rows:
                if isinstance(row, dict) and str(row.get('id')) == str(expense_id):
                    found = row
                    found_event_id = _safe_int(event_key, 0)
                    break
            if found:
                break
    if not found or not found_event_id:
        return jsonify({'error': 'File not found'}), 404
    event = data_manager.events.get(found_event_id)
    if not event:
        return jsonify({'error': 'Event not found'}), 404
    if not _current_user_can_access_event(event):
        return _event_access_denied_response()
    if not _finance_profit_loss_access(
        finance_data,
        found_event_id,
    )['canViewFinancials']:
        return _finance_profit_loss_expense_access_denied()
    attachment = found.get('attachment') if isinstance(found.get('attachment'), dict) else None
    absolute_path = upload_absolute_path(_workforce_folder(), (attachment or {}).get('storedPath'))
    if not attachment or not absolute_path or not os.path.isfile(absolute_path):
        return jsonify({'error': 'File not found'}), 404
    return send_file(
        absolute_path,
        mimetype=attachment.get('contentType') or 'application/octet-stream',
        as_attachment=request.args.get('download') == '1',
        download_name=attachment.get('originalName') or 'expense-upload',
        max_age=0,
    )


