@app.route('/api/quotations/<document_id>/convert-to-invoice', methods=['POST'])
@require_sales
def convert_quotation_to_invoice(document_id):
    with _finance_lock:
        finance_data = _load_finance_data()
        quotation = _finance_find_document(finance_data, document_id, 'quotation')
        if not quotation or not _finance_user_can_access(quotation):
            return jsonify({'error': 'Quotation not found'}), 404
        existing_invoice = next(
            (
                row for row in finance_data.get('documents') or []
                if row.get('type') == 'invoice' and row.get('sourceQuotationId') == document_id
            ),
            None,
        )
        if existing_invoice:
            pdf_visibility = {
                key: quotation.get(key)
                for key in (
                    'showUnitPrices',
                    'showDepartmentDiscounts',
                    'showDepartmentSubtotals',
                    'summaryBySubproject',
                    'showLineNumbers',
                    'showSignOff',
                )
            }
            pdf_visibility['sourceQuotationNumber'] = quotation.get('number') or ''
            updated_invoice = _normalise_finance_document(
                pdf_visibility,
                'invoice',
                existing_invoice,
            )
            finance_data['documents'] = [
                updated_invoice if str(row.get('id')) == str(existing_invoice.get('id')) else row
                for row in finance_data.get('documents') or []
            ]
            _save_finance_data(finance_data)
            return jsonify({'success': True, 'data': updated_invoice})

        source = dict(quotation)
        source.pop('id', None)
        source.pop('number', None)
        source['sourceQuotationId'] = document_id
        source['sourceQuotationNumber'] = quotation.get('number') or ''
        source['status'] = 'draft'
        invoice_date = datetime.now().strftime('%Y-%m-%d')
        invoice_due_date, payment_term_days = _finance_payment_due_date(
            invoice_date,
            quotation.get('paymentTerms'),
        )
        source['invoiceDate'] = invoice_date
        source['dueDate'] = invoice_due_date
        source['paymentTermDays'] = payment_term_days
        invoice = _normalise_finance_document(source, 'invoice')
        invoice['number'] = _next_finance_number(finance_data.get('documents') or [], 'invoice')
        finance_data.setdefault('documents', []).append(invoice)

        _save_finance_data(finance_data)
        log_action(f"Converted quotation {quotation.get('number')} to invoice {invoice['number']}")
        return jsonify({'success': True, 'data': invoice}), 201


def _finance_pdf_response(document_id, document_type):
    with _finance_lock:
        finance_data = _load_finance_data()
        stored = _finance_find_document(finance_data, document_id, document_type)
        if not stored or not _finance_user_can_access(stored):
            return jsonify({'error': f'{document_type.title()} not found'}), 404
        revision = _safe_int(request.args.get('revision'), 0)
        if revision and document_type == 'quotation':
            revision_row = next(
                (
                    row for row in stored.get('revisions') or []
                    if isinstance(row, dict)
                    and _safe_int(row.get('revision'), 0) == revision
                    and isinstance(row.get('snapshot'), dict)
                ),
                None,
            )
            if not revision_row:
                return jsonify({'error': 'Quotation revision not found'}), 404
            revision_source = {
                **revision_row['snapshot'],
                'id': stored.get('id'),
                'type': 'quotation',
                'number': revision_row.get('number') or revision_row['snapshot'].get('number'),
                'revision': revision,
                'status': 'sent',
                'sentAt': revision_row.get('sentAt') or '',
                'validUntil': revision_row.get('validUntil') or revision_row['snapshot'].get('validUntil') or '',
                'validityAmount': revision_row.get('validityAmount') or revision_row['snapshot'].get('validityAmount'),
                'validityUnit': revision_row.get('validityUnit') or revision_row['snapshot'].get('validityUnit'),
                'validityDays': revision_row.get('validityDays') or revision_row['snapshot'].get('validityDays'),
            }
            document = _normalise_finance_document(revision_source, document_type, {})
            document['number'] = revision_source['number']
            document['revision'] = revision
        else:
            document = _normalise_finance_document(stored, document_type, stored)
        document['salespersonPhone'] = _finance_salesperson_phone(document)
        export_error = _finance_export_error(document)
        if export_error:
            return jsonify({'error': export_error}), 400

    try:
        from io import BytesIO
        from quotation_pdf import build_finance_pdf, safe_pdf_filename

        settings = _normalise_pdf_settings(_load_pdf_settings())
        logo_path = _pdf_logo_path(settings)
        pdf_bytes = build_finance_pdf(document, settings, logo_path)
    except ImportError:
        logger.error("ReportLab is required for finance PDF export", exc_info=True)
        return jsonify({'error': 'PDF export dependency is not installed'}), 503
    except Exception as exc:
        logger.error("Failed to render finance PDF: %s", exc, exc_info=True)
        return jsonify({'error': 'Failed to generate PDF'}), 500

    return send_file(
        BytesIO(pdf_bytes),
        mimetype='application/pdf',
        as_attachment=request.args.get('download') == '1',
        download_name=safe_pdf_filename(document.get('number')),
        max_age=0,
    )


